        // Track last totals to detect when a new sale/price/discount state happens.
        private decimal _lastSalesPersonTotal = -1m;
        private decimal _lastSalesPersonDiscount = -1m;

        private void ResetSalesPersonIfTotalsChanged()
        {
            // If we haven't selected a salesperson, nothing to reset.
            if (string.IsNullOrWhiteSpace(currentSalesPersonCode) && string.IsNullOrWhiteSpace(currentSalesPersonName))
            {
                _lastSalesPersonTotal = currentTotal;
                _lastSalesPersonDiscount = currentDiscount;
                return;
            }

            // Reset when totals or discounts change (items added/removed, price changes, discount changes, etc.).
            if (_lastSalesPersonTotal != currentTotal || _lastSalesPersonDiscount != currentDiscount)
            {
                currentSalesPersonCode = null;
                currentSalesPersonName = null;
                UpdateSalesPersonDisplay();
            }

            _lastSalesPersonTotal = currentTotal;
            _lastSalesPersonDiscount = currentDiscount;
        }

        private void UpdateSalesPersonDisplay()
        {
            if (salesPersonDisplayLabel == null) return;

            if (string.IsNullOrWhiteSpace(currentSalesPersonName) && string.IsNullOrWhiteSpace(currentSalesPersonCode))
            {
                salesPersonDisplayLabel.Text = "Salesperson: (none)";
                salesPersonDisplayLabel.ForeColor = Color.DimGray;
            }
            else
            {
                var display = !string.IsNullOrWhiteSpace(currentSalesPersonName) ? currentSalesPersonName! : currentSalesPersonCode!;
                salesPersonDisplayLabel.Text = $"Salesperson: {display}";
                salesPersonDisplayLabel.ForeColor = Color.DarkSlateBlue;
            }
        }

