            this.FormClosing += MainForm_FormClosing;
        }

        public bool BeginReturnExchange(string originalReceiptNo, List<ReturnItemSelectionForm.ReturnItem> selectedReturnItems)
        {
            if (string.IsNullOrWhiteSpace(originalReceiptNo))
            {
                MessageBox.Show("Original receipt number is required.", "Return / Exchange", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return false;
            }

            if (selectedReturnItems == null || selectedReturnItems.Count == 0)
            {
                MessageBox.Show("No items selected for return.", "Return / Exchange", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return false;
            }

            if (salesListView.Items.Count > 0)
            {
                if (MessageBox.Show(
                        "The POS currently has an in-progress sale. Clear it and start the return/exchange?",
                        "Start Return / Exchange",
                        MessageBoxButtons.YesNo,
                        MessageBoxIcon.Question) != DialogResult.Yes)
                {
                    return false;
                }
            }

            ClearSaleAndPayments();

            isReturnExchangeMode = true;
            returnExchangeOriginalReceiptNo = originalReceiptNo;

            EnsureSaleMetadataColumns();

            foreach (var selected in selectedReturnItems)
            {
                int soldQty = Math.Abs(selected.Quantity);
                int returnQty = Math.Abs(selected.QuantityToReturn);
                if (soldQty <= 0 || returnQty <= 0)
                    continue;

                if (returnQty > soldQty)
                    returnQty = soldQty;

                decimal unitPrice = selected.UnitPrice > 0m
                    ? selected.UnitPrice
                    : (soldQty > 0 ? Math.Abs(selected.LineAmount) / soldQty : 0m);

                decimal perUnitAmount = soldQty > 0 && selected.LineAmount != 0m
                    ? Math.Abs(selected.LineAmount) / soldQty
                    : unitPrice;

                decimal lineAmount = decimal.Round(perUnitAmount * returnQty, 2);

                var item = new ListViewItem($"RETURN - {FunctionEvents.ToAscii(selected.Description)}");
                item.SubItems.Add(returnQty.ToString());
                item.SubItems.Add($"{unitPrice:F2}");
                item.SubItems.Add($"{-lineAmount:F2}");
                item.SubItems.Add(string.Empty);
                item.SubItems.Add(FunctionEvents.ToAscii(selected.ItemCode));
                item.Tag = ReturnLineTag;
                item.ForeColor = Color.Firebrick;

                salesListView.Items.Add(item);
                currentTotal -= lineAmount;
            }

            currentDiscount = 0m;
            currentDiscountDescription = string.Empty;
            grandTotal = currentTotal;
            UpdateTotal();

            checkoutButton.Text = "CHECKOUT EXCHANGE";
            checkoutButton.Tag = "EXCHANGE";
            checkoutButton.BackColor = Color.Firebrick;

            try
            {
                WindowState = FormWindowState.Maximized;
                Show();
                BringToFront();
                Activate();
            }
            catch { }

            MessageBox.Show(
                $"Return items from receipt {originalReceiptNo} were loaded into the POS.\n\nNow punch the replacement items on the main POS screen. The Grand Total will show the amount the customer still needs to pay.",
                "Return / Exchange",
                MessageBoxButtons.OK,
                MessageBoxIcon.Information);

            return true;
        }


        /// <summary>
        /// /// Populate the salesListView with lines from a persisted online order so the cashier
        /// can complete the sale. This sets a new receipt number and updates internal state
        /// (currentReceiptNo and currentTransNo) so the UI behaves as if a sale was started.
        /// </summary>
        /// <param name="orderId">Online Order ID (OrderID in dbo.OnlineOrderLines)</param>
        /// <param name="receiptNo">Receipt number to assign for the staged sale</param>
        public void StageOnlineOrderIntoSalesList(string orderId, string receiptNo)
        {
            if (string.IsNullOrWhiteSpace(orderId) || string.IsNullOrWhiteSpace(receiptNo)) return;

            try
            {
                // Clear any existing sale state
                this.Invoke(new Action(() =>
                {
                    try
                    {
                        currentTransNo = GetNextTransactionNoPlusOne().ToString();
                    }
                    catch
                    {
                        currentTransNo = DateTime.Now.Ticks.ToString();
                    }
                }));

                using (var conn = new SqlConnection(connectionString))
                {
                    conn.Open();
                    string q = @"SELECT l.Description, l.ItemCode, l.Quantity, l.Price, i.CategoryCode
                                     FROM dbo.OnlineOrderLines l
                                     LEFT JOIN Items i ON i.Code = l.ItemCode
                                     WHERE l.OrderID = @OrderID
                                     ORDER BY l.LineID";
                    using (var cmd = new SqlCommand(q, conn))
                    {
                        cmd.Parameters.AddWithValue("@OrderID", orderId);
                        using (var rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                string desc = rdr["Description"] != DBNull.Value ? rdr["Description"].ToString() ?? string.Empty : (rdr["ItemCode"] != DBNull.Value ? rdr["ItemCode"].ToString() ?? string.Empty : string.Empty);
                                string itemCode = rdr["ItemCode"] != DBNull.Value ? rdr["ItemCode"].ToString() ?? string.Empty : string.Empty;
                                string categoryCode = rdr["CategoryCode"] != DBNull.Value ? rdr["CategoryCode"].ToString() ?? string.Empty : string.Empty;
                                decimal qty = rdr["Quantity"] != DBNull.Value ? Convert.ToDecimal(rdr["Quantity"]) : 0m;
                                decimal price = rdr["Price"] != DBNull.Value ? Convert.ToDecimal(rdr["Price"]) : 0m;

                                var item = new ListViewItem(desc);
                                item.SubItems.Add((qty % 1 == 0) ? ((long)qty).ToString() : qty.ToString("0.##"));
                                item.SubItems.Add(price.ToString("0.##"));
                                decimal total = qty * price;
                                item.SubItems.Add(total.ToString("0.##"));

                                // Keep internal metadata via Tag but do not add visible columns for them.
                                // Store metadata in Tag using a simple pipe-delimited string: marker|itemCode|categoryCode
                                item.Tag = $"ONLINE_STAGED|{itemCode}|{categoryCode}";

                                // Add on UI thread
                                this.Invoke(new Action(() => { salesListView.Items.Add(item); }));
                            }
                        }
                    }
                }

                // Update totals on UI thread
                this.Invoke(new Action(() =>
                {
                    // Recompute totals from salesListView
                    try
                    {
                        currentTotal = 0m; currentDiscount = 0m; grandTotal = 0m;
                        foreach (ListViewItem it in salesListView.Items)
                        {
                            if (it.SubItems.Count >= 4)
                            {
                                if (decimal.TryParse(it.SubItems[3].Text, out var lineTotal)) currentTotal += lineTotal;
                            }
                        }
                        grandTotal = currentTotal - currentDiscount;
                        totalLabel.Text = $"Total: {currentTotal:0.00}";
                        grandTotalLabel.Text = $"Grand Total: {grandTotal:0.00}";
                        paymentsLabel.Text = $"Payments: {totalPaid:0.00}";
                        remainingBalanceLabel?.Invoke(new Action(() => { if (remainingBalanceLabel != null) remainingBalanceLabel.Text = $"Remaining: {grandTotal - totalPaid:0.00}"; }));
                    }
                    catch { }
                }));
            }
            catch (Exception ex)
            {
                try { MessageBox.Show($"Failed to stage online order into sales list: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error); } catch { }
            }
        }


        private void InitializeInactivityTimer()
        {
            inactivityTimer = new System.Windows.Forms.Timer();
            inactivityTimer.Interval = 1000; // tick every second for testing
            inactivityTimer.Tick += InactivityTimer_Tick;
            inactivityTimer.Start();

            // Reset timer on common user interactions
            this.MouseMove += (s, e) => ResetInactivityTimer();
            this.KeyDown += (s, e) => ResetInactivityTimer();
            this.MouseClick += (s, e) => ResetInactivityTimer();
            // Also handle controls that may take focus
            this.ControlAdded += (s, e) => { if (e.Control != null) WireControlActivityHandlers(e.Control); };
        }

        private void WireControlActivityHandlers(Control ctrl)
        {
            try
            {
                ctrl.MouseMove += (s, e) => ResetInactivityTimer();
                ctrl.Click += (s, e) => ResetInactivityTimer();
                ctrl.KeyDown += (s, e) => ResetInactivityTimer();
                // Also watch for KeyPress which is common during typing
                ctrl.KeyPress += (s, e) => ResetInactivityTimer();

                // If a control exposes TextChanged, subscribe using reflection to cover TextBox, ComboBox, etc.
                try
                {
                    var textChangedEvent = ctrl.GetType().GetEvent("TextChanged");
                    if (textChangedEvent != null)
                    {
                        textChangedEvent.AddEventHandler(ctrl, new EventHandler((s, e) => ResetInactivityTimer()));
                    }
                }
                catch { }

                // If a control exposes ValueChanged (NumericUpDown, DateTimePicker), subscribe as well
                try
                {
                    var valueChangedEvent = ctrl.GetType().GetEvent("ValueChanged");
                    if (valueChangedEvent != null)
                    {
                        valueChangedEvent.AddEventHandler(ctrl, new EventHandler((s, e) => ResetInactivityTimer()));
                    }
                }
                catch { }
            }
            catch
            {
                // ignore controls that don't support events
            }
            // wire recursively for children
            foreach (Control child in ctrl.Controls)
                WireControlActivityHandlers(child);
        }

        private void InactivityTimer_Tick(object? sender, EventArgs e)
        {
            try
            {
                var elapsed = DateTime.Now - lastActivity;
                if (elapsed.TotalSeconds >= inactivityTimeoutSeconds)
                {
                    // If there's an active sale (items in the salesListView), do not auto-logout.
                    try
                    {
                        if (salesListView != null && salesListView.Items.Count > 0)
                        {
                            // Treat as activity and reset timer instead of logging out
                            lastActivity = DateTime.Now;
                            return;
                        }
                    }
                    catch { /* ignore any UI inspection errors and continue with logout */ }

                    inactivityTimer.Stop();
                    PerformAutoLogout();
                }
            }
            catch
            {
                // ignore timer errors
            }
        }

        private void ResetInactivityTimer()
        {
            lastActivity = DateTime.Now;
            try { if (!inactivityTimer.Enabled) inactivityTimer.Start(); } catch { }
        }

        private void PerformAutoLogout()
        {
            try
            {
                // Force logout without prompting the user: stop timer, show login and close main form
                try { inactivityTimer?.Stop(); } catch { }
                this.Invoke((Action)(() =>
                {
                    // Create/show a fresh LoginForm to ensure a clean login UI
                    var loginForm = new LoginForm();
                    // Closing the login form should exit the app
                    loginForm.FormClosed += (s, args) => Application.Exit();
                    try
                    {
                        loginForm.Show();
                        loginForm.BringToFront();
                        loginForm.Activate();
                        loginForm.TopMost = true;
                        loginForm.TopMost = false;
                    }
                    catch { }

                    // Hide every other open form so only the new login form remains visible.
                    // Avoid Close() to prevent triggering FormClosed handlers that may close the login form.
                    var openForms = Application.OpenForms.Cast<Form>().ToList();
                    foreach (var f in openForms)
                    {
                        try
                        {
                            if (f == loginForm) continue;
                            try { f.Hide(); }
                            catch { try { f.Visible = false; } catch { } }
                        }
                        catch { }
                    }

                    try { loginForm.Focus(); } catch { }
                }));
            }
            catch
            {
                // best-effort
                try { Application.Exit(); } catch { }
            }
        }

        // Public helper so other forms (e.g., OnlineOrdersForm) can trigger a clean logout after specific flows like payment posting.
        public void ForceLogoutAfterPayment()
        {
            try { PerformAutoLogout(); } catch { }
        }

        // Public helper to reprint a sales receipt by receipt number. Loads items from ItemLedgerEntry or TransactionHeader
        public void PrintSaleReceipt(string receiptNo)
        {
            try
            {
                // Build receiptContent similar to GenerateReceiptContent but sourcing items from ItemLedgerEntry for the given receipt
                var receipt = new StringBuilder();
                string line = new string('-', GlobalSettings.ReceiptWidth);
                string onlineOrderId = OnlinefunctionsEvents.GetMappedOnlineOrderIdForReceipt(receiptNo);
                decimal headerDiscount = 0m;
                decimal? headerGrossAmount = null;
                decimal? headerNetAmount = null;
                string discountDescription = string.Empty;
                string headerDescription = string.Empty;

                receipt.AppendLine("      RS PET STOP");
                receipt.AppendLine("  AQUARIUM PRODUCTS");
                receipt.AppendLine("   & SOLUTIONS");
                receipt.AppendLine(line);
                receipt.AppendLine($"Date: {DateTime.Now:yyyy-MM-dd HH:mm}");
                receipt.AppendLine($"Receipt #: {receiptNo}");
                if (!string.IsNullOrWhiteSpace(onlineOrderId))
                {
                    receipt.AppendLine($"Online Order ID: {onlineOrderId}");
                }
                receipt.AppendLine(line);

                // Load item lines from ItemLedgerEntry for this receipt
                var lines = new List<string>();
                decimal subtotal = 0m;

                using (var conn = new SqlConnection(connectionString))
                {
                    conn.Open();
                    using (var headerCmd = new SqlCommand(@"SELECT TOP 1 Discount, GrossAmount, NetAmount, DiscountDescription, Description
                                                           FROM TransactionHeader
                                                           WHERE ReceiptNo = @receiptNo
                                                           ORDER BY TransactionNo DESC", conn))
                    {
                        headerCmd.Parameters.AddWithValue("@receiptNo", receiptNo);
                        using (var headerRdr = headerCmd.ExecuteReader())
                        {
                            if (headerRdr.Read())
                            {
                                headerDiscount = headerRdr["Discount"] != DBNull.Value ? Convert.ToDecimal(headerRdr["Discount"]) : 0m;
                                headerGrossAmount = headerRdr["GrossAmount"] != DBNull.Value ? Convert.ToDecimal(headerRdr["GrossAmount"]) : null;
                                headerNetAmount = headerRdr["NetAmount"] != DBNull.Value ? Convert.ToDecimal(headerRdr["NetAmount"]) : null;
                                discountDescription = headerRdr["DiscountDescription"]?.ToString() ?? string.Empty;
                                headerDescription = headerRdr["Description"]?.ToString() ?? string.Empty;
                            }
                        }
                    }

                    string query = @"SELECT ILE.ItemCode, ILE.Description, ILE.Quantity, ILE.UnitCost AS Price, ILE.TotalCost
                                     FROM ItemLedgerEntry ILE
                                     WHERE ILE.DocumentNo = @receiptNo OR ILE.DocumentNo = @receiptRev
                                     ORDER BY ILE.ID";

                    using (var cmd = new SqlCommand(query, conn))
                    {
                        cmd.Parameters.AddWithValue("@receiptNo", receiptNo);
                        cmd.Parameters.AddWithValue("@receiptRev", receiptNo + "-REV");
                        using (var rdr = cmd.ExecuteReader())
                        {
                            while (rdr.Read())
                            {
                                string desc = rdr["Description"]?.ToString() ?? rdr["ItemCode"]?.ToString() ?? "";
                                int qty = rdr["Quantity"] != DBNull.Value ? Convert.ToInt32(rdr["Quantity"]) : 0;
                                decimal price = rdr["Price"] != DBNull.Value ? Convert.ToDecimal(rdr["Price"]) : 0m;
                                decimal total = rdr["TotalCost"] != DBNull.Value ? Convert.ToDecimal(rdr["TotalCost"]) : qty * price;

                                subtotal += total;

                                // wrap desc to width (14) similar to existing logic
                                int wrapWidth = 14;
                                for (int i = 0; i < desc.Length; i += wrapWidth)
                                {
                                    string descLine = desc.Substring(i, Math.Min(wrapWidth, desc.Length - i));
                                    if (i == 0)
                                        lines.Add($"{descLine,-12} {qty,-3} {total:N2,-8}");
                                    else
                                        lines.Add($"{descLine,-12}");
                                }
                            }
                        }
                    }

                    decimal cardProcessingFee = ExtractCardProcessingFeeFromHeaderDescription(headerDescription);
                    if (cardProcessingFee > 0m)
                    {
                        subtotal += cardProcessingFee;
                        lines.Add($"{CardProcessingFeeDescription,-12} {1,-3} {cardProcessingFee:N2,-8}");
                    }

                    // Fallback: if no item ledger entries, try TransactionHeader single-line
                    if (lines.Count == 0)
                    {
                        string q2 = @"SELECT Description, Quantity, Price, NetAmount FROM TransactionHeader WHERE ReceiptNo = @receiptNo";
                        using (var cmd2 = new SqlCommand(q2, conn))
                        {
                            cmd2.Parameters.AddWithValue("@receiptNo", receiptNo);
                            using (var rdr2 = cmd2.ExecuteReader())
                            {
                                while (rdr2.Read())
                                {
                                    string desc = rdr2["Description"]?.ToString() ?? "SALE";
                                    int qty = rdr2["Quantity"] != DBNull.Value ? Convert.ToInt32(rdr2["Quantity"]) : 1;
                                    decimal price = rdr2["Price"] != DBNull.Value ? Convert.ToDecimal(rdr2["Price"]) : 0m;
                                    decimal net = rdr2["NetAmount"] != DBNull.Value ? Convert.ToDecimal(rdr2["NetAmount"]) : qty * price;
                                    subtotal += net;
                                    lines.Add($"{desc,-12} {qty,-3} {net:N2,-8}");
                                }
                            }
                        }
                    }
                }

                receipt.AppendLine("ITEMS:");
                receipt.AppendLine($"{"Item",-12} {"Qty",-3} {"Amount",-8}");
                receipt.AppendLine(line);
                foreach (var l in lines) receipt.AppendLine(l);
                receipt.AppendLine(line);
                receipt.AppendLine();
                AppendWrappedReceiptNote(receipt, ExtractSpecialNoteFromOrderDescription(headerDescription), GlobalSettings.ReceiptWidth);
                decimal printedSubtotal = headerGrossAmount ?? subtotal;
                decimal printedGrandTotal = headerNetAmount ?? printedSubtotal;
                receipt.AppendLine($"{"Subtotal:"} {printedSubtotal:N2}");
                if (headerDiscount > 0m)
                {
                    receipt.AppendLine($"{GetReceiptDiscountLabel(discountDescription)}: {headerDiscount:N2}");
                }
                receipt.AppendLine($"{"GRAND TOTAL:"} {printedGrandTotal:N2}");
                receipt.AppendLine(line);
                receipt.AppendLine();
                receipt.AppendLine("    THANK YOU!");
                receipt.AppendLine("  COME AGAIN SOON!");
                receipt.AppendLine(line);

                receiptContent = receipt.ToString();

                // Send to printer using existing printDocument
                printDocument.Print();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to reprint sale receipt: {ex.Message}", "Print Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        public MainForm() : this("") { }

        private void InitializeDatabase()
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    // Create TransPaymentEntry table if it doesn't exist
                    string createTransPaymentEntryTable = @"
                        IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='TransPaymentEntry' AND xtype='U')
                        CREATE TABLE TransPaymentEntry (
                            StoreNo NVARCHAR(10) NOT NULL,
                            POSTerminalNo NVARCHAR(10) NOT NULL,
                            TransactionNo NVARCHAR(20) NOT NULL,
                            TenderTypeCode NVARCHAR(10) NOT NULL,
                            [LineNo] INT NOT NULL,
                            ReceiptNo NVARCHAR(20) NULL,
                            Description NVARCHAR(200) NULL,
                            Amount DECIMAL(18,2) NOT NULL DEFAULT 0,
                            UserID NVARCHAR(50) NULL,
                            Date DATE DEFAULT CAST(GETDATE() AS DATE),
                            Time TIME DEFAULT CAST(GETDATE() AS TIME),
                            CreatedDate DATETIME DEFAULT GETDATE(),
                            CONSTRAINT PK_TransPaymentEntry PRIMARY KEY (StoreNo, POSTerminalNo, TransactionNo, TenderTypeCode, [LineNo])
                        )";
                    using (var command = new SqlCommand(createTransPaymentEntryTable, connection))
                    {
                        command.ExecuteNonQuery();
                    }
        
                    // Add LineNo column if table exists but column doesn't exist
                    string addLineNoColumn = @"
                        IF EXISTS (SELECT * FROM sysobjects WHERE name='TransPaymentEntry' AND xtype='U')
                        AND NOT EXISTS (SELECT * FROM syscolumns WHERE id = OBJECT_ID('TransPaymentEntry') AND name = 'LineNo')
                        BEGIN
                            ALTER TABLE TransPaymentEntry ADD [LineNo] INT NOT NULL DEFAULT 1;
                
                            -- Drop and recreate primary key to include LineNo
                            IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_TYPE = 'PRIMARY KEY' AND TABLE_NAME = 'TransPaymentEntry')
                            BEGIN
                                ALTER TABLE TransPaymentEntry DROP CONSTRAINT PK_TransPaymentEntry;
                                ALTER TABLE TransPaymentEntry ADD CONSTRAINT PK_TransPaymentEntry PRIMARY KEY (StoreNo, POSTerminalNo, TransactionNo, TenderTypeCode, [LineNo]);
                            END
                        END";
        
                    using (var command = new SqlCommand(addLineNoColumn, connection))
                    {
                        command.ExecuteNonQuery();
                    }
        
                    // Add Description column if missing
                    string addDescriptionColumn = @"
                        IF EXISTS (SELECT * FROM sysobjects WHERE name='TransPaymentEntry' AND xtype='U')
                        AND NOT EXISTS (SELECT * FROM syscolumns WHERE id = OBJECT_ID('TransPaymentEntry') AND name = 'Description')
                        BEGIN
                            ALTER TABLE TransPaymentEntry ADD Description NVARCHAR(200) NULL;
                        END";
        
                    using (var command2 = new SqlCommand(addDescriptionColumn, connection))
                    {
                        command2.ExecuteNonQuery();
                    }

                    string addDiscountDescriptionColumn = @"
                        IF EXISTS (SELECT * FROM sysobjects WHERE name='TransactionHeader' AND xtype='U')
                        AND NOT EXISTS (SELECT * FROM syscolumns WHERE id = OBJECT_ID('TransactionHeader') AND name = 'DiscountDescription')
                        BEGIN
                            ALTER TABLE TransactionHeader ADD DiscountDescription NVARCHAR(100) NULL;
                        END";

                    using (var command3 = new SqlCommand(addDiscountDescriptionColumn, connection))
                    {
                        command3.ExecuteNonQuery();
                    }

                    string addExpenseCategoryColumn = @"
                        IF EXISTS (SELECT * FROM sysobjects WHERE name='TransactionHeader' AND xtype='U')
                        AND NOT EXISTS (SELECT * FROM syscolumns WHERE id = OBJECT_ID('TransactionHeader') AND name = 'ExpenseCategory')
                        BEGIN
                            ALTER TABLE TransactionHeader ADD ExpenseCategory NVARCHAR(100) NULL;
                        END";

                    using (var command4 = new SqlCommand(addExpenseCategoryColumn, connection))
                    {
                        command4.ExecuteNonQuery();
                    }

                    // FullyPaid/DatePaid on AdvanceOrderHeader - previously a manual one-off script
                    // (sql_advance_order_paid_status.sql) that had to be run by hand and was easy to
                    // forget; auto-applying here on every startup (idempotent, additive-only ALTER)
                    // matches how the columns above are already self-healed instead of relying on
                    // someone remembering to run a script.
                    string addAdvanceOrderFullyPaidColumn = @"
                        IF EXISTS (SELECT * FROM sysobjects WHERE name='AdvanceOrderHeader' AND xtype='U')
                        AND NOT EXISTS (SELECT * FROM syscolumns WHERE id = OBJECT_ID('AdvanceOrderHeader') AND name = 'FullyPaid')
                        BEGIN
                            ALTER TABLE dbo.AdvanceOrderHeader ADD FullyPaid BIT NOT NULL CONSTRAINT DF_AdvanceOrderHeader_FullyPaid DEFAULT (0);
                        END";

                    using (var command5 = new SqlCommand(addAdvanceOrderFullyPaidColumn, connection))
                    {
                        command5.ExecuteNonQuery();
                    }

                    string addAdvanceOrderDatePaidColumn = @"
                        IF EXISTS (SELECT * FROM sysobjects WHERE name='AdvanceOrderHeader' AND xtype='U')
                        AND NOT EXISTS (SELECT * FROM syscolumns WHERE id = OBJECT_ID('AdvanceOrderHeader') AND name = 'DatePaid')
                        BEGIN
                            ALTER TABLE dbo.AdvanceOrderHeader ADD DatePaid DATETIME2 NULL;
                        END";

                    using (var command6 = new SqlCommand(addAdvanceOrderDatePaidColumn, connection))
                    {
                        command6.ExecuteNonQuery();
                    }

                    CompleteAquariumSetData.EnsureTablesExist(connectionString);

                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Database initialization error: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

