        // Called when the MainForm has finished loading. Initialize timers that require the UI to be ready.
        private void MainForm_Load(object? sender, EventArgs e)
        {
            try
            {
                // Initialize inactivity timer so auto-logout works as intended
                // InitializeInactivityTimer();
            }
            catch { }
            // Initialize and start background online sync timer (10s)
            try
            {
                if (onlineSyncTimer == null)
                {
                    onlineSyncTimer = new System.Windows.Forms.Timer();
                    onlineSyncTimer.Interval = 10000; // 10 seconds
                    onlineSyncTimer.Tick += OnlineSyncTimer_Tick;
                    onlineSyncTimer.Start();
                }

                // Master data (Warehouses/Items) auto-sync - runs every 5 minutes, much less
                // frequently than the order sync since this is slower-changing data. Each run:
                // 1) pulls the latest Warehouses/Items from the Pancake (pages.fm) API into the
                //    local DB (same calls as WarehouseSetupForm's/Sync Products' manual buttons), then
                // 2) pushes the resulting local data to Supabase.
                if (masterDataSyncTimer == null)
                {
                    masterDataSyncTimer = new System.Windows.Forms.Timer();
                    masterDataSyncTimer.Interval = 300000; // 5 minutes
                    masterDataSyncTimer.Tick += MasterDataSyncTimer_Tick;
                    masterDataSyncTimer.Start();
                    // Kick off one sync right away on startup too, instead of waiting a full 5 minutes.
                    Task.Run(() => MasterDataSyncTimer_Tick(null, EventArgs.Empty));
                }
                // Subscribe to network availability changes so we can attempt to resend failed transactions
                try
                {
                    NetworkChange.NetworkAvailabilityChanged += NetworkAvailabilityChangedHandler;
                }
                catch { }

                // Attempt a one-time startup resend of failed transactions in background
                try
                {
                    Task.Run(() => TrySendFailedTransactionsAsync());
                }
                catch { }
            }
            catch { }
        }

        // Online sync timer tick handler (runs on UI thread)
        private async void OnlineSyncTimer_Tick(object? sender, EventArgs e)
        {
            if (_isOnlineSyncRunning) return;
            _isOnlineSyncRunning = true;
            try
            {
                DataTable? table = null;
                //Pakibalik please ROIE
                // try
                // {
                //     table = await IntegrationEvents.SyncOrderListAsync(TimeSpan.FromSeconds(30)).ConfigureAwait(false);
                // }
                // catch (Exception ex)
                // {
                //     try { System.Diagnostics.Trace.TraceError($"OnlineSyncTimer: sync failed: {ex}"); } catch { }
                //     table = null;
                // }

                // If we have confirmed orders, notify admin similar to OnlineOrdersForm behavior
                try
                {
                    int confirmedCount = 0;
                    var confirmedOrderPairs = new System.Collections.Generic.List<string>();
                    if (table != null && table.Rows.Count > 0)
                    {
                        foreach (System.Data.DataRow rr in table.Rows)
                        {
                            var s = (rr["Status"] as string) ?? string.Empty;
                            if (string.Equals(s, "Confirmed", StringComparison.OrdinalIgnoreCase))
                            {
                                confirmedCount++;
                                try
                                {
                                    var oid = table.Columns.Contains("OrderID") ? (rr["OrderID"] as string ?? string.Empty) : string.Empty;
                                    var cname = table.Columns.Contains("CustomerName") ? (rr["CustomerName"] as string ?? string.Empty) : string.Empty;
                                    string pair = oid;
                                    if (!string.IsNullOrWhiteSpace(cname)) pair = string.IsNullOrWhiteSpace(oid) ? cname : $"{oid} ({cname})";
                                    if (!string.IsNullOrWhiteSpace(pair)) confirmedOrderPairs.Add(pair);
                                }
                                catch { }
                            }
                        }
                    }

                    if (confirmedCount > 0 && !string.IsNullOrWhiteSpace(GlobalSettings.AdminPageId) && GlobalSettings.AdminConversationIds != null && GlobalSettings.AdminConversationIds.Length > 0)
                    {
                        _ = System.Threading.Tasks.Task.Run(async () =>
                        {
                            try
                            {
                                string idsCsv = string.Join(", ", confirmedOrderPairs);
                                string extra = "Please pull this order in the POS and follow next steps. Thank you";
                                string header = confirmedCount > 0
                                    ? $"Hi Admin, There are {confirmedCount} new confirmed online orders{(string.IsNullOrWhiteSpace(idsCsv) ? "." : $": {idsCsv}")}"
                                    : "There are new confirmed online orders.";
                                string msg = header + Environment.NewLine + extra;
                                var firstOrderId = string.Empty;
                                try
                                {
                                    if (confirmedOrderPairs.Count > 0)
                                    {
                                        var p = confirmedOrderPairs[0] ?? string.Empty;
                                        var idx = p.IndexOf(" (");
                                        firstOrderId = idx > 0 ? p.Substring(0, idx) : p;
                                    }
                                }
                                catch { firstOrderId = string.Empty; }

                                // Send to each configured admin conversation id (ignore empty entries)
                                foreach (var conv in GlobalSettings.AdminConversationIds)
                                {
                                    try
                                    {
                                        if (string.IsNullOrWhiteSpace(conv)) continue;
                                        await IntegrationEvents.sendneworderupdatetoADMIN(firstOrderId, GlobalSettings.AdminPageId, conv, msg).ConfigureAwait(false);
                                    }
                                    catch (Exception ex2)
                                    {
                                        try { System.Diagnostics.Trace.TraceError($"OnlineSyncTimer admin notify to {conv} failed: {ex2}"); } catch { }
                                    }
                                }
                            }
                            catch (Exception ex)
                            {
                                try { System.Diagnostics.Trace.TraceError($"OnlineSyncTimer admin notify failed: {ex}"); } catch { }
                            }
                        });
                    }
                }
                catch { }
            }
            finally
            {
                _isOnlineSyncRunning = false;
            }
        }

        // Master data sync timer tick handler. Awaits the async sync calls with
        // ConfigureAwait(false) so the (potentially slow, many-HTTP-call) sync work runs on a
        // background thread instead of blocking the UI thread.
        // Pulls fresh Warehouses/Items from Pancake (pages.fm) into the local DB first, then
        // pushes the local data to Supabase, so Supabase ends up reflecting the latest Pancake data.
        private async void MasterDataSyncTimer_Tick(object? sender, EventArgs e)
        {
            if (_isMasterDataSyncRunning) return;
            _isMasterDataSyncRunning = true;
            try
            {
                try { await OnlinefunctionsEvents.SyncWarehouseAsync(TimeSpan.FromSeconds(60)).ConfigureAwait(false); } catch { /* best-effort, next tick will retry */ }
                try { await OnlinefunctionsEvents.SyncProductVariationsAsync(TimeSpan.FromSeconds(90)).ConfigureAwait(false); } catch { /* best-effort, next tick will retry */ }

                try { await OnlinefunctionsEvents.SyncWarehousesToSupabaseAsync().ConfigureAwait(false); } catch { /* best-effort, next tick will retry */ }
                try { await OnlinefunctionsEvents.SyncItemsToSupabaseAsync().ConfigureAwait(false); } catch { /* best-effort, next tick will retry */ }
                try { await OnlinefunctionsEvents.SyncOnlineOrdersToSupabaseAsync().ConfigureAwait(false); } catch { /* best-effort, next tick will retry */ }
                try { await OnlinefunctionsEvents.SyncAdvanceOrdersToSupabaseAsync().ConfigureAwait(false); } catch { /* best-effort, next tick will retry */ }

                // Opposite direction from everything else above (Supabase -> desktop) - the Web
                // Portal's Category Setup screen is the only place "Production Category" can be
                // toggled, so this is what makes that reach Stock Counts' own local filter.
                try { await OnlinefunctionsEvents.SyncCategoryProductionFlagsFromSupabaseAsync().ConfigureAwait(false); } catch { /* best-effort, next tick will retry */ }

                // Also Supabase -> desktop, but two-way (last-writer-wins) rather than single-owner
                // like Categories above - the Portal's Transfer Order Ship flow tags serials
                // IN_TRANSIT directly in Supabase (see staff_claim_serials_for_transfer_shipment),
                // which local wouldn't otherwise ever find out about.
                try { await OnlinefunctionsEvents.SyncItemSerialTrackingFromSupabaseAsync().ConfigureAwait(false); } catch { /* best-effort, next tick will retry */ }
            }
            finally
            {
                _isMasterDataSyncRunning = false;
            }
        }

        private void MainForm_FormClosing(object? sender, FormClosingEventArgs e)
        {
            try
            {
                if (onlineSyncTimer != null)
                {
                    try { onlineSyncTimer.Stop(); } catch { }
                    try { onlineSyncTimer.Tick -= OnlineSyncTimer_Tick; } catch { }
                    try { onlineSyncTimer.Dispose(); } catch { }
                    onlineSyncTimer = null;
                }
                if (masterDataSyncTimer != null)
                {
                    try { masterDataSyncTimer.Stop(); } catch { }
                    try { masterDataSyncTimer.Tick -= MasterDataSyncTimer_Tick; } catch { }
                    try { masterDataSyncTimer.Dispose(); } catch { }
                    masterDataSyncTimer = null;
                }
                try
                {
                    NetworkChange.NetworkAvailabilityChanged -= NetworkAvailabilityChangedHandler;
                }
                catch { }
            }
            catch { }
        }

        // Handler for system network availability changes. When network becomes available,
        // attempt to resend any failed transactions in background.
        private void NetworkAvailabilityChangedHandler(object? sender, NetworkAvailabilityEventArgs e)
        {
            try
            {
                if (!e.IsAvailable) return;
                // Run in background to avoid blocking the network event thread
                Task.Run(() => TrySendFailedTransactionsAsync());
            }
            catch { }
        }

        // Attempt to send failed transactions; guarded to prevent concurrent runs.
        private async Task TrySendFailedTransactionsAsync()
        {
            // Ensure only one runner at a time. Use Interlocked to set running flag (int).
            if (Interlocked.Exchange(ref _isSendingFailedTransactionsRunning, 1) == 1)
                return; // already running

            try
            {
                try
                {
                    // Call the existing synchronous helper on a background thread
                    int sent = await Task.Run(() => OnlinefunctionsEvents.SendFailedTransactionToCloud()).ConfigureAwait(false);
                    try { System.Diagnostics.Trace.TraceInformation($"SendFailedTransactionToCloud: Sent {sent} receipts."); } catch { }
                }
                catch (Exception ex)
                {
                    try { System.Diagnostics.Trace.TraceError($"SendFailedTransactionToCloud attempt failed: {ex}"); } catch { }
                }
            }
            finally
            {
                Interlocked.Exchange(ref _isSendingFailedTransactionsRunning, 0);
            }
        }

