                    if (selected == null) return; // user cancelled

                    currentSalesPersonCode = selected.Value.Code;
                    currentSalesPersonName = selected.Value.DisplayName;

                    UpdateSalesPersonDisplay();

                    // Capture totals at the time salesperson was selected, so we only reset on subsequent changes.
                    _lastSalesPersonTotal = currentTotal;
                    _lastSalesPersonDiscount = currentDiscount;

                    // Best-effort persistence to the current TransactionHeader, if it already exists.
                    // NOTE: Some flows create TransactionHeader only at posting/checkout, so in-memory is the main source.
                    TryPersistSalesPersonToCurrentTransactionHeader();

                    MessageBox.Show(this,
                        $"Salesperson set to: {currentSalesPersonName}",
                        "SalesPerson",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Information);
                }
                catch (Exception ex)
