        public static bool TryPromptAquariumSetShipmentMaterials(string packageName, int setQuantity, out List<AquariumSetShipmentMaterial> materials, out string errorMessage)
        {
            materials = new List<AquariumSetShipmentMaterial>();
            errorMessage = string.Empty;

            var mainForm = Application.OpenForms.OfType<MainForm>().FirstOrDefault();
            if (mainForm == null)
            {
                errorMessage = "Main POS window is not available.";
                return false;
            }

            return mainForm.TryPromptAquariumSetShipmentMaterialsInternal(packageName, setQuantity, out materials, out errorMessage);
        }

        private bool TryPromptAquariumSetShipmentMaterialsInternal(string packageName, int setQuantity, out List<AquariumSetShipmentMaterial> materials, out string errorMessage)
        {
            materials = new List<AquariumSetShipmentMaterial>();
            errorMessage = string.Empty;

            if (string.IsNullOrWhiteSpace(packageName))
            {
                errorMessage = "Package name is required.";
                return false;
            }

            if (setQuantity <= 0)
            {
                errorMessage = "Set quantity must be greater than zero.";
                return false;
            }

            List<CompleteAquariumSetData.PackageLine> packageLines;
            try
            {
                packageLines = CompleteAquariumSetData.GetPackageLines(connectionString, packageName)
                    .Where(line => !string.IsNullOrWhiteSpace(line.ItemNo))
                    .ToList();
            }
            catch (Exception ex)
            {
                errorMessage = ex.Message;
                return false;
            }

            if (packageLines.Count == 0)
            {
                errorMessage = "No package lines were found for the selected aquarium set.";
                return false;
            }

            var selection = PromptForAquariumSetAccessorySelection(packageName, packageLines, setQuantity);
            if (selection == null)
            {
                errorMessage = "Selection was cancelled.";
                return false;
            }

            var linesToExplode = BuildAquariumSetExplodeLines(packageLines, selection, setQuantity);
            materials = linesToExplode
                .Select(line => new AquariumSetShipmentMaterial
                {
                    ItemCode = line.ItemCode,
                    ItemName = line.ItemName,
                    CategoryCode = line.CategoryCode,
                    VariationId = line.VariationId,
                    Description = line.Description,
                    Price = line.Price,
                    Quantity = line.Quantity
                })
                .ToList();

            return true;
        }

        /// <summary>
        /// Prompts the user to select an employee from dbo.EmployeeSetup.
        /// This is intentionally schema-tolerant: it tries common columns and falls back gracefully.
        /// </summary>
        private EmployeeChoice? PromptForSalesPerson()
        {
            var employees = LoadEmployeesForPicker();
            if (employees.Count == 0)
            {
                MessageBox.Show(this,
                    "No employees found in EmployeeSetup. Please add employees in Employee Setup first.",
                    "SalesPerson",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information);
                return null;
            }

            using (var dlg = new Form())
            {
                dlg.Text = "Select Salesperson";
                dlg.StartPosition = FormStartPosition.CenterParent;
                dlg.FormBorderStyle = FormBorderStyle.FixedDialog;
                dlg.MinimizeBox = false;
                dlg.MaximizeBox = false;
                dlg.ShowInTaskbar = false;
                dlg.Size = new Size(520, 520);

                var searchBox = new TextBox
                {
                    PlaceholderText = "Search...",
                    Dock = DockStyle.Top,
                    Font = new Font("Arial", 11, FontStyle.Regular),
                };

                var list = new ListBox
                {
                    Dock = DockStyle.Fill,
                    Font = new Font("Arial", 11, FontStyle.Regular),
                };

                var buttonsPanel = new Panel
                {
                    Dock = DockStyle.Bottom,
                    Height = 55,
                    Padding = new Padding(10),
                };

                var ok = new Button
                {
                    Text = "OK",
                    DialogResult = DialogResult.OK,
                    Width = 110,
                    Height = 32,
                    Anchor = AnchorStyles.Right | AnchorStyles.Top,
                };

                var cancel = new Button
                {
                    Text = "Cancel",
                    DialogResult = DialogResult.Cancel,
                    Width = 110,
                    Height = 32,
                    Anchor = AnchorStyles.Right | AnchorStyles.Top,
                };

                // Layout buttons right-aligned
                cancel.Location = new Point(buttonsPanel.Width - cancel.Width - 10, 10);
                ok.Location = new Point(cancel.Left - ok.Width - 10, 10);
                buttonsPanel.Resize += (s, e) =>
                {
                    cancel.Left = buttonsPanel.Width - cancel.Width - 10;
                    ok.Left = cancel.Left - ok.Width - 10;
                    ok.Top = cancel.Top = 10;
                };

                buttonsPanel.Controls.Add(ok);
                buttonsPanel.Controls.Add(cancel);

                dlg.AcceptButton = ok;
                dlg.CancelButton = cancel;

                dlg.Controls.Add(list);
                dlg.Controls.Add(buttonsPanel);
                dlg.Controls.Add(searchBox);

                void RefreshList(string? filter)
                {
                    list.BeginUpdate();
                    try
                    {
                        list.Items.Clear();
                        var q = string.IsNullOrWhiteSpace(filter)
                            ? employees
                            : employees.Where(e => e.DisplayName.IndexOf(filter, StringComparison.OrdinalIgnoreCase) >= 0
                                                || e.Code.IndexOf(filter, StringComparison.OrdinalIgnoreCase) >= 0)
                                       .ToList();

                        foreach (var emp in q)
                            list.Items.Add(emp);
                    }
                    finally
                    {
                        list.EndUpdate();
                    }
                }

                // Store EmployeeChoice directly in the ListBox so we can retrieve it without parsing strings.
                list.DisplayMember = nameof(EmployeeChoice.DisplayName);
                RefreshList(null);
                list.SelectedIndex = 0;

                searchBox.TextChanged += (s, e) => RefreshList(searchBox.Text);
                list.DoubleClick += (s, e) =>
                {
                    if (list.SelectedItem != null)
                        dlg.DialogResult = DialogResult.OK;
                };

                var result = dlg.ShowDialog(this);
                if (result != DialogResult.OK) return null;
                if (list.SelectedItem is EmployeeChoice choice) return choice;

                return null;
            }
        }

