                    Width = 100,
                    Location = new Point(70, 8)
                };

                quantityPanel.Controls.Add(quantityLabel);
                quantityPanel.Controls.Add(quantityUpDown);

                var list = new ListBox
                {
                    Dock = DockStyle.Fill,
                    Font = new Font("Arial", 11, FontStyle.Regular),
                    DisplayMember = nameof(CompleteAquariumSetData.PackageHeader.DisplayText)
                };

                var buttonsPanel = new Panel
                {
                    Dock = DockStyle.Bottom,
                    Height = 55,
                    Padding = new Padding(10),
                };

                var ok = new Button
                {
                    Text = "OK",
                    DialogResult = DialogResult.OK,
                    Width = 110,
                    Height = 32,
                    Anchor = AnchorStyles.Right | AnchorStyles.Top,
                };

                var cancel = new Button
                {
                    Text = "Cancel",
                    DialogResult = DialogResult.Cancel,
                    Width = 110,
                    Height = 32,
                    Anchor = AnchorStyles.Right | AnchorStyles.Top,
                };

                cancel.Location = new Point(buttonsPanel.Width - cancel.Width - 10, 10);
                ok.Location = new Point(cancel.Left - ok.Width - 10, 10);
                buttonsPanel.Resize += (s, e) =>
