                        MessageBoxIcon.Information);
                    return null;
                }

                return new AquariumSetSelection(package.PackageName, Decimal.ToInt32(quantityUpDown.Value));
            }
        }

        private void AddAquariumSetToSale(string packageName, int setQuantity)
        {
            if (string.IsNullOrWhiteSpace(packageName))
            {
                return;
            }

            var packageHeader = CompleteAquariumSetData.GetPackageHeaders(connectionString)
                .FirstOrDefault(header => string.Equals(header.PackageName, packageName, StringComparison.OrdinalIgnoreCase));
            var lines = CompleteAquariumSetData.GetPackageLines(connectionString, packageName)
                .Where(line => !string.IsNullOrWhiteSpace(line.ItemNo))
                .ToList();

            var invalidQuantities = lines
                .Select(line => new
                {
                    line.ItemNo,
                    TotalQuantity = line.Quantity * setQuantity
                })
                .Where(x => x.TotalQuantity <= 0m || decimal.Truncate(x.TotalQuantity) != x.TotalQuantity)
                .ToList();

            if (invalidQuantities.Count > 0)
            {
                var details = string.Join(Environment.NewLine, invalidQuantities.Select(x => $"- {x.ItemNo}: {x.TotalQuantity:N2}"));
                MessageBox.Show(this,
                    "This aquarium set cannot be exploded into the POS because one or more resulting quantities are not whole numbers.\n\n"
                    + details,
                    "Aquarium Set",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Warning);
                return;
            }

            var accessorySelection = PromptForAquariumSetAccessorySelection(packageName, lines, setQuantity);
            if (accessorySelection == null)
            {
                return;
            }

            var linesToExplode = BuildAquariumSetExplodeLines(lines, accessorySelection, setQuantity);
            decimal packageUnitPrice = packageHeader?.PackagePrice ?? 0m;

            AddToSale(packageName,
                setQuantity,
                packageUnitPrice,
                "AQUARIUM SET",
                null,
                packageHeader?.VariantID,
                packageName,
                true);

            foreach (var line in linesToExplode)
            {
                var displayName = string.IsNullOrWhiteSpace(line.ItemName) ? line.ItemCode : line.ItemName;
                AddToSale(displayName, line.Quantity, 0m, line.CategoryCode, line.ItemCode, line.VariationId, string.IsNullOrWhiteSpace(line.Description) ? displayName : line.Description, true);
                if (salesListView != null && salesListView.Items.Count > 0)
                {
                    salesListView.Items[salesListView.Items.Count - 1].Name = AquariumSetComponentLineMarker;
                }
            }

            MessageBox.Show(this,
                $"Exploded {setQuantity} x '{packageName}' into {linesToExplode.Count + 1} POS line(s).",
                "Aquarium Set",
                MessageBoxButtons.OK,
                MessageBoxIcon.Information);
        }

        private AquariumAccessorySelectionResult? PromptForAquariumSetAccessorySelection(string packageName, List<CompleteAquariumSetData.PackageLine> packageLines, int setQuantity)
        {
            using (var dialog = new Form())
            {
                dialog.Text = $"{packageName} Accessories";
                dialog.StartPosition = FormStartPosition.CenterParent;
                dialog.FormBorderStyle = FormBorderStyle.FixedDialog;
                dialog.MinimizeBox = false;
                dialog.MaximizeBox = false;
                dialog.ShowInTaskbar = false;
                dialog.ClientSize = new Size(860, 760);

                var contentPanel = new Panel
                {
                    Dock = DockStyle.Fill,
                    AutoScroll = true,
                    Padding = new Padding(0, 0, 0, 10)
                };

                var instructionsLabel = new Label
                {
                    Text = "Review included products and choose variants or accessories for this complete setup.",
                    Left = 24,
                    Top = 18,
                    Width = 560,
                    Height = 24,
                    Font = new Font("Arial", 11, FontStyle.Bold)
                };

                AquariumAccessoryChoice? selectedLight = null;
                AquariumAccessoryChoice? selectedOptionalSump = null;
                AquariumAccessoryChoice? selectedOptionalStand = null;
                AquariumAccessoryChoice? selectedMeshBag = null;
                AquariumAccessoryChoice? selectedPump = null;
                AquariumAccessoryChoice? selectedPipe = null;
                NumericUpDown? optionalSumpQtyUpDown = null;
                NumericUpDown? optionalStandQtyUpDown = null;
                var selectedMedias = new AquariumAccessoryChoice?[5];
                var mediaQtyUpDowns = new NumericUpDown[5];
                var itemCategories = LoadAquariumSetItemCategories(packageLines.Select(line => line.ItemNo?.Trim() ?? string.Empty)
                    .Where(code => !string.IsNullOrWhiteSpace(code))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList());
                var accessoryItemCodes = GetAquariumSetAccessoryItemCodes(packageLines);
                var variantSelectionStates = BuildAquariumVariantSelectionStates(packageLines, itemCategories, accessoryItemCodes, setQuantity);

                var lightDefaults = BuildAccessoryDefaultState(packageLines, setQuantity, "LIGHT", "LIGHTS", "LIGHT");
