                void CreateVariantSelectionRow(AquariumVariantSelectionState? variantState, ref int y)
                {
                    if (variantState?.SourceLine == null)
                    {
                        return;
                    }

                    CreateLabel(variantState.FieldLabel, y);
                    var textBox = CreateReadOnlyPickerTextBox(y);
                    var quantityUpDown = CreateQuantityUpDown(y);
                    quantityUpDown.Value = Math.Max(quantityUpDown.Minimum, Math.Min(quantityUpDown.Maximum, variantState.Quantity));
                    textBox.Text = variantState.SelectedVariant != null
                        ? BuildAquariumVariantPickerText(variantState.SelectedVariant)
                        : (string.IsNullOrWhiteSpace(variantState.SourceLine.ItemName) ? variantState.SourceLine.ItemNo : variantState.SourceLine.ItemName);

                    var selectButton = CreatePickerButton(y, () =>
                    {
                        var choice = PromptForAquariumSetVariantSelection(variantState, dialog);
                        if (choice == SaleVariantSelection.Cancelled || choice == null)
                        {
                            return;
                        }

                        variantState.SelectedVariant = choice;
                        textBox.Text = BuildAquariumVariantPickerText(choice);
                    });

                    if (!variantState.HasVariantOptions)
                    {
                        selectButton.Enabled = false;
                        selectButton.BackColor = Color.Gray;
                    }

                    y += standardRowSpacing;
                }

                foreach (var variantState in variantSelectionStates)
                {
                    CreateVariantSelectionRow(variantState, ref top);
                }

                bool hasSumpRow = variantSelectionStates.Any(state => string.Equals(state.FieldLabel, "Sump", StringComparison.OrdinalIgnoreCase));
                bool hasStandRow = variantSelectionStates.Any(state => string.Equals(state.FieldLabel, "Stand", StringComparison.OrdinalIgnoreCase));

                if (!hasSumpRow)
                {
                    CreateLabel("Sump", top);
                    var sumpTextBox = CreateReadOnlyPickerTextBox(top);
                    optionalSumpQtyUpDown = CreateQuantityUpDown(top);
                    CreatePickerButton(top, () =>
