                var pumpQtyUpDown = CreateQuantityUpDown(top);
                ApplyAccessoryDefault(pumpDefaults, ref selectedPump, pumpTextBox, pumpQtyUpDown);
                CreatePickerButton(top, () =>
                {
                    var choice = PromptForAquariumAccessoryItemSelection("Pump", "PUMP", "PUMP", "PUMPS");
                    if (choice == null)
                    {
                        return;
                    }

                    selectedPump = choice;
                    pumpTextBox.Text = choice.DisplayText;
                });
                top += standardRowSpacing;

                CreateLabel("Pipe", top);
                var pipeTextBox = CreateReadOnlyPickerTextBox(top);
                var pipeQtyUpDown = CreateQuantityUpDown(top);
                ApplyAccessoryDefault(pipeDefaults, ref selectedPipe, pipeTextBox, pipeQtyUpDown);
                CreatePickerButton(top, () =>
                {
                    var choice = PromptForAquariumAccessoryItemSelection("Pipe", "PIPE", "PIPE", "PIPES", "PVC");
                    if (choice == null)
                    {
                        return;
                    }

                    selectedPipe = choice;
                    pipeTextBox.Text = choice.DisplayText;
                });

                var footerPanel = new Panel
                {
                    Dock = DockStyle.Bottom,
                    Height = 58,
                    Padding = new Padding(20, 8, 20, 8)
                };

                var okButton = new Button
                {
                    Text = "OK",
                    Width = 110,
                    Height = 32,
                    Top = 8,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };

                var cancelButton = new Button
                {
                    Text = "Cancel",
                    DialogResult = DialogResult.Cancel,
                    Width = 110,
                    Height = 32,
                    Top = 8,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };

                void CenterFooterButtons()
                {
                    const int gap = 14;
                    int totalWidth = okButton.Width + gap + cancelButton.Width;
                    int startLeft = Math.Max(20, (footerPanel.ClientSize.Width - totalWidth) / 2);
                    okButton.Left = startLeft;
                    cancelButton.Left = okButton.Right + gap;
                }

                footerPanel.Resize += (s, e) => CenterFooterButtons();
                CenterFooterButtons();

                footerPanel.Controls.Add(okButton);
                footerPanel.Controls.Add(cancelButton);

                dialog.AcceptButton = okButton;
                dialog.CancelButton = cancelButton;
                contentPanel.Controls.Add(instructionsLabel);
                contentPanel.AutoScrollMinSize = new Size(0, top + 120);
                dialog.Controls.Add(contentPanel);
                dialog.Controls.Add(footerPanel);

                AquariumAccessorySelectionResult? selectionResult = null;
                okButton.Click += (s, e) =>
                {
                    var pendingVariantSelection = variantSelectionStates.FirstOrDefault(state =>
                        state.RequiresExplicitVariantChoice && string.IsNullOrWhiteSpace(state.SelectedVariant?.VariationId));
                    if (pendingVariantSelection != null)
                    {
                        MessageBox.Show(dialog,
                            $"Please select the variant for {pendingVariantSelection.FieldLabel}.",
                            "Aquarium Set",
                            MessageBoxButtons.OK,
                            MessageBoxIcon.Information);
                        return;
                    }

                    if (selectedLight == null)
                    {
                        MessageBox.Show(dialog, "Please select the Lights item.", "Aquarium Set", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    if (!hasSumpRow && selectedOptionalSump == null)
                    {
                        MessageBox.Show(dialog, "Please select the Sump item.", "Aquarium Set", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    if (!hasStandRow && selectedOptionalStand == null)
                    {
                        MessageBox.Show(dialog, "Please select the Stand item.", "Aquarium Set", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    if (selectedPump == null)
                    {
                        MessageBox.Show(dialog, "Please select the Pump item.", "Aquarium Set", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    if (selectedPipe == null)
                    {
                        MessageBox.Show(dialog, "Please select the Pipe item.", "Aquarium Set", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    selectionResult = new AquariumAccessorySelectionResult();
                    foreach (var accessoryItemCode in GetAquariumSetAccessoryItemCodes(packageLines))
                    {
                        selectionResult.ExcludedItemCodes.Add(accessoryItemCode);
                    }

                    void AddSelectedExplodeLine(string excludedItemCode, string itemCode, string itemName, decimal price, decimal quantity, string categoryCode = "", string variationId = "", string description = "")
                    {
                        if (decimal.Truncate(quantity) != quantity || quantity <= 0m)
                        {
                            return;
                        }

                        if (!string.IsNullOrWhiteSpace(excludedItemCode))
                        {
                            selectionResult.ExcludedItemCodes.Add(excludedItemCode);
                        }

                        selectionResult.SelectedLines.Add(new AquariumSetExplodeLine
                        {
                            ItemCode = itemCode,
                            ItemName = itemName,
                            CategoryCode = categoryCode,
                            VariationId = variationId,
                            Description = string.IsNullOrWhiteSpace(description) ? itemName : description,
                            Price = price,
                            Quantity = Decimal.ToInt32(quantity)
                        });
                    }

                    void AddSelectedAccessoryLine(AquariumAccessoryChoice choice, decimal quantity)
                    {
                        AddSelectedExplodeLine(choice.ItemCode, choice.ItemCode, choice.ItemName, choice.Price, quantity, choice.CategoryCode, string.Empty, choice.ItemName);
                    }

                    void AddSelectedVariantLine(AquariumVariantSelectionState? variantState)
                    {
                        if (variantState?.SourceLine == null || variantState.SelectedVariant == null)
                        {
                            return;
                        }

                        AddSelectedExplodeLine(
                            variantState.SourceLine.ItemNo,
                            string.IsNullOrWhiteSpace(variantState.SelectedVariant.ItemCode) ? variantState.SourceLine.ItemNo : variantState.SelectedVariant.ItemCode,
                            string.IsNullOrWhiteSpace(variantState.SelectedVariant.DisplayText) ? (variantState.SourceLine.ItemName ?? variantState.SourceLine.ItemNo) : variantState.SelectedVariant.DisplayText,
                            variantState.SelectedVariant.Price > 0m ? variantState.SelectedVariant.Price : variantState.SourceLine.Price,
                            variantState.Quantity,
                            variantState.SelectedVariant.CategoryCode,
                            variantState.SelectedVariant.VariationId,
                            string.IsNullOrWhiteSpace(variantState.SelectedVariant.Description) ? variantState.SelectedVariant.DisplayText : variantState.SelectedVariant.Description);
                    }

                    foreach (var variantState in variantSelectionStates)
                    {
                        AddSelectedVariantLine(variantState);
                    }
                    if (selectedOptionalSump != null)
                    {
                        AddSelectedAccessoryLine(selectedOptionalSump, optionalSumpQtyUpDown?.Value ?? 1m);
                    }
                    if (selectedOptionalStand != null)
                    {
                        AddSelectedAccessoryLine(selectedOptionalStand, optionalStandQtyUpDown?.Value ?? 1m);
                    }
                    AddSelectedAccessoryLine(selectedLight, lightsQtyUpDown.Value);
                    if (selectedMeshBag != null)
                    {
                        AddSelectedAccessoryLine(selectedMeshBag, meshBagQtyUpDown.Value);
                    }
                    AddSelectedAccessoryLine(selectedPump, pumpQtyUpDown.Value);
                    AddSelectedAccessoryLine(selectedPipe, pipeQtyUpDown.Value);

                    for (int mediaIndex = 0; mediaIndex < selectedMedias.Length; mediaIndex++)
                    {
                        var selectedMedia = selectedMedias[mediaIndex];
                        if (selectedMedia == null)
                        {
                            continue;
                        }

                        AddSelectedAccessoryLine(selectedMedia, mediaQtyUpDowns[mediaIndex].Value);
                    }

                    var confirmSelection = MessageBox.Show(dialog,
                        "Are you sure this is the correct materials for this set? Please confirm",
                        "Confirm Materials",
                        MessageBoxButtons.YesNo,
                        MessageBoxIcon.Question,
                        MessageBoxDefaultButton.Button2);
                    if (confirmSelection != DialogResult.Yes)
                    {
                        selectionResult = null;
                        return;
                    }

                    dialog.DialogResult = DialogResult.OK;
                    dialog.Close();
                };

                var result = dialog.ShowDialog(this);
                if (result != DialogResult.OK)
                {
                    return null;
                }

                return selectionResult ?? new AquariumAccessorySelectionResult();
            }
        }

        private List<AquariumSetExplodeLine> BuildAquariumSetExplodeLines(List<CompleteAquariumSetData.PackageLine> packageLines, AquariumAccessorySelectionResult accessorySelection, int setQuantity)
        {
            var linesToExplode = new List<AquariumSetExplodeLine>();
            var excludedItemCodes = accessorySelection.ExcludedItemCodes;

            foreach (var packageLine in packageLines)
            {
                string itemCode = packageLine.ItemNo?.Trim() ?? string.Empty;
                if (string.IsNullOrWhiteSpace(itemCode) || excludedItemCodes.Contains(itemCode))
                {
                    continue;
                }

                linesToExplode.Add(new AquariumSetExplodeLine
                {
                    ItemCode = itemCode,
                    ItemName = string.IsNullOrWhiteSpace(packageLine.ItemName) ? itemCode : packageLine.ItemName,
                    Description = string.IsNullOrWhiteSpace(packageLine.ItemName) ? itemCode : packageLine.ItemName,
                    Price = packageLine.Price,
                    Quantity = Decimal.ToInt32(packageLine.Quantity * setQuantity)
                });
            }

            linesToExplode.AddRange(accessorySelection.SelectedLines);
            return linesToExplode;
        }

        private List<AquariumVariantSelectionState> BuildAquariumVariantSelectionStates(List<CompleteAquariumSetData.PackageLine> packageLines, Dictionary<string, string> itemCategories, HashSet<string> accessoryItemCodes, int setQuantity)
        {
            var states = new List<AquariumVariantSelectionState>();

            foreach (var packageLine in packageLines)
            {
                string itemCode = packageLine.ItemNo?.Trim() ?? string.Empty;
                if (string.IsNullOrWhiteSpace(itemCode) || accessoryItemCodes.Contains(itemCode))
                {
                    continue;
                }

                var state = BuildAquariumVariantSelectionState(packageLine, itemCategories, setQuantity);
                if (state != null)
                {
                    states.Add(state);
                }
            }

            return states;
        }

        private AquariumVariantSelectionState? BuildAquariumVariantSelectionState(CompleteAquariumSetData.PackageLine sourceLine, Dictionary<string, string> itemCategories, int setQuantity)
        {
            decimal totalQuantity = sourceLine.Quantity * setQuantity;
            if (totalQuantity <= 0m || decimal.Truncate(totalQuantity) != totalQuantity)
            {
                return null;
            }

            string itemCode = sourceLine.ItemNo?.Trim() ?? string.Empty;
            string itemName = string.IsNullOrWhiteSpace(sourceLine.ItemName) ? itemCode : sourceLine.ItemName;
            string mainItemCode = ResolveAquariumVariantMainItemCode(itemCode, itemName);
            var variants = LoadSaleVariants(mainItemCode, sourceLine.Price);
            var matchedVariant = FindDefaultAquariumVariantSelection(variants, itemCode, itemName);
            var fallbackCategoryCode = itemCategories.TryGetValue(itemCode, out var existingCategoryCode) ? existingCategoryCode : string.Empty;

            return new AquariumVariantSelectionState
            {
                FieldLabel = BuildAquariumVariantFieldLabel(sourceLine),
                SourceLine = sourceLine,
                Quantity = Decimal.ToInt32(totalQuantity),
                HasVariantOptions = variants.Count > 0,
                RequiresExplicitVariantChoice = variants.Count > 0 && matchedVariant == null,
                SelectedVariant = variants.Count > 0
                    ? matchedVariant
                    : new SaleVariantSelection
                {
                    ItemCode = itemCode,
                    DisplayText = itemName,
                    Description = itemName,
                    CategoryCode = fallbackCategoryCode,
                    Price = sourceLine.Price
                }
            };
        }

        private string BuildAquariumVariantFieldLabel(CompleteAquariumSetData.PackageLine sourceLine)
        {
            string itemCode = sourceLine.ItemNo?.Trim() ?? string.Empty;
            string itemName = sourceLine.ItemName?.Trim() ?? string.Empty;
            string combined = $"{itemCode} {itemName}".ToUpperInvariant();

            if (IsSumpVariantCode(itemCode) || ContainsAquariumLookupWord(combined, "SUMP"))
            {
                return "Sump";
            }

            if (IsAquariumVariantCode(itemCode)
                || ContainsAquariumLookupWord(combined, "AQUARIUM")
                || ContainsAquariumLookupWord(combined, "TANK")
                || ContainsAquariumLookupWord(combined, "OVERHEAD")
                || ContainsAquariumLookupWord(combined, "RIMLESS")
                || combined.StartsWith("AQ-", StringComparison.OrdinalIgnoreCase)
                || combined.Contains(" GLASS", StringComparison.OrdinalIgnoreCase)
                || combined.Contains("MM GLASS", StringComparison.OrdinalIgnoreCase))
            {
                return "Aquarium";
            }

            if (IsStandVariantCode(itemCode)
                || ContainsAquariumLookupWord(combined, "STAND")
                || ContainsAquariumLookupWord(combined, "CABINET"))
            {
                return "Stand";
            }

            return string.IsNullOrWhiteSpace(itemCode) ? itemName : itemCode;
        }

        private bool IsAquariumVariantCode(string itemCode)
        {
            string normalizedItemCode = itemCode?.Trim() ?? string.Empty;
            return normalizedItemCode.StartsWith("AQ-", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("CUSTOM-AQUARIUM", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("CUSTOM_AQUARIUM", StringComparison.OrdinalIgnoreCase);
        }

        private bool IsSumpVariantCode(string itemCode)
        {
            string normalizedItemCode = itemCode?.Trim() ?? string.Empty;
            return normalizedItemCode.StartsWith("S-", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("SUMP-", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("CUSTOM-SUMP", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("CUSTOM_SUMP", StringComparison.OrdinalIgnoreCase);
        }

        private bool IsStandVariantCode(string itemCode)
        {
            string normalizedItemCode = itemCode?.Trim() ?? string.Empty;
            return normalizedItemCode.StartsWith("AST-", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("STAND-", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("CABINET-", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("CUSTOM-STAND", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("CUSTOM_STAND", StringComparison.OrdinalIgnoreCase);
        }

        private bool ContainsAquariumLookupWord(string value, string word)
        {
            if (string.IsNullOrWhiteSpace(value) || string.IsNullOrWhiteSpace(word))
            {
                return false;
            }

            return System.Text.RegularExpressions.Regex.IsMatch(
                value,
                $@"(?<![A-Z0-9]){System.Text.RegularExpressions.Regex.Escape(word)}(?![A-Z0-9])",
                System.Text.RegularExpressions.RegexOptions.IgnoreCase | System.Text.RegularExpressions.RegexOptions.CultureInvariant);
        }

        private string NormalizeAquariumVariantLookupText(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return string.Empty;
            }

            string uppercase = value.ToUpperInvariant();
            uppercase = System.Text.RegularExpressions.Regex.Replace(uppercase, @"[^A-Z0-9]+", " ");
            uppercase = System.Text.RegularExpressions.Regex.Replace(uppercase, @"\s+", " ").Trim();
            return uppercase;
        }

        private List<string> BuildAquariumVariantLookupTokens(string itemCode, string itemName)
        {
            var tokens = new List<string>();
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string combined = NormalizeAquariumVariantLookupText($"{itemCode} {itemName}");
            if (string.IsNullOrWhiteSpace(combined))
            {
                return tokens;
            }

            foreach (System.Text.RegularExpressions.Match match in System.Text.RegularExpressions.Regex.Matches(combined, @"[A-Z0-9]+"))
            {
                string token = match.Value.Trim();
                if (token.Length < 2)
                {
                    continue;
                }

                if (token.Equals("AQ", StringComparison.OrdinalIgnoreCase)
                    || token.Equals("ST", StringComparison.OrdinalIgnoreCase)
                    || token.Equals("IN", StringComparison.OrdinalIgnoreCase)
                    || token.Equals("MM", StringComparison.OrdinalIgnoreCase)
                    || token.Equals("GLASS", StringComparison.OrdinalIgnoreCase)
                    || token.Equals("STANDARD", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (token.All(char.IsDigit) && token.Length < 2)
                {
                    continue;
                }

                if (seen.Add(token))
                {
                    tokens.Add(token);
                }
            }

            return tokens;
        }

        private int ScoreAquariumVariantMainItemCandidate(string candidateCode, string candidateName, string sourceItemCode, string sourceItemName, IReadOnlyCollection<string> lookupTokens)
        {
            int score = 0;
            string normalizedSource = NormalizeAquariumVariantLookupText($"{sourceItemCode} {sourceItemName}");
            string normalizedCandidate = NormalizeAquariumVariantLookupText($"{candidateCode} {candidateName}");

            if (string.IsNullOrWhiteSpace(normalizedCandidate))
            {
                return score;
            }

            if (!string.IsNullOrWhiteSpace(sourceItemCode) && string.Equals(candidateCode, sourceItemCode, StringComparison.OrdinalIgnoreCase))
            {
                score += 500;
            }

            if (!string.IsNullOrWhiteSpace(sourceItemName) && string.Equals(candidateName, sourceItemName, StringComparison.OrdinalIgnoreCase))
            {
                score += 300;
            }

            if (!string.IsNullOrWhiteSpace(normalizedSource))
            {
                if (normalizedCandidate.Contains(normalizedSource, StringComparison.OrdinalIgnoreCase))
                {
                    score += 200;
                }
                else if (normalizedSource.Contains(normalizedCandidate, StringComparison.OrdinalIgnoreCase))
                {
                    score += 80;
                }
            }

            foreach (var token in lookupTokens)
            {
                if (normalizedCandidate.Contains(token, StringComparison.OrdinalIgnoreCase))
                {
                    score += token.All(char.IsDigit) ? 20 : 35;
                }
            }

            if (candidateCode.StartsWith("AQ-", StringComparison.OrdinalIgnoreCase))
            {
                score += 15;
            }

            return score;
        }

        private SaleVariantSelection? FindDefaultAquariumVariantSelection(List<SaleVariantSelection> variants, string sourceItemCode, string sourceItemName)
        {
            if (variants == null || variants.Count == 0)
            {
                return null;
            }

            string normalizedItemCode = (sourceItemCode ?? string.Empty).Trim();
            string normalizedItemName = (sourceItemName ?? string.Empty).Trim();

            var exactCodeMatch = variants.FirstOrDefault(variant =>
                string.Equals(variant.ItemCode, normalizedItemCode, StringComparison.OrdinalIgnoreCase));
            if (exactCodeMatch != null)
            {
                return exactCodeMatch;
            }

            if (!string.IsNullOrWhiteSpace(normalizedItemName))
            {
                var exactNameMatch = variants.FirstOrDefault(variant =>
                    string.Equals(variant.DisplayText, normalizedItemName, StringComparison.OrdinalIgnoreCase)
                    || string.Equals(variant.VariantName, normalizedItemName, StringComparison.OrdinalIgnoreCase)
                    || string.Equals(variant.Description, normalizedItemName, StringComparison.OrdinalIgnoreCase));
                if (exactNameMatch != null)
                {
                    return exactNameMatch;
                }

                var containsNameMatch = variants.FirstOrDefault(variant =>
                    (!string.IsNullOrWhiteSpace(variant.DisplayText) &&
                     (variant.DisplayText.IndexOf(normalizedItemName, StringComparison.OrdinalIgnoreCase) >= 0
                      || normalizedItemName.IndexOf(variant.DisplayText, StringComparison.OrdinalIgnoreCase) >= 0))
                    || (!string.IsNullOrWhiteSpace(variant.VariantName) &&
                        (variant.VariantName.IndexOf(normalizedItemName, StringComparison.OrdinalIgnoreCase) >= 0
                         || normalizedItemName.IndexOf(variant.VariantName, StringComparison.OrdinalIgnoreCase) >= 0))
                    || (!string.IsNullOrWhiteSpace(variant.Description) &&
                        (variant.Description.IndexOf(normalizedItemName, StringComparison.OrdinalIgnoreCase) >= 0
                         || normalizedItemName.IndexOf(variant.Description, StringComparison.OrdinalIgnoreCase) >= 0)));
                if (containsNameMatch != null)
                {
                    return containsNameMatch;
                }
            }

            if (variants.Count == 1)
            {
                return variants[0];
            }

            return null;
        }

        private string ResolveAquariumVariantMainItemCode(string itemCode, string itemName)
        {
            if (string.IsNullOrWhiteSpace(itemCode))
            {
                return string.Empty;
            }

            using var connection = new SqlConnection(connectionString);
            connection.Open();

            bool hasVariantTable;
            using (var existsCommand = new SqlCommand("SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Variant'", connection))
            {
                hasVariantTable = Convert.ToInt32(existsCommand.ExecuteScalar()) > 0;
            }

            if (!hasVariantTable)
            {
                return itemCode;
            }

            using var command = new SqlCommand(@"
SELECT TOP 1 ISNULL(NULLIF(MainItemCode, ''), @ItemCode)
FROM dbo.[Variant]
WHERE MainItemCode = @ItemCode OR ItemCode = @ItemCode
ORDER BY CASE WHEN MainItemCode = @ItemCode THEN 0 ELSE 1 END, VariationId", connection);
            command.Parameters.AddWithValue("@ItemCode", itemCode);

            var result = command.ExecuteScalar()?.ToString()?.Trim();
            if (!string.IsNullOrWhiteSpace(result))
            {
                return result;
            }

            var lookupTokens = BuildAquariumVariantLookupTokens(itemCode, itemName);
            if (lookupTokens.Count == 0 && string.IsNullOrWhiteSpace(itemName))
            {
                return itemCode;
            }

            using var fallbackCommand = new SqlCommand(@"
SELECT DISTINCT
    v.MainItemCode,
    ISNULL(NULLIF(mainItem.Name, ''), ISNULL(NULLIF(mainItem.Description, ''), v.MainItemCode)) AS MainItemName
FROM dbo.[Variant] v
LEFT JOIN dbo.Items mainItem ON mainItem.Code = v.MainItemCode
WHERE ISNULL(NULLIF(v.MainItemCode, ''), '') <> ''", connection);

            using var reader = fallbackCommand.ExecuteReader();
            string bestMainItemCode = itemCode;
            int bestScore = 0;

            while (reader.Read())
            {
                string candidateCode = reader["MainItemCode"]?.ToString()?.Trim() ?? string.Empty;
                if (string.IsNullOrWhiteSpace(candidateCode))
                {
                    continue;
                }

                string candidateName = reader["MainItemName"]?.ToString()?.Trim() ?? string.Empty;
                int candidateScore = ScoreAquariumVariantMainItemCandidate(candidateCode, candidateName, itemCode, itemName, lookupTokens);
                if (candidateScore > bestScore)
                {
                    bestScore = candidateScore;
                    bestMainItemCode = candidateCode;
                }
            }

            return bestScore >= 70 ? bestMainItemCode : itemCode;
        }

        private SaleVariantSelection? PromptForAquariumSetVariantSelection(AquariumVariantSelectionState variantState, IWin32Window owner)
        {
            if (variantState.SourceLine == null)
            {
                return null;
            }

            string sourceItemCode = variantState.SourceLine.ItemNo?.Trim() ?? string.Empty;
            string sourceItemName = string.IsNullOrWhiteSpace(variantState.SourceLine.ItemName) ? sourceItemCode : variantState.SourceLine.ItemName;
            string mainItemCode = ResolveAquariumVariantMainItemCode(sourceItemCode, sourceItemName);
            return PromptForSaleVariantSelection(mainItemCode, sourceItemName, variantState.SourceLine.Price, owner);
        }

        private HashSet<string> GetAquariumSetAccessoryItemCodes(List<CompleteAquariumSetData.PackageLine> packageLines)
        {
            var itemCodes = packageLines
                .Select(line => line.ItemNo?.Trim() ?? string.Empty)
                .Where(code => !string.IsNullOrWhiteSpace(code))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            var accessoryItemCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (itemCodes.Count == 0)
            {
                return accessoryItemCodes;
            }

            var itemCategories = LoadAquariumSetItemCategories(itemCodes);
            var accessoryChoices = LoadAllAquariumAccessoryItemChoices();

            foreach (var packageLine in packageLines)
            {
                string itemCode = packageLine.ItemNo?.Trim() ?? string.Empty;
                if (string.IsNullOrWhiteSpace(itemCode))
                {
                    continue;
                }

                if (itemCategories.TryGetValue(itemCode, out var categoryCode) && IsAquariumAccessoryCategory(categoryCode))
                {
                    accessoryItemCodes.Add(itemCode);
                    continue;
                }

                if (MatchAccessoryChoice(accessoryChoices, packageLine) != null)
                {
                    accessoryItemCodes.Add(itemCode);
                }
            }

            return accessoryItemCodes;
        }

        private Dictionary<string, string> LoadAquariumSetItemCategories(List<string> itemCodes)
        {
            var categories = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (itemCodes.Count == 0)
            {
                return categories;
            }

            using var connection = new SqlConnection(connectionString);
            connection.Open();

            using var command = new SqlCommand();
            command.Connection = connection;

            var parameters = new List<string>();
            for (int index = 0; index < itemCodes.Count; index++)
            {
                string parameterName = $"@ItemCode{index}";
                parameters.Add(parameterName);
                command.Parameters.AddWithValue(parameterName, itemCodes[index]);
            }

            command.CommandText = $@"
SELECT Code, ISNULL(CategoryCode, '') AS CategoryCode
FROM dbo.Items
WHERE Code IN ({string.Join(", ", parameters)})";

            using var reader = command.ExecuteReader();
            while (reader.Read())
            {
                string code = reader["Code"]?.ToString()?.Trim() ?? string.Empty;
                if (string.IsNullOrWhiteSpace(code))
                {
                    continue;
                }

                categories[code] = reader["CategoryCode"]?.ToString()?.Trim() ?? string.Empty;
            }

            return categories;
        }

        private List<AquariumAccessoryChoice> LoadAllAquariumAccessoryItemChoices()
        {
            return LoadAquariumAccessoryItemChoices("LIGHT", "LIGHTS", "LIGHT")
                .Concat(LoadAquariumAccessoryItemChoices("MEDIA", "MEDIA", "MEDIAS", "FILTERMEDIA", "FILTER MEDIA", "FILTERMEDIAS", "FILTER MEDIAS"))
                .Concat(LoadAquariumAccessoryItemChoices("MESH", "MESH BAG", "MESHBAG", "BAG"))
                .Concat(LoadAquariumAccessoryItemChoices("PUMP", "PUMP", "PUMPS"))
                .Concat(LoadAquariumAccessoryItemChoices("PIPE", "PIPE", "PIPES", "PVC"))
                .GroupBy(choice => choice.ItemCode, StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .ToList();
        }

        private bool IsAquariumAccessoryCategory(string categoryCode)
        {
            if (string.IsNullOrWhiteSpace(categoryCode))
            {
                return false;
            }

            string normalized = categoryCode.Trim();
            return string.Equals(normalized, "LIGHT", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "LIGHTS", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "MEDIA", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "MEDIAS", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "FILTERMEDIA", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "FILTER MEDIA", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "FILTERMEDIAS", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "FILTER MEDIAS", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "MESH", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "MESH BAG", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "MESHBAG", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "BAG", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "PUMP", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "PUMPS", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "PIPE", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "PIPES", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalized, "PVC", StringComparison.OrdinalIgnoreCase);
        }

        private void ApplyAccessoryDefault(AquariumAccessorySelectionState? defaults, ref AquariumAccessoryChoice? selectedChoice, TextBox displayTextBox, NumericUpDown quantityUpDown)
        {
            if (defaults?.Choice == null)
            {
                return;
            }

            selectedChoice = defaults.Choice;
            displayTextBox.Text = defaults.Choice.DisplayText;
            decimal boundedQuantity = Math.Max(quantityUpDown.Minimum, Math.Min(quantityUpDown.Maximum, defaults.Quantity));
            quantityUpDown.Value = boundedQuantity;
        }

        private AquariumAccessorySelectionState? BuildAccessoryDefaultState(List<CompleteAquariumSetData.PackageLine> packageLines, int setQuantity, string keyword, params string[] categoryCodes)
        {
            return BuildAccessoryDefaultStates(packageLines, setQuantity, 1, keyword, categoryCodes).FirstOrDefault();
        }

        private List<AquariumAccessorySelectionState> BuildAccessoryDefaultStates(List<CompleteAquariumSetData.PackageLine> packageLines, int setQuantity, int maxItems, string keyword, params string[] categoryCodes)
        {
            var defaults = new List<AquariumAccessorySelectionState>();
            if (packageLines == null || packageLines.Count == 0 || maxItems <= 0)
            {
                return defaults;
            }

            var availableChoices = LoadAquariumAccessoryItemChoices(keyword, categoryCodes);
            if (availableChoices.Count == 0)
            {
                return defaults;
            }

            foreach (var line in packageLines)
            {
                if (defaults.Count >= maxItems)
                {
                    break;
                }

                var matchedChoice = MatchAccessoryChoice(availableChoices, line);
                if (matchedChoice == null)
                {
                    continue;
                }

                if (defaults.Any(existing => string.Equals(existing.Choice?.ItemCode, matchedChoice.ItemCode, StringComparison.OrdinalIgnoreCase)))
                {
                    continue;
                }

                decimal totalQuantity = line.Quantity * setQuantity;
                if (totalQuantity <= 0m || decimal.Truncate(totalQuantity) != totalQuantity)
                {
                    continue;
                }

                defaults.Add(new AquariumAccessorySelectionState
                {
                    Choice = matchedChoice,
                    Quantity = Decimal.ToInt32(totalQuantity)
                });
            }

            return defaults;
        }

        private AquariumAccessoryChoice? MatchAccessoryChoice(List<AquariumAccessoryChoice> availableChoices, CompleteAquariumSetData.PackageLine line)
        {
            string itemNo = line.ItemNo?.Trim() ?? string.Empty;
            string itemName = line.ItemName?.Trim() ?? string.Empty;

            if (!string.IsNullOrWhiteSpace(itemNo))
            {
                var byCode = availableChoices.FirstOrDefault(choice => string.Equals(choice.ItemCode, itemNo, StringComparison.OrdinalIgnoreCase));
                if (byCode != null)
                {
                    return byCode;
                }
            }

            if (!string.IsNullOrWhiteSpace(itemName))
            {
                var byName = availableChoices.FirstOrDefault(choice => string.Equals(choice.ItemName, itemName, StringComparison.OrdinalIgnoreCase));
                if (byName != null)
                {
                    return byName;
                }

                return availableChoices.FirstOrDefault(choice =>
                    choice.ItemName.IndexOf(itemName, StringComparison.OrdinalIgnoreCase) >= 0
                    || itemName.IndexOf(choice.ItemName, StringComparison.OrdinalIgnoreCase) >= 0);
            }

            return null;
        }

        private AquariumAccessoryChoice? PromptForAquariumAccessoryItemSelection(string fieldLabel, string keyword, params string[] categoryCodes)
        {
            var items = LoadAquariumAccessoryItemChoices(keyword, categoryCodes);
            if (items.Count == 0)
            {
                MessageBox.Show(this,
                    $"No active items were found for {fieldLabel}. Please set them up in Items first.",
                    "Aquarium Set",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information);
                return null;
            }

            using (var dlg = new Form())
            {
                dlg.Text = $"Select {fieldLabel}";
                dlg.StartPosition = FormStartPosition.CenterParent;
                dlg.FormBorderStyle = FormBorderStyle.FixedDialog;
                dlg.MinimizeBox = false;
                dlg.MaximizeBox = false;
                dlg.ShowInTaskbar = false;
                dlg.Size = new Size(860, 560);

                var searchBox = new TextBox
                {
                    PlaceholderText = $"Search {fieldLabel}...",
                    Dock = DockStyle.Top,
                    Font = new Font("Arial", 11, FontStyle.Regular),
                };

                var previewPanel = new GroupBox
                {
                    Text = "Product Image",
                    Dock = DockStyle.Right,
                    Width = 260,
                    Padding = new Padding(10),
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };

                var previewPictureBox = new PictureBox
                {
                    Dock = DockStyle.Top,
                    Height = 340,
                    BorderStyle = BorderStyle.FixedSingle,
                    SizeMode = PictureBoxSizeMode.Zoom,
                    BackColor = Color.WhiteSmoke
                };

                var previewStatusLabel = new Label
                {
                    Dock = DockStyle.Fill,
                    Text = "Select an item to preview",
                    Font = new Font("Arial", 9, FontStyle.Regular),
                    ForeColor = Color.DimGray,
                    TextAlign = ContentAlignment.TopLeft
                };

                previewPictureBox.LoadCompleted += (s, e) =>
                {
                    previewStatusLabel.Text = e.Error == null && !e.Cancelled
                        ? "Image loaded"
                        : "Unable to load image";
                };

                previewPanel.Controls.Add(previewStatusLabel);
                previewPanel.Controls.Add(previewPictureBox);

                var list = new ListBox
                {
                    Dock = DockStyle.Fill,
                    Font = new Font("Arial", 11, FontStyle.Regular),
                    DisplayMember = nameof(AquariumAccessoryChoice.DisplayText)
                };

                var buttonsPanel = new Panel
                {
                    Dock = DockStyle.Bottom,
                    Height = 55,
                    Padding = new Padding(10),
                };

                var ok = new Button
                {
                    Text = "OK",
                    DialogResult = DialogResult.OK,
                    Width = 110,
                    Height = 32,
                    Anchor = AnchorStyles.Right | AnchorStyles.Top,
                };

                var cancel = new Button
                {
                    Text = "Cancel",
                    DialogResult = DialogResult.Cancel,
                    Width = 110,
                    Height = 32,
                    Anchor = AnchorStyles.Right | AnchorStyles.Top,
                };

                cancel.Location = new Point(buttonsPanel.Width - cancel.Width - 10, 10);
                ok.Location = new Point(cancel.Left - ok.Width - 10, 10);
                buttonsPanel.Resize += (s, e) =>
                {
                    cancel.Left = buttonsPanel.Width - cancel.Width - 10;
                    ok.Left = cancel.Left - ok.Width - 10;
                    ok.Top = cancel.Top = 10;
                };

                buttonsPanel.Controls.Add(ok);
                buttonsPanel.Controls.Add(cancel);

                dlg.AcceptButton = ok;
                dlg.CancelButton = cancel;
                dlg.Controls.Add(previewPanel);
                dlg.Controls.Add(list);
                dlg.Controls.Add(buttonsPanel);
                dlg.Controls.Add(searchBox);

                void UpdateSelectionPreview()
                {
                    if (list.SelectedItem is AquariumAccessoryChoice selectedChoice)
                    {
                        UpdateProductPreview(previewPictureBox, previewStatusLabel, selectedChoice.Images);
                        return;
                    }

                    UpdateProductPreview(previewPictureBox, previewStatusLabel, null);
                }

                void RefreshList(string? filter)
                {
                    list.BeginUpdate();
                    try
                    {
                        list.Items.Clear();
                        var filtered = string.IsNullOrWhiteSpace(filter)
                            ? items
                            : items.Where(item => item.DisplayText.IndexOf(filter, StringComparison.OrdinalIgnoreCase) >= 0
                                               || item.ItemCode.IndexOf(filter, StringComparison.OrdinalIgnoreCase) >= 0
                                               || item.ItemName.IndexOf(filter, StringComparison.OrdinalIgnoreCase) >= 0)
                                   .ToList();

                        foreach (var item in filtered)
                        {
                            list.Items.Add(item);
                        }
                    }
                    finally
                    {
                        list.EndUpdate();
                    }
                }

                RefreshList(null);
                if (list.Items.Count > 0)
                {
                    list.SelectedIndex = 0;
                }
                UpdateSelectionPreview();

                searchBox.TextChanged += (s, e) => RefreshList(searchBox.Text);
                list.SelectedIndexChanged += (s, e) => UpdateSelectionPreview();
                list.DoubleClick += (s, e) =>
                {
                    if (list.SelectedItem != null)
                    {
                        dlg.DialogResult = DialogResult.OK;
                    }
                };

                var result = dlg.ShowDialog(this);
                if (result != DialogResult.OK)
                {
                    return null;
                }

                return list.SelectedItem as AquariumAccessoryChoice;
            }
        }

        private List<AquariumAccessoryChoice> LoadAquariumAccessoryItemChoices(string keyword, params string[] categoryCodes)
        {
            var items = new List<AquariumAccessoryChoice>();

            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();

                bool hasImagesColumn = false;
                try
                {
                    using var imgColCmd = new SqlCommand("SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Items' AND COLUMN_NAME = 'Images'", connection);
                    hasImagesColumn = Convert.ToInt32(imgColCmd.ExecuteScalar() ?? 0) > 0;
                }
                catch
                {
                    hasImagesColumn = false;
                }

                var normalizedCategories = categoryCodes
                    .Where(code => !string.IsNullOrWhiteSpace(code))
                    .Select(code => code.Trim())
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();

                var categoryFilters = new List<string>();
                using var command = new SqlCommand();
                command.Connection = connection;

                for (int i = 0; i < normalizedCategories.Count; i++)
                {
                    string paramName = $"@Category{i}";
                    categoryFilters.Add(paramName);
                    command.Parameters.AddWithValue(paramName, normalizedCategories[i]);
                }

                command.Parameters.AddWithValue("@Keyword", keyword ?? string.Empty);
                command.Parameters.AddWithValue("@KeywordLike", $"%{keyword}%");

                string categoryClause = categoryFilters.Count > 0
                    ? $"LTRIM(RTRIM(ISNULL(i.CategoryCode, ''))) IN ({string.Join(", ", categoryFilters)})"
                    : "1 = 0";

                command.CommandText = $@"
SELECT
    i.Code,
    ISNULL(NULLIF(i.[Name], ''), ISNULL(i.[Description], '')) AS ItemName,
    ISNULL(i.CategoryCode, '') AS CategoryCode,
    ISNULL(i.Price, 0) AS Price,
    {(hasImagesColumn ? "ISNULL(i.Images, '')" : "CAST('' AS NVARCHAR(MAX))")} AS Images
FROM dbo.Items i
WHERE i.IsActive = 1
  AND (
        {categoryClause}
        OR i.Code LIKE @KeywordLike
        OR i.[Name] LIKE @KeywordLike
        OR i.[Description] LIKE @KeywordLike
      )
ORDER BY i.[Description], i.[Name], i.Code";

                using var reader = command.ExecuteReader();
                while (reader.Read())
                {
                    var code = reader["Code"]?.ToString()?.Trim() ?? string.Empty;
                    var itemName = reader["ItemName"]?.ToString()?.Trim() ?? string.Empty;
                    var categoryCode = reader["CategoryCode"]?.ToString()?.Trim() ?? string.Empty;
                    decimal price = reader["Price"] != DBNull.Value ? Convert.ToDecimal(reader["Price"]) : 0m;
                    string images = reader["Images"]?.ToString()?.Trim() ?? string.Empty;

                    if (string.IsNullOrWhiteSpace(code) && string.IsNullOrWhiteSpace(itemName))
                    {
                        continue;
                    }

                    items.Add(new AquariumAccessoryChoice
                    {
                        ItemCode = code,
                        ItemName = string.IsNullOrWhiteSpace(itemName) ? code : itemName,
                        CategoryCode = categoryCode,
                        Price = price,
                        Images = images
                    });
                }
            }

            return items
                .GroupBy(item => item.ItemCode, StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .OrderBy(item => item.ItemName, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => item.ItemCode, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private void AddAquariumSetDiscountLine(string packageName, decimal discountAmount)
        {
            if (salesListView == null || string.IsNullOrWhiteSpace(packageName) || discountAmount <= 0m)
            {
                return;
            }

            decimal lineAmount = -decimal.Round(discountAmount, 2);

            var item = new ListViewItem(FunctionEvents.ToAscii($"{packageName} Promotion"));
            item.SubItems.Add("1");
            item.SubItems.Add($"{lineAmount:F2}");
            item.SubItems.Add($"{lineAmount:F2}");
            item.SubItems.Add(string.Empty);
            item.SubItems.Add(string.Empty);
            item.SubItems.Add(string.Empty);
            item.Tag = AquariumSetDiscountTag;

            salesListView.Items.Add(item);
            currentTotal += lineAmount;
            UpdateTotal();
        }

        private void AddAquariumSetAccessoryLines(IEnumerable<string> accessoryLines)
        {
            if (salesListView == null)
            {
                return;
            }

            foreach (var accessoryLine in accessoryLines)
            {
                if (string.IsNullOrWhiteSpace(accessoryLine))
                {
                    continue;
                }

                var item = new ListViewItem(FunctionEvents.ToAscii(accessoryLine));
                item.SubItems.Add("1");
                item.SubItems.Add("0.00");
                item.SubItems.Add("0.00");
                item.SubItems.Add(string.Empty);
                item.SubItems.Add(string.Empty);
                item.SubItems.Add(string.Empty);
                item.Tag = AquariumSetAccessoryTag;

                salesListView.Items.Add(item);
            }

            UpdateTotal();
        }

        private List<EmployeeChoice> LoadEmployeesForPicker()
        {
            var list = new List<EmployeeChoice>();

            using (var conn = new SqlConnection(connectionString))
            {
                conn.Open();

                // Schema-tolerant approach:
                // - Prefer IsActive filtering if it exists.
                // - Find a "code" column (EmployeeCode/Code/Username/etc.) and a "name" column (Name/FullName/Description).
                // First, get column names.
                var colCmd = new SqlCommand(@"SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='EmployeeSetup'", conn);
                var cols = new List<string>();
                using (var r = colCmd.ExecuteReader())
                {
                    while (r.Read())
                        cols.Add(r.GetString(0));
                }

                if (cols.Count == 0)
                    return list; // table not found or no permission

                string? FindCol(params string[] preferred)
                {
                    foreach (var p in preferred)
                    {
                        var c = cols.FirstOrDefault(x => string.Equals(x, p, StringComparison.OrdinalIgnoreCase));
                        if (c != null) return c;
                    }
                    return null;
                }

                var codeCol = FindCol("EmployeeCode", "EmployeeNo", "Code", "Username", "UserName", "ID");
                var nameCol = FindCol("FullName", "EmployeeName", "Name", "Description", "DisplayName");
                var isActiveCol = FindCol("IsActive", "Active");

                if (codeCol == null)
                    codeCol = cols.First(); // fallback to first column
                if (nameCol == null)
                    nameCol = codeCol; // fallback

                string sql;
                if (isActiveCol != null)
                {
                    sql = $@"SELECT {Bracket(codeCol)} AS Code, {Bracket(nameCol)} AS Name
                            FROM dbo.EmployeeSetup
                            WHERE {Bracket(isActiveCol)} = 1
                            ORDER BY {Bracket(nameCol)}";
                }
                else
                {
                    sql = $@"SELECT {Bracket(codeCol)} AS Code, {Bracket(nameCol)} AS Name
                            FROM dbo.EmployeeSetup
                            ORDER BY {Bracket(nameCol)}";
                }

                using (var cmd = new SqlCommand(sql, conn))
                using (var rdr = cmd.ExecuteReader())
                {
                    while (rdr.Read())
                    {
                        var code = rdr["Code"] != DBNull.Value ? rdr["Code"].ToString() ?? "" : "";
                        var name = rdr["Name"] != DBNull.Value ? rdr["Name"].ToString() ?? "" : "";

                        if (string.IsNullOrWhiteSpace(code) && string.IsNullOrWhiteSpace(name))
                            continue;

                        var display = string.IsNullOrWhiteSpace(name) ? code : name;
                        // If code and name are different, show both.
                        if (!string.IsNullOrWhiteSpace(code) && !string.Equals(display, code, StringComparison.OrdinalIgnoreCase))
                            display = $"{display} ({code})";

                        list.Add(new EmployeeChoice(code, display));
                    }
                }
            }

            return list;
        }

        private static string Bracket(string identifier) => $"[{identifier.Replace("]", "]]")}]";

        private void TryPersistSalesPersonToCurrentTransactionHeader()
        {
            if (string.IsNullOrWhiteSpace(currentReceiptNo)) return;
            if (string.IsNullOrWhiteSpace(currentSalesPersonCode) && string.IsNullOrWhiteSpace(currentSalesPersonName)) return;

            try
            {
                using (var conn = new SqlConnection(connectionString))
                {
                    conn.Open();

                    // If TransactionHeader doesn't exist yet for this receipt, skip.
                    var existsCmd = new SqlCommand("SELECT COUNT(1) FROM TransactionHeader WHERE ReceiptNo = @r", conn);
                    existsCmd.Parameters.AddWithValue("@r", currentReceiptNo);
                    var exists = Convert.ToInt32(existsCmd.ExecuteScalar() ?? 0) > 0;
                    if (!exists) return;

                    // Schema-tolerant column write: try common columns.
                    // We update the first matching column and ignore if not present.
                    var columns = new List<string>();
                    var colCmd = new SqlCommand(@"SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='TransactionHeader'", conn);
                    using (var r = colCmd.ExecuteReader())
                    {
                        while (r.Read())
                            columns.Add(r.GetString(0));
                    }

                    string? Find(params string[] preferred)
                    {
                        foreach (var p in preferred)
                        {
                            var c = columns.FirstOrDefault(x => string.Equals(x, p, StringComparison.OrdinalIgnoreCase));
                            if (c != null) return c;
                        }
                        return null;
                    }

                    var col = Find("SalesPerson", "SalesPersonCode", "Salesperson", "SalespersonCode", "Employee", "EmployeeCode");
                    if (col == null) return;

                    var val = !string.IsNullOrWhiteSpace(currentSalesPersonCode) ? currentSalesPersonCode! : currentSalesPersonName!;
                    var upd = new SqlCommand($"UPDATE TransactionHeader SET {Bracket(col)} = @v WHERE ReceiptNo = @r", conn);
                    upd.Parameters.AddWithValue("@v", val);
                    upd.Parameters.AddWithValue("@r", currentReceiptNo);
                    upd.ExecuteNonQuery();
                }
            }
            catch
            {
                // Best-effort persistence only; keep the in-memory selection.
            }
        }
