        private async Task RunManualProductSyncAsync(Button syncButton, Action? onSuccess = null)
        {
            if (_isOnlineSyncRunning)
            {
                MessageBox.Show("Sync is already running.", "Sync", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            _isOnlineSyncRunning = true;
            var originalText = syncButton.Text;
            syncButton.Enabled = false;
            syncButton.Text = "Syncing...";

            try
            {
                int updated = await OnlinefunctionsEvents.SyncProductVariationsAsync(TimeSpan.FromSeconds(60));
                onSuccess?.Invoke();
                MessageBox.Show($"Sync completed. Items updated: {updated}", "Sync", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Sync failed: {ex.Message}", "Sync", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
            finally
            {
                _isOnlineSyncRunning = false;
                syncButton.Text = originalText;
                syncButton.Enabled = true;
            }
        }

