                ForeColor = Color.DarkBlue,
                Dock = DockStyle.Top,
                Height = 35
            };

            salesListView = new ListView
            {
                Dock = DockStyle.Fill,
                View = View.Details,
                FullRowSelect = true,
                GridLines = true,
