            salesListView.Columns.Add("Code", "Code", 0);
            salesListView.Columns.Add("VariationId", "VariationId", 0);

            // Adjust description column to fill remaining width of salesPanel
            int fixedColumnsWidth = 80 + 120 + 120 + 140 + 40; // Qty + Price + Total + Category + padding
            int descWidth = Math.Max(200, salesPanel.Width - fixedColumnsWidth);
            salesListView.Columns[0].Width = descWidth;
            salesListView.Columns[1].Width = 80;
            salesListView.Columns[2].Width = 120;
            salesListView.Columns[3].Width = 120;
            salesListView.Columns[4].Width = 140;
            salesListView.Columns[5].Width = 0;
            salesListView.Columns[6].Width = 0;

            // Add controls in order: label (top), then listview (fills remaining)
            salesPanel.Controls.Add(salesListView);
            salesPanel.Controls.Add(salesLabel);
            // If you want paymentsLabel, paymentsListView, remainingBalanceLabel visible, dock/bottom them as needed
