            // remainingBalanceLabel.Dock = DockStyle.Bottom;
            // salesPanel.Controls.Add(paymentsLabel);
            // salesPanel.Controls.Add(paymentsListView);
            // salesPanel.Controls.Add(remainingBalanceLabel);

            this.Controls.Add(salesPanel);
        }

