        private void EnsureGlassPricingSetupTableSchema(SqlConnection connection)
        {
            using var cmd = new SqlCommand(@"
IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'GlassPricingSetup')
BEGIN
    CREATE TABLE GlassPricingSetup (
        UOM NVARCHAR(50) NOT NULL,
        Units NVARCHAR(100) NOT NULL,
        PricePerSqFt DECIMAL(18,2) NOT NULL,
        TurnAroundDays NVARCHAR(100) NULL
    )
END
IF COL_LENGTH('GlassPricingSetup', 'TurnAroundDays') IS NULL
BEGIN
    ALTER TABLE GlassPricingSetup ADD TurnAroundDays NVARCHAR(100) NULL
END", connection);
            cmd.ExecuteNonQuery();
        }

        // Handler for Glass Pricing Setup button
        private void GlassPricingButton_Click(object? sender, EventArgs e)
        {
            void RefreshGrid(DataGridView grid, Label countLabel)
            {
                grid.Rows.Clear();
                int rowCount = 0;

                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    EnsureGlassPricingSetupTableSchema(connection);
                    var command = new SqlCommand("SELECT UOM, Units, PricePerSqFt, TurnAroundDays FROM GlassPricingSetup ORDER BY UOM, Units", connection);
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string uom = reader["UOM"].ToString() ?? "";
                            string units = reader["Units"].ToString() ?? "";
                            decimal price = reader["PricePerSqFt"] != DBNull.Value ? reader.GetDecimal(reader.GetOrdinal("PricePerSqFt")) : 0m;
                            string turnAroundDays = reader["TurnAroundDays"]?.ToString() ?? string.Empty;
                            grid.Rows.Add(uom, units, price, turnAroundDays, "Edit");
                            rowCount++;
                        }
                    }
                }
                countLabel.Text = $"Total Glass Types: {rowCount}";
            }

            void ExportGlassPricingJson(IWin32Window owner)
            {
                try
                {
                    var rows = new System.Collections.Generic.List<object>();

                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();
                        EnsureGlassPricingSetupTableSchema(connection);
                        using var command = new SqlCommand("SELECT UOM, Units, PricePerSqFt, TurnAroundDays FROM GlassPricingSetup ORDER BY UOM, Units", connection);
                        using var reader = command.ExecuteReader();
                        while (reader.Read())
                        {
                            rows.Add(new
                            {
                                UOM = reader["UOM"]?.ToString() ?? string.Empty,
                                Units = reader["Units"]?.ToString() ?? string.Empty,
                                PricePerSqFt = reader["PricePerSqFt"] != DBNull.Value ? Convert.ToDecimal(reader["PricePerSqFt"]) : 0m,
                                TurnAroundDays = reader["TurnAroundDays"]?.ToString() ?? string.Empty
                            });
                        }
                    }

                    using var saveDialog = new SaveFileDialog
                    {
                        Filter = "JSON Files|*.json",
                        Title = "Export Glass Pricing JSON",
                        FileName = "glass-pricing.json",
                        OverwritePrompt = true
                    };

                    if (saveDialog.ShowDialog(owner) != DialogResult.OK)
                    {
                        return;
                    }

                    string json = JsonSerializer.Serialize(rows, new JsonSerializerOptions { WriteIndented = true });
                    File.WriteAllText(saveDialog.FileName, json, Encoding.UTF8);

                    MessageBox.Show(owner,
                        $"Glass pricing exported successfully.\nFile saved: {saveDialog.FileName}",
                        "Export Successful",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Information);
                }
                catch (Exception exExport)
                {
                    MessageBox.Show(owner,
                        $"Failed to export glass pricing JSON: {exExport.Message}",
                        "Export Error",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Error);
                }
            }

            try
            {
                var tableForm = new Form
                {
                    Text = "Glass Pricing Setup",
                    Size = new Size(760, 430),
                    StartPosition = FormStartPosition.CenterParent,
                    BackColor = Color.White
