                    Size = new Size(360, 25),
                    Font = new Font("Arial", 9)
                };

                var addButton = new Button
                {
                    Text = "Add",
                    Location = new Point(470, 300),
                    Size = new Size(60, 30),
                    BackColor = Color.Green,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 9, FontStyle.Bold)
                };
                addButton.Click += (s, args) =>
                {
                    string uom = uomBox.SelectedItem?.ToString() ?? "";
                    string units = unitsBox.Text.Trim();
                    decimal price = priceBox.Value;
                    string turnAroundDays = turnAroundBox.Text.Trim();
                    if (string.IsNullOrWhiteSpace(uom) || string.IsNullOrWhiteSpace(units) || price <= 0)
                    {
                        MessageBox.Show("Please enter valid UOM, units, and price.", "Input Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        return;
                    }
                    try
                    {
                        using (var connection = new SqlConnection(connectionString))
                        {
                            connection.Open();
                            EnsureGlassPricingSetupTableSchema(connection);
                            var cmd = new SqlCommand("INSERT INTO GlassPricingSetup (UOM, Units, PricePerSqFt, TurnAroundDays) VALUES (@uom, @units, @price, @turnAroundDays)", connection);
                            cmd.Parameters.AddWithValue("@uom", uom);
                            cmd.Parameters.AddWithValue("@units", units);
                            cmd.Parameters.AddWithValue("@price", price);
                            cmd.Parameters.AddWithValue("@turnAroundDays", turnAroundDays);
                            cmd.ExecuteNonQuery();
                        }
                        RefreshGrid(dataGridView, countLabel);
                        unitsBox.Clear();
                        priceBox.Value = 100;
                        turnAroundBox.Clear();
                        MessageBox.Show("Entry added successfully!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                    catch (Exception ex2)
                    {
                        MessageBox.Show($"Failed to add entry: {ex2.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                };

                var closeButton = new Button
                {
                    Text = "Close",
                    Location = new Point(670, 340),
                    Size = new Size(70, 30),
                    BackColor = Color.DarkBlue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 9, FontStyle.Bold)
                };
                closeButton.Click += (s, args) => tableForm.Close();

                var exportJsonButton = new Button
                {
                    Text = "Export JSON",
                    Location = new Point(550, 340),
                    Size = new Size(110, 30),
                    BackColor = Color.SaddleBrown,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 9, FontStyle.Bold)
                };
                exportJsonButton.Click += (s, args) => ExportGlassPricingJson(tableForm);

                tableForm.Controls.AddRange(new Control[] { dataGridView, countLabel, uomLabel, uomBox, unitsLabel, unitsBox, priceLabel, priceBox, turnAroundLabel, turnAroundBox, addButton, exportJsonButton, closeButton });
                RefreshGrid(dataGridView, countLabel);
                tableForm.ShowDialog();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Database connection failed: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        // Handler for Excel Export button
        private void ExcelExportButton_Click(object? sender, EventArgs e)
        {
            try
            {
                // Set EPPlus license context
                ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

                SaveFileDialog saveFileDialog = new SaveFileDialog
                {
                    Filter = "Excel Files|*.xlsx",
                    Title = "Save Excel Template",
                    FileName = $"Items_Template_{DateTime.Now:yyyyMMdd_HHmmss}.xlsx"
                };

                if (saveFileDialog.ShowDialog() == DialogResult.OK)
                {
                    using (var package = new ExcelPackage())
                    {
                        var worksheet = package.Workbook.Worksheets.Add("Items Template");

                        // Add headers (include PromoPrice)
                        string[] headers = { "Code", "Name", "Description", "Cost", "Price", "WholesalePrice", "RetailPrice", "PromoPrice",
                                           "CategoryCode", "Brand", "SKU", "QuantityInStock", "MinimumStock", "IsActive" };

                        for (int i = 0; i < headers.Length; i++)
                        {
                            worksheet.Cells[1, i + 1].Value = headers[i];
                            worksheet.Cells[1, i + 1].Style.Font.Bold = true;
                            worksheet.Cells[1, i + 1].Style.Fill.PatternType = ExcelFillStyle.Solid;
                            worksheet.Cells[1, i + 1].Style.Fill.BackgroundColor.SetColor(Color.LightBlue);
                        }

                        // Export existing data from database
                        using (var connection = new SqlConnection(connectionString))
                        {
                            connection.Open();
                            var checkTable = new SqlCommand("SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Items'", connection);
                            int tableExists = (int)checkTable.ExecuteScalar();

                            if (tableExists > 0)
                            {
                                var command = new SqlCommand("SELECT Code, Name, Description, Cost, Price, WholesalePrice, RetailPrice, PromoPrice, CategoryCode, Brand, SKU, QuantityInStock, MinimumStock, IsActive FROM Items ORDER BY CategoryCode, Code", connection);
                                using (var reader = command.ExecuteReader())
                                {
                                    int row = 2;
                                    while (reader.Read())
                                    {
                                        worksheet.Cells[row, 1].Value = reader["Code"].ToString();
                                        worksheet.Cells[row, 2].Value = reader["Name"].ToString();
                                        worksheet.Cells[row, 3].Value = reader["Description"].ToString();
                                        worksheet.Cells[row, 4].Value = reader["Cost"] != DBNull.Value ? Convert.ToDecimal(reader["Cost"]) : 0m;
                                        worksheet.Cells[row, 5].Value = reader["Price"] != DBNull.Value ? Convert.ToDecimal(reader["Price"]) : 0m;
                                        worksheet.Cells[row, 6].Value = reader["WholesalePrice"] != DBNull.Value ? Convert.ToDecimal(reader["WholesalePrice"]) : 0m;
                                        worksheet.Cells[row, 7].Value = reader["RetailPrice"] != DBNull.Value ? Convert.ToDecimal(reader["RetailPrice"]) : 0m;
                                        worksheet.Cells[row, 8].Value = reader["PromoPrice"] != DBNull.Value ? Convert.ToDecimal(reader["PromoPrice"]) : 0m;
                                        worksheet.Cells[row, 9].Value = reader["CategoryCode"].ToString();
                                        worksheet.Cells[row, 10].Value = reader["Brand"].ToString();
                                        worksheet.Cells[row, 11].Value = reader["SKU"].ToString();
                                        worksheet.Cells[row, 12].Value = reader["QuantityInStock"] != DBNull.Value ? Convert.ToInt32(reader["QuantityInStock"]) : 0;
                                        worksheet.Cells[row, 13].Value = reader["MinimumStock"] != DBNull.Value ? Convert.ToInt32(reader["MinimumStock"]) : 0;
                                        worksheet.Cells[row, 14].Value = reader["IsActive"] != DBNull.Value ? reader.GetBoolean(reader.GetOrdinal("IsActive")) : true;
                                        row++;
                                    }
                                }
                            }
                        }

                        // Add sample rows for template
                        if (worksheet.Dimension?.Rows == 1) // Only headers, add sample data
                        {
                            worksheet.Cells[2, 1].Value = "FISH001";
                            worksheet.Cells[2, 2].Value = "Sample Fish";
                            worksheet.Cells[2, 3].Value = "Beautiful tropical fish";
                            worksheet.Cells[2, 4].Value = 12.50;
                            worksheet.Cells[2, 5].Value = 25.99;
                            worksheet.Cells[2, 6].Value = 15.00;
                            worksheet.Cells[2, 7].Value = 29.99;
                            worksheet.Cells[2, 8].Value = 19.99; // PromoPrice sample
                            worksheet.Cells[2, 9].Value = "FISH";
                            worksheet.Cells[2, 10].Value = "AquaBrand";
                            worksheet.Cells[2, 11].Value = "FISH001_SKU";
                            worksheet.Cells[2, 12].Value = 50;
                            worksheet.Cells[2, 13].Value = 10;
                            worksheet.Cells[2, 14].Value = true;
                        }

                        // Auto-fit columns
                        if (worksheet.Dimension != null)
                        {
                            worksheet.Cells[worksheet.Dimension.Address].AutoFitColumns();
                        }

                        // Add data validation for CategoryCode column
                        var categoryValidation = worksheet.DataValidations.AddListValidation("I:I");
                        // Get category codes from database for validation
                        using (var connection = new SqlConnection(connectionString))
                        {
                            connection.Open();
                            var catCommand = new SqlCommand("SELECT Code FROM Category ORDER BY Code", connection);
                            using (var catReader = catCommand.ExecuteReader())
                            {
                                while (catReader.Read())
                                {
                                    categoryValidation.Formula.Values.Add(catReader["Code"].ToString());
                                }
                            }
                        }
                        categoryValidation.ShowErrorMessage = true;
                        categoryValidation.ErrorTitle = "Invalid Category";
                        categoryValidation.Error = "Please select a valid category code from the dropdown list.";

                        // Add data validation for IsActive column
                        var activeValidation = worksheet.DataValidations.AddListValidation("N:N");
                        activeValidation.Formula.Values.Add("TRUE");
                        activeValidation.Formula.Values.Add("FALSE");

                        // Save the file
                        package.SaveAs(new FileInfo(saveFileDialog.FileName));
                    }

                    MessageBox.Show($"Excel template exported successfully!\nFile saved: {saveFileDialog.FileName}", "Export Successful", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to export Excel template: {ex.Message}", "Export Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        // Handler for Excel Import button
        private void ExcelImportButton_Click(object? sender, EventArgs e)
        {
            try
            {
                // Set EPPlus license context
                ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

                OpenFileDialog openFileDialog = new OpenFileDialog
                {
                    Filter = "Excel Files|*.xlsx;*.xls",
                    Title = "Select Excel File to Import"
                };

                if (openFileDialog.ShowDialog() == DialogResult.OK)
                {
                    using (var package = new ExcelPackage(new FileInfo(openFileDialog.FileName)))
                    {
                        var worksheet = package.Workbook.Worksheets.First();
                        int rowCount = worksheet.Dimension?.Rows ?? 0;

                        if (rowCount < 2)
                        {
                            MessageBox.Show("The Excel file appears to be empty or contains only headers.", "Import Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                            return;
                        }

                        // Ask user for import options
                        var importResult = MessageBox.Show("Do you want to:\n\nYES = Update existing items and add new ones\nNO = Only add new items (skip existing)\nCANCEL = Cancel import",
                                                         "Import Options", MessageBoxButtons.YesNoCancel, MessageBoxIcon.Question);

                        if (importResult == DialogResult.Cancel)
                            return;

                        bool updateExisting = importResult == DialogResult.Yes;
                        int successCount = 0;
                        int errorCount = 0;
                        var errorMessages = new List<string>();

                        using (var connection = new SqlConnection(connectionString))
                        {
                            connection.Open();

                            // Ensure Items table exists with new structure (Code as primary key)
                            var createTableCmd = new SqlCommand(@"
                                -- Check if Items table needs restructuring (old structure with ID)
                                IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Items')
                                BEGIN
                                    IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Items' AND COLUMN_NAME = 'ID')
                                    BEGIN
                                        -- Drop dependent tables first
                                        IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'ItemLedgerEntry')
                                            DROP TABLE ItemLedgerEntry
                                        DROP TABLE Items
                                    END
                                END
                                        Images NVARCHAR(MAX),
                                        CategoryCode NVARCHAR(50),
                                        Brand NVARCHAR(100),
                                        SKU NVARCHAR(100),
                                        QuantityInStock INT DEFAULT 0,
                                        MinimumStock INT DEFAULT 0,
                                        IsActive BIT DEFAULT 1,
                                        CreatedDate DATETIME2 DEFAULT GETDATE(),
                                        CONSTRAINT FK_Items_Category FOREIGN KEY (CategoryCode) REFERENCES Category(Code)
                                    )
                                END

                                -- Ensure ItemLedgerEntry table exists with correct structure
                                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'ItemLedgerEntry')
                                BEGIN
                                    CREATE TABLE ItemLedgerEntry (
                                        ID INT IDENTITY(1,1) PRIMARY KEY,
                                        EntryDate DATETIME2 DEFAULT GETDATE(),
                                        ItemCode NVARCHAR(50) NOT NULL,
                                        DocumentType NVARCHAR(50) NOT NULL,
                                        DocumentNo NVARCHAR(100),
                                        Quantity INT NOT NULL,
                                        UnitCost DECIMAL(10,2) DEFAULT 0,
                                        TotalCost DECIMAL(10,2) DEFAULT 0,
                                        Description NVARCHAR(500),
                                        UserID NVARCHAR(100) DEFAULT 'SYSTEM',
                                        CONSTRAINT FK_ItemLedgerEntry_Items FOREIGN KEY (ItemCode) REFERENCES Items(Code) ON DELETE CASCADE
                                    )
                                END", connection);
                            createTableCmd.ExecuteNonQuery();

                            for (int row = 2; row <= rowCount; row++)
                            {
                                try
                                {
                                    string? code = worksheet.Cells[row, 1].Text?.Trim();
                                    if (string.IsNullOrWhiteSpace(code)) continue;

                                    string name = worksheet.Cells[row, 2].Text?.Trim() ?? "";
                                    string description = worksheet.Cells[row, 3].Text?.Trim() ?? "";
                                    decimal cost = decimal.TryParse(worksheet.Cells[row, 4].Text, out decimal c) ? c : 0;
                                    decimal price = decimal.TryParse(worksheet.Cells[row, 5].Text, out decimal p) ? p : 0;
                                    decimal wholesalePrice = decimal.TryParse(worksheet.Cells[row, 6].Text, out decimal wp) ? wp : 0;
                                    decimal retailPrice = decimal.TryParse(worksheet.Cells[row, 7].Text, out decimal rp) ? rp : 0;

                                    // Detect whether the sheet includes a PromoPrice column (header in row 1)
                                    bool hasPromo = string.Equals(worksheet.Cells[1, 8].Text?.Trim(), "PromoPrice", StringComparison.OrdinalIgnoreCase)
                                                    || string.Equals(worksheet.Cells[1, 8].Text?.Trim(), "Promo Price", StringComparison.OrdinalIgnoreCase);

                                    decimal promoPrice = 0;
                                    string categoryCode;
                                    string brand;
                                    string sku;
                                    int quantityInStock;
                                    int minimumStock;
                                    bool isActive;

                                    if (hasPromo)
                                    {
                                        promoPrice = decimal.TryParse(worksheet.Cells[row, 8].Text, out decimal pp) ? pp : 0;
                                        categoryCode = worksheet.Cells[row, 9].Text?.Trim() ?? "";
                                        brand = worksheet.Cells[row, 10].Text?.Trim() ?? "";
                                        sku = worksheet.Cells[row, 11].Text?.Trim() ?? "";
                                        quantityInStock = int.TryParse(worksheet.Cells[row, 12].Text, out int qty) ? qty : 0;
                                        minimumStock = int.TryParse(worksheet.Cells[row, 13].Text, out int minStock) ? minStock : 0;
                                        isActive = bool.TryParse(worksheet.Cells[row, 14].Text, out bool active) ? active : true;
                                    }
                                    else
                                    {
                                        // Legacy template without PromoPrice: use previous column indexes
                                        promoPrice = 0;
                                        categoryCode = worksheet.Cells[row, 8].Text?.Trim() ?? "";
                                        brand = worksheet.Cells[row, 9].Text?.Trim() ?? "";
                                        sku = worksheet.Cells[row, 10].Text?.Trim() ?? "";
                                        quantityInStock = int.TryParse(worksheet.Cells[row, 11].Text, out int qty2) ? qty2 : 0;
                                        minimumStock = int.TryParse(worksheet.Cells[row, 12].Text, out int minStock2) ? minStock2 : 0;
                                        isActive = bool.TryParse(worksheet.Cells[row, 13].Text, out bool active2) ? active2 : true;
                                    }

                                    // Validate and handle CategoryCode
                                    if (!string.IsNullOrWhiteSpace(categoryCode))
                                    {
                                        var categoryCheckCmd = new SqlCommand("SELECT COUNT(*) FROM Category WHERE Code = @code", connection);
                                        categoryCheckCmd.Parameters.AddWithValue("@code", categoryCode);
                                        int categoryExists = (int)categoryCheckCmd.ExecuteScalar();

                                        if (categoryExists == 0)
                                        {
                                            // Create the category if it doesn't exist
                                            var createCategoryCmd = new SqlCommand("INSERT INTO Category (Code, Description) VALUES (@code, @description)", connection);
                                            createCategoryCmd.Parameters.AddWithValue("@code", categoryCode);
                                            createCategoryCmd.Parameters.AddWithValue("@description", categoryCode); // Use code as description by default
                                            createCategoryCmd.ExecuteNonQuery();
                                        }
                                    }

                                    // Check if item exists
                                    var checkCmd = new SqlCommand("SELECT COUNT(*) FROM Items WHERE Code = @code", connection);
                                    checkCmd.Parameters.AddWithValue("@code", code);
                                    int exists = (int)checkCmd.ExecuteScalar();

                                    if (exists > 0 && !updateExisting)
                                    {
                                        continue; // Skip existing items
                                    }

                                    if (exists > 0 && updateExisting)
                                    {
                                        // Get current quantity before update
                                        var getCurrentCmd = new SqlCommand("SELECT QuantityInStock FROM Items WHERE Code = @code", connection);
                                        getCurrentCmd.Parameters.AddWithValue("@code", code);
                                        int currentQty = 0;
                                        var qtyResult = getCurrentCmd.ExecuteScalar();
                                        if (qtyResult != null && qtyResult != DBNull.Value)
                                            currentQty = (int)qtyResult;

                                        // Update existing item
                                        var updateCmd = new SqlCommand(@"
                                            UPDATE Items SET 
                                                Name = @name,
                                                Description = @description,
                                                Cost = @cost,
                                                Price = @price,
                                                WholesalePrice = @wholesalePrice,
                                                RetailPrice = @retailPrice,
                                                PromoPrice = @promoPrice,
                                                CategoryCode = @categoryCode,
                                                Brand = @brand,
                                                SKU = @sku,
                                                QuantityInStock = @quantityInStock,
                                                MinimumStock = @minimumStock,
                                                IsActive = @isActive,
                                                UpdatedDate = GETDATE()
                                            WHERE Code = @code", connection);

                                        updateCmd.Parameters.AddWithValue("@code", code);
                                        updateCmd.Parameters.AddWithValue("@name", name);
                                        updateCmd.Parameters.AddWithValue("@description", description);
                                        updateCmd.Parameters.AddWithValue("@cost", cost);
                                        updateCmd.Parameters.AddWithValue("@price", price);
                                        updateCmd.Parameters.AddWithValue("@wholesalePrice", wholesalePrice);
                                        updateCmd.Parameters.AddWithValue("@retailPrice", retailPrice);
                                        updateCmd.Parameters.AddWithValue("@promoPrice", promoPrice);
                                        updateCmd.Parameters.AddWithValue("@categoryCode", string.IsNullOrWhiteSpace(categoryCode) ? (object)DBNull.Value : categoryCode);
                                        updateCmd.Parameters.AddWithValue("@brand", brand);
                                        updateCmd.Parameters.AddWithValue("@sku", sku);
                                        updateCmd.Parameters.AddWithValue("@quantityInStock", quantityInStock);
                                        updateCmd.Parameters.AddWithValue("@minimumStock", minimumStock);
                                        updateCmd.Parameters.AddWithValue("@isActive", isActive);
                                        updateCmd.ExecuteNonQuery();

                                        // Create Item Ledger Entry for quantity adjustment if quantity changed
                                        int qtyChange = quantityInStock - currentQty;
                                        if (qtyChange != 0)
                                        {
                                            var ledgerCmd = new SqlCommand(@"
                                                INSERT INTO ItemLedgerEntry (EntryDate, ItemCode, DocumentType, DocumentNo, Quantity, UnitCost, TotalCost, Description, UserID)
                                                VALUES (GETDATE(), @itemCode, @docType, @docNo, @quantity, @unitCost, @totalCost, @description, 'EXCEL_IMPORT')", connection);

                                            ledgerCmd.Parameters.AddWithValue("@itemCode", code);
                                            ledgerCmd.Parameters.AddWithValue("@docType", qtyChange > 0 ? "POSITIVE_ADJ" : "NEGATIVE_ADJ");
                                            ledgerCmd.Parameters.AddWithValue("@docNo", $"EXCEL_IMPORT_{DateTime.Now:yyyyMMdd_HHmmss}");
                                            ledgerCmd.Parameters.AddWithValue("@quantity", qtyChange);
                                            ledgerCmd.Parameters.AddWithValue("@unitCost", cost);
                                            ledgerCmd.Parameters.AddWithValue("@totalCost", cost * Math.Abs(qtyChange));
                                            ledgerCmd.Parameters.AddWithValue("@description", $"Excel import adjustment for {name}");
                                            ledgerCmd.ExecuteNonQuery();
                                        }
                                    }
                                    else
                                    {
                                        // Insert new item
                                        var insertCmd = new SqlCommand(@"
                                            INSERT INTO Items (Code, Name, Description, Cost, Price, WholesalePrice, RetailPrice, PromoPrice, CategoryCode, Brand, SKU, QuantityInStock, MinimumStock, IsActive)
                                            VALUES (@code, @name, @description, @cost, @price, @wholesalePrice, @retailPrice, @promoPrice, @categoryCode, @brand, @sku, @quantityInStock, @minimumStock, @isActive)", connection);

                                        insertCmd.Parameters.AddWithValue("@code", code);
                                        insertCmd.Parameters.AddWithValue("@name", name);
                                        insertCmd.Parameters.AddWithValue("@description", description);
                                        insertCmd.Parameters.AddWithValue("@cost", cost);
                                        insertCmd.Parameters.AddWithValue("@price", price);
                                        insertCmd.Parameters.AddWithValue("@wholesalePrice", wholesalePrice);
                                        insertCmd.Parameters.AddWithValue("@retailPrice", retailPrice);
                                        insertCmd.Parameters.AddWithValue("@promoPrice", promoPrice);
                                        insertCmd.Parameters.AddWithValue("@categoryCode", string.IsNullOrWhiteSpace(categoryCode) ? (object)DBNull.Value : categoryCode);
                                        insertCmd.Parameters.AddWithValue("@brand", brand);
                                        insertCmd.Parameters.AddWithValue("@sku", sku);
                                        insertCmd.Parameters.AddWithValue("@quantityInStock", quantityInStock);
                                        insertCmd.Parameters.AddWithValue("@minimumStock", minimumStock);
                                        insertCmd.Parameters.AddWithValue("@isActive", isActive);

                                        insertCmd.ExecuteNonQuery();

                                        // Create Item Ledger Entry for initial stock if quantity > 0
                                        if (quantityInStock > 0)
                                        {
                                            var ledgerCmd = new SqlCommand(@"
                                                INSERT INTO ItemLedgerEntry (EntryDate, ItemCode, DocumentType, DocumentNo, Quantity, UnitCost, TotalCost, Description, UserID)
                                                VALUES (GETDATE(), @itemCode, 'INITIAL', @docNo, @quantity, @unitCost, @totalCost, @description, 'EXCEL_IMPORT')", connection);

                                            ledgerCmd.Parameters.AddWithValue("@itemCode", code);
                                            ledgerCmd.Parameters.AddWithValue("@docNo", $"EXCEL_IMPORT_{DateTime.Now:yyyyMMdd_HHmmss}");
                                            ledgerCmd.Parameters.AddWithValue("@quantity", quantityInStock);
                                            ledgerCmd.Parameters.AddWithValue("@unitCost", cost);
                                            ledgerCmd.Parameters.AddWithValue("@totalCost", cost * quantityInStock);
                                            ledgerCmd.Parameters.AddWithValue("@description", $"Initial stock from Excel import for {name}");
                                            ledgerCmd.ExecuteNonQuery();
                                        }
                                    }

                                    successCount++;
                                }
                                catch (Exception rowEx)
                                {
                                    errorCount++;
                                    errorMessages.Add($"Row {row}: {rowEx.Message}");
                                }
                            }
                        }

                        string resultMessage = $"Import completed!\n\nSuccessful: {successCount} items\nErrors: {errorCount} items";
                        if (errorMessages.Count > 0 && errorMessages.Count <= 10)
                        {
                            resultMessage += "\n\nErrors:\n" + string.Join("\n", errorMessages);
                        }
                        else if (errorMessages.Count > 10)
                        {
                            resultMessage += $"\n\nFirst 10 errors:\n" + string.Join("\n", errorMessages.Take(10)) + "\n... and more";
                        }

                        MessageBox.Show(resultMessage, "Import Results", MessageBoxButtons.OK,
                                      errorCount == 0 ? MessageBoxIcon.Information : MessageBoxIcon.Warning);
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to import Excel file: {ex.Message}", "Import Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        // Handler for Category Management button
        private void EnsureCategoryTableSchema(SqlConnection connection)
        {
            var createTableCmd = new SqlCommand(@"
                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Category')
                BEGIN
                    CREATE TABLE Category (
                        Code NVARCHAR(50) PRIMARY KEY,
                        Description NVARCHAR(255) NOT NULL,
                        WholeSale BIT NOT NULL CONSTRAINT DF_Category_WholeSale DEFAULT(0),
                        DisableChangePrice BIT NOT NULL CONSTRAINT DF_Category_DisableChangePrice DEFAULT(0),
                        IsProductionCategory BIT NOT NULL CONSTRAINT DF_Category_IsProductionCategory DEFAULT(0),
                        ShowInMainPos BIT NOT NULL CONSTRAINT DF_Category_ShowInMainPos DEFAULT(1),
                        ExcludeOnInventoryReport BIT NOT NULL CONSTRAINT DF_Category_ExcludeOnInventoryReport DEFAULT(0),
                        CreatedDate DATETIME2 DEFAULT GETDATE(),
                        UpdatedDate DATETIME2 DEFAULT GETDATE()
                    )
                END
                BEGIN
                    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Category' AND COLUMN_NAME = 'WholeSale')
                    BEGIN
                        ALTER TABLE Category ADD WholeSale BIT NOT NULL CONSTRAINT DF_Category_WholeSale DEFAULT(0)
                    END

                    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Category' AND COLUMN_NAME = 'DisableChangePrice')
                    BEGIN
                        ALTER TABLE Category ADD DisableChangePrice BIT NOT NULL CONSTRAINT DF_Category_DisableChangePrice DEFAULT(0)
                    END

                    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Category' AND COLUMN_NAME = 'IsProductionCategory')
                    BEGIN
                        ALTER TABLE Category ADD IsProductionCategory BIT NOT NULL CONSTRAINT DF_Category_IsProductionCategory DEFAULT(0)
                    END

                    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Category' AND COLUMN_NAME = 'ShowInMainPos')
                    BEGIN
                        ALTER TABLE Category ADD ShowInMainPos BIT NOT NULL CONSTRAINT DF_Category_ShowInMainPos DEFAULT(1)
                    END

                    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Category' AND COLUMN_NAME = 'ExcludeOnInventoryReport')
                    BEGIN
                        ALTER TABLE Category ADD ExcludeOnInventoryReport BIT NOT NULL CONSTRAINT DF_Category_ExcludeOnInventoryReport DEFAULT(0)
                    END
                END", connection);
            createTableCmd.ExecuteNonQuery();
        }

        private void CategoryMgmtButton_Click(object? sender, EventArgs e)
        {
            bool isRefreshingCategoryGrid = false;

            static void MatchParentFormBounds(Form form)
            {
                try
                {
                    var main = Application.OpenForms.Cast<Form>().FirstOrDefault(f => f.GetType().Name == "MainForm");
                    if (main != null)
                    {
                        form.StartPosition = FormStartPosition.Manual;
                        form.Bounds = main.Bounds;
                        form.WindowState = main.WindowState;
                        form.Location = main.Location;
                    }
                    else
                    {
                        form.WindowState = FormWindowState.Maximized;
                    }
                }
                catch
                {
                    form.WindowState = FormWindowState.Maximized;
                }
            }

            static bool TryParseCategoryBoolean(string? text, out bool value)
            {
                value = false;
                if (string.IsNullOrWhiteSpace(text))
                    return false;

                string normalized = text.Trim();
                if (bool.TryParse(normalized, out value))
                    return true;

                switch (normalized.ToUpperInvariant())
                {
                    case "1":
                    case "YES":
                    case "Y":
                        value = true;
                        return true;
                    case "0":
                    case "NO":
                    case "N":
                        value = false;
                        return true;
                    default:
                        return false;
                }
            }

            void RefreshCategoryGrid(DataGridView grid, Label countLabel)
            {
                isRefreshingCategoryGrid = true;
                grid.Rows.Clear();
                int rowCount = 0;
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    EnsureCategoryTableSchema(connection);
                    var command = new SqlCommand("SELECT Code, Description, WholeSale, DisableChangePrice, IsProductionCategory, ShowInMainPos, ExcludeOnInventoryReport FROM Category ORDER BY Code", connection);
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string code = reader["Code"].ToString() ?? "";
                            string description = reader["Description"].ToString() ?? "";
                            bool wholeSale = reader["WholeSale"] != DBNull.Value && Convert.ToBoolean(reader["WholeSale"]);
                            bool disableChangePrice = reader["DisableChangePrice"] != DBNull.Value && Convert.ToBoolean(reader["DisableChangePrice"]);
                            bool isProductionCategory = reader["IsProductionCategory"] != DBNull.Value && Convert.ToBoolean(reader["IsProductionCategory"]);
                            bool showInMainPos = reader["ShowInMainPos"] != DBNull.Value && Convert.ToBoolean(reader["ShowInMainPos"]);
                            bool excludeOnInventoryReport = reader["ExcludeOnInventoryReport"] != DBNull.Value && Convert.ToBoolean(reader["ExcludeOnInventoryReport"]);
                            grid.Rows.Add(code, description, wholeSale, disableChangePrice, isProductionCategory, showInMainPos, excludeOnInventoryReport, "Edit", "Delete");
                            rowCount++;
                        }
                    }
                }
                countLabel.Text = $"Total Categories: {rowCount}";
                isRefreshingCategoryGrid = false;
            }

            void ExportCategoriesToExcel()
            {
                ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

                using var saveDialog = new SaveFileDialog
                {
                    Filter = "Excel Files|*.xlsx",
                    Title = "Export Categories",
                    FileName = $"Categories_{DateTime.Now:yyyyMMdd_HHmmss}.xlsx"
                };

                if (saveDialog.ShowDialog() != DialogResult.OK)
                    return;

                using var package = new ExcelPackage();
                var worksheet = package.Workbook.Worksheets.Add("Categories");
                string[] headers = { "Code", "Description", "WholeSale", "DisableChangePrice", "IsProductionCategory", "ShowInMainPos", "ExcludeOnInventoryReport" };

                for (int i = 0; i < headers.Length; i++)
                {
                    worksheet.Cells[1, i + 1].Value = headers[i];
                    worksheet.Cells[1, i + 1].Style.Font.Bold = true;
                    worksheet.Cells[1, i + 1].Style.Fill.PatternType = ExcelFillStyle.Solid;
                    worksheet.Cells[1, i + 1].Style.Fill.BackgroundColor.SetColor(Color.LightBlue);
                }

                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    EnsureCategoryTableSchema(connection);

                    using var command = new SqlCommand("SELECT Code, Description, WholeSale, DisableChangePrice, IsProductionCategory, ShowInMainPos, ExcludeOnInventoryReport FROM Category ORDER BY Code", connection);
                    using var reader = command.ExecuteReader();

                    int row = 2;
                    while (reader.Read())
                    {
                        worksheet.Cells[row, 1].Value = reader["Code"]?.ToString() ?? string.Empty;
                        worksheet.Cells[row, 2].Value = reader["Description"]?.ToString() ?? string.Empty;
                        worksheet.Cells[row, 3].Value = reader["WholeSale"] != DBNull.Value && Convert.ToBoolean(reader["WholeSale"]);
                        worksheet.Cells[row, 4].Value = reader["DisableChangePrice"] != DBNull.Value && Convert.ToBoolean(reader["DisableChangePrice"]);
                        worksheet.Cells[row, 5].Value = reader["IsProductionCategory"] != DBNull.Value && Convert.ToBoolean(reader["IsProductionCategory"]);
                        worksheet.Cells[row, 6].Value = reader["ShowInMainPos"] != DBNull.Value && Convert.ToBoolean(reader["ShowInMainPos"]);
                        worksheet.Cells[row, 7].Value = reader["ExcludeOnInventoryReport"] != DBNull.Value && Convert.ToBoolean(reader["ExcludeOnInventoryReport"]);
                        row++;
                    }

                    if (row == 2)
                    {
                        worksheet.Cells[2, 1].Value = "FISH";
                        worksheet.Cells[2, 2].Value = "Fish and Aquatic Animals";
                        worksheet.Cells[2, 3].Value = false;
                        worksheet.Cells[2, 4].Value = false;
                        worksheet.Cells[2, 5].Value = false;
                        worksheet.Cells[2, 6].Value = true;
                        worksheet.Cells[2, 7].Value = false;
                    }
                }

                if (worksheet.Dimension != null)
                {
                    worksheet.Cells[worksheet.Dimension.Address].AutoFitColumns();
                }

                var wholesaleValidation = worksheet.DataValidations.AddListValidation("C:C");
                wholesaleValidation.Formula.Values.Add("TRUE");
                wholesaleValidation.Formula.Values.Add("FALSE");
                var disableValidation = worksheet.DataValidations.AddListValidation("D:D");
                disableValidation.Formula.Values.Add("TRUE");
                disableValidation.Formula.Values.Add("FALSE");
                var productionValidation = worksheet.DataValidations.AddListValidation("E:E");
                productionValidation.Formula.Values.Add("TRUE");
                productionValidation.Formula.Values.Add("FALSE");
                var showValidation = worksheet.DataValidations.AddListValidation("F:F");
                showValidation.Formula.Values.Add("TRUE");
                showValidation.Formula.Values.Add("FALSE");
                var excludeValidation = worksheet.DataValidations.AddListValidation("G:G");
                excludeValidation.Formula.Values.Add("TRUE");
                excludeValidation.Formula.Values.Add("FALSE");

                package.SaveAs(new FileInfo(saveDialog.FileName));
                MessageBox.Show($"Categories exported successfully.\nFile saved: {saveDialog.FileName}", "Export Successful", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }

            void ImportCategoriesFromExcel(DataGridView grid, Label countLabel)
            {
                ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

                using var openDialog = new OpenFileDialog
                {
                    Filter = "Excel Files|*.xlsx;*.xls",
                    Title = "Import Categories"
                };

                if (openDialog.ShowDialog() != DialogResult.OK)
                    return;

                using var package = new ExcelPackage(new FileInfo(openDialog.FileName));
                var worksheet = package.Workbook.Worksheets.FirstOrDefault();
                if (worksheet == null)
                {
                    MessageBox.Show("The selected Excel file does not contain any worksheets.", "Import Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                int rowCount = worksheet.Dimension?.Rows ?? 0;
                if (rowCount < 2)
                {
                    MessageBox.Show("The Excel file appears to be empty or contains only headers.", "Import Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                string[] expectedHeaders = { "Code", "Description", "WholeSale", "DisableChangePrice", "IsProductionCategory", "ShowInMainPos", "ExcludeOnInventoryReport" };
                for (int i = 0; i < expectedHeaders.Length; i++)
                {
                    string actualHeader = worksheet.Cells[1, i + 1].Text?.Trim() ?? string.Empty;
                    if (!string.Equals(actualHeader, expectedHeaders[i], StringComparison.OrdinalIgnoreCase))
                    {
                        MessageBox.Show("Invalid category import template. Expected headers: Code, Description, WholeSale, DisableChangePrice, IsProductionCategory, ShowInMainPos, ExcludeOnInventoryReport.", "Import Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        return;
                    }
                }

                var importResult = MessageBox.Show("Do you want to:\n\nYES = Update existing categories and add new ones\nNO = Only add new categories (skip existing)\nCANCEL = Cancel import",
                    "Import Options", MessageBoxButtons.YesNoCancel, MessageBoxIcon.Question);

                if (importResult == DialogResult.Cancel)
                    return;

                bool updateExisting = importResult == DialogResult.Yes;
                int successCount = 0;
                int skippedCount = 0;
                var errors = new List<string>();

                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    EnsureCategoryTableSchema(connection);

                    for (int row = 2; row <= rowCount; row++)
                    {
                        try
                        {
                            string code = worksheet.Cells[row, 1].Text?.Trim().ToUpperInvariant() ?? string.Empty;
                            string description = worksheet.Cells[row, 2].Text?.Trim() ?? string.Empty;

                            if (string.IsNullOrWhiteSpace(code))
                                continue;

                            if (string.IsNullOrWhiteSpace(description))
                                throw new InvalidOperationException("Description is required.");

                            if (!TryParseCategoryBoolean(worksheet.Cells[row, 3].Text, out bool wholesale))
                                wholesale = false;
                            if (!TryParseCategoryBoolean(worksheet.Cells[row, 4].Text, out bool disableChangePrice))
                                disableChangePrice = false;
                            if (!TryParseCategoryBoolean(worksheet.Cells[row, 5].Text, out bool isProductionCategory))
                                isProductionCategory = false;
                            if (!TryParseCategoryBoolean(worksheet.Cells[row, 6].Text, out bool showInMainPos))
                                showInMainPos = true;
                            if (!TryParseCategoryBoolean(worksheet.Cells[row, 7].Text, out bool excludeOnInventoryReport))
                                excludeOnInventoryReport = false;

                            using var existsCmd = new SqlCommand("SELECT COUNT(*) FROM Category WHERE Code = @code", connection);
                            existsCmd.Parameters.AddWithValue("@code", code);
                            int exists = Convert.ToInt32(existsCmd.ExecuteScalar() ?? 0);

                            if (exists > 0)
                            {
                                if (!updateExisting)
                                {
                                    skippedCount++;
                                    continue;
                                }

                                using var updateCmd = new SqlCommand(@"
UPDATE Category
SET Description = @description,
    WholeSale = @wholeSale,
    DisableChangePrice = @disableChangePrice,
    IsProductionCategory = @isProductionCategory,
    ShowInMainPos = @showInMainPos,
    ExcludeOnInventoryReport = @excludeOnInventoryReport,
    UpdatedDate = GETDATE()
WHERE Code = @code", connection);
                                updateCmd.Parameters.AddWithValue("@code", code);
                                updateCmd.Parameters.AddWithValue("@description", description);
                                updateCmd.Parameters.AddWithValue("@wholeSale", wholesale);
                                updateCmd.Parameters.AddWithValue("@disableChangePrice", disableChangePrice);
                                updateCmd.Parameters.AddWithValue("@isProductionCategory", isProductionCategory);
                                updateCmd.Parameters.AddWithValue("@showInMainPos", showInMainPos);
                                updateCmd.Parameters.AddWithValue("@excludeOnInventoryReport", excludeOnInventoryReport);
                                updateCmd.ExecuteNonQuery();
                            }
                            else
                            {
                                using var insertCmd = new SqlCommand(@"
INSERT INTO Category (Code, Description, WholeSale, DisableChangePrice, IsProductionCategory, ShowInMainPos, ExcludeOnInventoryReport)
VALUES (@code, @description, @wholeSale, @disableChangePrice, @isProductionCategory, @showInMainPos, @excludeOnInventoryReport)", connection);
                                insertCmd.Parameters.AddWithValue("@code", code);
                                insertCmd.Parameters.AddWithValue("@description", description);
                                insertCmd.Parameters.AddWithValue("@wholeSale", wholesale);
                                insertCmd.Parameters.AddWithValue("@disableChangePrice", disableChangePrice);
                                insertCmd.Parameters.AddWithValue("@isProductionCategory", isProductionCategory);
                                insertCmd.Parameters.AddWithValue("@showInMainPos", showInMainPos);
                                insertCmd.Parameters.AddWithValue("@excludeOnInventoryReport", excludeOnInventoryReport);
                                insertCmd.ExecuteNonQuery();
                            }

                            successCount++;
                        }
                        catch (Exception rowEx)
                        {
                            errors.Add($"Row {row}: {rowEx.Message}");
                        }
                    }
                }

                RefreshCategoryGrid(grid, countLabel);

                string resultMessage = $"Import completed!\n\nSuccessful: {successCount} categories\nSkipped: {skippedCount} categories\nErrors: {errors.Count} categories";
                if (errors.Count > 0)
                {
                    resultMessage += "\n\nErrors:\n" + string.Join("\n", errors.Take(10));
                    if (errors.Count > 10)
                        resultMessage += "\n... and more";
                }

                MessageBox.Show(resultMessage, "Category Import Results", MessageBoxButtons.OK, errors.Count == 0 ? MessageBoxIcon.Information : MessageBoxIcon.Warning);
            }

            try
            {
                // Ensure Category table exists
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    EnsureCategoryTableSchema(connection);

                    // Insert default categories if table is empty
                    var checkCount = new SqlCommand("SELECT COUNT(*) FROM Category", connection);
                    int categoryCount = (int)checkCount.ExecuteScalar();

                    if (categoryCount == 0)
                    {
                        var insertDefaults = new SqlCommand(@"
                            INSERT INTO Category (Code, Description, WholeSale, IsProductionCategory, ShowInMainPos) VALUES 
                            ('FISH', 'Fish and Aquatic Animals', 0, 0, 1),
                            ('STONES', 'Decorative Stones and Rocks', 0, 0, 1),
                            ('WOODS', 'Driftwood and Aquatic Plants', 0, 0, 1),
                            ('AQUARIUMS', 'Aquarium Tanks', 0, 0, 1),
