                    Size = new Size(120, 22),
                    Font = new Font("Arial", 9, FontStyle.Regular),
                    Checked = false
                };
                disableChangePriceCheckBox.Anchor = AnchorStyles.Right | AnchorStyles.Bottom;

                var isProductionCategoryCheckBox = new CheckBox
                {
                    Text = "Production",
                    Location = new Point(700, 558),
                    Size = new Size(95, 22),
                    Font = new Font("Arial", 9, FontStyle.Regular),
                    Checked = false
                };
                isProductionCategoryCheckBox.Anchor = AnchorStyles.Right | AnchorStyles.Bottom;

                var excludeOnInventoryReportCheckBox = new CheckBox
                {
                    Text = "Exclude on Inventory Report",
                    Location = new Point(700, 586),
                    Size = new Size(190, 22),
                    Font = new Font("Arial", 9, FontStyle.Regular),
                    Checked = false
                };
                excludeOnInventoryReportCheckBox.Anchor = AnchorStyles.Right | AnchorStyles.Bottom;

                var addButton = new Button
                {
                    Text = "Add",
                    Location = new Point(1085, 556),
                    Size = new Size(65, 30),
                    BackColor = Color.Green,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 9, FontStyle.Bold)
                };
                addButton.Anchor = AnchorStyles.Right | AnchorStyles.Bottom;

                addButton.Click += (s, args) =>
                {
                    string newCode = newCodeTextBox.Text.Trim().ToUpper();
                    string newDesc = newDescTextBox.Text.Trim();

                    if (string.IsNullOrWhiteSpace(newCode) || string.IsNullOrWhiteSpace(newDesc))
                    {
                        MessageBox.Show("Both Code and Description are required.", "Validation Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        return;
                    }

                    try
                    {
                        using (var connection = new SqlConnection(connectionString))
                        {
                            connection.Open();
                            EnsureCategoryTableSchema(connection);
                            var cmd = new SqlCommand("INSERT INTO Category (Code, Description, WholeSale, DisableChangePrice, IsProductionCategory, ShowInMainPos, ExcludeOnInventoryReport) VALUES (@code, @description, @wholeSale, @disableChangePrice, @isProductionCategory, @showInMainPos, @excludeOnInventoryReport)", connection);
                            cmd.Parameters.AddWithValue("@code", newCode);
                            cmd.Parameters.AddWithValue("@description", newDesc);
                            cmd.Parameters.AddWithValue("@wholeSale", wholeSaleCheckBox.Checked);
                            cmd.Parameters.AddWithValue("@disableChangePrice", disableChangePriceCheckBox.Checked);
                            cmd.Parameters.AddWithValue("@isProductionCategory", isProductionCategoryCheckBox.Checked);
                            cmd.Parameters.AddWithValue("@showInMainPos", showInMainPosCheckBox.Checked);
                            cmd.Parameters.AddWithValue("@excludeOnInventoryReport", excludeOnInventoryReportCheckBox.Checked);
                            cmd.ExecuteNonQuery();
                        }
                        RefreshCategoryGrid(dataGridView, countLabel);
                        newCodeTextBox.Clear();
                        newDescTextBox.Clear();
                        showInMainPosCheckBox.Checked = true;
                        wholeSaleCheckBox.Checked = false;
                        disableChangePriceCheckBox.Checked = false;
                        isProductionCategoryCheckBox.Checked = false;
                        excludeOnInventoryReportCheckBox.Checked = false;
                        MessageBox.Show("Category added successfully!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Failed to add category: {ex.Message}\n\nCategory code might already exist.", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                };

                var syncButton = new Button
                {
                    Text = "Sync",
                    Location = new Point(890, 612),
                    Size = new Size(80, 30),
                    BackColor = Color.MidnightBlue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 9, FontStyle.Bold)
                };
                syncButton.Anchor = AnchorStyles.Right | AnchorStyles.Bottom;
                syncButton.Click += async (s, args) =>
                {
                    await RunManualCategorySyncAsync(syncButton, () => RefreshCategoryGrid(dataGridView, countLabel));
                };

                var exportButton = new Button
                {
                    Text = "Export",
                    Location = new Point(710, 612),
                    Size = new Size(80, 30),
                    BackColor = Color.SeaGreen,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 9, FontStyle.Bold)
                };
                exportButton.Anchor = AnchorStyles.Right | AnchorStyles.Bottom;
                exportButton.Click += (s, args) =>
                {
                    try
                    {
                        ExportCategoriesToExcel();
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Failed to export categories: {ex.Message}", "Export Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                };

                var importButton = new Button
                {
                    Text = "Import",
                    Location = new Point(800, 612),
                    Size = new Size(80, 30),
                    BackColor = Color.DarkOrange,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 9, FontStyle.Bold)
                };
                importButton.Anchor = AnchorStyles.Right | AnchorStyles.Bottom;
                importButton.Click += (s, args) =>
                {
                    try
                    {
                        ImportCategoriesFromExcel(dataGridView, countLabel);
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Failed to import categories: {ex.Message}", "Import Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                };

                var closeButton = new Button
                {
                    Text = "Close",
                    Location = new Point(980, 612),
                    Size = new Size(80, 30),
                    BackColor = Color.DarkBlue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 9, FontStyle.Bold)
                };
                closeButton.Anchor = AnchorStyles.Right | AnchorStyles.Bottom;
                closeButton.Click += (s, args) => categoryForm.Close();

                categoryForm.Controls.AddRange(new Control[] {
                    dataGridView, countLabel, newCodeLabel, newCodeTextBox, newDescLabel, newDescTextBox, showInMainPosCheckBox, wholeSaleCheckBox, disableChangePriceCheckBox, isProductionCategoryCheckBox, excludeOnInventoryReportCheckBox, addButton, exportButton, importButton, syncButton, closeButton
                });

                RefreshCategoryGrid(dataGridView, countLabel);
                categoryForm.ShowDialog();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to open Category Management: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        // Handler for Items Management button
        private void ItemsMgmtButton_Click(object? sender, EventArgs e)
        {
            void RefreshItemsGrid(DataGridView grid, Label countLabel)
            {
                grid.Rows.Clear();
                int rowCount = 0;
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var command = new SqlCommand(@"
               SELECT i.Code, i.Name, i.Description, i.Cost, i.Price, i.WholesalePrice, i.RetailPrice, i.PromoPrice, 
                   c.Description as CategoryName, i.CategoryCode, i.Brand, i.SKU, 
                   i.MinimumStock, i.IsActive,
                   ISNULL(SUM(ile.Quantity), 0) as CalculatedStock
               FROM Items i 
               LEFT JOIN Category c ON i.CategoryCode = c.Code 
               LEFT JOIN ItemLedgerEntry ile ON i.Code = ile.ItemCode
               GROUP BY i.Code, i.Name, i.Description, i.Cost, i.Price, i.WholesalePrice, i.RetailPrice, i.PromoPrice, 
                     c.Description, i.CategoryCode, i.Brand, i.SKU, i.MinimumStock, i.IsActive
               ORDER BY c.Description, i.Name", connection);
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string code = reader["Code"].ToString() ?? "";
                            string name = reader["Name"].ToString() ?? "";
                            string description = reader["Description"].ToString() ?? "";
                            decimal cost = reader["Cost"] != DBNull.Value ? Convert.ToDecimal(reader["Cost"]) : 0m;
                            decimal price = reader["Price"] != DBNull.Value ? Convert.ToDecimal(reader["Price"]) : 0m;
                            decimal wholesalePrice = reader["WholesalePrice"] != DBNull.Value ? Convert.ToDecimal(reader["WholesalePrice"]) : 0m;
                            decimal retailPrice = reader["RetailPrice"] != DBNull.Value ? Convert.ToDecimal(reader["RetailPrice"]) : 0m;
                            string categoryName = reader["CategoryName"].ToString() ?? "";
                            string categoryCode = reader["CategoryCode"].ToString() ?? "";
                            string brand = reader["Brand"].ToString() ?? "";
                            string sku = reader["SKU"].ToString() ?? "";
                            int stock = reader["CalculatedStock"] != DBNull.Value ? Convert.ToInt32(reader["CalculatedStock"]) : 0;
                            int minStock = reader["MinimumStock"] != DBNull.Value ? Convert.ToInt32(reader["MinimumStock"]) : 0;
                            bool isActive = reader["IsActive"] != DBNull.Value ? Convert.ToBoolean(reader["IsActive"]) : true;

                            string status = stock <= minStock ? "LOW STOCK" : "OK";
                            string activeStatus = isActive ? "Active" : "Inactive";

                            int rowIndex = grid.Rows.Add(code, name, description, cost, price, wholesalePrice, retailPrice,
                                         categoryName, brand, sku, stock, minStock, status, activeStatus,
                                         "Edit", "Delete");

                            // Color low stock items red
                            if (stock <= minStock)
                            {
                                grid.Rows[rowIndex].DefaultCellStyle.BackColor = Color.LightCoral;
                                grid.Rows[rowIndex].DefaultCellStyle.ForeColor = Color.DarkRed;
                            }

                            rowCount++;
                        }
                    }
                }
                countLabel.Text = $"Total Items: {rowCount}";
            }

            try
            {
                // Ensure Items table exists
                // using (var connection = new SqlConnection(connectionString))
                // {
                //     connection.Open();
                //     var createTableCmd = new SqlCommand(@"
                //         IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Items')
                //         BEGIN
                //             CREATE TABLE Items (
                //                     ID INT IDENTITY(1,1) PRIMARY KEY,
                //                     Name NVARCHAR(255) NOT NULL,
                //                     Description NVARCHAR(MAX),
                //                     Cost DECIMAL(10,2) DEFAULT 0,
                //                     Price DECIMAL(10,2) NOT NULL DEFAULT 0,
                //                     WholesalePrice DECIMAL(10,2) DEFAULT 0,
                //                     RetailPrice DECIMAL(10,2) DEFAULT 0,
                //                     PromoPrice DECIMAL(10,2) DEFAULT 0,
                //                     CategoryCode NVARCHAR(50),
                //                     Brand NVARCHAR(100),
                //                     SKU NVARCHAR(100),
                //                     QuantityInStock INT DEFAULT 0,
                //                     MinimumStock INT DEFAULT 0,
                //                     IsActive BIT DEFAULT 1,
                //                     CreatedDate DATETIME2 DEFAULT GETDATE(),
                //                     UpdatedDate DATETIME2 DEFAULT GETDATE(),
                //                     CONSTRAINT FK_Items_Category FOREIGN KEY (CategoryCode) REFERENCES Category(Code)
                //                 )
                //         END
                //         ELSE
                //         BEGIN
                //             -- Add Cost column if it doesn't exist
                //             IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Items' AND COLUMN_NAME = 'Cost')
                //             BEGIN
                //                 ALTER TABLE Items ADD Cost DECIMAL(10,2) DEFAULT 0
                //             END
                //             -- Add PromoPrice column if missing
                //             IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Items' AND COLUMN_NAME = 'PromoPrice')
                //             BEGIN
                //                 ALTER TABLE Items ADD PromoPrice DECIMAL(10,2) DEFAULT 0
                //             END
                //         END", connection);
                //     createTableCmd.ExecuteNonQuery();
                // }

                var itemsForm = new Form
                {
                    Text = "Items Management",
                    Size = new Size(1400, 700),
                    StartPosition = FormStartPosition.CenterParent,
                    BackColor = Color.White,
                    WindowState = FormWindowState.Maximized
                };

                var dataGridView = new DataGridView
                {
                    Location = new Point(10, 10),
                    Size = new Size(1360, 500),
                    ReadOnly = true,
                    AllowUserToAddRows = false,
                    AllowUserToDeleteRows = false,
                    AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.None,
                    ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                    SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                    BackgroundColor = Color.White,
                    BorderStyle = BorderStyle.Fixed3D,
                    RowHeadersVisible = false
                };

                // Add columns
                dataGridView.Columns.Add("Code", "Code");
                dataGridView.Columns.Add("Name", "Product Name");
                dataGridView.Columns.Add("Description", "Description");
                dataGridView.Columns.Add("Cost", "Cost");
