                dataGridView.Columns["Active"].Width = 60;

                // Format currency columns
                dataGridView.Columns["Cost"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["Price"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["PromoPrice"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["WholesalePrice"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["RetailPrice"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["Cost"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleRight;
                dataGridView.Columns["PromoPrice"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleRight;
                dataGridView.Columns["Price"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleRight;
                dataGridView.Columns["WholesalePrice"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleRight;
                dataGridView.Columns["RetailPrice"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleRight;

                // Center align other columns
                dataGridView.Columns["Stock"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleCenter;
                dataGridView.Columns["MinStock"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleCenter;
                dataGridView.Columns["Status"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleCenter;
                dataGridView.Columns["Active"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleCenter;

                var countLabel = new Label
                {
                    Text = "Total Items: 0",
                    Location = new Point(10, 520),
                    Size = new Size(250, 20),
                    Font = new Font("Arial", 10, FontStyle.Bold),
                    ForeColor = Color.DarkBlue
                };

                // Handle button clicks
                dataGridView.CellClick += (gridSender, gridE) =>
                {
                    if (gridE.RowIndex >= 0)
                    {
                        var row = dataGridView.Rows[gridE.RowIndex];
                        string itemCode = row.Cells["Code"].Value?.ToString() ?? "";
                        string itemName = row.Cells["Name"].Value?.ToString() ?? "";

                        if (gridE.ColumnIndex == dataGridView.Columns["Edit"].Index)
                        {
                            ShowItemEditForm(itemCode, () => RefreshItemsGrid(dataGridView, countLabel));
                        }
                        else if (gridE.ColumnIndex == dataGridView.Columns["Delete"].Index)
                        {
                            var result = MessageBox.Show($"Are you sure you want to delete item '{itemName}' (Code: {itemCode})?\n\nThis action cannot be undone.",
                                                       "Confirm Delete", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);

                            if (result == DialogResult.Yes)
                            {
                                try
                                {
                                    using (var connection = new SqlConnection(connectionString))
                                    {
                                        connection.Open();
                                        var cmd = new SqlCommand("DELETE FROM Items WHERE Code = @code", connection);
                                        cmd.Parameters.AddWithValue("@code", itemCode);
                                        int affected = cmd.ExecuteNonQuery();

                                        if (affected > 0)
                                        {
                                            RefreshItemsGrid(dataGridView, countLabel);
                                            MessageBox.Show("Item deleted successfully!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                        }
                                        else
                                        {
                                            MessageBox.Show("Item not found.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                                        }
                                    }
                                }
                                catch (Exception ex)
                                {
                                    MessageBox.Show($"Failed to delete item: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                                }
                            }
                        }
                    }
                };

                // Add new item button
                var addItemButton = new Button
                {
                    Text = "Add New Item",
                    Location = new Point(10, 550),
                    Size = new Size(120, 40),
                    BackColor = Color.Green,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
