                // Add Excel Export button
                var excelExportButton = new Button
                {
                    Text = "Export to Excel",
                    Location = new Point(140, 550),
                    Size = new Size(130, 40),
                    BackColor = Color.DarkGreen,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                excelExportButton.Click += (s, args) => ExcelExportButton_Click(s, args);

                // Add Excel Import button
                var excelImportButton = new Button
                {
                    Text = "Import from Excel",
                    Location = new Point(280, 550),
                    Size = new Size(130, 40),
                    BackColor = Color.DarkRed,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                excelImportButton.Click += (s, args) =>
                {
                    ExcelImportButton_Click(s, args);
