                var closeButton = new Button
                {
                    Text = "Close",
                    Location = new Point(1300, 550),
                    Size = new Size(70, 40),
                    BackColor = Color.DarkBlue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                closeButton.Click += (s, args) => itemsForm.Close();

                itemsForm.Controls.AddRange(new Control[] {
                    dataGridView, countLabel, addItemButton, excelExportButton, excelImportButton, closeButton
                });

                RefreshItemsGrid(dataGridView, countLabel);
                itemsForm.ShowDialog();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to open Items Management: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

