            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                var catCommand = new SqlCommand("SELECT Code, Description FROM Category ORDER BY Description", connection);
                using (var reader = catCommand.ExecuteReader())
                {
                    int buttonIndex = 0;
                    int buttonsPerRow = 4;
                    int buttonWidth = 90;
                    int buttonHeight = 25;
                    int spacing = 5;
                    int startX = 5;
                    int startY = 30;

                    while (reader.Read())
                    {
                        string code = reader["Code"].ToString() ?? "";
                        string description = reader["Description"].ToString() ?? "";

                        int row = buttonIndex / buttonsPerRow;
                        int col = buttonIndex % buttonsPerRow;

                        var categoryButton = new Button
                        {
                            Text = description,
                            Tag = code,
                            Location = new Point(startX + col * (buttonWidth + spacing), startY + row * (buttonHeight + spacing)),
                            Size = new Size(buttonWidth, buttonHeight),
                            BackColor = Color.LightBlue,
                            ForeColor = Color.Black,
                            Font = new Font("Arial", 8, FontStyle.Regular),
                            UseVisualStyleBackColor = false
                        };

                        categoryButton.Click += (s, e) =>
                        {
                            var btn = (Button)s!;
                            selectedCategoryCode = btn.Tag?.ToString() ?? "";
                            selectedCategoryLabel.Text = $"Selected: {btn.Text}";
                            selectedCategoryLabel.ForeColor = Color.DarkGreen;

                            // Reset all category buttons to normal color
                            foreach (Control ctrl in categoryPanel.Controls)
                            {
                                if (ctrl is Button catBtn)
                                {
                                    catBtn.BackColor = Color.LightBlue;
                                }
                            }
                            // Highlight selected button
                            btn.BackColor = Color.DarkBlue;
                            btn.ForeColor = Color.White;
                        };

                        categoryPanel.Controls.Add(categoryButton);
                        buttonIndex++;
                    }
                }
            }

            // Minimum Stock (on same row as Category)
            var minStockLabel = new Label
            {
                Text = "Minimum:",
                Location = new Point(330, 300),
                Size = new Size(70, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            var minStockNumeric = new NumericUpDown
            {
                Location = new Point(410, 298),
                Size = new Size(100, 25),
                Font = new Font("Arial", 10),
                Maximum = 999999,
                Minimum = 0
            };

            // Brand
            var brandLabel = new Label
            {
                Text = "Brand:",
                Location = new Point(20, 340),
                Size = new Size(100, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            var brandTextBox = new TextBox
            {
                Location = new Point(130, 338),
                Size = new Size(180, 25),
                Font = new Font("Arial", 10)
            };

            // SKU
            var skuLabel = new Label
            {
                Text = "SKU:",
                Location = new Point(330, 340),
                Size = new Size(50, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            var skuTextBox = new TextBox
            {
                Location = new Point(390, 338),
                Size = new Size(140, 25),
                Font = new Font("Arial", 10)
            };

            // Quantity In Stock
            var stockLabel = new Label
            {
                Text = "Quantity in Stock:",
                Location = new Point(20, 380),
                Size = new Size(120, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            var stockNumeric = new NumericUpDown
            {
                Location = new Point(150, 378),
                Size = new Size(100, 25),
                Font = new Font("Arial", 10),
                Maximum = 999999,
                // Allow negative stock values (backorders/adjustments); databases may contain negative quantities
                Minimum = -999999
            };

            // Is Active
            var activeCheckBox = new CheckBox
            {
                Text = "Active",
                Location = new Point(130, 420),
                Size = new Size(80, 25),
                Font = new Font("Arial", 10, FontStyle.Bold),
                Checked = true
            };

            // Load existing data if editing
            if (!isNewItem)
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var cmd = new SqlCommand(@"
               SELECT Code, Name, Description, Cost, Price, PromoPrice, WholesalePrice, RetailPrice, CategoryCode, 
                   Brand, SKU, QuantityInStock, MinimumStock, IsActive 
                        FROM Items WHERE Code = @code", connection);
                    cmd.Parameters.AddWithValue("@code", itemCode);
                    using (var reader = cmd.ExecuteReader())
                    {
                        if (reader.Read())
                        {
                            codeTextBox.Text = reader["Code"].ToString() ?? "";
                            codeTextBox.ReadOnly = true; // Code should not be editable when editing
                            nameTextBox.Text = reader["Name"].ToString() ?? "";
                            descTextBox.Text = reader["Description"].ToString() ?? "";
                            costNumeric.Value = reader["Cost"] != DBNull.Value ? Convert.ToDecimal(reader["Cost"]) : 0;
                            priceNumeric.Value = reader["Price"] != DBNull.Value ? Convert.ToDecimal(reader["Price"]) : 0;
                            promoNumeric.Value = reader["PromoPrice"] != DBNull.Value ? Convert.ToDecimal(reader["PromoPrice"]) : 0;
                            wholesaleNumeric.Value = reader["WholesalePrice"] != DBNull.Value ? Convert.ToDecimal(reader["WholesalePrice"]) : 0;
                            retailNumeric.Value = reader["RetailPrice"] != DBNull.Value ? Convert.ToDecimal(reader["RetailPrice"]) : 0;
                            brandTextBox.Text = reader["Brand"].ToString() ?? "";
                            skuTextBox.Text = reader["SKU"].ToString() ?? "";
                            stockNumeric.Value = reader["QuantityInStock"] != DBNull.Value ? Convert.ToInt32(reader["QuantityInStock"]) : 0;
                            minStockNumeric.Value = reader["MinimumStock"] != DBNull.Value ? Convert.ToInt32(reader["MinimumStock"]) : 0;
                            activeCheckBox.Checked = reader["IsActive"] != DBNull.Value ? Convert.ToBoolean(reader["IsActive"]) : true;

                            string categoryCode = reader["CategoryCode"].ToString() ?? "";
                            selectedCategoryCode = categoryCode;

                            // Set the selected category in the UI
                            if (!string.IsNullOrEmpty(categoryCode))
                            {
                                foreach (Control ctrl in categoryPanel.Controls)
                                {
                                    if (ctrl is Button catBtn && catBtn.Tag?.ToString() == categoryCode)
                                    {
                                        selectedCategoryLabel.Text = $"Selected: {catBtn.Text}";
                                        selectedCategoryLabel.ForeColor = Color.DarkGreen;
                                        catBtn.BackColor = Color.DarkBlue;
                                        catBtn.ForeColor = Color.White;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Save button
            var saveButton = new Button
            {
                Text = "Save",
                Location = new Point(350, 550),
                Size = new Size(80, 35),
                BackColor = Color.Green,
                ForeColor = Color.White,
                Font = new Font("Arial", 11, FontStyle.Bold)
            };

            saveButton.Click += (s, args) =>
            {
                if (string.IsNullOrWhiteSpace(codeTextBox.Text))
                {
                    MessageBox.Show("Item code is required.", "Validation Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (string.IsNullOrWhiteSpace(nameTextBox.Text))
                {
                    MessageBox.Show("Product name is required.", "Validation Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                try
                {
                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();
                        SqlCommand cmd;

                        if (isNewItem)
                        {
                            // Check if code already exists
                            var checkCmd = new SqlCommand("SELECT COUNT(*) FROM Items WHERE Code = @code", connection);
                            checkCmd.Parameters.AddWithValue("@code", codeTextBox.Text.Trim());
                            int exists = (int)checkCmd.ExecuteScalar();

                            if (exists > 0)
                            {
                                MessageBox.Show("An item with this code already exists.", "Validation Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                                return;
                            }

                            cmd = new SqlCommand(@"
                                    INSERT INTO Items (Code, Name, Description, Cost, Price, PromoPrice, WholesalePrice, RetailPrice, CategoryCode, 
                                                     Brand, SKU, QuantityInStock, MinimumStock, IsActive)
                                    VALUES (@code, @name, @desc, @cost, @price, @promo, @wholesale, @retail, @category, @brand, @sku, @stock, @minStock, @active)", connection);
                            cmd.Parameters.AddWithValue("@code", codeTextBox.Text.Trim());
                        }
                        else
                        {
                            cmd = new SqlCommand(@"
                                    UPDATE Items SET Name = @name, Description = @desc, Cost = @cost, Price = @price, PromoPrice = @promo, WholesalePrice = @wholesale, 
                                                   RetailPrice = @retail, CategoryCode = @category, Brand = @brand, SKU = @sku, 
                                                   QuantityInStock = @stock, MinimumStock = @minStock, IsActive = @active, UpdatedDate = GETDATE()
                                    WHERE Code = @code", connection);
                            cmd.Parameters.AddWithValue("@code", itemCode);
                        }

                        cmd.Parameters.AddWithValue("@name", nameTextBox.Text.Trim());
                        cmd.Parameters.AddWithValue("@desc", descTextBox.Text.Trim());
                        cmd.Parameters.AddWithValue("@cost", costNumeric.Value);
                        cmd.Parameters.AddWithValue("@price", priceNumeric.Value);
                        cmd.Parameters.AddWithValue("@wholesale", wholesaleNumeric.Value);
                        cmd.Parameters.AddWithValue("@retail", retailNumeric.Value);
                        cmd.Parameters.AddWithValue("@category", !string.IsNullOrEmpty(selectedCategoryCode) ? selectedCategoryCode : (object)DBNull.Value);
                        cmd.Parameters.AddWithValue("@brand", brandTextBox.Text.Trim());
                        cmd.Parameters.AddWithValue("@sku", skuTextBox.Text.Trim());
                        cmd.Parameters.AddWithValue("@stock", (int)stockNumeric.Value);
                        cmd.Parameters.AddWithValue("@minStock", (int)minStockNumeric.Value);
                        cmd.Parameters.AddWithValue("@active", activeCheckBox.Checked);
                        // Promo price
                        cmd.Parameters.AddWithValue("@promo", promoNumeric.Value);

                        cmd.ExecuteNonQuery();
                    }

                    refreshCallback();
                    MessageBox.Show($"Item {(isNewItem ? "added" : "updated")} successfully!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    editForm.Close();
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Failed to {(isNewItem ? "add" : "update")} item: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            // Cancel button
            var cancelButton = new Button
            {
                Text = "Cancel",
                Location = new Point(450, 550),
                Size = new Size(80, 35),
                BackColor = Color.Gray,
                ForeColor = Color.White,
                Font = new Font("Arial", 11, FontStyle.Bold)
            };
            cancelButton.Click += (s, args) => editForm.Close();

            editForm.Controls.AddRange(new Control[] {
                codeLabel, codeTextBox, nameLabel, nameTextBox, descLabel, descTextBox, costLabel, costNumeric,
                priceLabel, priceNumeric, promoLabel, promoNumeric, wholesaleLabel, wholesaleNumeric, retailLabel, retailNumeric,
                categoryLabel, categoryPanel, brandLabel, brandTextBox, skuLabel, skuTextBox,
                stockLabel, stockNumeric, minStockLabel, minStockNumeric, activeCheckBox, saveButton, cancelButton
            });

            editForm.ShowDialog();
        }

        private void CreateButtonGrid()
        {
            buttonPanel = new Panel
            {
                Dock = DockStyle.Bottom,
                Height = 240,
                BackColor = Color.LightGray,
                BorderStyle = BorderStyle.FixedSingle
            };
            // Make panel scrollable and responsive
            buttonPanel.AutoScroll = true;
            // Create category-based button grid
            CreateCategoryButtons();
            // Rebuild buttons on resize so the grid remains responsive
            buttonPanel.Resize += (s, e) =>
            {
                // Don't overwrite tender buttons while in checkout mode.
                if (!isInCheckoutMode)
                    CreateCategoryButtons();
            };
            this.Controls.Add(buttonPanel);
        }

        private void CreateCategoryButtons()
        {
            buttonPanel.Controls.Clear();
            originalBottomButtons.Clear();

            // Ensure we start at the top of the scrollable area so buttons are visible.
            try { buttonPanel.AutoScrollPosition = new Point(0, 0); } catch { }

            int maxColumns = 9;
            int buttonHeight = 50;

            // Use a TableLayoutPanel to avoid overlap (DPI-safe + responsive).
            var grid = new TableLayoutPanel
            {
                ColumnCount = maxColumns,
                RowCount = 0,
                Dock = DockStyle.Top,
                AutoSize = true,
                AutoSizeMode = AutoSizeMode.GrowAndShrink,
                GrowStyle = TableLayoutPanelGrowStyle.AddRows,
                Padding = new Padding(10),
                Margin = new Padding(0),
                BackColor = buttonPanel.BackColor
            };
            grid.SuspendLayout();
            grid.ColumnStyles.Clear();
            float colPercent = 100f / maxColumns;
            for (int i = 0; i < maxColumns; i++)
                grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, colPercent));

            // Define category colors
            var categoryColors = new Dictionary<string, Color>
            {
                { "FISH", Color.DarkOrange },
                { "STONES", Color.SaddleBrown },
                { "WOODS", Color.Sienna },
                { "AQUARIUMS", Color.DarkSlateBlue },
                { "ACCESSORIES", Color.DarkCyan },
                { "PLANTS", Color.DarkGreen },
                { "EQUIPMENT", Color.DarkSlateGray },
                { "FOOD", Color.Brown }
            };

            List<dynamic> allButtons = new List<dynamic>();

            // Load categories from database
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    EnsureCategoryTableSchema(connection);
                    var command = new SqlCommand("SELECT Code, Description FROM Category WHERE ShowInMainPos = 1 ORDER BY Description", connection);
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string code = reader["Code"].ToString() ?? "";
                            string description = reader["Description"].ToString() ?? "";

                            // Get color for category or use default
                            Color buttonColor = categoryColors.ContainsKey(code)
                                ? categoryColors[code]
                                : Color.MediumSlateBlue;

                            allButtons.Add(new
                            {
                                Text = description.ToUpper(),
                                Color = buttonColor,
                                Category = "Category_" + code,
                                Type = "Category"
                            });
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error loading categories: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }

            // Add essential action buttons. Only show SETTINGS if current user is a super user.
            var baseActions = new List<dynamic>
            {
                new { Text = "ALL ITEMS", Color = Color.MediumSlateBlue, Category = "All", Type = "Action" },
                new { Text = "CUSTOM\nAQUARIUM", Color = Color.Blue, Category = "CustomAquarium", Type = "Action" },
                // Stand Price Calculator button placed after Custom Aquarium
                new { Text = "STAND\nCALC", Color = Color.DarkCyan, Category = "StandPriceCalculator", Type = "Action" },
                new { Text = "VOID TRANSACTION", Color = Color.DarkRed, Category = "VoidTransaction", Type = "Action" },
                new { Text = "VOID\nLINE", Color = Color.DarkRed, Category = "VoidLine", Type = "Action" },
                new { Text = "QTY\nCHANGE", Color = Color.Brown, Category = "QtyChange", Type = "Action" },
                // New CHANGE PRICE action button
                new { Text = "CHANGE\nPRICE", Color = Color.OrangeRed, Category = "ChangePrice", Type = "Action" }
            };

            if (CurrentUser.IsSuperUser)
            {
                baseActions.Add(new { Text = "SETTINGS", Color = Color.Green, Category = "Settings", Type = "Action" });
            }

            // Buttons that should always follow
            baseActions.AddRange(new[]
            {
                new { Text = "EOD", Color = Color.DarkRed, Category = "EOD", Type = "Action" },
                new { Text = "TENDER DECLARATION", Color = Color.DarkRed, Category = "TENDER DECLARATION", Type = "Action" },
                new { Text = "STOCK\nCOUNTS", Color = Color.DarkCyan, Category = "StockCounts", Type = "Action" },
                new { Text = "ITEM\nINVENTORY", Color = Color.Purple, Category = "ItemInventory", Type = "Action" },
                new { Text = "SERIAL\nTRACKER", Color = Color.MediumPurple, Category = "SerialTracker", Type = "Action" },
                new { Text = "EXPENSE", Color = Color.DarkOrange, Category = "Expense", Type = "Action" },
                new { Text = "INCOME", Color = Color.DarkGreen, Category = "Income", Type = "Action" },
                new { Text = "CUSTOM STICKERS", Color = Color.Blue, Category = "CustomStickers", Type = "Action" },
                new { Text = "PURCHASE ORDER", Color = Color.MediumBlue, Category = "PurchaseOrder", Type = "Action" },
                new { Text = "TRANSFER\nREQUEST", Color = Color.DodgerBlue, Category = "TransferRequest", Type = "Action" },
                new { Text = "POSTED TRANSFER ORDER", Color = Color.SteelBlue, Category = "TransferOrder", Type = "Action" },
                new { Text = "REPORTS", Color = Color.DarkSlateBlue, Category = "Reports", Type = "Action" },
                new { Text = "LOGOFF", Color = Color.Red, Category = "Logoff", Type = "Action" }
            });

            allButtons.AddRange(baseActions);

            // Create buttons in grid layout
            int currentRow = 0;
            int currentCol = 0;

            foreach (var data in allButtons)
            {
                // If next column would exceed maxColumns, move to next row
                if (currentCol >= maxColumns)
                {
                    currentCol = 0;
                    currentRow++;
                }

                // If this is the SETTINGS button, make it span two columns (wider)
                bool isSettings = (data.Category?.ToString() ?? "") == "Settings";
                // If settings would overflow the row (e.g., currentCol == maxColumns -1), push to next row first
                if (isSettings && currentCol == (maxColumns - 1))
                {
                    currentCol = 0;
                    currentRow++;
                }

                while (grid.RowCount <= currentRow)
                {
                    grid.RowCount++;
                    grid.RowStyles.Add(new RowStyle(SizeType.Absolute, buttonHeight + 6));
                }

                var button = new Button
                {
                    Text = data.Text,
                    AutoSize = false,
                    // Category-type buttons should be black per user request; keep action buttons' configured colors
                    BackColor = (data.Type?.ToString() ?? "") == "Category" ? Color.Black : data.Color,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 9, FontStyle.Bold),
                    Tag = data.Category,
                    TextAlign = ContentAlignment.MiddleCenter,
                    UseVisualStyleBackColor = false,
                    Dock = DockStyle.Fill,
                    Margin = new Padding(2),
                    MinimumSize = new Size(0, buttonHeight)
                };
                button.Click += ButtonGrid_Click;
                grid.Controls.Add(button, currentCol, currentRow);
                if (isSettings)
                    grid.SetColumnSpan(button, 2);
                originalBottomButtons.Add(button);

                // Advance column index; if button spanned two columns advance an extra column
                currentCol++;
                if (isSettings) currentCol++;
            }

            grid.ResumeLayout(true);
            buttonPanel.Controls.Add(grid);
        }

        private void ButtonGrid_Click(object? sender, EventArgs e)
        {



            if (sender is Button button && button.Tag != null)
            {
                string action = button.Tag.ToString() ?? "";

                // Handle category buttons
                if (action.StartsWith("Category_"))
                {
                    string categoryCode = action.Replace("Category_", "");
                    LoadProductsByCategory(categoryCode);
                    return;
                }

                // Handle other actions
                switch (action)
                {
                    case "VoidTransaction":
                        // VOID TRANSACTION functionality: clear the current transaction
                        DialogResult confirmResult = MessageBox.Show("Are you sure you want to void the entire transaction?", "Confirm Void Transaction", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);
                        if (confirmResult == DialogResult.Yes)
                        {
                            salesListView.Items.Clear();
                            currentTotal = 0;
                            currentDiscount = 0;
                            currentDiscountDescription = string.Empty;
                            grandTotal = 0;
                            payments.Clear();
                            totalPaid = 0;
                            currentReceiptNo = "";
                            currentTransNo = "";

                            // Reset salesperson when voiding a transaction
                            currentSalesPersonCode = null;
                            currentSalesPersonName = null;
                            UpdateSalesPersonDisplay();

                            UpdateTotal();
                            // Optionally, clear payment list view and other UI elements
                            if (paymentsListView != null)
                                paymentsListView.Items.Clear();
                            if (remainingBalanceLabel != null)
                                remainingBalanceLabel.Text = "";
                        }
                        break;
                    case "All":
                        ShowSalesItemsDialog();
                        break;
                    case "CustomAquarium":
                        ShowCustomAquariumDialog();
                        break;
                    case "VoidLine":
                        VoidSelectedLine();
                        break;
                    case "StandPriceCalculator":
                        try
                        {
                            using (var sp = new StandPriceCalculatorForm())
                            {
                                var dr = sp.ShowDialog(this);
                                if (dr == DialogResult.OK && sp.SelectedPrice > 0)
                                {
                                    try
                                    {
                                        AddToSale(sp.SelectedDescription ?? "Stand", 1, sp.SelectedPrice, "STAND");
                                        MessageBox.Show($"Added {sp.SelectedDescription} to sale!\nPrice: {sp.SelectedPrice:N2}", "Stand Added", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                    }
                                    catch { }
                                }
                            }
                        }
                        catch { }
                        break;
                    case "QtyChange":
                        ChangeQuantity();
                        break;
                    case "ChangePrice":
                        ChangePrice();
                        break;
                    case "StockJournal":
                        using (var sj = new StockJournalForm())
                        {
                            sj.ShowDialog(this);
                        }
                        break;
                    case "ItemInventory":
                        ShowItemsButton_Click(this, EventArgs.Empty);
                        break;
                    case "SerialTracker":
                        using (var tracker = new ProductSerialTrackingForm())
                        {
                            tracker.ShowDialog(this);
                        }
                        break;
                    case "Reports":
                        ShowReportsDialog();
                        break;
                    case "TENDER DECLARATION":
                        ShowTenderDeclarationDialog();
                        break;
                    case "StockCounts":
                        try
                        {
                            using (var scf = new StockCountsForm())
                            {
                                scf.ShowDialog(this);
                            }
                        }
                        catch { }
                        break;
                    // Tender Declaration button beside Settings           
                    case "Settings":
                        ShowSettingsDialog();
                        break;
                    case "EOD":
                        ShowEndOfDayDialog();
                        break;
                    case "Logoff":
                        LogoffUser();
                        break;
                    case "Expense":
                        ShowExpenseDialog();
                        break;
                    case "Income":
                        ShowIncomeDialog();
                        break;
                    case "CustomStickers":
                        ShowCustomStickersDialog();
                        break;
                    case "TransferOrder":
                        try
                        {
                            using (var transferHeaderForm = new TransferHeaderForm())
                            {
                                transferHeaderForm.ShowDialog(this);
                            }
                        }
                        catch (Exception ex)
                        {
                            try { MessageBox.Show(this, $"Failed to open Transfer Order: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error); } catch { }
                        }
                        break;
                    case "TransferRequest":
                        try
                        {
                            using (var transferHeaderForm = new TransferHeaderForm(TransferOrderData.TransferRequests))
                            {
                                transferHeaderForm.ShowDialog(this);
                            }
                        }
                        catch (Exception ex)
                        {
                            try { MessageBox.Show(this, $"Failed to open Transfer Request: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error); } catch { }
                        }
                        break;
                    case "DeleteTrans":
                        // Delete all data from specified tables
                        var confirmDelete = MessageBox.Show("Are you sure you want to delete ALL data from key tables? This action cannot be undone.", "Confirm Data Deletion", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);
                        if (confirmDelete == DialogResult.Yes)
                        {
                            try
                            {
                                using (var connection = new SqlConnection(connectionString))
                                {
                                    connection.Open();
                                    var tables = new[] {
                                        "AdvanceOrderHeader",
                                        "AdvanceOrderLines",
                                        "CashFloatLines",
                                        "ItemLedgerEntry",
                                        "LoginLogs",
                                        "Prod_Order_Header",
                                        "Prod_Order_Lines",
                                        "TenderDeclLines",
                                        "TransactionHeader",
                                        "TransPaymentEntry"
                                    };
                                    foreach (var table in tables)
                                    {
                                        var cmd = new SqlCommand($"DELETE FROM [{table}]", connection);
                                        cmd.ExecuteNonQuery();
                                    }
                                }
                                MessageBox.Show("All specified tables have been cleared.", "Data Deleted", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show($"Error deleting data: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            }
                        }
                        break;
                    case "PurchaseOrder":
                        ShowPurchaseDialog();
                        break;
                    default:
                        MessageBox.Show($"{action} feature coming soon!", "Feature", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        break;
                }
            }
        }

