        private void ShowExpenseDescriptionDialog(decimal amount, string? prefillDescription = null, string? itemCode = null, string? variationId = null)
        {
            bool isExistingItemExpense = !string.IsNullOrWhiteSpace(itemCode);

            var descForm = new Form
            {
                Text = "Record Expense",
                Size = new Size(900, 900),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false,
                MinimizeBox = false
            };

            var amountLabel = new Label
            {
                Text = "Amount:",
                Location = new Point(50, 30),
                Size = new Size(800, 60),
                Font = new Font("Arial", 30, FontStyle.Bold),
                TextAlign = ContentAlignment.MiddleLeft
            };
            var amountNumeric = new NumericUpDown
            {
                Location = new Point(50, 95),
                Size = new Size(800, 60),
                Font = new Font("Arial", 24),
                DecimalPlaces = 2,
                Maximum = 999999,
                Minimum = 0,
                Value = amount > 0 ? amount : 0,
                ReadOnly = isExistingItemExpense,
                Increment = 1
            };
            if (!isExistingItemExpense)
            {
                amountNumeric.Text = string.Empty;
            }

            var existingItemButton = new Button
            {
                Text = "Existing Item",
                Location = new Point(50, 170),
                Size = new Size(240, 60),
                BackColor = Color.LightGray,
                Font = new Font("Arial", 16, FontStyle.Bold),
                Visible = !isExistingItemExpense
            };

            var categoryLabel = new Label
            {
                Text = "Expense Category:",
                Location = new Point(50, 250),
                Size = new Size(800, 60),
                Font = new Font("Arial", 28, FontStyle.Bold),
                TextAlign = ContentAlignment.MiddleLeft
            };
            var categoryComboBox = new ComboBox();
            {
                categoryComboBox.Location = new Point(50, 320);
                categoryComboBox.Size = new Size(800, 60);
                categoryComboBox.Font = new Font("Arial", 24);
                categoryComboBox.DropDownStyle = ComboBoxStyle.DropDownList;
            }
                ;
            var descLabel = new Label
            {
                Text = "Expense Description:",
                Location = new Point(50, 400),
                Size = new Size(800, 120),
                Font = new Font("Arial", 36, FontStyle.Bold),
                TextAlign = ContentAlignment.MiddleLeft
            };
            var descTextBox = new TextBox();
            {
                descTextBox.Location = new Point(50, 530);
                descTextBox.Size = new Size(800, 180); // Increased height for multiline
                descTextBox.Font = new Font("Arial", 28);
                descTextBox.Multiline = true;
                descTextBox.ScrollBars = ScrollBars.Vertical;
                descTextBox.MaxLength = 255;
                if (!string.IsNullOrWhiteSpace(prefillDescription))
                {
                    descTextBox.Text = prefillDescription;
                }
            }
                ;
            var okButton = new Button();
            {
                okButton.Text = "OK";
                okButton.Location = new Point(240, 760);
                okButton.Size = new Size(200, 70);
                okButton.BackColor = Color.White;
                okButton.Font = new Font("Arial", 28, FontStyle.Bold);
            }
                ;
            var cancelButton = new Button();
            {
                cancelButton.Text = "Cancel";
                cancelButton.Location = new Point(460, 760);
                cancelButton.Size = new Size(200, 70);
                cancelButton.BackColor = Color.LightGray;
                cancelButton.Font = new Font("Arial", 28, FontStyle.Bold);
            }
                ;
            // Make Enter key trigger OK button
            descTextBox.KeyDown += (s, e) =>
            {
                if (e.KeyCode == Keys.Enter)
                {
                    okButton.PerformClick();
                }
            };

            amountNumeric.KeyDown += (s, e) =>
            {
                if (e.KeyCode == Keys.Enter)
                {
                    okButton.PerformClick();
                }
            };

            existingItemButton.Click += (s, args) =>
            {
                descForm.Close();
                ShowSelectExistingItemForExpense();
            };

            cancelButton.Click += (s, args) =>
            {
                descForm.Close();
            };

            try
            {
                using (var categoryConnection = new SqlConnection(connectionString))
                {
                    categoryConnection.Open();
                    var categoryCommand = new SqlCommand(
                        "SELECT Code, Description, ISNULL(InStoreItems, 0) AS InStoreItems FROM ExpenseCategorySetup ORDER BY Code",
                        categoryConnection);
                    using (var reader = categoryCommand.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string code = reader["Code"]?.ToString()?.Trim() ?? string.Empty;
                            string description = reader["Description"]?.ToString()?.Trim() ?? string.Empty;
                            bool inStoreItems = reader["InStoreItems"] != DBNull.Value && Convert.ToBoolean(reader["InStoreItems"]);

                            if (isExistingItemExpense && !inStoreItems)
                            {
                                continue;
                            }

                            if (!isExistingItemExpense && inStoreItems)
                            {
                                continue;
                            }

                            string display = string.IsNullOrWhiteSpace(description) ? code : $"{code} - {description}";
                            if (!string.IsNullOrWhiteSpace(display))
                            {
                                categoryComboBox.Items.Add(display);
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to load expense categories: {ex.Message}", "Expense Categories", MessageBoxButtons.OK, MessageBoxIcon.Error);
                descForm.Close();
                return;
            }

            if (categoryComboBox.Items.Count == 0)
            {
                string missingCategoryMessage = isExistingItemExpense
                    ? "No expense categories are marked as In-Store-Items yet. Please update one in Settings > Expense Categories."
                    : "No expense categories are set up yet. Please create one in Settings > Expense Categories.";
                MessageBox.Show(missingCategoryMessage, "Expense Categories", MessageBoxButtons.OK, MessageBoxIcon.Information);
                descForm.Close();
                return;
            }

            if (isExistingItemExpense)
            {
                categoryComboBox.SelectedIndex = 0;
                categoryComboBox.Enabled = false;
            }
            else
            {
                categoryComboBox.SelectedIndex = -1;
            }

            okButton.Click += (s, args) =>
            {
                if (amountNumeric.Value <= 0)
                {
                    MessageBox.Show("Please enter a valid amount.", "Validation Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (string.IsNullOrWhiteSpace(descTextBox.Text))
                {
                    MessageBox.Show("Please enter an expense description.", "Validation Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (categoryComboBox.SelectedItem == null)
                {
                    MessageBox.Show("Please select an expense category.", "Validation Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                try
                {
                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();

                        // Don't write to TransactionHeader yet; expense will be posted when user clicks POST
                        // Generate receipt number placeholder for this expense group if not already set
                        if (string.IsNullOrEmpty(currentReceiptNo))
                        {
                            currentReceiptNo = GenerateCentralizedReceiptNumber();
                        }
                    }

                    // Also log this expense into the current sale list so it can be posted to ItemLedgerEntry later
                    try
                    {
                        decimal enteredAmount = amountNumeric.Value;
                        string desc = descTextBox.Text.Trim();
                        string expenseCategory = categoryComboBox.SelectedItem?.ToString()?.Trim() ?? string.Empty;
                        int qty = 1;
                        decimal price = enteredAmount;
                        decimal total = price * qty;
                        string category = "EXPENSE";
                        string code = string.IsNullOrWhiteSpace(itemCode) ? "EXPENSE" : itemCode;

                        ListViewItem expenseItem = new ListViewItem(desc);
                        expenseItem.SubItems.Add(qty.ToString());
                        expenseItem.SubItems.Add($"{price:F2}");
                        expenseItem.SubItems.Add($"{total:F2}");
                        expenseItem.SubItems.Add(category);
                        expenseItem.SubItems.Add(code);
                        expenseItem.SubItems.Add(variationId ?? string.Empty);
                        // Tag the line so we can identify it as an expense (not a payment)
                        expenseItem.Tag = new PendingExpenseTag(expenseCategory);

                        EnsureSaleMetadataColumns();

                        salesListView.Items.Add(expenseItem);
                        currentTotal += total;
                        UpdateTotal();
                        // If this expense was manually entered (no itemCode), prompt for tender type and record payment
                        if (string.IsNullOrWhiteSpace(itemCode))
                        {
                            try
                            {
                                using (var tenderForm = new Form()
                                {
                                    Text = "Select Tender Type",
                                    Size = new Size(760, 260),
                                    StartPosition = FormStartPosition.CenterParent,
                                    BackColor = Color.White,
                                    FormBorderStyle = FormBorderStyle.FixedDialog,
                                    MaximizeBox = false,
                                    MinimizeBox = false
                                })
                                {
                                    var lbl = new Label { Text = "Tender Type:", Location = new Point(24, 24), Size = new Size(160, 40), Font = new Font("Arial", 18, FontStyle.Bold) };
                                    var tenderCombo = new ComboBox { Location = new Point(200, 24), Size = new Size(520, 42), DropDownStyle = ComboBoxStyle.DropDownList, Font = new Font("Arial", 18) };
                                    var amtDisplay = new Label { Text = $"Amount: {enteredAmount:F2}", Location = new Point(24, 80), Size = new Size(680, 34), Font = new Font("Arial", 16, FontStyle.Bold), ForeColor = Color.DarkBlue };
                                    var okBtn = new Button { Text = "OK", Location = new Point(220, 120), Size = new Size(200, 64), BackColor = Color.Green, ForeColor = Color.White, Font = new Font("Arial", 18, FontStyle.Bold) };
                                    var cancelBtn = new Button { Text = "Cancel", Location = new Point(440, 120), Size = new Size(200, 64), BackColor = Color.Gray, ForeColor = Color.White, Font = new Font("Arial", 18, FontStyle.Bold) };

                                    // Load tender types
                                    try
                                    {
                                        using (var conn = new SqlConnection(connectionString))
                                        {
                                            conn.Open();
                                            var cmd = new SqlCommand("SELECT Code, Description FROM TenderTypes WHERE Code = 'CASH' ORDER BY Code", conn);
                                            using (var rdr = cmd.ExecuteReader())
                                            {
                                                while (rdr.Read())
                                                {
                                                    string Code = rdr["Code"]?.ToString() ?? "";
                                                    string Desc = rdr["Description"]?.ToString() ?? Code;
                                                    tenderCombo.Items.Add(new { Code = Code, Desc = Desc });
                                                }
                                            }
                                        }
                                        tenderCombo.DisplayMember = "Desc";
                                        tenderCombo.ValueMember = "Code";
                                        if (tenderCombo.Items.Count > 0) tenderCombo.SelectedIndex = 0;
                                    }
                                    catch
                                    {
                                        tenderCombo.Items.Add(new { Code = "CASH", Desc = "Cash" });
                                        tenderCombo.DisplayMember = "Desc";
                                        tenderCombo.ValueMember = "Code";
                                        tenderCombo.SelectedIndex = 0;
                                    }

                                    okBtn.Click += (s2, a2) =>
                                    {
                                        if (tenderCombo.SelectedItem == null)
                                        {
                                            MessageBox.Show("Please select a tender type.", "Validation", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                                            return;
                                        }

                                        string selectedCode = "";
                                        string selectedDesc = "";
                                        try
                                        {
                                            var sel = tenderCombo.SelectedItem;
                                            var t = sel.GetType();
                                            var codeProp = t.GetProperty("Code");
                                            var descProp = t.GetProperty("Desc");
                                            selectedCode = codeProp?.GetValue(sel)?.ToString() ?? "";
                                            selectedDesc = descProp?.GetValue(sel)?.ToString() ?? selectedCode;
                                        }
                                        catch
                                        {
                                            selectedCode = tenderCombo.SelectedItem.ToString() ?? "CASH";
                                            selectedDesc = selectedCode;
                                        }

                                        decimal paymentAmount = enteredAmount;

                                        // Record payment for the expense line
                                        AddPayment(selectedDesc, selectedCode, paymentAmount);
                                        //  RecordPaymentEntry();
                                        tenderForm.DialogResult = DialogResult.OK;
                                        tenderForm.Close();
                                    };

                                    cancelBtn.Click += (s2, a2) =>
                                    {
                                        tenderForm.DialogResult = DialogResult.Cancel;
                                        tenderForm.Close();
                                    };

                                    tenderForm.Controls.AddRange(new Control[] { lbl, tenderCombo, amtDisplay, okBtn, cancelBtn });
                                    tenderForm.ShowDialog();
                                }
                            }
                            catch
                            {
                                // ignore tender recording errors but keep expense line
                            }
                        }
                    }
                    catch { }

                    // MessageBox.Show($"Expense recorded successfully!\nAmount: P{amount:F2}\nDescription: {descTextBox.Text}",
                    //               "Expense Saved", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    descForm.Close();
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error saving expense: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            descForm.Controls.Add(amountLabel);
            descForm.Controls.Add(amountNumeric);
            descForm.Controls.Add(existingItemButton);
            descForm.Controls.Add(descLabel);
            descForm.Controls.Add(descTextBox);
            descForm.Controls.Add(categoryLabel);
            descForm.Controls.Add(categoryComboBox);
            descForm.Controls.Add(okButton);
            descForm.Controls.Add(cancelButton);
            descForm.ShowDialog();
        }

        private void ShowIncomeDialog()
