        private void ShowIncomeDescriptionDialog(decimal amount, string? prefillDescription = null, string? itemCode = null)
        {
            var descForm = new Form
            {
                Text = "Record Income",
                Size = new Size(900, 600),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false,
                MinimizeBox = false
            };

            var descLabel = new Label
            {
                Text = "Income Description:",
                Location = new Point(50, 50),
                Size = new Size(800, 120),
                Font = new Font("Arial", 36, FontStyle.Bold),
                TextAlign = ContentAlignment.MiddleLeft
            };
            var descTextBox = new TextBox();
            descTextBox.Location = new Point(50, 180);
            descTextBox.Size = new Size(800, 180);
            descTextBox.Font = new Font("Arial", 28);
            descTextBox.Multiline = true;
            descTextBox.ScrollBars = ScrollBars.Vertical;
            descTextBox.MaxLength = 255;
            if (!string.IsNullOrWhiteSpace(prefillDescription))
            {
                descTextBox.Text = prefillDescription;
            }

            var okButton = new Button();
            okButton.Text = "OK";
            okButton.Location = new Point(350, 400);
            okButton.Size = new Size(200, 70);
            okButton.BackColor = Color.White;
            okButton.Font = new Font("Arial", 28, FontStyle.Bold);

            descTextBox.KeyDown += (s, e) =>
            {
                if (e.KeyCode == Keys.Enter)
                {
                    okButton.PerformClick();
                }
            };

            okButton.Click += (s, args) =>
            {
                if (string.IsNullOrWhiteSpace(descTextBox.Text))
                {
                    MessageBox.Show("Please enter an income description.", "Validation Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                try
                {
                    // Log to current sale list as INCOME so it can be posted when POST is clicked
                    string desc = descTextBox.Text.Trim();
                    int qty = 1;
                    decimal price = amount;
                    decimal total = price * qty;
                    string category = "INCOME";
                    string code = string.IsNullOrWhiteSpace(itemCode) ? "INCOME" : itemCode;

                    ListViewItem incomeItem = new ListViewItem(desc);
                    incomeItem.SubItems.Add(qty.ToString());
                    incomeItem.SubItems.Add($"{price:F2}");
                    incomeItem.SubItems.Add($"{total:F2}");
                    incomeItem.SubItems.Add(category);
                    incomeItem.SubItems.Add(code);
                    incomeItem.Tag = "INCOME";

                    EnsureSaleMetadataColumns();

                    salesListView.Items.Add(incomeItem);
                    currentTotal += total;
                    UpdateTotal();

                    // After adding income line, prompt user to select tender type and record payment
                    try
                    {
                        using (var tenderForm = new Form()
                        {
                            Text = "Select Tender Type",
                            Size = new Size(760, 260),
                            StartPosition = FormStartPosition.CenterParent,
                            BackColor = Color.White,
                            FormBorderStyle = FormBorderStyle.FixedDialog,
                            MaximizeBox = false,
                            MinimizeBox = false
                        })
                        {
                            // Much larger, more readable fonts and control sizes
                            var lbl = new Label { Text = "Tender Type:", Location = new Point(24, 24), Size = new Size(160, 40), Font = new Font("Arial", 18, FontStyle.Bold) };
                            var tenderCombo = new ComboBox { Location = new Point(200, 24), Size = new Size(520, 42), DropDownStyle = ComboBoxStyle.DropDownList, Font = new Font("Arial", 18) };
                            // For INCOME flow we use the previously-entered amount, so do not show an amount input here.
                            var amtDisplay = new Label { Text = $"Amount: {amount:F2}", Location = new Point(24, 80), Size = new Size(680, 34), Font = new Font("Arial", 16, FontStyle.Bold), ForeColor = Color.DarkBlue };
                            var okBtn = new Button { Text = "OK", Location = new Point(220, 120), Size = new Size(200, 64), BackColor = Color.Green, ForeColor = Color.White, Font = new Font("Arial", 18, FontStyle.Bold) };
                            var cancelBtn = new Button { Text = "Cancel", Location = new Point(440, 120), Size = new Size(200, 64), BackColor = Color.Gray, ForeColor = Color.White, Font = new Font("Arial", 18, FontStyle.Bold) };

                            // Load tender types
                            try
                            {
                                using (var conn = new SqlConnection(connectionString))
                                {
                                    conn.Open();
                                    var cmd = new SqlCommand("SELECT Code, Description FROM TenderTypes WHERE Code <> 'ADVANCEORDERS' ORDER BY Code", conn);
                                    using (var rdr = cmd.ExecuteReader())
                                    {
                                        while (rdr.Read())
                                        {
                                            string Code = rdr["Code"]?.ToString() ?? "";
                                            string Desc = rdr["Description"]?.ToString() ?? Code;
                                            tenderCombo.Items.Add(new { Code = Code, Desc = Desc });
                                        }
                                    }
                                }
                                // Format items for display (since we added anonymous objects)
                                tenderCombo.DisplayMember = "Desc";
                                tenderCombo.ValueMember = "Code";
                                if (tenderCombo.Items.Count > 0) tenderCombo.SelectedIndex = 0;
                            }
                            catch
                            {
                                // Fallback to cash if tender types not available
                                tenderCombo.Items.Add(new { Code = "CASH", Desc = "Cash" });
                                tenderCombo.DisplayMember = "Desc";
                                tenderCombo.ValueMember = "Code";
                                tenderCombo.SelectedIndex = 0;
                            }

                            okBtn.Click += (s2, a2) =>
                            {
                                if (tenderCombo.SelectedItem == null)
                                {
                                    MessageBox.Show("Please select a tender type.", "Validation", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                                    return;
                                }

                                // Extract selected item code/desc
                                string selectedCode = "";
                                string selectedDesc = "";
                                try
                                {
                                    // Use dynamic to read anonymous object fields
                                    var sel = tenderCombo.SelectedItem;
                                    var t = sel.GetType();
                                    var codeProp = t.GetProperty("Code");
                                    var descProp = t.GetProperty("Desc");
                                    selectedCode = codeProp?.GetValue(sel)?.ToString() ?? "";
                                    selectedDesc = descProp?.GetValue(sel)?.ToString() ?? selectedCode;
                                }
                                catch
                                {
                                    selectedCode = tenderCombo.SelectedItem.ToString() ?? "CASH";
                                    selectedDesc = selectedCode;
                                }

                                // Use the amount supplied to ShowIncomeDescriptionDialog (entered earlier)
                                decimal paymentAmount = amount;

                                // Record payment in current payment tracking using original amount
                                AddPayment(selectedDesc, selectedCode, paymentAmount);

                                tenderForm.DialogResult = DialogResult.OK;
                                tenderForm.Close();
                            };

                            cancelBtn.Click += (s2, a2) =>
                            {
                                tenderForm.DialogResult = DialogResult.Cancel;
                                tenderForm.Close();
                            };

                            tenderForm.Controls.AddRange(new Control[] { lbl, tenderCombo, amtDisplay, okBtn, cancelBtn });
                            tenderForm.ShowDialog();
                        }
                    }
                    catch
                    {
                        // ignore tender recording errors but keep income line
                    }

                    descForm.Close();
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error saving income: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            descForm.Controls.Add(descLabel);
            descForm.Controls.Add(descTextBox);
            descForm.Controls.Add(okButton);
            descForm.ShowDialog();
        }

        private void ShowSelectExistingItemForExpense()
        {
            var selectForm = new Form
            {
                Text = "Select Existing Item",
                Size = new Size(900, 600),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false,
                MinimizeBox = false
            };

            var searchLabel = new Label { Text = "Search:", Location = new Point(20, 20), Size = new Size(70, 24) };
            var searchTextBox = new TextBox { Location = new Point(100, 18), Size = new Size(420, 26) };

            var itemsGrid = new DataGridView
            {
                Location = new Point(20, 60),
                Size = new Size(840, 320),
                ReadOnly = true,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill,
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false
            };

            // Use DataTable so we can filter via DataView
            var itemsTable = new System.Data.DataTable();
            itemsTable.Columns.Add("Code", typeof(string));
            itemsTable.Columns.Add("Name", typeof(string));
            itemsTable.Columns.Add("Price", typeof(decimal));
            itemsTable.Columns.Add("Stock", typeof(int));

            // Load items from DB into DataTable
            try
            {
                using (var conn = new SqlConnection(connectionString))
                {
                    conn.Open();
                    var cmd = new SqlCommand("SELECT Code, Name, Price, QuantityInStock FROM Items WHERE IsActive = 1 ORDER BY Name", conn);
                    using (var reader = cmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string code = reader["Code"].ToString() ?? string.Empty;
                            string name = reader["Name"].ToString() ?? string.Empty;
                            decimal price = reader["Price"] != DBNull.Value ? Convert.ToDecimal(reader["Price"]) : 0m;
                            int stock = reader["QuantityInStock"] != DBNull.Value ? Convert.ToInt32(reader["QuantityInStock"]) : 0;
                            itemsTable.Rows.Add(code, name, price, stock);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to load items: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                selectForm.Close();
                return;
            }

            itemsGrid.DataSource = itemsTable;
            // Format price column
            if (itemsGrid.Columns.Contains("Price"))
            {
                itemsGrid.Columns["Price"].DefaultCellStyle.Format = "F2";
            }

            // Wire search box to filter the DataView
            searchTextBox.TextChanged += (s, e) =>
            {
                var txt = searchTextBox.Text.Replace("'", "''");
                if (string.IsNullOrWhiteSpace(txt))
                {
                    itemsTable.DefaultView.RowFilter = string.Empty;
                }
                else
                {
                    // Filter by Code or Name
                    itemsTable.DefaultView.RowFilter = $"Code LIKE '%{txt}%' OR Name LIKE '%{txt}%'";
                }
            };

            selectForm.Controls.Add(searchLabel);
            selectForm.Controls.Add(searchTextBox);

            var qtyLabel = new Label { Text = "Quantity:", Location = new Point(20, 460), Size = new Size(80, 30) };
            var qtyUp = new NumericUpDown { Location = new Point(110, 460), Size = new Size(100, 30), Minimum = 1, Maximum = 9999, Value = 1 };
            var selectButton = new Button { Text = "Select & Continue", Location = new Point(230, 455), Size = new Size(160, 40), BackColor = Color.Green, ForeColor = Color.White };
            var cancelButton = new Button { Text = "Cancel", Location = new Point(410, 455), Size = new Size(100, 40), BackColor = Color.Gray, ForeColor = Color.White };

            selectButton.Click += (s, e) =>
            {
                if (itemsGrid.SelectedRows.Count == 0)
                {
                    MessageBox.Show("Please select an item.", "Validation", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                var row = itemsGrid.SelectedRows[0];
                string name = row.Cells[1].Value?.ToString() ?? "";
                decimal price = 0m;
                decimal.TryParse(row.Cells[2].Value?.ToString() ?? "0", out price);
                int qty = (int)qtyUp.Value;
                string code = row.Cells[0].Value?.ToString() ?? "";
                string variationId = string.Empty;
                string displayName = name;
                decimal unitPrice = price;

                var variantChoice = PromptForSaleVariantSelection(code, name, price, selectForm);
                if (variantChoice == SaleVariantSelection.Cancelled)
                    return;

                if (variantChoice != null)
                {
                    displayName = string.IsNullOrWhiteSpace(variantChoice.DisplayText) ? name : variantChoice.DisplayText;
                    unitPrice = variantChoice.Price > 0 ? variantChoice.Price : price;
                    code = string.IsNullOrWhiteSpace(variantChoice.ItemCode) ? code : variantChoice.ItemCode;
                    variationId = variantChoice.VariationId ?? string.Empty;
                }

                decimal amount = unitPrice * qty;
                string prefill = $"{displayName} x{qty} @ P{unitPrice:F2}";

                selectForm.Close();
                ShowExpenseDescriptionDialog(amount, prefill, code, variationId);
            };

            cancelButton.Click += (s, e) => selectForm.Close();

            selectForm.Controls.Add(itemsGrid);
            selectForm.Controls.Add(qtyLabel);
            selectForm.Controls.Add(qtyUp);
            selectForm.Controls.Add(selectButton);
            selectForm.Controls.Add(cancelButton);
            selectForm.ShowDialog();
        }

        private void VoidSelectedLine()
        {
            // VOID LINE functionality: delete selected item from salesListView
            if (salesListView.SelectedItems.Count == 0)
            {
                MessageBox.Show("Please select a line to void.", "No Line Selected", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
            else
            {
                ListViewItem selectedItem = salesListView.SelectedItems[0];
                decimal itemTotal = 0;
                if (selectedItem.Tag is decimal)
                    itemTotal = (decimal)selectedItem.Tag;
                else if (decimal.TryParse(selectedItem.Tag?.ToString(), out decimal parsedTotal))
                    itemTotal = parsedTotal;
                salesListView.Items.Remove(selectedItem);
                // Recalculate totals
                decimal newTotal = 0;
                foreach (ListViewItem item in salesListView.Items)
                {
                    if (item.Tag is decimal)
                        newTotal += (decimal)item.Tag;
                    else if (decimal.TryParse(item.Tag?.ToString(), out decimal parsedTotal2))
                        newTotal += parsedTotal2;
                }
                currentTotal = newTotal;
                UpdateTotal();
            }
        }

