            var deleteTransButton2 = new Button
            {
                Text = "DELETE TRANS",
                Visible = false,
                Dock = DockStyle.Top,
                Height = 40,
                BackColor = Color.DarkOrange,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            deleteTransButton2.Click += (s, e) =>
            {
                FunctionEvents.ConfirmAndDeleteAllTables(settingsForm);
            };

            // Button to clear EODID entries for a specific date (e.g., 2025-09-10)
            var clearEODForDateButton = new Button
            {
                Text = "CLEAR EODID - 2025-09-10",
                Dock = DockStyle.Top,
                Height = 40,
                BackColor = Color.Maroon,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            clearEODForDateButton.Click += (s, e) =>
            {
                // Prompt user for the date to clear (expecting YYYY-MM-DD)
                string input = Microsoft.VisualBasic.Interaction.InputBox("Enter the EOD date to clear (YYYY-MM-DD):", "Clear EODID", DateTime.Now.ToString("yyyy-MM-dd"));
                if (string.IsNullOrWhiteSpace(input))
                {
                    MessageBox.Show("No date entered.", "Cancelled", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }

                if (!DateTime.TryParse(input, out DateTime parsedDate))
                {
                    MessageBox.Show("Invalid date format. Please enter a valid date in YYYY-MM-DD format.", "Invalid Date", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                string target = parsedDate.ToString("yyyy-MM-dd");

                var confirm = MessageBox.Show($"This will clear EODID values equal to '{target}' from TransactionHeader and TransPaymentEntry.\nType YES to confirm.", "Confirm Clear EODID", MessageBoxButtons.OKCancel, MessageBoxIcon.Warning);
                if (confirm != DialogResult.OK) return;

                // Ask for explicit typed confirmation
                string typed = Microsoft.VisualBasic.Interaction.InputBox($"Type YES to proceed with clearing EODID for date {target}:", "Confirm Clear EODID", "");
                if (!string.Equals(typed?.Trim(), "YES", StringComparison.OrdinalIgnoreCase))
                {
                    MessageBox.Show("Operation cancelled.", "Cancelled", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }

                try
                {
                    using (var conn = new SqlConnection(connectionString))
                    {
                        conn.Open();

                        // Clear EODID in TransactionHeader
                        var cmd1 = new SqlCommand("UPDATE TransactionHeader SET EODID = NULL WHERE EODID = @target", conn);
                        cmd1.Parameters.AddWithValue("@target", target);
                        int affected1 = cmd1.ExecuteNonQuery();

                        // Clear EODID in TransPaymentEntry
                        var cmd2 = new SqlCommand("UPDATE TransPaymentEntry SET EODID = NULL WHERE EODID = @target", conn);
                        cmd2.Parameters.AddWithValue("@target", target);
                        int affected2 = cmd2.ExecuteNonQuery();

                        MessageBox.Show($"Cleared EODID for {affected1} TransactionHeader rows and {affected2} TransPaymentEntry rows.", "Done", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error clearing EODID: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            // Button to reprint a Tender Declaration by receipt number
            var reprintTenderDeclButton = new Button
            {
                Text = "REPRINT TENDER DECL",
                Dock = DockStyle.Top,
                Height = 40,
                BackColor = Color.Teal,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            reprintTenderDeclButton.Click += (s, e) =>
            {
                try
                {
                    // Ask for a date to find tender declarations (default to today)
                    string dateInput = Microsoft.VisualBasic.Interaction.InputBox("Enter date for Tender Declarations (YYYY-MM-DD):", "Reprint Tender Declaration by Date", DateTime.Now.ToString("yyyy-MM-dd"));
                    if (string.IsNullOrWhiteSpace(dateInput))
                    {
                        MessageBox.Show("No date entered.", "Cancelled", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    if (!DateTime.TryParse(dateInput, out DateTime parsedDate))
                    {
                        MessageBox.Show("Invalid date format. Please use YYYY-MM-DD.", "Invalid Date", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        return;
                    }

                    string targetDate = parsedDate.ToString("yyyy-MM-dd");

                    // Query distinct receipt numbers from TenderDeclLines for that date
                    var receipts = new System.Collections.Generic.List<string>();
                    using (var conn = new SqlConnection(connectionString))
                    {
                        conn.Open();
                        // Try matching against the Date column if present, else CreatedDate
                        string query = @"SELECT DISTINCT ReceiptNo FROM TenderDeclLines WHERE (CAST(Date AS DATE) = @d) OR (CAST(CreatedDate AS DATE) = @d)";
                        using (var cmd = new SqlCommand(query, conn))
                        {
                            cmd.Parameters.AddWithValue("@d", parsedDate.Date);
                            using (var rdr = cmd.ExecuteReader())
                            {
                                while (rdr.Read())
                                {
                                    var r = rdr["ReceiptNo"]?.ToString();
                                    if (!string.IsNullOrWhiteSpace(r)) receipts.Add(r);
                                }
                            }
                        }
                    }

                    if (receipts.Count == 0)
                    {
                        MessageBox.Show($"No tender declarations found for {targetDate}.", "No Records", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    string selectedReceipt;
                    if (receipts.Count == 1)
                    {
                        selectedReceipt = receipts[0];
                    }
                    else
                    {
                        // If multiple receipts, prompt user to pick one (simple join list)
                        string list = string.Join("\n", receipts.Select(r => r));
                        selectedReceipt = Microsoft.VisualBasic.Interaction.InputBox($"Multiple receipts found for {targetDate}:\n{list}\n\nEnter receipt number to reprint:", "Choose Receipt", receipts[0]);
                        if (string.IsNullOrWhiteSpace(selectedReceipt))
                        {
                            MessageBox.Show("No receipt selected.", "Cancelled", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            return;
                        }
                    }

                    // Call existing print method
                    PrintTenderDeclReceipt(selectedReceipt.Trim());
                    MessageBox.Show("Reprint request sent to printer.", "Reprint", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Failed to reprint tender declaration: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            // Positive adjustments for AQUARIUM category (moved from EmployeeSetup UI)
            var positiveAdjButton = new Button
            {
                Text = "Positive Adj (Aquarium)",
                Dock = DockStyle.Top,
                Height = 40,
                BackColor = Color.DarkCyan,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            positiveAdjButton.Click += (s, e) =>
            {
                try
                {
                    var plan = FunctionEvents.GetAquariumPositiveAdjustmentPlan();
                    if (plan == null || plan.Count == 0)
                    {
                        MessageBox.Show("No negative balances found for items in the AQUARIUM category. No adjustments required.", "Positive Adj", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    var sb = new System.Text.StringBuilder();
                    sb.AppendLine("The following positive adjustments are proposed:");
                    sb.AppendLine("");
                    foreach (var p in plan)
                    {
                        sb.AppendLine($"{p.ItemCode} - {p.ItemName} : {p.Needed}");
                    }
                    sb.AppendLine("");
                    sb.AppendLine("Proceed to insert positive adjustment lines (Description will be 'positive_adj - ItemName')?");

                    var resp = MessageBox.Show(sb.ToString(), "Positive Adj - Dry Run", MessageBoxButtons.YesNo, MessageBoxIcon.Question);
                    if (resp != DialogResult.Yes) return;

                    string docNo = "POSITIVE_ADJ_" + DateTime.Now.ToString("yyyyMMddHHmmss");
                    int inserted = FunctionEvents.ApplyAquariumPositiveAdjustments(plan, docNo, "SYSTEM", settingsForm);
                    MessageBox.Show($"Inserted {inserted} adjustment row(s) (Document: {docNo}).", "Positive Adj", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error running positive adjustments: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            // Move REPORTS into the Settings dialog for superusers (placed after DELETE TRANS)
            var reportsButton = new Button
            {
                Text = "X-REPORT",
                Dock = DockStyle.Top,
                Height = 40,
                BackColor = Color.Indigo,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            reportsButton.Click += (s, e) =>
            {
                ShowReportsDialog();
            };

            // Move User Setup to appear near DELETE TRANS (stacked together)
            userSetupTopButton.Dock = DockStyle.Top;
            userSetupTopButton.Height = 40;
            userSetupTopButton.Margin = new Padding(0);
            userSetupTopButton.BackColor = Color.DarkSlateBlue;


            var closeButton = new Button
            {
                Text = "Close",
                Dock = DockStyle.Bottom,
                Height = 40
            };
            closeButton.Click += (s, e) => settingsForm.Close();

            // Add top horizontal button bar, then the stacked controls. Close remains at bottom.
            settingsForm.Controls.Add(closeButton);
            settingsForm.Controls.Add(deleteTransButton2);
            // Place Employee Setup directly under DELETE TRANS per request
            settingsForm.Controls.Add(employeeSetupTopButton);
            // Place Wholesale Setup directly under Employee Setup
            settingsForm.Controls.Add(wholesaleSetupTopButton);
            // Place General Setup directly under Employee Setup
            settingsForm.Controls.Add(generalSetupTopButton);
            // Place Warehouse Setup directly under Employee Setup
            settingsForm.Controls.Add(warehouseSetupTopButton);
            // Place SerialTracking directly under Warehouse Setup
            settingsForm.Controls.Add(serialTrackingTopButton);
            settingsForm.Controls.Add(aquariumSetTopButton);
            // Positive adjustments button placed under Employee Setup
            settingsForm.Controls.Add(positiveAdjButton);
            // Clear EODID button under Delete Trans
            settingsForm.Controls.Add(clearEODForDateButton);
            // Reprint tender declaration button
            settingsForm.Controls.Add(reprintTenderDeclButton);
            // Add Reports button under Delete Trans
            settingsForm.Controls.Add(reportsButton);
            settingsForm.Controls.Add(userSetupTopButton);
            settingsForm.Controls.Add(printerSettingsButton);
            settingsForm.Controls.Add(productionStatusButton);
            settingsForm.Controls.Add(topButtonPanel);
            settingsForm.ShowDialog();
        }

        private void ShowWholesaleSetupDialog(IWin32Window? owner = null)
        {
            var wholesaleForm = new Form
            {
                Text = "Wholesale Setup",
                Size = new Size(980, 640),
                MinimumSize = new Size(980, 640),
                StartPosition = owner == null ? FormStartPosition.CenterScreen : FormStartPosition.CenterParent,
                BackColor = Color.White
            };

            var grid = new DataGridView
            {
                Dock = DockStyle.Fill,
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.None,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.Fixed3D,
                RowHeadersVisible = false,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                EditMode = DataGridViewEditMode.EditOnEnter
            };

            var countLabel = new Label
            {
                Text = "Total Items: 0",
                Dock = DockStyle.Left,
                Width = 240,
                TextAlign = ContentAlignment.MiddleLeft,
                Font = new Font("Arial", 10, FontStyle.Bold),
                ForeColor = Color.DarkBlue
            };

            var buttonPanel = new Panel
            {
                Dock = DockStyle.Bottom,
                Height = 56,
                BackColor = Color.WhiteSmoke
            };

            var saveButton = new Button
            {
                Text = "Save",
                Size = new Size(90, 34),
                Location = new Point(580, 11),
                BackColor = Color.DarkGreen,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var refreshButton = new Button
            {
                Text = "Refresh",
                Size = new Size(90, 34),
                Location = new Point(680, 11),
                BackColor = Color.SteelBlue,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var exportButton = new Button
            {
                Text = "Export",
                Size = new Size(90, 34),
                Location = new Point(780, 11),
                BackColor = Color.DarkOliveGreen,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var importButton = new Button
            {
                Text = "Import",
                Size = new Size(90, 34),
                Location = new Point(880, 11),
                BackColor = Color.DarkRed,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var closeButton = new Button
            {
                Text = "Close",
                Size = new Size(90, 34),
                Location = new Point(980, 11),
                BackColor = Color.Gray,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var instructionsLabel = new Label
            {
                Text = "Edit the Wholesale Price column for items whose category is marked Wholesale.",
                Dock = DockStyle.Top,
                Height = 32,
                Padding = new Padding(12, 8, 12, 0),
                Font = new Font("Arial", 9, FontStyle.Bold),
                ForeColor = Color.DarkSlateGray
            };

            var bindingTable = new DataTable();

            void ConfigureGridColumns()
            {
                if (!grid.Columns.Contains("Code")) return;

                grid.Columns["Code"].HeaderText = "Code";
                grid.Columns["Code"].Width = 110;
                grid.Columns["Code"].ReadOnly = true;

                grid.Columns["Name"].HeaderText = "Item Name";
                grid.Columns["Name"].Width = 220;
                grid.Columns["Name"].ReadOnly = true;

                grid.Columns["Description"].HeaderText = "Description";
                grid.Columns["Description"].Width = 240;
                grid.Columns["Description"].ReadOnly = true;

                grid.Columns["CategoryCode"].HeaderText = "Category";
                grid.Columns["CategoryCode"].Width = 90;
                grid.Columns["CategoryCode"].ReadOnly = true;

                grid.Columns["CategoryName"].HeaderText = "Category Name";
                grid.Columns["CategoryName"].Width = 140;
                grid.Columns["CategoryName"].ReadOnly = true;

                grid.Columns["Price"].HeaderText = "Retail Price";
                grid.Columns["Price"].Width = 95;
                grid.Columns["Price"].ReadOnly = true;
                grid.Columns["Price"].DefaultCellStyle.Format = "C2";
                grid.Columns["Price"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleRight;

                grid.Columns["WholesalePrice"].HeaderText = "Wholesale Price";
                grid.Columns["WholesalePrice"].Width = 115;
                grid.Columns["WholesalePrice"].ReadOnly = false;
                grid.Columns["WholesalePrice"].DefaultCellStyle.Format = "C2";
                grid.Columns["WholesalePrice"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleRight;

                if (grid.Columns.Contains("IsActive"))
                {
                    grid.Columns["IsActive"].HeaderText = "Active";
                    grid.Columns["IsActive"].Width = 60;
                    grid.Columns["IsActive"].ReadOnly = true;
                }

                foreach (DataGridViewColumn column in grid.Columns)
                {
                    if (!string.Equals(column.Name, "WholesalePrice", StringComparison.OrdinalIgnoreCase))
                    {
                        column.ReadOnly = true;
                    }
                }
            }

            void LoadWholesaleItems()
            {
                var table = new DataTable();
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    using var adapter = new SqlDataAdapter(@"
SELECT i.Code,
       i.Name,
       i.Description,
       i.CategoryCode,
       ISNULL(c.Description, '') AS CategoryName,
       ISNULL(i.Price, 0) AS Price,
       ISNULL(i.WholesalePrice, 0) AS WholesalePrice,
       ISNULL(i.IsActive, 1) AS IsActive
FROM dbo.Items i
INNER JOIN dbo.Category c ON c.Code = i.CategoryCode
WHERE ISNULL(c.WholeSale, 0) = 1
ORDER BY c.Description, i.Name, i.Code", connection);
                    adapter.Fill(table);
                }

                bindingTable = table;
                grid.DataSource = bindingTable;
                ConfigureGridColumns();
                countLabel.Text = $"Total Items: {bindingTable.Rows.Count}";
            }

            void ExportWholesaleItems()
            {
                grid.EndEdit();
                if (bindingTable == null || bindingTable.Rows.Count == 0)
                {
                    MessageBox.Show("No wholesale items to export.", "Wholesale Setup", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }

                ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

                using var saveDialog = new SaveFileDialog
                {
                    Filter = "Excel Files|*.xlsx",
                    Title = "Export Wholesale Setup",
                    FileName = $"Wholesale_Setup_{DateTime.Now:yyyyMMdd_HHmmss}.xlsx"
                };

                if (saveDialog.ShowDialog() != DialogResult.OK)
                    return;

                using var package = new ExcelPackage();
                var worksheet = package.Workbook.Worksheets.Add("Wholesale Setup");
                string[] headers = { "Code", "Name", "Description", "CategoryCode", "CategoryName", "Price", "WholesalePrice", "IsActive" };

                for (int i = 0; i < headers.Length; i++)
                {
                    worksheet.Cells[1, i + 1].Value = headers[i];
                    worksheet.Cells[1, i + 1].Style.Font.Bold = true;
                    worksheet.Cells[1, i + 1].Style.Fill.PatternType = ExcelFillStyle.Solid;
                    worksheet.Cells[1, i + 1].Style.Fill.BackgroundColor.SetColor(Color.LightBlue);
                }

                int rowIndex = 2;
                foreach (DataRow row in bindingTable.Rows)
                {
                    worksheet.Cells[rowIndex, 1].Value = row["Code"]?.ToString() ?? string.Empty;
                    worksheet.Cells[rowIndex, 2].Value = row["Name"]?.ToString() ?? string.Empty;
                    worksheet.Cells[rowIndex, 3].Value = row["Description"]?.ToString() ?? string.Empty;
                    worksheet.Cells[rowIndex, 4].Value = row["CategoryCode"]?.ToString() ?? string.Empty;
                    worksheet.Cells[rowIndex, 5].Value = row["CategoryName"]?.ToString() ?? string.Empty;
                    worksheet.Cells[rowIndex, 6].Value = row["Price"] == DBNull.Value ? 0m : Convert.ToDecimal(row["Price"]);
                    worksheet.Cells[rowIndex, 7].Value = row["WholesalePrice"] == DBNull.Value ? 0m : Convert.ToDecimal(row["WholesalePrice"]);
                    worksheet.Cells[rowIndex, 8].Value = row["IsActive"] != DBNull.Value && Convert.ToBoolean(row["IsActive"]);
                    rowIndex++;
                }

                if (rowIndex > 2)
                {
                    worksheet.Cells[$"F2:G{rowIndex - 1}"].Style.Numberformat.Format = "#,##0.00";
                }

                if (worksheet.Dimension != null)
                {
                    worksheet.Cells[worksheet.Dimension.Address].AutoFitColumns();
                }

                package.SaveAs(new FileInfo(saveDialog.FileName));
                MessageBox.Show($"Wholesale setup exported successfully.\nFile saved: {saveDialog.FileName}", "Export Successful", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }

            void ImportWholesaleItems()
            {
                ExcelPackage.LicenseContext = LicenseContext.NonCommercial;

                using var openDialog = new OpenFileDialog
                {
                    Filter = "Excel Files|*.xlsx;*.xls",
                    Title = "Import Wholesale Setup"
                };

                if (openDialog.ShowDialog() != DialogResult.OK)
                    return;

                using var package = new ExcelPackage(new FileInfo(openDialog.FileName));
                var worksheet = package.Workbook.Worksheets.FirstOrDefault();
                if (worksheet == null)
                {
                    MessageBox.Show("The selected Excel file does not contain any worksheets.", "Import Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                int rowCount = worksheet.Dimension?.Rows ?? 0;
                if (rowCount < 2)
                {
                    MessageBox.Show("The Excel file appears to be empty or contains only headers.", "Import Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                string codeHeader = worksheet.Cells[1, 1].Text?.Trim() ?? string.Empty;
                string wholesaleHeader = worksheet.Cells[1, 7].Text?.Trim() ?? string.Empty;
                if (!string.Equals(codeHeader, "Code", StringComparison.OrdinalIgnoreCase)
                    || !string.Equals(wholesaleHeader, "WholesalePrice", StringComparison.OrdinalIgnoreCase))
                {
                    MessageBox.Show("Invalid wholesale import template. Expected 'Code' in column A and 'WholesalePrice' in column G.", "Import Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                int updatedCount = 0;
                int skippedCount = 0;
                var errors = new List<string>();

                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    using var transaction = connection.BeginTransaction();

                    for (int rowIndex = 2; rowIndex <= rowCount; rowIndex++)
                    {
                        try
                        {
                            string code = worksheet.Cells[rowIndex, 1].Text?.Trim() ?? string.Empty;
                            if (string.IsNullOrWhiteSpace(code))
                                continue;

                            if (!decimal.TryParse(worksheet.Cells[rowIndex, 7].Text, out var wholesalePrice))
                            {
                                throw new InvalidOperationException("WholesalePrice must be a valid number.");
                            }

                            using var checkCmd = new SqlCommand(@"
SELECT COUNT(*)
FROM dbo.Items i
INNER JOIN dbo.Category c ON c.Code = i.CategoryCode
WHERE i.Code = @code
  AND ISNULL(c.WholeSale, 0) = 1", connection, transaction);
                            checkCmd.Parameters.AddWithValue("@code", code);
                            int exists = Convert.ToInt32(checkCmd.ExecuteScalar() ?? 0);
                            if (exists <= 0)
                            {
                                skippedCount++;
                                continue;
                            }

                            using var updateCmd = new SqlCommand(@"
UPDATE dbo.Items
SET WholesalePrice = @wholesalePrice,
    UpdatedDate = GETDATE()
WHERE Code = @code", connection, transaction);
                            updateCmd.Parameters.AddWithValue("@code", code);
                            updateCmd.Parameters.AddWithValue("@wholesalePrice", wholesalePrice);
                            updatedCount += updateCmd.ExecuteNonQuery();
                        }
                        catch (Exception rowEx)
                        {
                            errors.Add($"Row {rowIndex}: {rowEx.Message}");
                        }
                    }

                    transaction.Commit();
                }

                LoadWholesaleItems();

                var resultMessage = $"Import completed!\n\nUpdated: {updatedCount} items\nSkipped: {skippedCount} items";
                if (errors.Count > 0)
                {
                    resultMessage += "\n\nErrors:\n" + string.Join("\n", errors.Take(10));
                    if (errors.Count > 10)
                        resultMessage += "\n... and more";
                }

                MessageBox.Show(resultMessage, "Wholesale Setup Import", MessageBoxButtons.OK, errors.Count == 0 ? MessageBoxIcon.Information : MessageBoxIcon.Warning);
            }

            saveButton.Click += (s, e) =>
            {
                try
                {
                    grid.EndEdit();
                    if (bindingTable == null)
                        return;

                    var changes = bindingTable.GetChanges();
                    if (changes == null || changes.Rows.Count == 0)
                    {
                        MessageBox.Show("No wholesale price changes to save.", "Wholesale Setup", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();
                        using var transaction = connection.BeginTransaction();

                        foreach (DataRow row in changes.Rows)
                        {
                            if (row.RowState == DataRowState.Deleted)
                                continue;

                            string code = row["Code"]?.ToString()?.Trim() ?? string.Empty;
                            if (string.IsNullOrWhiteSpace(code))
                                continue;

                            decimal wholesalePrice;
                            try
                            {
                                wholesalePrice = row["WholesalePrice"] == DBNull.Value ? 0m : Convert.ToDecimal(row["WholesalePrice"]);
                            }
                            catch
                            {
                                throw new InvalidOperationException($"Invalid wholesale price for item '{code}'.");
                            }

                            using var cmd = new SqlCommand(@"
UPDATE dbo.Items
SET WholesalePrice = @wholesalePrice,
    UpdatedDate = GETDATE()
WHERE Code = @code", connection, transaction);
                            cmd.Parameters.AddWithValue("@code", code);
                            cmd.Parameters.AddWithValue("@wholesalePrice", wholesalePrice);
                            cmd.ExecuteNonQuery();
                        }

                        transaction.Commit();
                    }

                    bindingTable.AcceptChanges();
                    MessageBox.Show("Wholesale prices updated successfully.", "Wholesale Setup", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    LoadWholesaleItems();
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Failed to save wholesale prices: {ex.Message}", "Wholesale Setup", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            refreshButton.Click += (s, e) =>
            {
                try
                {
                    LoadWholesaleItems();
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Failed to refresh wholesale items: {ex.Message}", "Wholesale Setup", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            exportButton.Click += (s, e) =>
            {
                try
                {
                    ExportWholesaleItems();
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Failed to export wholesale items: {ex.Message}", "Wholesale Setup", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            importButton.Click += (s, e) =>
            {
                try
                {
                    ImportWholesaleItems();
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Failed to import wholesale items: {ex.Message}", "Wholesale Setup", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            closeButton.Click += (s, e) => wholesaleForm.Close();

            buttonPanel.Controls.Add(countLabel);
            buttonPanel.Controls.Add(saveButton);
            buttonPanel.Controls.Add(refreshButton);
            buttonPanel.Controls.Add(exportButton);
            buttonPanel.Controls.Add(importButton);
            buttonPanel.Controls.Add(closeButton);

            wholesaleForm.Controls.Add(grid);
            wholesaleForm.Controls.Add(buttonPanel);
            wholesaleForm.Controls.Add(instructionsLabel);

            try
            {
                LoadWholesaleItems();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to load wholesale items: {ex.Message}", "Wholesale Setup", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }

            if (owner == null)
                wholesaleForm.ShowDialog();
            else
                wholesaleForm.ShowDialog(owner);
        }

        private void EnsureGeneralSetupTableSchema(SqlConnection connection)
        {
            using var cmd = new SqlCommand(@"
IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'GeneralSetup')
BEGIN
    CREATE TABLE GeneralSetup (
        [Key] NVARCHAR(100) NOT NULL PRIMARY KEY,
        [Value] NVARCHAR(255) NULL,
        UpdatedDate DATETIME2 NOT NULL CONSTRAINT DF_GeneralSetup_UpdatedDate DEFAULT(GETDATE())
    )
END", connection);
            cmd.ExecuteNonQuery();
        }

        private decimal LoadMinimumWholesalesPrice()
        {
            try
            {
                string setupValue = LoadGeneralSetupValue("MinimumWholesalesPrice");
                return decimal.TryParse(setupValue, out decimal value) ? value : 0m;
            }
            catch
            {
                return 0m;
            }
        }

        private decimal LoadCardMarkupPercent()
        {
            try
            {
                string setupValue = LoadGeneralSetupValue("CardMarkupPercent");
                if (string.IsNullOrWhiteSpace(setupValue))
                {
                    return 0m;
                }

                if (decimal.TryParse(setupValue, out decimal value))
                {
                    return value < 0m ? 0m : value;
                }

                if (decimal.TryParse(setupValue, System.Globalization.NumberStyles.Number, System.Globalization.CultureInfo.InvariantCulture, out value))
                {
                    return value < 0m ? 0m : value;
                }

                return 0m;
            }
            catch
            {
                return 0m;
            }
        }

        private void SaveMinimumWholesalesPrice(decimal value)
        {
            SaveGeneralSetupValue("MinimumWholesalesPrice", value.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture));
        }

        private void SaveCardMarkupPercent(decimal value)
        {
            decimal normalized = value < 0m ? 0m : value;
            SaveGeneralSetupValue("CardMarkupPercent", normalized.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture));
        }

        private bool IsCreditCardTender(string tenderCode, string tenderDescription)
        {
            string code = (tenderCode ?? string.Empty).Trim();
            if (string.IsNullOrWhiteSpace(code))
            {
                return false;
            }

            try
            {
                using var connection = new SqlConnection(connectionString);
                connection.Open();

                using var colCmd = new SqlCommand(@"SELECT COUNT(*)
                                                    FROM INFORMATION_SCHEMA.COLUMNS
                                                    WHERE TABLE_NAME = 'TenderTypes' AND COLUMN_NAME = 'Is_Card_Payment'", connection);
                bool hasFlagColumn = Convert.ToInt32(colCmd.ExecuteScalar()) > 0;
                if (!hasFlagColumn)
                {
                    return false;
                }

                using var cmd = new SqlCommand("SELECT TOP 1 ISNULL(Is_Card_Payment, 0) FROM TenderTypes WHERE Code = @code", connection);
                cmd.Parameters.AddWithValue("@code", code);
                object? result = cmd.ExecuteScalar();
                return result != null && result != DBNull.Value && Convert.ToBoolean(result);
            }
            catch
            {
                string description = (tenderDescription ?? string.Empty).Trim();
                return description.IndexOf("credit", StringComparison.OrdinalIgnoreCase) >= 0
                    && description.IndexOf("card", StringComparison.OrdinalIgnoreCase) >= 0;
            }
        }

        private static decimal ApplyMarkupPercent(decimal baseAmount, decimal markupPercent)
        {
            if (baseAmount <= 0m || markupPercent <= 0m)
            {
                return baseAmount;
            }

            decimal multiplier = 1m + (markupPercent / 100m);
            return decimal.Round(baseAmount * multiplier, 2, MidpointRounding.AwayFromZero);
        }

        private static decimal CalculateCardProcessingFeeFromChargedAmount(decimal chargedAmount, decimal markupPercent)
        {
            if (chargedAmount <= 0m || markupPercent <= 0m)
            {
                return 0m;
            }

            decimal feeAmount = chargedAmount * (markupPercent / (100m + markupPercent));
            return decimal.Round(feeAmount, 2, MidpointRounding.AwayFromZero);
        }

        private void AddOrIncreaseCardProcessingFeeLine(decimal feeAmount)
        {
            if (feeAmount <= 0m)
            {
                return;
            }

            ListViewItem? existingFeeLine = salesListView.Items.Cast<ListViewItem>()
                .FirstOrDefault(item => string.Equals(item.Tag?.ToString(), CardProcessingFeeTag, StringComparison.OrdinalIgnoreCase));

            if (existingFeeLine != null)
            {
                decimal existingAmount = GetListViewItemTotal(existingFeeLine);
                decimal updatedAmount = decimal.Round(existingAmount + feeAmount, 2, MidpointRounding.AwayFromZero);
                existingFeeLine.SubItems[2].Text = $"{updatedAmount:F2}";
                existingFeeLine.SubItems[3].Text = $"{updatedAmount:F2}";
                currentTotal += feeAmount;
                UpdateTotal();
                return;
            }

            var feeLine = new ListViewItem(CardProcessingFeeDescription);
            feeLine.SubItems.Add("1");
            feeLine.SubItems.Add($"{feeAmount:F2}");
            feeLine.SubItems.Add($"{feeAmount:F2}");
            feeLine.SubItems.Add(string.Empty);
            feeLine.SubItems.Add(CardProcessingFeeTag);
            feeLine.ForeColor = Color.DarkBlue;
            feeLine.Tag = CardProcessingFeeTag;
            salesListView.Items.Add(feeLine);
            currentTotal += feeAmount;
            UpdateTotal();
        }

        private string LoadGeneralSetupValue(string key)
        {
            using var connection = new SqlConnection(connectionString);
            connection.Open();
            EnsureGeneralSetupTableSchema(connection);

            using var cmd = new SqlCommand("SELECT [Value] FROM GeneralSetup WHERE [Key] = @key", connection);
            cmd.Parameters.AddWithValue("@key", key);

            object? result = cmd.ExecuteScalar();
            return result == null || result == DBNull.Value ? string.Empty : result.ToString()?.Trim() ?? string.Empty;
        }

        private void SaveGeneralSetupValue(string key, string value)
        {
            using var connection = new SqlConnection(connectionString);
            connection.Open();
            EnsureGeneralSetupTableSchema(connection);

            using var cmd = new SqlCommand(@"
IF EXISTS (SELECT 1 FROM GeneralSetup WHERE [Key] = @key)
BEGIN
    UPDATE GeneralSetup
    SET [Value] = @value,
        UpdatedDate = GETDATE()
    WHERE [Key] = @key
END
ELSE
BEGIN
    INSERT INTO GeneralSetup ([Key], [Value], UpdatedDate)
    VALUES (@key, @value, GETDATE())
END", connection);
            cmd.Parameters.AddWithValue("@key", key);
            cmd.Parameters.AddWithValue("@value", value ?? string.Empty);
            cmd.ExecuteNonQuery();
        }

        private void ShowGeneralSetupDialog(IWin32Window owner)
        {
            try
