                {
                    Text = "General Setup",
                    Size = new Size(460, 280),
                    StartPosition = FormStartPosition.CenterParent,
                    BackColor = Color.White,
                    FormBorderStyle = FormBorderStyle.FixedDialog,
                    MaximizeBox = false,
                    MinimizeBox = false
                };

                var titleLabel = new Label
                {
                    Text = "General Setup",
                    Location = new Point(20, 20),
                    Size = new Size(220, 24),
                    Font = new Font("Arial", 12, FontStyle.Bold),
                    ForeColor = Color.DarkOliveGreen
                };

                var minimumWholesaleLabel = new Label
                {
                    Text = "Minimum Wholesales Price:",
                    Location = new Point(20, 70),
                    Size = new Size(180, 24),
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };

                var minimumWholesaleInput = new NumericUpDown
                {
                    Location = new Point(210, 68),
                    Size = new Size(180, 26),
                    Font = new Font("Arial", 10),
                    DecimalPlaces = 2,
                    ThousandsSeparator = true,
                    Minimum = 0,
                    Maximum = 1000000,
                    Value = LoadMinimumWholesalesPrice()
                };

                var cardMarkupLabel = new Label
                {
                    Text = "Card Markup %:",
                    Location = new Point(20, 106),
                    Size = new Size(180, 24),
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };

                var cardMarkupInput = new NumericUpDown
                {
                    Location = new Point(210, 104),
                    Size = new Size(180, 26),
                    Font = new Font("Arial", 10),
                    DecimalPlaces = 2,
                    ThousandsSeparator = true,
                    Minimum = 0,
                    Maximum = 100,
                    Value = LoadCardMarkupPercent()
                };

                var cardMarkupHintLabel = new Label
                {
                    Text = "Applied automatically to credit card payments.",
                    Location = new Point(20, 136),
                    Size = new Size(370, 18),
                    Font = new Font("Arial", 8, FontStyle.Italic),
                    ForeColor = Color.DimGray
                };

                var saveButton = new Button
                {
                    Text = "Save",
                    Location = new Point(210, 176),
                    Size = new Size(80, 32),
                    BackColor = Color.Green,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };

                var closeButton = new Button
                {
                    Text = "Close",
                    Location = new Point(310, 176),
                    Size = new Size(80, 32),
                    BackColor = Color.Gray,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };

                saveButton.Click += (_, _) =>
                {
                    try
                    {
                        SaveMinimumWholesalesPrice(minimumWholesaleInput.Value);
                        SaveCardMarkupPercent(cardMarkupInput.Value);
                        MessageBox.Show("General setup saved successfully.", "General Setup", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Failed to save general setup: {ex.Message}", "General Setup", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                };

                closeButton.Click += (_, _) => setupForm.Close();

                setupForm.Controls.AddRange(new Control[]
                {
                    titleLabel,
                    minimumWholesaleLabel,
                    minimumWholesaleInput,
                    cardMarkupLabel,
                    cardMarkupInput,
                    cardMarkupHintLabel,
                    saveButton,
                    closeButton
                });

                setupForm.ShowDialog(owner);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to open General Setup: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

