            string ConvertInchesToSelectedUnit(double inches, string? uom)
            {
                switch (uom)
                {
                    case "CM":
                        return (inches * 2.54).ToString("F1");
                    case "MM":
                        return (inches * 25.4).ToString("F1");
                    case "Ft":
                        return (inches / 12.0).ToString("F3");
                    default:
                        return inches.ToString("F0");
                }
            }

            void ApplyMainFiltrationDefaults()
            {
                try
                {
                    var sel = optionComboBox.SelectedItem?.ToString() ?? "Aquarium only";
                    double? defaultInches = null;

                    if (string.Equals(sel, "Undersump", StringComparison.OrdinalIgnoreCase))
                    {
                        defaultInches = 18.0;
                    }
                    else if (string.Equals(sel, "Overheadsump", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(sel, "Overhead Sump", StringComparison.OrdinalIgnoreCase))
                    {
                        defaultInches = 6.0;
                    }

                    if (defaultInches.HasValue)
                    {
                        var defaultVal = ConvertInchesToSelectedUnit(defaultInches.Value, unitComboBox.SelectedItem?.ToString() ?? "Inches");
                        widthTextBox.Text = defaultVal;
                        heightTextBox.Text = defaultVal;
                    }
                }
                catch { }
            }

            void ApplySumpFiltrationDefaults()
            {
                try
                {
                    if (!completeSetCheckBox.Checked)
                        return;

                    var selType = sumpTypeComboBox.SelectedItem?.ToString() ?? "Undersump";
                    double defaultInches = string.Equals(selType, "Undersump", StringComparison.OrdinalIgnoreCase) ? 18.0 : 6.0;

                    var defaultVal = ConvertInchesToSelectedUnit(defaultInches, sumpUnitCombo.SelectedItem?.ToString() ?? unitComboBox.SelectedItem?.ToString() ?? "Inches");
                    sumpWidthBox.Text = defaultVal;
                    sumpHeightBox.Text = defaultVal;
                }
                catch { }
            }

            double? GetMainAquariumLengthInFeet()
            {
                try
                {
                    if (!double.TryParse(lengthTextBox.Text, out double length) || length <= 0)
                        return null;

                    var uom = unitComboBox.SelectedItem?.ToString() ?? "Inches";
                    return uom switch
                    {
                        "CM" => length / 30.48,
                        "MM" => length / 304.8,
                        "Ft" => length,
                        _ => length / 12.0
                    };
                }
                catch
                {
                    return null;
                }
            }

            void ApplyDefaultLightSelection()
            {
                try
                {
                    if (submersibleLightItemCombo.Items.Count == 0)
                        return;

                    double? lengthInFeet = GetMainAquariumLengthInFeet();
                    if (!lengthInFeet.HasValue)
                    {
                        submersibleLightItemCombo.SelectedIndex = -1;
                        return;
                    }

                    int? targetFeet = null;
                    if (lengthInFeet.Value >= 6.0)
                        targetFeet = 6;
                    else if (lengthInFeet.Value >= 5.0)
                        targetFeet = 5;
                    else if (lengthInFeet.Value >= 4.0)
                        targetFeet = 4;
                    else if (lengthInFeet.Value >= 3.0)
                        targetFeet = 3;

                    if (!targetFeet.HasValue)
                    {
                        submersibleLightItemCombo.SelectedIndex = -1;
                        return;
                    }

                    bool matched = false;

                    for (int i = 0; i < submersibleLightItemCombo.Items.Count; i++)
                    {
                        string itemText = submersibleLightItemCombo.Items[i]?.ToString() ?? string.Empty;
                        string normalized = itemText.ToUpperInvariant()
                            .Replace(" ", string.Empty)
                            .Replace("-", string.Empty);

                        if (normalized.Contains($"{targetFeet.Value}FT") ||
                            normalized.Contains($"{targetFeet.Value}FEET") ||
                            normalized.Contains($"{targetFeet.Value}FOOT"))
                        {
                            submersibleLightItemCombo.SelectedIndex = i;
                            matched = true;
                            break;
                        }
                    }

                    if (!matched)
                    {
                        submersibleLightItemCombo.SelectedIndex = -1;
                    }
                }
                catch { }
            }

