            string? GetRequiredGlassFromSafetyMessage(string? message)
            {
                if (string.IsNullOrWhiteSpace(message)) return null;

                string msg = message.ToLowerInvariant();

                if (msg.Contains("12mm")) return "12mm";
                if (msg.Contains("10mm")) return "10mm";
                if (msg.Contains("6mm")) return "6mm";
                if (msg.Contains("3mm")) return "3mm";

                return null;
            }

            decimal CalculateStickerPrice(double panelLengthInInches, double panelWidthInInches, decimal pricePerSqFt)
            {
                if (panelLengthInInches <= 0 || panelWidthInInches <= 0 || pricePerSqFt <= 0m)
                    return 0m;

                double areaSqFeet = (panelLengthInInches / 12.0) * (panelWidthInInches / 12.0);
                if (areaSqFeet <= 0)
                    return 0m;

                decimal estimatedPrice = (decimal)areaSqFeet * pricePerSqFt;
                return Math.Ceiling(estimatedPrice / 10m) * 10m;
            }

            string GetSelectedStickerType(ComboBox comboBox)
            {
                return comboBox.SelectedItem?.ToString() ?? "Plain Sticker";
            }

            bool TryGetDimensionsInInches(out double lengthInInches, out double widthInInches, out double heightInInches)
            {
                lengthInInches = 0;
                widthInInches = 0;
                heightInInches = 0;

                if (!double.TryParse(lengthTextBox.Text, out double length) ||
                    !double.TryParse(widthTextBox.Text, out double width) ||
                    !double.TryParse(heightTextBox.Text, out double height) ||
                    length <= 0 || width <= 0 || height <= 0)
                {
                    return false;
                }

                switch (unitComboBox.SelectedItem?.ToString() ?? "Inches")
                {
                    case "CM":
                        lengthInInches = length / 2.54;
                        widthInInches = width / 2.54;
                        heightInInches = height / 2.54;
                        break;
                    case "Ft":
                        lengthInInches = length * 12;
                        widthInInches = width * 12;
                        heightInInches = height * 12;
                        break;
                    case "MM":
                        lengthInInches = length / 25.4;
                        widthInInches = width / 25.4;
                        heightInInches = height / 25.4;
                        break;
                    default:
                        lengthInInches = length;
                        widthInInches = width;
                        heightInInches = height;
                        break;
                }

                return true;
            }

            void DrawCustomAquariumPreview(Graphics graphics)
            {
                var bounds = aquariumPreviewPanel.ClientRectangle;
                graphics.Clear(Color.White);
                graphics.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;

                using (var backgroundBrush = new System.Drawing.Drawing2D.LinearGradientBrush(
                    bounds,
                    Color.FromArgb(250, 252, 255),
                    Color.FromArgb(233, 240, 247),
                    System.Drawing.Drawing2D.LinearGradientMode.Vertical))
                {
                    graphics.FillRectangle(backgroundBrush, bounds);
                }

                if (!TryGetDimensionsInInches(out double lengthInches, out double widthInches, out double heightInches))
                {
                    using var hintBorder = new Pen(Color.Silver, 1) { DashStyle = System.Drawing.Drawing2D.DashStyle.Dash };
                    using var hintBrush = new SolidBrush(Color.DimGray);
                    using var hintFont = new Font("Arial", 10, FontStyle.Bold);
                    using var format = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };

                    var inner = Rectangle.Inflate(bounds, -18, -18);
                    graphics.DrawRectangle(hintBorder, inner);
                    graphics.DrawString("3D aquarium preview", hintFont, hintBrush, inner, format);
                    return;
                }

                bool showStand = standCheckBox.Checked;
                bool showSump = completeSetCheckBox.Checked;
                bool overheadSump = string.Equals(sumpTypeComboBox.SelectedItem?.ToString(), "Overhead Sump", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(optionComboBox.SelectedItem?.ToString(), "Overheadsump", StringComparison.OrdinalIgnoreCase);

                int topReserve = showSump && overheadSump ? 18 : 6;
                int bottomReserve = showStand ? 42 : 20;
                int leftPad = 22;
                int rightPad = 22;
                int depthOffset = Math.Max(18, Math.Min(50, (int)Math.Round(widthInches * 1.25)));

                int usableWidth = Math.Max(110, bounds.Width - leftPad - rightPad - depthOffset);
                int usableHeight = Math.Max(80, bounds.Height - topReserve - bottomReserve);
                double scale = Math.Min(usableWidth / Math.Max(1d, lengthInches), usableHeight / Math.Max(1d, heightInches)) * 0.88;

                int frontWidth = Math.Max(90, Math.Min(usableWidth, (int)Math.Round(lengthInches * scale)));
                int frontHeight = Math.Max(60, Math.Min(usableHeight, (int)Math.Round(heightInches * scale)));
                int depth = Math.Max(18, Math.Min(depthOffset, (int)Math.Round(widthInches * scale * 0.55)));

                int frontLeft = leftPad + Math.Max(0, (usableWidth - frontWidth) / 2);
                int frontTop = Math.Max(16, topReserve + Math.Max(0, (usableHeight - frontHeight) / 2) + 6);

                var frontRect = new Rectangle(frontLeft, frontTop, frontWidth, frontHeight);
                var backRect = new Rectangle(frontRect.Left + depth, frontRect.Top - depth, frontRect.Width, frontRect.Height);

                Point[] topFace =
                {
                    new Point(frontRect.Left, frontRect.Top),
                    new Point(frontRect.Right, frontRect.Top),
                    new Point(backRect.Right, backRect.Top),
                    new Point(backRect.Left, backRect.Top)
                };

                Point[] sideFace =
                {
                    new Point(frontRect.Right, frontRect.Top),
                    new Point(frontRect.Right, frontRect.Bottom),
                    new Point(backRect.Right, backRect.Bottom),
                    new Point(backRect.Right, backRect.Top)
                };

                var shadowRect = new Rectangle(frontRect.Left + 10, frontRect.Bottom + 10, frontRect.Width + depth + 6, 16);
                using (var shadowBrush = new SolidBrush(Color.FromArgb(45, 0, 0, 0)))
                {
                    graphics.FillEllipse(shadowBrush, shadowRect);
                }

                Color borderColor = temperedCheckBox.Checked ? Color.Firebrick : Color.FromArgb(52, 103, 161);
                Color faceColor = lowIronCheckBox.Checked ? Color.FromArgb(145, 181, 239, 234) : Color.FromArgb(145, 113, 184, 239);
                Color sideColor = lowIronCheckBox.Checked ? Color.FromArgb(120, 154, 217, 221) : Color.FromArgb(110, 88, 152, 214);
                Color topColor = lowIronCheckBox.Checked ? Color.FromArgb(110, 210, 245, 241) : Color.FromArgb(95, 167, 213, 247);
                Color backPanelColor = stickerBackgroundCheckBox.Checked ? Color.FromArgb(210, 66, 99, 140) : Color.FromArgb(55, 255, 255, 255);

                using (var backBrush = new SolidBrush(backPanelColor))
                {
                    graphics.FillRectangle(backBrush, backRect);
                }

                using (var topBrush = new SolidBrush(topColor))
                {
                    graphics.FillPolygon(topBrush, topFace);
                }

                using (var sideBrush = new SolidBrush(sideColor))
                {
                    graphics.FillPolygon(sideBrush, sideFace);
                }

                using (var frontBrush = new System.Drawing.Drawing2D.LinearGradientBrush(
                    frontRect,
                    faceColor,
                    Color.FromArgb(95, 255, 255, 255),
                    System.Drawing.Drawing2D.LinearGradientMode.Vertical))
                {
                    graphics.FillRectangle(frontBrush, frontRect);
                }

                int waterInset = Math.Max(5, frontRect.Width / 28);
                int waterTopInset = rimlessCheckBox.Checked ? 7 : 12;
                var frontWaterRect = Rectangle.Inflate(frontRect, -waterInset, -waterInset);
                frontWaterRect.Y += waterTopInset;
                frontWaterRect.Height = Math.Max(12, frontWaterRect.Height - waterTopInset);

                var sideWaterPolygon = new[]
                {
                    new Point(frontRect.Right - waterInset, frontRect.Top + waterTopInset),
                    new Point(frontRect.Right - waterInset, frontRect.Bottom - waterInset),
                    new Point(backRect.Right - waterInset, backRect.Bottom - waterInset),
                    new Point(backRect.Right - waterInset, backRect.Top + waterTopInset)
                };

                using (var waterBrush = new SolidBrush(Color.FromArgb(130, 72, 170, 224)))
                {
                    graphics.FillRectangle(waterBrush, frontWaterRect);
                    graphics.FillPolygon(waterBrush, sideWaterPolygon);
                }

                if (!rimlessCheckBox.Checked)
                {
                    using var trimBrush = new SolidBrush(Color.FromArgb(75, 75, 75));
                    graphics.FillRectangle(trimBrush, frontRect.Left - 1, frontRect.Top - 3, frontRect.Width + 2, 7);
                    graphics.FillPolygon(trimBrush, topFace);
                }

                if (highstripCheckBox.Checked)
                {
                    using var highStripBrush = new SolidBrush(Color.FromArgb(215, 143, 43, 43));
                    graphics.FillRectangle(highStripBrush, frontRect.Left + 10, frontRect.Top + 10, Math.Max(16, frontRect.Width - 20), 10);
                }

                if (aioCheckBox.Checked)
                {
                    int chamberWidth = Math.Max(18, frontRect.Width / 7);
                    var aioRect = new Rectangle(frontRect.Right - chamberWidth - 8, frontRect.Top + 10, chamberWidth, Math.Max(30, frontRect.Height - 20));
                    using var aioBrush = new SolidBrush(Color.FromArgb(135, 60, 96, 148));
                    graphics.FillRectangle(aioBrush, aioRect);
                    graphics.DrawRectangle(Pens.DarkSlateBlue, aioRect);
                }

                if (showSump)
                {
                    int sumpWidth = Math.Max(70, frontRect.Width / 2);
                    int sumpHeight = Math.Max(18, frontRect.Height / 5);
                    int sumpLeft = frontRect.Left + (frontRect.Width - sumpWidth) / 2;
                    int sumpTop = overheadSump ? Math.Max(8, backRect.Top - sumpHeight - 8) : Math.Min(bounds.Bottom - sumpHeight - 10, frontRect.Bottom + 16);
                    var sumpRect = new Rectangle(sumpLeft, sumpTop, sumpWidth, sumpHeight);

                    using var sumpBrush = new SolidBrush(Color.FromArgb(200, 226, 236, 240));
                    graphics.FillRectangle(sumpBrush, sumpRect);
                    graphics.DrawRectangle(Pens.DarkSlateGray, sumpRect);

                    using var pipePen = new Pen(Color.DarkSlateGray, 3);
                    int pipeX = frontRect.Left + (frontRect.Width / 2);
                    if (overheadSump)
                    {
                        graphics.DrawLine(pipePen, pipeX, sumpRect.Bottom, pipeX, frontRect.Top);
                    }
                    else
                    {
                        graphics.DrawLine(pipePen, pipeX, frontRect.Bottom, pipeX, sumpRect.Top);
                    }
                }

                if (showStand)
                {
                    int standTop = frontRect.Bottom + 14;
                    int standHeight = 22;
                    int standWidth = Math.Max(80, frontRect.Width - 24);
                    var standRect = new Rectangle(frontRect.Left + 12, standTop, standWidth, standHeight);
                    using var standPen = new Pen(Color.SaddleBrown, 4);
                    graphics.DrawRectangle(standPen, standRect);
                    graphics.DrawLine(standPen, standRect.Left + 16, standRect.Top, standRect.Left + 16, standRect.Bottom);
                    graphics.DrawLine(standPen, standRect.Right - 16, standRect.Top, standRect.Right - 16, standRect.Bottom);
                }

                if (enclosureCheckBox.Checked)
                {
                    var enclosureRect = Rectangle.Inflate(frontRect, 8, 8);
                    using var enclosurePen = new Pen(Color.DarkGray, 2);
                    graphics.DrawRectangle(enclosurePen, enclosureRect);
                }

                int glassPenWidth = glassComboBox.SelectedItem?.ToString() switch
                {
                    "3mm" => 2,
                    "6mm" => 3,
                    "10mm" => 4,
                    "12mm" => 5,
                    _ => 3
                };

                using (var glassPen = new Pen(borderColor, glassPenWidth))
                {
                    graphics.DrawRectangle(glassPen, frontRect);
                    graphics.DrawPolygon(glassPen, topFace);
                    graphics.DrawPolygon(glassPen, sideFace);
                    graphics.DrawRectangle(glassPen, backRect);
                }

                using var textBrush = new SolidBrush(Color.FromArgb(42, 59, 76));
                using var captionFont = new Font("Arial", 8.5f, FontStyle.Bold);
                graphics.DrawString(
                    $"{lengthInches:F1}\" x {widthInches:F1}\" x {heightInches:F1}\"",
                    captionFont,
                    textBrush,
                    new PointF(10, bounds.Height - 20));
            }

            aquariumPreviewPanel.Paint += (s, e) => DrawCustomAquariumPreview(e.Graphics);

            void UpdateTemperedGlassRequirement(bool notifyUser)
            {
                bool dimensionsAvailable = TryGetDimensionsInInches(out _, out double widthInInches, out double heightInInches);
                bool shouldRequireTempered = dimensionsAvailable && (widthInInches >= 36.0 || heightInInches >= 36.0);
                bool wasRequired = temperedGlassMandatoryBySize;

                temperedGlassMandatoryBySize = shouldRequireTempered;

                try
                {
                    isTemperedRuleUpdate = true;

                    if (shouldRequireTempered)
                    {
                        temperedCheckBox.Checked = true;
                        temperedCheckBox.Enabled = false;
                        temperedCheckBox.Text = "Tempered Glass (Mandatory)";

                        if (notifyUser && !wasRequired)
                        {
                            MessageBox.Show(
                                "Tempered glass is mandatory when the custom aquarium width or height reaches 36 inches or more. The Tempered Glass option has been enabled automatically.",
                                "Tempered Glass Required",
                                MessageBoxButtons.OK,
                                MessageBoxIcon.Information);
                        }
                    }
                    else
                    {
                        temperedCheckBox.Text = "Tempered Glass";
                        temperedCheckBox.Enabled = !lowIronCheckBox.Checked;
                    }
                }
                catch { }
                finally
                {
                    isTemperedRuleUpdate = false;
                }
            }

            decimal GetSelectedStickerPrice(ComboBox comboBox)
            {
                return string.Equals(GetSelectedStickerType(comboBox), "Sticker Tiles", StringComparison.OrdinalIgnoreCase)
                    ? GlobalSettings.pricePerSqInchTiles
                    : GlobalSettings.pricePerSqInchPlain;
            }

            string GetStickerBackgroundDescription()
            {
                if (!stickerBackgroundCheckBox.Checked)
                {
                    return string.Empty;
                }

                return stickerBackgroundAllSidesCheckBox.Checked
                    ? $"Sticker Background ({GetSelectedStickerType(stickerTypeComboBox)}, All Sides)"
                    : $"Sticker Background ({GetSelectedStickerType(stickerTypeComboBox)})";
            }

            string GetStickerBottomDescription()
            {
                if (!stickerBottomCheckBox.Checked)
                {
                    return string.Empty;
                }

                return $"Sticker Bottom ({GetSelectedStickerType(stickerBottomTypeComboBox)})";
            }

            // Auto-calculation method
            Action performCalculation = () =>
            {
                if (double.TryParse(lengthTextBox.Text, out double length) &&
                    double.TryParse(widthTextBox.Text, out double width) &&
                    double.TryParse(heightTextBox.Text, out double height) &&
                    length > 0 && width > 0 && height > 0)
                {
                    string selectedUnit = unitComboBox.SelectedItem?.ToString() ?? "Inches";
                    string selectedGlass = glassComboBox.SelectedItem?.ToString() ?? "6mm";
                    bool isTempered = temperedCheckBox.Checked;
                    bool isAio = aioCheckBox.Checked;
                    bool isLowIron = lowIronCheckBox.Checked;
                    bool hasAquascapeService = aquascapeServiceCheckBox.Checked;
                    bool hasEnclosure = enclosureCheckBox.Checked;
                    bool hasStickerBackground = stickerBackgroundCheckBox.Checked;
                    bool hasStickerBottom = stickerBottomCheckBox.Checked;
                    var stickerDescriptions = new List<string>();
                    if (hasStickerBackground)
                    {
                        stickerDescriptions.Add(GetStickerBackgroundDescription());
                    }
                    if (hasStickerBottom)
                    {
                        stickerDescriptions.Add(GetStickerBottomDescription());
                    }
                    string stickerOptionText = stickerDescriptions.Count > 0 ? $" {string.Join(" ", stickerDescriptions)}" : string.Empty;
                    double lengthInInches, widthInInches, heightInInches;

                    // Convert to inches based on selected unit
                    switch (selectedUnit)
                    {
                        case "CM":
                            lengthInInches = length / 2.54;
                            widthInInches = width / 2.54;
                            heightInInches = height / 2.54;
                            dimensionsText = $"L: {length:F1}cm x W: {width:F1}cm x H: {height:F1}cm ({selectedGlass}{(isLowIron ? " Low Iron" : "")}{(isTempered ? " Tempered" : "")}{(isAio ? " AIO" : "")}{(hasAquascapeService ? " Aquascape" : "")}{(hasEnclosure ? " Enclosure" : "")}{stickerOptionText})";
                            break;
                        case "Ft":
                            lengthInInches = length * 12;
                            widthInInches = width * 12;
                            heightInInches = height * 12;
                            dimensionsText = $"L: {length:F1}ft x W: {width:F1}ft x H: {height:F1}ft ({selectedGlass}{(isLowIron ? " Low Iron" : "")}{(isTempered ? " Tempered" : "")}{(isAio ? " AIO" : "")}{(hasAquascapeService ? " Aquascape" : "")}{(hasEnclosure ? " Enclosure" : "")}{stickerOptionText})";
                            break;
                        case "MM":
                            lengthInInches = length / 25.4;
                            widthInInches = width / 25.4;
                            heightInInches = height / 25.4;
                            dimensionsText = $"L: {length:F1}mm x W: {width:F1}mm x H: {height:F1}mm ({selectedGlass}{(isLowIron ? " Low Iron" : "")}{(isTempered ? " Tempered" : "")}{(isAio ? " AIO" : "")}{(hasAquascapeService ? " Aquascape" : "")}{(hasEnclosure ? " Enclosure" : "")}{stickerOptionText})";
                            break;
                        default: // Inches
                            lengthInInches = length;
                            widthInInches = width;
                            heightInInches = height;
                                dimensionsText = $"L: {length:F1}\" x W: {width:F1}\" x H: {height:F1}\" ({selectedGlass}{(isLowIron ? " Low Iron" : "")}{(isTempered ? " Tempered" : "")}{(isAio ? " AIO" : "")}{(hasAquascapeService ? " Aquascape" : "")}{(hasEnclosure ? " Enclosure" : "")}{stickerOptionText})";
                            break;
                    }

                    // Calculate volume in gallons (1 gallon = 231 cubic inches) early so we can use it in safety checks
                    gallons = (lengthInInches * widthInInches * heightInInches) / 231.0;

                    // Centralized safety validation using FunctionEvents.safetyrules
                    bool isRimless = rimlessCheckBox.Checked;
                    var safety = FunctionEvents.safetyrules(lengthInInches, widthInInches, heightInInches, selectedGlass, isTempered, isRimless);
                    // If the safety function indicates an automatic change (e.g. upgrade 3mm -> 6mm), apply it and recalculate
                    if (!string.IsNullOrWhiteSpace(safety.AutoChangeTo))
                    {
                        var auto = safety.AutoChangeTo;
                        try
                        {
                            glassComboBox.SelectedItem = auto;
                        }
                        catch { }
                        MessageBox.Show(safety.Message, "Glass Auto-upgrade", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        // Re-run calculation with updated glass selection by triggering the Calculate button click
                        calculateButton.PerformClick();
                        return;
                    }

                    if (!safety.IsSafe)
                    {
                        var requiredGlass = GetRequiredGlassFromSafetyMessage(safety.Message);
                        if (!string.IsNullOrWhiteSpace(requiredGlass))
                        {
                            try
                            {
                                if (safety.Message.IndexOf("tempered 12mm", StringComparison.OrdinalIgnoreCase) >= 0)
                                {
                                    temperedCheckBox.Checked = true;
                                }

                                glassComboBox.SelectedItem = requiredGlass;
                                MessageBox.Show($"{safety.Message}\n\nGlass thickness has been updated to {requiredGlass}.", "Glass Auto-upgrade", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                calculateButton.PerformClick();
                                return;
                            }
                            catch { }
                        }

                        // Populate inches label for reference
                        inchesLabel.Text = $"Dimensions (in): L: {lengthInInches:F1}\" x W: {widthInInches:F1}\" x H: {heightInInches:F1}\" ({selectedGlass})";
                        MessageBox.Show(safety.Message, "Glass Thickness Required", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        volumeLabel.Text = "Volume: 0 gallons";
                        priceLabel.Text = "Estimated Price: 0.00";
                        addToSaleButton.Enabled = false;
                        hasCalculated = false;
                        return;
                    }

                    // If High Strip is selected, compute high-strip price using linear feet formula: (L + W*2) in feet * acrylic price per sqft (P90)
                    highStripComponentPrice = 0m;
                    if (highstripCheckBox.Checked)
                    {
                        const decimal acrylicPricePerSqFt = 90.00m; // P90 per sqft as requested
                        // linear feet = (L + W*2) converted from inches to feet
                        double linearFeet = ((lengthInInches + widthInInches) * 2.0) / 12.0;
                        highStripComponentPrice = (decimal)linearFeet * acrylicPricePerSqFt;
                        // do NOT return here; we'll add this on top of the regular glass price below
                    }

                    // Get glass pricing from database
                    decimal pricePerSqFt = 100.00m; // Default fallback price
                    try
                    {
                        using (var connection = new SqlConnection(connectionString))
                        {
                            
                            connection.Open();
                            var cmd = new SqlCommand("SELECT PricePerSqFt FROM GlassPricingSetup WHERE UOM = 'MM' AND Units = @thickness", connection);
                            cmd.Parameters.AddWithValue("@thickness", selectedGlass.Replace("mm", ""));
                            var result = cmd.ExecuteScalar();
                            if (result != null && result != DBNull.Value)
                            {
                                pricePerSqFt = (decimal)result;
                                
                            }
                        }
                    }
                    catch
                    {
                        // Use fallback pricing if database access fails
                        pricePerSqFt = selectedGlass switch
                        {
                            "3mm" => 85.00m,
                            "6mm" => 185.00m,
                            "10mm" => 290.00m,
                            "12mm" => 330.00m,
                            _ => 100.00m
                        };
                    }

                    double glassSurfaceArea = (2 * (lengthInInches * heightInInches)) +
                                            (2 * (widthInInches * heightInInches)) +
                                            (lengthInInches * widthInInches);

                    // Convert to square feet by dividing by 144
                    double totalSqFt = glassSurfaceArea / 144.0;

                    // Apply pricing adjustments based on glass type and tank size
                    decimal finalPricePerSqFt = pricePerSqFt;

                    // Discount for small 6mm glass tanks (less than 90 gallons)
                    if (gallons < 90 && selectedGlass == "6mm")
                    {
                        finalPricePerSqFt = 117.00m; // Set to ?117 per sq ft for small 6mm tanks
                    }
                    // Surcharge for very large 12mm glass tanks (300+ gallons)
                    else if (gallons >= 300 && selectedGlass == "12mm")
                    {
                        finalPricePerSqFt += 145.00m; // Add ?130 per sq ft for very large tanks with 12mm glass
                    }
                    // Surcharge for large 12mm glass tanks (170+ gallons)
                    else if (gallons >= 170 && selectedGlass == "12mm")
                    {
                        finalPricePerSqFt += 110.00m; // Add ?95 per sq ft for large tanks with 12mm glass
                    }

                    // Apply tempered glass multiplier (2x rate)
                    if (isTempered)
                    {
                        finalPricePerSqFt *= 2;
                    }

                    // Calculate final price (glass base)
                    calculatedPrice = (decimal)(totalSqFt * (double)finalPricePerSqFt);
                    glassComponentPrice = calculatedPrice;

                    // If High Strip price was computed, add it on top of the glass price
                    if (highStripComponentPrice > 0m)
                    {
                        calculatedPrice += highStripComponentPrice;
                    }

                    // If a filtration sump is included (Complete setup), calculate sump glass price
                    try
                    {
                        if (completeSetCheckBox.Checked)
                        {
                            // Parse sump dimensions and convert to inches according to sump UOM
                            if (double.TryParse(sumpLengthBox.Text, out double sLen) && sLen > 0
                                && double.TryParse(sumpWidthBox.Text, out double sWid) && sWid > 0
                                && double.TryParse(sumpHeightBox.Text, out double sHei) && sHei > 0)
                            {
                                string sumpUom = sumpUnitCombo.SelectedItem?.ToString() ?? unitComboBox.SelectedItem?.ToString() ?? "Inches";
                                double sLenIn, sWidIn, sHeiIn;
                                switch (sumpUom)
                                {
                                    case "CM":
                                        sLenIn = sLen / 2.54; sWidIn = sWid / 2.54; sHeiIn = sHei / 2.54; break;
                                    case "Ft":
                                        sLenIn = sLen * 12.0; sWidIn = sWid * 12.0; sHeiIn = sHei * 12.0; break;
                                    case "MM":
                                        sLenIn = sLen / 25.4; sWidIn = sWid / 25.4; sHeiIn = sHei / 25.4; break;
                                    default:
                                        sLenIn = sLen; sWidIn = sWid; sHeiIn = sHei; break;
                                }

                                double sumpSurfaceArea = (2 * (sLenIn * sHeiIn)) + (2 * (sWidIn * sHeiIn)) + (sLenIn * sWidIn);
                                double sumpSqFt = sumpSurfaceArea / 144.0;

                                // Use same base price per sq ft (from glass pricing lookup). Apply tempered multiplier if chosen.
                                decimal sumpFinalPricePerSqFt = pricePerSqFt;
                                if (isTempered) sumpFinalPricePerSqFt *= 2;

                                decimal sumpPrice = (decimal)sumpSqFt * sumpFinalPricePerSqFt;
                                // Record and add sump price to total calculated price so markups and rounding include it
                                sumpComponentPrice = sumpPrice;
                                calculatedPrice += sumpComponentPrice;

                                // If filter media is selected, calculate media price based on sump volume
                                filterMediaComponentPrice = 0m;
                                try
                                {
                                    if (filterMediasCheckBox.Visible && filterMediasCheckBox.Checked)
                                    {
                                        // Convert sump dimensions in inches to feet for volume calculation
                                        double sLenFt = sLenIn / 12.0;
                                        double sWidFt = sWidIn / 12.0;
                                        double sHeiFt = sHeiIn / 12.0;

                                        // Calculate media using configurable rate and fill ratio
                                        double volumeCuFt = sLenFt * sWidFt * sHeiFt;
                                        double liters = volumeCuFt * 28.316; // 1 cubic foot ≈ 28.316 liters

                                        // Apply CalculateMedia-style formula: media_kg = liters * fill_ratio; price = media_kg * rate_per_kg
                                        const double ratePerKg = 300.0;   // ₱ per kg

                                        // Undersump vs Overhead Sump fill ratios
                                        double fillRatio;
                                        var sumpTypeForMedia = sumpTypeComboBox.SelectedItem?.ToString() ?? "Undersump";
                                        if (string.Equals(sumpTypeForMedia, "Overhead Sump", StringComparison.OrdinalIgnoreCase))
                                        {
                                            fillRatio = 0.18; // Overhead sump
                                        }
                                        else
                                        {
                                            fillRatio = 0.04; // Undersump / default
                                        }

                                        double mediaKgExact = liters * fillRatio;
                                        double mediaKgRounded = Math.Round(mediaKgExact); // round to nearest kg for pricing

                                        filterMediaKg = mediaKgRounded;
                                        // Simple rule: 1 mesh bag and 1 filter wool per kg
                                        filterMediaMeshBags = (int)Math.Round(mediaKgRounded);
                                        filterMediaFilterWools = (int)Math.Round(mediaKgRounded);

                                        filterMediaComponentPrice = (decimal)(mediaKgRounded * ratePerKg);
                                        calculatedPrice += filterMediaComponentPrice;
                                    }
                                }
                                catch { filterMediaComponentPrice = 0m; }

                                // Show sump dimensions in inches for user reference
                                try
                                {
                                    var sumpTypeText = sumpTypeComboBox.SelectedItem?.ToString() ?? "Sump";
                                    sumpInchesLabel.Text = $"{sumpTypeText} Dimensions (in): L: {sLenIn:F1}\" x W: {sWidIn:F1}\" x H: {sHeiIn:F1}\"";
                                    sumpInchesLabel.Visible = true;

                                    // Show filter media details just below the sump dimensions when available
                                    if (filterMediasCheckBox.Visible && filterMediasCheckBox.Checked && filterMediaKg > 0)
                                    {
                                        // Show labels only, without quantities as requested
                                        filterMediaDetailsLabel.Text = "Filter Medias | Mesh Bags | Filter Wools";
                                        filterMediaDetailsLabel.Visible = true;
                                    }
                                    else
                                    {
                                        filterMediaDetailsLabel.Text = "";
                                        filterMediaDetailsLabel.Visible = false;
                                    }
                                    // Update sump details caption (UOM, piping/overflow state)
                                    try
                                    {
                                        var sumpUomText = sumpUnitCombo.SelectedItem?.ToString() ?? unitComboBox.SelectedItem?.ToString() ?? "Inches";
                                        var pipingState = pipingCheckBox.Visible && pipingCheckBox.Checked ? "Piping: Yes" : "Piping: No";
                                        var overflowState = overflowBoxCheckBox.Visible && overflowBoxCheckBox.Checked ? "Overflow: Yes" : "Overflow: No";
                                        var filterState = filterMediasCheckBox.Visible && filterMediasCheckBox.Checked ? "Filter Medias: Yes" : "Filter Medias: No";
                                        var lightState = submersibleLightCheckBox.Visible && submersibleLightCheckBox.Checked ? "Submersible Light: Yes" : "Submersible Light: No";
                                        var pumpState = submersiblePumpCheckBox.Visible && submersiblePumpCheckBox.Checked ? "Submersible Pump: Yes" : "Submersible Pump: No";
                                        var coverState = allumTopCoverCheckBox.Visible && allumTopCoverCheckBox.Checked ? "Allum Top Cover: Yes" : "Allum Top Cover: No";
                                        // Show selected extras in the details caption
                                        sumpDetailsLabel.Text = $"{sumpTypeText} | UOM: {sumpUomText} | {pipingState} | {overflowState} | {filterState} | {lightState} | {pumpState} | {coverState}";
                                        sumpDetailsLabel.Visible = true;
                                    }
                                    catch { sumpDetailsLabel.Visible = false; }
                                }
                                catch { sumpInchesLabel.Visible = false; }
                            }
                        }
                    }
                    catch { }

                    // Add fixed-price extras for undersump options if selected
                    // NOTE: pipingComponentPrice will be applied on top of the final total (after markup/rounding) as requested
                    pipingComponentPrice = 0.00m;
                    aquascapeServiceComponentPrice = 0.00m;
                    overflowComponentPrice = 0.00m;
                    lightComponentPrice = 0.00m;
                    pumpComponentPrice = 0.00m;
                    allumTopCoverComponentPrice = 0.00m;
                    stickerBackgroundComponentPrice = 0.00m;
                    stickerBottomComponentPrice = 0.00m;
                    try
                    {
                        if (pipingCheckBox.Visible && pipingCheckBox.Checked)
                        {
                            // If the sump is an Overhead Sump, use the lower piping price; otherwise use the undersump pricing.
                            var sumpTypeText = sumpTypeComboBox.SelectedItem?.ToString() ?? "";
                            if (string.Equals(sumpTypeText, "Overhead Sump", StringComparison.OrdinalIgnoreCase))
                            {
                                pipingComponentPrice = 450.00m; // Overhead sump piping special price (deferred)
                            }
                            else
                            {
                                pipingComponentPrice = 2200.00m; // Set of Piping (undersump/default) (deferred)
                            }
                        }
                        if (overflowBoxCheckBox.Visible && overflowBoxCheckBox.Checked)
                        {
                            // Overflow box remains part of the calculated price and is subject to markups/rounding
                            overflowComponentPrice = 1900.00m;
                            calculatedPrice += overflowComponentPrice; // part of marked-up total
                        }

                        // Submersible light price based on selected light item
                        if (submersibleLightCheckBox.Visible && submersibleLightCheckBox.Checked && submersibleLightItemCombo.Items.Count > 0)
                        {
                            try
                            {
                                string selectedLight = submersibleLightItemCombo.SelectedItem?.ToString() ?? string.Empty;
                                string lightCode = selectedLight;
                                int openIdx = selectedLight.LastIndexOf('(');
                                int closeIdx = selectedLight.LastIndexOf(')');
                                if (openIdx >= 0 && closeIdx > openIdx)
                                {
                                    lightCode = selectedLight.Substring(openIdx + 1, closeIdx - openIdx - 1).Trim();
                                }

                                if (!string.IsNullOrWhiteSpace(lightCode))
                                {
                                    using (var conn = new SqlConnection(connectionString))
                                    {
                                        conn.Open();
                                        using (var cmd = new SqlCommand("SELECT Price FROM Items WHERE Code = @code", conn))
                                        {
                                            cmd.Parameters.AddWithValue("@code", lightCode);
                                            var result = cmd.ExecuteScalar();
                                            if (result != null && result != DBNull.Value)
                                            {
                                                lightComponentPrice = Convert.ToDecimal(result);
                                                if (lightComponentPrice > 0m)
                                                {
                                                    calculatedPrice += lightComponentPrice; // part of marked-up total
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            catch { lightComponentPrice = 0.00m; }
                        }

                        // Submersible pump price based on selected pump item
                        if (submersiblePumpCheckBox.Visible && submersiblePumpCheckBox.Checked && submersiblePumpItemCombo.Items.Count > 0)
                        {
                            try
                            {
                                string selectedPump = submersiblePumpItemCombo.SelectedItem?.ToString() ?? string.Empty;
                                string pumpCode = selectedPump;
                                int openIdxP = selectedPump.LastIndexOf('(');
                                int closeIdxP = selectedPump.LastIndexOf(')');
                                if (openIdxP >= 0 && closeIdxP > openIdxP)
                                {
                                    pumpCode = selectedPump.Substring(openIdxP + 1, closeIdxP - openIdxP - 1).Trim();
                                }

                                if (!string.IsNullOrWhiteSpace(pumpCode))
                                {
                                    using (var conn = new SqlConnection(connectionString))
                                    {
                                        conn.Open();
                                        using (var cmd = new SqlCommand("SELECT Price FROM Items WHERE Code = @code", conn))
                                        {
                                            cmd.Parameters.AddWithValue("@code", pumpCode);
                                            var result = cmd.ExecuteScalar();
                                            if (result != null && result != DBNull.Value)
                                            {
                                                pumpComponentPrice = Convert.ToDecimal(result);
                                                if (pumpComponentPrice > 0m)
                                                {
                                                    calculatedPrice += pumpComponentPrice; // part of marked-up total
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            catch { pumpComponentPrice = 0.00m; }
                        }

                        // Allum Top Cover price using the same calculation as Custom Stickers "Allum TopCover" type
                        // If sump type is Overhead Sump, deduct sump width from aquarium width when computing cover area.
                        if (allumTopCoverCheckBox.Visible && allumTopCoverCheckBox.Checked)
                        {
                            try
                            {
                                double effectiveWidthInInches = widthInInches;

                                // When an Overhead Sump is used and sump width is available, deduct it from the aquarium width
                                var sumpTypeForCover = sumpTypeComboBox.SelectedItem?.ToString() ?? string.Empty;
                                if (string.Equals(sumpTypeForCover, "Overhead Sump", StringComparison.OrdinalIgnoreCase))
                                {
                                    if (double.TryParse(sumpWidthBox.Text, out double sWid) && sWid > 0)
                                    {
                                        string sumpUom = sumpUnitCombo.SelectedItem?.ToString() ?? unitComboBox.SelectedItem?.ToString() ?? "Inches";
                                        double sWidIn;
                                        switch (sumpUom)
                                        {
                                            case "CM":
                                                sWidIn = sWid / 2.54; break;
                                            case "Ft":
                                                sWidIn = sWid * 12.0; break;
                                            case "MM":
                                                sWidIn = sWid / 25.4; break;
                                            default:
                                                sWidIn = sWid; break;
                                        }

                                        // Deduct sump width from aquarium width, but never below zero
                                        effectiveWidthInInches = Math.Max(0.0, widthInInches - sWidIn);
                                    }
                                }

                                // Top area = tank length x effective width, converted to square feet
                                double lengthInFeet = lengthInInches / 12.0;
                                double widthInFeet = effectiveWidthInInches / 12.0;
                                double areaSqFeet = lengthInFeet * widthInFeet;

                                const decimal pricePerSqFtAllum = 500m; // 500 per sq ft (same as stickers)
                                decimal estimatedCoverPrice = (decimal)areaSqFeet * pricePerSqFtAllum;
                                // Round up to nearest 10, same as Custom Stickers implementation
                                decimal roundedCoverPrice = Math.Ceiling(estimatedCoverPrice / 10m) * 10m;

                                allumTopCoverComponentPrice = roundedCoverPrice;
                            }
                            catch
                            {
                                allumTopCoverComponentPrice = 0.00m;
                            }
                        }

                        if (stickerBackgroundCheckBox.Checked)
                        {
                            decimal selectedStickerPrice = GetSelectedStickerPrice(stickerTypeComboBox);
                            stickerBackgroundComponentPrice = CalculateStickerPrice(lengthInInches, heightInInches, selectedStickerPrice);

                            if (stickerBackgroundAllSidesCheckBox.Checked)
                            {
                                stickerBackgroundComponentPrice += CalculateStickerPrice(widthInInches, heightInInches, selectedStickerPrice) * 2m;
                            }
                        }

                        if (stickerBottomCheckBox.Checked)
                        {
                            decimal selectedBottomStickerPrice = GetSelectedStickerPrice(stickerBottomTypeComboBox);
                            stickerBottomComponentPrice = CalculateStickerPrice(lengthInInches, widthInInches, selectedBottomStickerPrice);
                        }
                    }
                    catch { }

                    // After computing pipingPrice, update the sump details caption to include the piping price if applicable
                    try
                    {
                        if (completeSetCheckBox.Checked)
                        {
                            var st = sumpTypeComboBox.SelectedItem?.ToString() ?? "Sump";
                            var sumpUomText = sumpUnitCombo.SelectedItem?.ToString() ?? unitComboBox.SelectedItem?.ToString() ?? "Inches";
                            var pipingState = pipingCheckBox.Visible && pipingCheckBox.Checked ? $"Piping: Yes" : "Piping: No";
                            var overflowState = overflowBoxCheckBox.Visible && overflowBoxCheckBox.Checked ? "Overflow: Yes" : "Overflow: No";
                            var filterState = filterMediasCheckBox.Visible && filterMediasCheckBox.Checked ? "Filter Medias: Yes" : "Filter Medias: No";
                            var lightState = submersibleLightCheckBox.Visible && submersibleLightCheckBox.Checked ? "Submersible Light: Yes" : "Submersible Light: No";
                            var pumpState = submersiblePumpCheckBox.Visible && submersiblePumpCheckBox.Checked ? "Submersible Pump: Yes" : "Submersible Pump: No";
                            var coverState = allumTopCoverCheckBox.Visible && allumTopCoverCheckBox.Checked ? "Allum Top Cover: Yes" : "Allum Top Cover: No";
                            sumpDetailsLabel.Text = $"{st} | UOM: {sumpUomText} | {pipingState} | {overflowState} | {filterState} | {lightState} | {pumpState} | {coverState}";
                            sumpDetailsLabel.Visible = true;
                        }
                        else
                        {
                            sumpDetailsLabel.Text = "";
                            sumpDetailsLabel.Visible = false;
                        }
                    }
                    catch { }

                    // Apply option-based markup: 90% increase for undersump or overheadsump options
                    try
                    {
                        var opt = optionComboBox.SelectedItem?.ToString() ?? "Aquarium only";
                        if (string.Equals(opt, "Undersump", StringComparison.OrdinalIgnoreCase) ||
                            string.Equals(opt, "Overheadsump", StringComparison.OrdinalIgnoreCase) ||
                            string.Equals(opt, "Overheadsum", StringComparison.OrdinalIgnoreCase))
                        {
                            calculatedPrice = Math.Round(calculatedPrice * 1.90m, 2);
                        }

                        // Apply AIO markup: add 140% on top of the original aquarium price
                        if (aioCheckBox.Checked)
                        {
                            calculatedPrice = Math.Round(calculatedPrice * 2.40m, 2);
                        }

                        // Apply Low Iron markup: add 70% on top of the current aquarium price
                        if (lowIronCheckBox.Checked)
                        {
                            calculatedPrice = Math.Round(calculatedPrice * 1.70m, 2);
                        }

                    }
                    catch { }

                    // Round to the nearest tens only if price is 1000 or more
                    if (calculatedPrice >= 1000)
                    {
                        calculatedPrice = Math.Round(calculatedPrice / 10) * 10;
                    }

                    // At this point markups/rounding have been applied. Add pipingComponentPrice on top of the total as requested.
                    if (pipingComponentPrice > 0m)
                    {
                        calculatedPrice += pipingComponentPrice;
                    }

                    // Add Allum Top Cover price after markups/rounding, using same rules as Custom Stickers
                    if (allumTopCoverComponentPrice > 0m)
                    {
                        calculatedPrice += allumTopCoverComponentPrice;
                    }

                    if (stickerBackgroundComponentPrice > 0m)
                    {
                        calculatedPrice += stickerBackgroundComponentPrice;
                    }

                    if (stickerBottomComponentPrice > 0m)
                    {
                        calculatedPrice += stickerBottomComponentPrice;
                    }

                    // Aquascape service: ₱2100 per 10 gallons (₱210 per gallon), proportional to volume
                    if (aquascapeServiceCheckBox.Checked)
                    {
                        try
                        {
                            // Example: 10 gal => 2100; 20 gal => 4200; 15 gal => 3150
                            aquascapeServiceComponentPrice = Math.Round((decimal)gallons * 210.00m, 0, MidpointRounding.AwayFromZero);
                            calculatedPrice += aquascapeServiceComponentPrice;
                        }
                        catch { aquascapeServiceComponentPrice = 0.00m; }
                    }

                    // Enclosure markup: compute the final total price x 210%
                    if (enclosureCheckBox.Checked)
                    {
                        calculatedPrice = Math.Round(calculatedPrice * 2.10m, 2);
                        if (calculatedPrice >= 1000)
                        {
                            calculatedPrice = Math.Round(calculatedPrice / 10) * 10;
                        }
                    }

                    // Capture aquarium-only price (so stand can be added without being affected by enclosure)
                    aquariumOnlyCalculatedPrice = calculatedPrice;

                    // Stand price is added after aquarium markups/rounding and is NOT affected by enclosure multiplier
                    if (standCheckBox.Checked && standComponentPrice > 0m)
                    {
                        calculatedPrice += standComponentPrice;
                    }

                    bool requiresManualLightSelection = submersibleLightCheckBox.Visible
                        && submersibleLightCheckBox.Checked
                        && submersibleLightItemCombo.Items.Count > 0
                        && submersibleLightItemCombo.SelectedIndex < 0;

                    bool requiresManualPumpSelection = submersiblePumpCheckBox.Visible
                        && submersiblePumpCheckBox.Checked
                        && submersiblePumpItemCombo.Items.Count > 0
                        && submersiblePumpItemCombo.SelectedIndex < 0;

                    volumeLabel.Text = $"Volume: {gallons:F1} gallons";

                    // Final price after adding piping (piping is not subject to additional markup/rounding)
                    priceLabel.Text = requiresManualLightSelection
                        ? "Price: select light first"
                        : requiresManualPumpSelection
                        ? "Price: select pump first"
                        : $"Price: {calculatedPrice:N2}";

                    // Show dimensions in inches for user reference
                    inchesLabel.Text = $"Dimensions (in): L: {lengthInInches:F1}\" x W: {widthInInches:F1}\" x H: {heightInInches:F1}\"";

                    addToSaleButton.Enabled = !requiresManualLightSelection && !requiresManualPumpSelection;
                    hasCalculated = true;
                }
                else
                {
                    volumeLabel.Text = "Volume: 0 gallons";
                    priceLabel.Text = "Estimated Price: 0.00";
                    inchesLabel.Text = "";
                    sumpInchesLabel.Text = "";
                    sumpInchesLabel.Visible = false;
                    filterMediaDetailsLabel.Text = "";
                    filterMediaDetailsLabel.Visible = false;
                    addToSaleButton.Enabled = false;
                    hasCalculated = false;
                    aquariumOnlyCalculatedPrice = 0m;
                }
            };

            // Add change event handlers for auto-recalculation
            // Auto-recalculate immediately when any input or selection changes.
            EventHandler textChanged = (s, e) =>
            {
                // Always attempt recalculation; performCalculation will validate inputs and update the UI.
                UpdateTemperedGlassRequirement(true);
                aquariumPreviewPanel.Invalidate();
                performCalculation();
            };

            EventHandler selectionChanged = (s, e) =>
            {
                // Enforce AIO and Low Iron safety rules against thin glass.
                try
                {
                    if (aioCheckBox.Checked && glassComboBox.SelectedItem != null && glassComboBox.SelectedItem.ToString() == "3mm")
                    {
                        // Automatically upgrade to 6mm when AIO is selected.
                        if (glassComboBox.Items.Contains("6mm"))
                        {
                            glassComboBox.SelectedItem = "6mm";
                        }
                        MessageBox.Show("AIO setup is not allowed with 3mm glass. Glass thickness has been set to 6mm.", "Glass Thickness", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }

                    // Low Iron + Tempered must use at least 10mm glass.
                    if (lowIronCheckBox.Checked && temperedCheckBox.Checked && glassComboBox.SelectedItem != null)
                    {
                        var currentGlass = glassComboBox.SelectedItem.ToString();
                        if (currentGlass == "3mm" || currentGlass == "6mm")
                        {
                            if (glassComboBox.Items.Contains("10mm"))
                            {
                                glassComboBox.SelectedItem = "10mm";
                            }
                            MessageBox.Show("Low Iron Tempered glass must be at least 10mm. Glass thickness has been set to 10mm.", "Glass Thickness", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }
                    }
                }
                catch { }

                UpdateTemperedGlassRequirement(true);

                // Stand rule: if aquarium glass is 10mm and above, stand tubular must be 2x2.
                // If a non-2x2 stand was already selected, clear it to force recalculation.
                try
                {
                    if (!isStandAutoUpdate)
                    {
                        var g = glassComboBox.SelectedItem?.ToString() ?? string.Empty;
                        bool requires2x2 = string.Equals(g, "10mm", StringComparison.OrdinalIgnoreCase)
                            || string.Equals(g, "12mm", StringComparison.OrdinalIgnoreCase)
                            || string.Equals(g, "18mm", StringComparison.OrdinalIgnoreCase);

                        if (requires2x2 && standCheckBox.Checked && standComponentPrice > 0m)
                        {
                            bool is2x2 = (standComponentDescription ?? string.Empty).IndexOf("2x2", StringComparison.OrdinalIgnoreCase) >= 0;
                            if (!is2x2)
                            {
                                isStandAutoUpdate = true;
                                standComponentPrice = 0m;
                                standComponentDescription = string.Empty;
                                standSelectedLabel.Text = "Stand: (none)";
                                standDetailsTextBox.Text = "";
                                standCheckBox.Checked = false;

                                MessageBox.Show("For 10mm and above aquariums, the stand tubular must be 2x2. Please recalculate the stand.", "Stand Rule", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            }
                        }
                    }
                }
                catch { }
                finally { isStandAutoUpdate = false; }

                // Selection changes (UOM, glass, options, checkboxes) should also trigger calculation immediately.
                aquariumPreviewPanel.Invalidate();
                performCalculation();
            };

            // AIO and Enclosure are mutually exclusive.
            bool isMutualExclusionUpdate = false;

            lengthTextBox.TextChanged += textChanged;
            lengthTextBox.TextChanged += (s, e) =>
            {
                try { ApplyDefaultLightSelection(); } catch { }
            };
            widthTextBox.TextChanged += textChanged;
            heightTextBox.TextChanged += textChanged;
            sumpLengthBox.TextChanged += textChanged;
            sumpWidthBox.TextChanged += textChanged;
            sumpHeightBox.TextChanged += textChanged;
            unitComboBox.SelectedIndexChanged += selectionChanged;
            unitComboBox.SelectedIndexChanged += (s, e) =>
            {
                try
                {
                    ApplyMainFiltrationDefaults();
                    ApplySumpFiltrationDefaults();
                    ApplyDefaultLightSelection();
                }
                catch { }
            };
            optionComboBox.SelectedIndexChanged += selectionChanged;
            glassComboBox.SelectedIndexChanged += selectionChanged;
            aquascapeServiceCheckBox.CheckedChanged += selectionChanged;
            standCheckBox.CheckedChanged += selectionChanged;
            aioCheckBox.CheckedChanged += (s, e) =>
            {
                if (isMutualExclusionUpdate) return;

                try
                {
                    if (aioCheckBox.Checked && completeSetCheckBox.Checked)
                    {
                        isMutualExclusionUpdate = true;
                        aioCheckBox.Checked = false;
                        MessageBox.Show("AIO cannot be selected when Filtration sump is enabled.", "Option Conflict", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    if (aioCheckBox.Checked && enclosureCheckBox.Checked)
                    {
                        isMutualExclusionUpdate = true;
                        enclosureCheckBox.Checked = false;
                        MessageBox.Show("AIO and Enclosure cannot both be selected.", "Option Conflict", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                }
                catch { }
                finally { isMutualExclusionUpdate = false; }

                selectionChanged(s, e);
            };
            lowIronCheckBox.CheckedChanged += (s, e) =>
            {
                try
                {
                    if (lowIronCheckBox.Checked && !temperedCheckBox.Checked)
                    {
                        // Low iron panels are assumed tempered; keep them in sync when enabling.
                        temperedCheckBox.Checked = true;
                    }

                    // If Low Iron is enabled, Tempered must remain enabled.
                    temperedCheckBox.Enabled = !lowIronCheckBox.Checked;
                    if (lowIronCheckBox.Checked)
                    {
                        temperedCheckBox.Checked = true;
                    }
                }
                catch { }

                selectionChanged(s, e);
            };
            temperedCheckBox.CheckedChanged += (s, e) =>
            {
                if (isTemperedRuleUpdate)
                {
                    selectionChanged(s, e);
                    return;
                }

                if (isMutualExclusionUpdate) return;

                try
                {
                    if (lowIronCheckBox.Checked && !temperedCheckBox.Checked)
                    {
                        isMutualExclusionUpdate = true;
                        temperedCheckBox.Checked = true;
                        return;
                    }

                    if (temperedGlassMandatoryBySize && !temperedCheckBox.Checked)
                    {
                        isMutualExclusionUpdate = true;
                        temperedCheckBox.Checked = true;
                        MessageBox.Show(
                            "Tempered glass is mandatory when the custom aquarium width or height reaches 36 inches or more.",
                            "Tempered Glass Required",
                            MessageBoxButtons.OK,
                            MessageBoxIcon.Information);
                        return;
                    }
                }
                catch { }
                finally { isMutualExclusionUpdate = false; }

                selectionChanged(s, e);
            };
            rimlessCheckBox.CheckedChanged += selectionChanged;
            highstripCheckBox.CheckedChanged += selectionChanged;
            stickerBackgroundCheckBox.CheckedChanged += (s, e) =>
            {
                try
                {
                    stickerBackgroundAllSidesCheckBox.Enabled = stickerBackgroundCheckBox.Checked;
                    stickerTypeLabel.Enabled = stickerBackgroundCheckBox.Checked;
                    stickerTypeComboBox.Enabled = stickerBackgroundCheckBox.Checked;
                    if (!stickerBackgroundCheckBox.Checked)
                    {
                        stickerBackgroundAllSidesCheckBox.Checked = false;
                    }
                }
                catch { }

                selectionChanged(s, e);
            };
            stickerBackgroundAllSidesCheckBox.CheckedChanged += selectionChanged;
            stickerTypeComboBox.SelectedIndexChanged += selectionChanged;
            stickerBottomCheckBox.CheckedChanged += (s, e) =>
            {
                try
                {
                    stickerBottomTypeLabel.Enabled = stickerBottomCheckBox.Checked;
                    stickerBottomTypeComboBox.Enabled = stickerBottomCheckBox.Checked;
                }
                catch { }

                selectionChanged(s, e);
            };
            stickerBottomTypeComboBox.SelectedIndexChanged += selectionChanged;
            completeSetCheckBox.CheckedChanged += (s, e) =>
            {
                if (isMutualExclusionUpdate) return;

                try
                {
                    // When Filtration sump is enabled, AIO and Enclosure must be off.
                    isMutualExclusionUpdate = true;

                    if (completeSetCheckBox.Checked)
                    {
                        aioCheckBox.Checked = false;
                        enclosureCheckBox.Checked = false;
                        aioCheckBox.Enabled = false;
                        enclosureCheckBox.Enabled = false;
                    }
                    else
                    {
                        aioCheckBox.Enabled = true;
                        enclosureCheckBox.Enabled = true;
                    }
                }
                catch { }
                finally { isMutualExclusionUpdate = false; }

                selectionChanged(s, e);
            };
            enclosureCheckBox.CheckedChanged += (s, e) =>
            {
                if (isMutualExclusionUpdate) return;

                try
                {
                    if (enclosureCheckBox.Checked && completeSetCheckBox.Checked)
                    {
                        isMutualExclusionUpdate = true;
                        enclosureCheckBox.Checked = false;
                        MessageBox.Show("Enclosure cannot be selected when Filtration sump is enabled.", "Option Conflict", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    if (enclosureCheckBox.Checked && aioCheckBox.Checked)
                    {
                        isMutualExclusionUpdate = true;
                        aioCheckBox.Checked = false;
                        MessageBox.Show("Enclosure and AIO cannot both be selected.", "Option Conflict", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                }
                catch { }
                finally { isMutualExclusionUpdate = false; }

                selectionChanged(s, e);
            };
            sumpTypeComboBox.SelectedIndexChanged += selectionChanged;
            sumpUnitCombo.SelectedIndexChanged += (s, e) =>
            {
                try
                {
                    ApplySumpFiltrationDefaults();
                }
                catch { }
                selectionChanged(s, e);
            };
            // Ensure toggling piping/overflow immediately recalculates the price
            pipingCheckBox.CheckedChanged += selectionChanged;
            overflowBoxCheckBox.CheckedChanged += selectionChanged;
            filterMediasCheckBox.CheckedChanged += selectionChanged;
            // Changing specific light/pump options should also revalidate price
            submersibleLightItemCombo.SelectedIndexChanged += (s, e) =>
            {
                try
                {
                    if (submersibleLightItemCombo.SelectedIndex < 0 && submersibleLightCheckBox.Checked)
                    {
                        submersibleLightCheckBox.Checked = false;
                    }
                }
                catch { }

                selectionChanged(s, e);
            };
            submersiblePumpItemCombo.SelectedIndexChanged += (s, e) =>
            {
                try
                {
                    if (submersiblePumpItemCombo.SelectedIndex < 0 && submersiblePumpCheckBox.Checked)
                    {
                        submersiblePumpCheckBox.Checked = false;
                    }
                }
                catch { }

                selectionChanged(s, e);
            };
            submersibleLightCheckBox.CheckedChanged += (s, e) =>
            {
                // Enable/disable light selection based on checkbox
                try
                {
                    submersibleLightItemCombo.Enabled = submersibleLightCheckBox.Checked && submersibleLightItemCombo.Visible && submersibleLightItemCombo.Items.Count > 0;
                    if (submersibleLightCheckBox.Checked)
                    {
                        ApplyDefaultLightSelection();

                        if (submersibleLightItemCombo.Items.Count > 0 && submersibleLightItemCombo.SelectedIndex < 0)
                        {
                            MessageBox.Show("Please fill in the light selection.", "Light Required", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            try { submersibleLightItemCombo.DroppedDown = true; } catch { }
                            try { submersibleLightItemCombo.Focus(); } catch { }
                        }
                    }
                }
                catch { }
                selectionChanged(s, e);
            };
            submersiblePumpCheckBox.CheckedChanged += (s, e) =>
            {
                // Enable/disable pump selection based on checkbox
                try
                {
                    submersiblePumpItemCombo.Enabled = submersiblePumpCheckBox.Checked && submersiblePumpItemCombo.Visible && submersiblePumpItemCombo.Items.Count > 0;
                    if (submersiblePumpCheckBox.Checked)
                    {
                        if (submersiblePumpItemCombo.Items.Count > 0 && submersiblePumpItemCombo.SelectedIndex < 0)
                        {
                            MessageBox.Show("Please fill in the pump selection.", "Pump Required", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            try { submersiblePumpItemCombo.DroppedDown = true; } catch { }
                            try { submersiblePumpItemCombo.Focus(); } catch { }
                        }
                    }
                }
                catch { }
                selectionChanged(s, e);
            };
            allumTopCoverCheckBox.CheckedChanged += selectionChanged;

            // Calculate button click event
            calculateButton.Click += (s, args) =>
            {
                performCalculation();
                if (!hasCalculated)
                {
                    MessageBox.Show("Please enter valid positive numbers for all dimensions.", "Invalid Input", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                }
            };

            // Stand calculator button click event
            standCalculatorButton.Click += (s, e) =>
            {
                try
                {
                    if (!double.TryParse(lengthTextBox.Text, out double l) || l <= 0 || !double.TryParse(widthTextBox.Text, out double w) || w <= 0)
                    {
                        MessageBox.Show("Please enter valid Length and Width first.", "Stand Calculator", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    string selectedUnit = unitComboBox.SelectedItem?.ToString() ?? "Inches";
                    decimal lIn;
                    decimal wIn;
                    switch (selectedUnit)
                    {
                        case "CM":
                            lIn = (decimal)(l / 2.54);
                            wIn = (decimal)(w / 2.54);
                            break;
                        case "Ft":
                            lIn = (decimal)(l * 12.0);
                            wIn = (decimal)(w * 12.0);
                            break;
                        case "MM":
                            lIn = (decimal)(l / 25.4);
                            wIn = (decimal)(w / 25.4);
                            break;
                        default:
                            lIn = (decimal)l;
                            wIn = (decimal)w;
                            break;
                    }

                    using (var sp = new StandPriceCalculatorForm(selectionOnly: true))
                    {
                        try { sp.PrefillFootprintInInches(lIn, wIn); } catch { }

                        // Force 2x2 tubular when aquarium glass is 10mm and above
                        try
                        {
                            var g = glassComboBox.SelectedItem?.ToString() ?? string.Empty;
                            bool requires2x2 = string.Equals(g, "10mm", StringComparison.OrdinalIgnoreCase)
                                || string.Equals(g, "12mm", StringComparison.OrdinalIgnoreCase)
                                || string.Equals(g, "18mm", StringComparison.OrdinalIgnoreCase);
                            if (requires2x2)
                                sp.ForceTubular("2x2", lockSelection: true);
                            else
                                sp.ForceTubular("2x2", lockSelection: false); // unlock if previously locked in a prior run
                        }
                        catch { }

                        var dr = sp.ShowDialog(customForm);
                        if (dr == DialogResult.OK && sp.SelectedPrice > 0m)
                        {
                            standComponentPrice = sp.SelectedPrice;
                            standComponentDescription = sp.SelectedDescription ?? "Stand";
                            standSelectedLabel.Text = $"Stand: ₱{standComponentPrice:N2}";
                            try
                            {
                                var unit = string.IsNullOrWhiteSpace(sp.SelectedUnit) ? (unitComboBox.SelectedItem?.ToString() ?? "") : sp.SelectedUnit;
                                standDetailsTextBox.Text =
                                    $"Stand Dimension: {sp.SelectedLength}x{sp.SelectedWidth}x{sp.SelectedHeight} {unit}\r\n" +
                                    $"No. of layers: {sp.SelectedLayers}\r\n" +
                                    $"Tubular: {sp.SelectedTubular}";
                            }
                            catch
                            {
                                standDetailsTextBox.Text = "";
                            }
                            standCheckBox.Checked = true;
                            performCalculation();
                        }
                    }
                }
                catch { }
            };

            // Add to sale button click event - add a detailed breakdown of components to the sales view
            addToSaleButton.Click += (s, args) =>
            {
                if (calculatedPrice > 0)
                {
                    if (sealantComboBox.SelectedIndex <= 0 || string.IsNullOrWhiteSpace(sealantComboBox.SelectedItem?.ToString()))
                    {
                        MessageBox.Show("Please choose a sealant color for this custom aquarium.", "Sealant Required", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        try { sealantComboBox.Focus(); } catch { }
                        return;
                    }

                    if (submersibleLightCheckBox.Visible && submersibleLightCheckBox.Checked && submersibleLightItemCombo.Items.Count > 0 && submersibleLightItemCombo.SelectedIndex < 0)
                    {
                        MessageBox.Show("Please choose a light for this custom aquarium.", "Light Required", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        try { submersibleLightItemCombo.Focus(); } catch { }
                        return;
                    }

                    if (submersiblePumpCheckBox.Visible && submersiblePumpCheckBox.Checked && submersiblePumpItemCombo.Items.Count > 0 && submersiblePumpItemCombo.SelectedIndex < 0)
                    {
                        MessageBox.Show("Please choose a pump for this custom aquarium.", "Pump Required", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        try { submersiblePumpItemCombo.Focus(); } catch { }
                        return;
                    }

                    string customAquariumName = $"Custom Aquarium {dimensionsText} ({gallons:F1} gal)";
                    string tankSizeDetail = $"Tank {dimensionsText} ({gallons:F1} gal)";
                    string setupOptionDetail = optionComboBox.SelectedItem?.ToString() ?? string.Empty;
                    string sealantDetail = $"{sealantComboBox.SelectedItem?.ToString() ?? "Clear"} sealant";
                    string glassBuildDetail = BuildDetailedSaleDescription(
                        "Aquarium Build",
                        tankSizeDetail,
                        $"Glass {glassComboBox.SelectedItem?.ToString() ?? string.Empty}",
                        sealantDetail,
                        setupOptionDetail,
                        lowIronCheckBox.Checked ? "Low Iron" : null,
                        temperedCheckBox.Checked ? "Tempered" : null,
                        aioCheckBox.Checked ? "AIO" : null,
                        enclosureCheckBox.Checked ? "Enclosure" : null,
                        rimlessCheckBox.Checked ? "Rimless" : null);
                    string sumpSizeDetail = string.Empty;
                    if (!string.IsNullOrWhiteSpace(sumpLengthBox.Text)
                        && !string.IsNullOrWhiteSpace(sumpWidthBox.Text)
                        && !string.IsNullOrWhiteSpace(sumpHeightBox.Text))
                    {
                        sumpSizeDetail = $"Sump {sumpLengthBox.Text.Trim()}x{sumpWidthBox.Text.Trim()}x{sumpHeightBox.Text.Trim()} {(sumpUnitCombo.SelectedItem?.ToString() ?? unitComboBox.SelectedItem?.ToString() ?? string.Empty)}";
                    }
                    // We no longer add a zero-priced header line because
                    // zero prices are not allowed when posting.
                    sealantComboBox.SelectedIndexChanged += selectionChanged;

                    // Build component list so we can spread the final price across them as whole amounts.
                    // For inventory-backed extras (submersible light/pump) we also track the ItemCode so checkout/sync
                    // can use the exact code (and its VariationId) without relying on the description text.
                    var components = new System.Collections.Generic.List<(string Description, decimal Amount, string ItemCode)>();
                    if (glassComponentPrice > 0m)
                    {
                        components.Add((glassBuildDetail, glassComponentPrice, ""));
                    }
                    if (highStripComponentPrice > 0m)
                    {
                        components.Add((BuildDetailedSaleDescription("High Strip", tankSizeDetail), highStripComponentPrice, ""));
                    }
                    if (sumpComponentPrice > 0m)
                    {
                        var st = sumpTypeComboBox.SelectedItem?.ToString() ?? "Sump";
                        components.Add((BuildDetailedSaleDescription($"{st} Glass", sumpSizeDetail, tankSizeDetail), sumpComponentPrice, ""));
                    }
                    if (filterMediaComponentPrice > 0m)
                    {
                        components.Add((BuildDetailedSaleDescription("Filter Medias", sumpSizeDetail), filterMediaComponentPrice, ""));
                    }
                    if (lightComponentPrice > 0m)
                    {
                        var selectedLight = submersibleLightItemCombo.SelectedItem?.ToString() ?? "Submersible Light";
                        string lightCode = string.Empty;
                        try
                        {
                            // selectedLight format: "Description" or "Description (CODE)" -> we want CODE
                            string codeText = selectedLight;
                            int openIdx = codeText.LastIndexOf('(');
                            int closeIdx = codeText.LastIndexOf(')');
                            if (openIdx >= 0 && closeIdx > openIdx)
                            {
                                codeText = codeText.Substring(openIdx + 1, closeIdx - openIdx - 1).Trim();
                            }
                            if (!string.IsNullOrWhiteSpace(codeText))
                            {
                                lightCode = codeText; // exact Item.Code used later for VariantId lookup
                            }
                        }
                        catch { lightCode = string.Empty; }

                        components.Add((BuildDetailedSaleDescription($"Submersible Light - {selectedLight}", tankSizeDetail), lightComponentPrice, lightCode));
                    }
                    if (overflowComponentPrice > 0m)
                    {
                        components.Add((BuildDetailedSaleDescription("Overflow Box", sumpSizeDetail, tankSizeDetail), overflowComponentPrice, ""));
                    }
                    if (pipingComponentPrice > 0m)
                    {
                        components.Add((BuildDetailedSaleDescription("Set of Piping", sumpSizeDetail, tankSizeDetail), pipingComponentPrice, ""));
                    }
                    if (pumpComponentPrice > 0m)
                    {
                        var selectedPump = submersiblePumpItemCombo.SelectedItem?.ToString() ?? "Submersible Pump";
                        string pumpCode = string.Empty;
                        try
                        {
                            string codeText = selectedPump;
                            int openIdxP = codeText.LastIndexOf('(');
                            int closeIdxP = codeText.LastIndexOf(')');
                            if (openIdxP >= 0 && closeIdxP > openIdxP)
                            {
                                codeText = codeText.Substring(openIdxP + 1, closeIdxP - openIdxP - 1).Trim();
                            }
                            if (!string.IsNullOrWhiteSpace(codeText))
                            {
                                pumpCode = codeText;
                            }
                        }
                        catch { pumpCode = string.Empty; }

                        components.Add((BuildDetailedSaleDescription($"Submersible Pump - {selectedPump}", sumpSizeDetail, tankSizeDetail), pumpComponentPrice, pumpCode));
                    }
                    if (allumTopCoverComponentPrice > 0m)
                    {
                        components.Add((BuildDetailedSaleDescription("Allum Top Cover", tankSizeDetail), allumTopCoverComponentPrice, ""));
                    }

                    if (stickerBackgroundComponentPrice > 0m)
                    {
                        components.Add((BuildDetailedSaleDescription(GetStickerBackgroundDescription(), tankSizeDetail), stickerBackgroundComponentPrice, ""));
                    }

                    if (stickerBottomComponentPrice > 0m)
                    {
                        components.Add((BuildDetailedSaleDescription(GetStickerBottomDescription(), tankSizeDetail), stickerBottomComponentPrice, ""));
                    }

                    if (aquascapeServiceComponentPrice > 0m)
                    {
                        components.Add((BuildDetailedSaleDescription("Aquascape service", tankSizeDetail), aquascapeServiceComponentPrice, ""));
                    }

                    // Spread the final calculated price across component lines as whole pesos, with no negatives.
                    if (components.Count > 0)
                    {
                        decimal targetTotal = aquariumOnlyCalculatedPrice;
                        decimal baseSum = components.Sum(c => c.Amount);
                        var allocated = new decimal[components.Count];
                        var rawShares = new decimal[components.Count];

                        if (baseSum <= 0m)
                        {
                            // Fallback: put the whole amount on the first component
                            allocated[0] = Math.Round(targetTotal, 0, MidpointRounding.AwayFromZero);
                        }
                        else
                        {
                            for (int i = 0; i < components.Count; i++)
                            {
                                rawShares[i] = targetTotal * (components[i].Amount / baseSum);
                                allocated[i] = Math.Floor(rawShares[i]); // start with rounded down amounts
                            }

                            decimal sumAllocated = allocated.Sum();
                            decimal remainder = targetTotal - sumAllocated;

                            if (remainder != 0m)
                            {
                                int sign = remainder > 0 ? 1 : -1;
                                int steps = (int)Math.Round(Math.Abs(remainder), MidpointRounding.AwayFromZero);
                                if (steps > 0)
                                {
                                    int[] order;
                                    if (sign > 0)
                                    {
                                        // For positive remainder, give extra pesos to components with largest fractional parts
                                        order = System.Linq.Enumerable.Range(0, components.Count)
                                            .OrderByDescending(i => rawShares[i] - Math.Floor(rawShares[i]))
                                            .ToArray();
                                    }
                                    else
                                    {
                                        // For negative remainder, reduce from components with the largest allocated values
                                        order = System.Linq.Enumerable.Range(0, components.Count)
                                            .OrderByDescending(i => allocated[i])
                                            .ToArray();
                                    }

                                    int orderLen = order.Length;
                                    for (int k = 0; k < steps; k++)
                                    {
                                        int idx = order[k % orderLen];
                                        if (sign > 0)
                                        {
                                            allocated[idx] += 1m;
                                        }
                                        else if (allocated[idx] > 0m)
                                        {
                                            allocated[idx] -= 1m;
                                        }
                                    }
                                }
                            }
                        }

                        // Finally add each component line with its allocated whole-peso amount
                        for (int i = 0; i < components.Count; i++)
                        {
                            decimal displayPrice = allocated[i];
                            if (displayPrice < 0m) displayPrice = 0m; // safety: never allow negative

                            // Use a shorter display description for inventory-backed extras
                            string baseDescription = components[i].Description;
                            string displayDescription = baseDescription;

                            // For submersible light and pump, show only the item description (no code / prefixes)
                            if (baseDescription.StartsWith("Submersible Light", StringComparison.OrdinalIgnoreCase))
                            {
                                try
                                {
                                    string selectedLight = submersibleLightItemCombo.SelectedItem?.ToString() ?? string.Empty;
                                    // selectedLight format: "Description" or "Description (CODE)" -> we want just Description
                                    int openIdx = selectedLight.LastIndexOf('(');
                                    if (openIdx > 0)
                                    {
                                        displayDescription = selectedLight.Substring(0, openIdx).Trim();
                                    }
                                    else if (!string.IsNullOrWhiteSpace(selectedLight))
                                    {
                                        displayDescription = selectedLight.Trim();
                                    }
                                }
                                catch { }
                            }
                            else if (baseDescription.StartsWith("Submersible Pump", StringComparison.OrdinalIgnoreCase))
                            {
                                try
                                {
                                    string selectedPump = submersiblePumpItemCombo.SelectedItem?.ToString() ?? string.Empty;
                                    int openIdxP = selectedPump.LastIndexOf('(');
                                    if (openIdxP > 0)
                                    {
                                        displayDescription = selectedPump.Substring(0, openIdxP).Trim();
                                    }
                                    else if (!string.IsNullOrWhiteSpace(selectedPump))
                                    {
                                        displayDescription = selectedPump.Trim();
                                    }
                                }
                                catch { }
                            }

                            string d = FunctionEvents.ToAscii(displayDescription);

                            string category = ResolveCustomAquariumCalculatorCategory(displayDescription, components[i].ItemCode);
                            string code = ShouldResolveCustomAquariumCatalogVariation(category)
                                ? category
                                : (string.IsNullOrWhiteSpace(components[i].ItemCode) ? "CUSTOM-AQUARIUM" : components[i].ItemCode);

                            AddToSale("  " + d, 1, displayPrice, category, code, null, "  " + d, true);
                        }
                    }

                    // Add stand as its own line item (not included in aquarium component allocation)
                    if (standCheckBox.Checked && standComponentPrice > 0m)
                    {
                        decimal displayStandPrice = Math.Round(standComponentPrice, 0, MidpointRounding.AwayFromZero);
                        if (displayStandPrice < 0m) displayStandPrice = 0m;

                        string standDesc = string.IsNullOrWhiteSpace(standComponentDescription) ? "Stand" : standComponentDescription;
                        standDesc = BuildDetailedSaleDescription(standDesc, standDetailsTextBox.Text, tankSizeDetail);
                        standDesc = FunctionEvents.ToAscii(standDesc);

                        string standCategory = ResolveCustomAquariumCalculatorCategory(standDesc, "CUSTOM_STAND");
                        string standCode = ShouldResolveCustomAquariumCatalogVariation(standCategory)
                            ? standCategory
                            : "CUSTOM_STAND";

                        AddToSale("  " + standDesc, 1, displayStandPrice, standCategory, standCode, null, "  " + standDesc, true);
                    }

                    pendingCustomAquariumSpecialNote = NormalizeSaleDetailText(specialNoteTextBox.Text);

                    // Refresh totals in UI
                    UpdateTotal();

                    MessageBox.Show(FunctionEvents.ToAscii($"Added {customAquariumName} to sale!\nPrice: {calculatedPrice:N2}"), "Custom Aquarium Added", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    customForm.Close();
                }
            };

            // Close button click event
            closeButton.Click += (s, args) => customForm.Close();

            // Add controls to form
            customForm.Controls.AddRange(new Control[]
            {
                titleLabel, optionLabel, optionComboBox, unitLabel, unitComboBox, sealantLabel, sealantComboBox, specialNoteLabel, specialNoteTextBox,
                aquariumPreviewPanel,
                glassLabel, glassComboBox, aquascapeServiceCheckBox, enclosureCheckBox, standCheckBox, standCalculatorButton, standSelectedLabel, standDetailsTextBox, aioCheckBox, lowIronCheckBox, temperedCheckBox, rimlessCheckBox, highstripCheckBox, completeSetCheckBox, stickerBackgroundCheckBox, stickerBackgroundAllSidesCheckBox, stickerTypeLabel, stickerTypeComboBox, stickerBottomCheckBox, stickerBottomTypeLabel, stickerBottomTypeComboBox, sumpTypeComboBox,
                sumpCaptionLabel, sumpLengthLabel, sumpLengthBox, sumpWidthLabel, sumpWidthBox, sumpHeightLabel, sumpHeightBox,
                lengthLabel, lengthTextBox, widthLabel, widthTextBox, heightLabel, heightTextBox,
                calculateButton, volumeLabel, priceLabel, inchesLabel, sumpInchesLabel, filterMediaDetailsLabel, sumpDetailsLabel,
                addToSaleButton, closeButton,
                pipingCheckBox, overflowBoxCheckBox, filterMediasCheckBox,
                submersibleLightCheckBox, submersibleLightItemCombo, submersiblePumpCheckBox, submersiblePumpItemCombo,
                allumTopCoverCheckBox, sumpUnitLabel, sumpUnitCombo
            });

            // Perform initial right-alignment and keep it aligned on resize.
            try
            {
                customForm.Resize += (s, e) => { try { layoutStandControls(); } catch { } };
                layoutStandControls();
            }
            catch { }

            // Ensure the Calculate Price button is rendered on top when controls overlap
            calculateButton.BringToFront();

            // Ensure Enclosure is not hidden by overlapping controls (DPI/layout)
            enclosureCheckBox.BringToFront();

            // Ensure sump selector visibility matches the Complete set checkbox at startup
            sumpTypeComboBox.Visible = completeSetCheckBox.Checked;
            if (sumpTypeComboBox.Visible)
                sumpTypeComboBox.BringToFront();

            aquariumPreviewPanel.Invalidate();

            customForm.ShowDialog();
        }

        private void ShowCustomStickersDialog()
        {
            var f = new Form
            {
                Text = "Custom Stickers",
                Size = new Size(700, 480),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false
            };

            var titleLabel = new Label { Text = "Custom Sticker Size", Font = new Font("Arial", 16, FontStyle.Bold), Location = new Point(20, 16), Size = new Size(400, 28) };

            var unitLabel = new Label { Text = "Unit of Measure:", Location = new Point(20, 60), Size = new Size(140, 24), Font = new Font("Arial", 12, FontStyle.Bold) };
            var unitCombo = new ComboBox { Location = new Point(180, 58), Size = new Size(140, 28), Font = new Font("Arial", 12), DropDownStyle = ComboBoxStyle.DropDownList };
            unitCombo.Items.AddRange(new string[] { "Inches", "CM", "Ft", "MM" });
            unitCombo.SelectedIndex = 0;

            var stickerTypeLabel = new Label { Text = "Type:", Location = new Point(20, 90), Size = new Size(140, 24), Font = new Font("Arial", 12, FontStyle.Bold) };
            var stickerTypeCombo = new ComboBox { Location = new Point(180, 88), Size = new Size(200, 28), Font = new Font("Arial", 12), DropDownStyle = ComboBoxStyle.DropDownList };
            // Add additional sticker options: Rubber Matting, Glass, Acrylic and Allum TopCover
            stickerTypeCombo.Items.AddRange(new string[] { "Tiles Sticker", "Plain Sticker", "Rubber Matting", "Glass", "Acrylic", "Allum TopCover" });
            stickerTypeCombo.SelectedIndex = 0;

            var thicknessLabel = new Label { Text = "Thickness:", Location = new Point(20, 120), Size = new Size(100, 24), Font = new Font("Arial", 12, FontStyle.Bold), Visible = false };
            var thicknessCombo = new ComboBox { Location = new Point(140, 118), Size = new Size(120, 28), Font = new Font("Arial", 12), DropDownStyle = ComboBoxStyle.DropDownList, Visible = false };
                thicknessCombo.Items.AddRange(new string[] { "3mm", "6mm", "10mm", "12mm" });
            thicknessCombo.SelectedIndex = 1; // default 6mm

            var repairCheckBox = new CheckBox
            {
                Text = "Repair",
                Location = new Point(340, 190),
                Size = new Size(160, 28),
                Font = new Font("Arial", 12, FontStyle.Bold),
                Visible = false
            };

            var lengthLabel = new Label { Text = "Length:", Location = new Point(20, 160), Size = new Size(100, 24), Font = new Font("Arial", 12, FontStyle.Bold) };
            var lengthBox = new TextBox { Location = new Point(140, 158), Size = new Size(120, 28), Font = new Font("Arial", 12) };

            var widthLabel = new Label { Text = "Width:", Location = new Point(20, 200), Size = new Size(100, 24), Font = new Font("Arial", 12, FontStyle.Bold) };
            var widthBox = new TextBox { Location = new Point(140, 198), Size = new Size(120, 28), Font = new Font("Arial", 12) };

            // (Height removed - stickers require only Length and Width)
            // Position inputs on the left stacked, controls/results on the right
            var calcButton = new Button { Text = "Calculate Price", Location = new Point(20, 240), Size = new Size(260, 44), BackColor = Color.DarkBlue, ForeColor = Color.White, Font = new Font("Arial", 12, FontStyle.Bold) };

            var resultLabel = new Label
            {
                Text = "Area: 0",
                Location = new Point(340, 110),
                Size = new Size(320, 36),
                Font = new Font("Arial", 12, FontStyle.Bold),
                ForeColor = Color.DarkGreen,
                AutoSize = false,
                TextAlign = ContentAlignment.MiddleLeft
            };
            var priceLabel = new Label
            {
                Text = "Estimated Price: 0.00",
                Location = new Point(340, 152),
                Size = new Size(320, 36),
                Font = new Font("Arial", 12, FontStyle.Bold),
                ForeColor = Color.DarkRed,
                AutoSize = false,
                TextAlign = ContentAlignment.MiddleLeft
            };

            // Pricing per square inch for different sticker types (from global settings)
            decimal pricePerSqInchPlain = GlobalSettings.pricePerSqInchPlain;
            decimal pricePerSqInchTiles = GlobalSettings.pricePerSqInchTiles;

            calcButton.Click += (s, e) =>
            {
                if (!double.TryParse(lengthBox.Text, out double length) || length <= 0 || !double.TryParse(widthBox.Text, out double width) || width <= 0)
                {
                    MessageBox.Show("Please enter valid positive numbers for length and width.", "Invalid Input", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                // Convert to feet for area calculation, then to square inches
                string uom = unitCombo.SelectedItem?.ToString() ?? "Inches";
                double lengthInFeet;
                double widthInFeet;
                switch (uom)
                {
                    case "CM":
                        // 1 foot = 30.48 cm
                        lengthInFeet = length / 30.48;
                        widthInFeet = width / 30.48;
                        break;
                    case "MM":
                        // 1 foot = 304.8 mm
                        lengthInFeet = length / 304.8;
                        widthInFeet = width / 304.8;
                        break;
                    case "Ft":
                        // Already in feet
                        lengthInFeet = length;
                        widthInFeet = width;
                        break;
                    default: // Inches
                        lengthInFeet = length / 12.0;
                        widthInFeet = width / 12.0;
                        break;
                }

                double areaSqFeet = lengthInFeet * widthInFeet;
                // Choose price per sq inch based on sticker type (thickness-aware for Rubber/Glass)
                string stickerType = stickerTypeCombo.SelectedItem?.ToString() ?? "Plain Sticker";
                string thickness = thicknessCombo.SelectedItem?.ToString() ?? "";
                decimal pricePerSqInch = stickerType switch
                {
                    "Tiles Sticker" => pricePerSqInchTiles,
                    "Acrylic" => GlobalSettings.pricePerSqInchAcrylicHighStrip,
                    "Rubber Matting" => GlobalSettings.GetRubberPricePerSqInch(thickness),
                    "Glass" => GlobalSettings.GetGlassPricePerSqInch(thickness),
                    "Allum TopCover" => 500m, // 500 per sq ft
                    _ => pricePerSqInchPlain,
                };
                decimal estimatedPrice = (decimal)areaSqFeet * pricePerSqInch;
                bool isRepair = stickerType == "Glass" && repairCheckBox.Checked;
                if (isRepair)
                    estimatedPrice *= 2.5m; // 250% of base (2.5x)
                // Round up to nearest 10
                decimal roundedPrice = Math.Ceiling(estimatedPrice / 10m) * 10m;

                resultLabel.Text = $"Area: {areaSqFeet:F2} sq ft";
                priceLabel.Text = thickness.Length > 0 && (stickerType == "Rubber Matting" || stickerType == "Glass")
                    ? $"Estimated Price: {roundedPrice:N2} ({stickerType} {thickness}{(isRepair ? " REPAIR" : "")})"
                    : $"Estimated Price: {roundedPrice:N2} ({stickerType}{(isRepair ? " REPAIR" : "")})";
            };

            var addButton = new Button { Text = "Add to Sale", Location = new Point(340, 230), Size = new Size(160, 48), BackColor = Color.Green, ForeColor = Color.White, Font = new Font("Arial", 12, FontStyle.Bold) };
            addButton.Click += (s, e) =>
            {
                // Recalculate to ensure values
                if (!double.TryParse(lengthBox.Text, out double length) || length <= 0 || !double.TryParse(widthBox.Text, out double width) || width <= 0)
                {
                    MessageBox.Show("Please enter valid positive numbers for length and width.", "Invalid Input", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                string uom = unitCombo.SelectedItem?.ToString() ?? "Inches";
                double lengthInFeet;
                double widthInFeet;
                switch (uom)
                {
                    case "CM":
                        lengthInFeet = length / 30.48;
                        widthInFeet = width / 30.48;
                        break;
                    case "MM":
                        lengthInFeet = length / 304.8;
                        widthInFeet = width / 304.8;
                        break;
                    case "Ft":
                        lengthInFeet = length;
                        widthInFeet = width;
                        break;
                    default:
                        lengthInFeet = length / 12.0;
                        widthInFeet = width / 12.0;
                        break;
                }

                double areaSqFeet = lengthInFeet * widthInFeet;
                // double areaSqInches = areaSqFeet * 144.0;
                string stickerType = stickerTypeCombo.SelectedItem?.ToString() ?? "Plain Sticker";
                string thickness = thicknessCombo.SelectedItem?.ToString() ?? "";
                bool isRepair = stickerType == "Glass" && repairCheckBox.Checked;
                decimal pricePerSqInch = stickerType switch
                {
                    "Tiles Sticker" => pricePerSqInchTiles,
                    "Acrylic" => GlobalSettings.pricePerSqInchAcrylicHighStrip,
                    "Rubber Matting" => GlobalSettings.GetRubberPricePerSqInch(thickness),
                    "Glass" => GlobalSettings.GetGlassPricePerSqInch(thickness),
                    "Allum TopCover" => 500m, // 500 per sq ft
                    _ => pricePerSqInchPlain,
                };
                decimal estimatedPrice = (decimal)areaSqFeet * pricePerSqInch;
                if (isRepair)
                    estimatedPrice *= 2.5m; // 250% of base (2.5x)
                // Round up to nearest 10 for final price charged
                decimal roundedPrice = Math.Ceiling(estimatedPrice / 10m) * 10m;
                string desc = (thickness.Length > 0 && (stickerType == "Rubber Matting" || stickerType == "Glass"))
                    ? $"{stickerType}{(isRepair ? " REPAIR" : "")} ({thickness}) {length}{(unitCombo.SelectedItem?.ToString() ?? "")} x {width}{(unitCombo.SelectedItem?.ToString() ?? "")}"
                    : $"{stickerType}{(isRepair ? " REPAIR" : "")} {length}{(unitCombo.SelectedItem?.ToString() ?? "")} x {width}{(unitCombo.SelectedItem?.ToString() ?? "")}";
                AddToSale(desc, 1, roundedPrice, "CUSTOM-STICKER");
                //MessageBox.Show($"Added custom sticker to sale:\n{desc}\nPrice: {roundedPrice:N2}", "Added", MessageBoxButtons.OK, MessageBoxIcon.Information);
                f.Close();
            };

            var close = new Button { Text = "Close", Location = new Point(340, 300), Size = new Size(160, 40) };
            close.Click += (s, e) => f.Close();

            void AutoRecalculateIfPossible()
            {
                try
                {
                    if (double.TryParse(lengthBox.Text, out double l) && l > 0 && double.TryParse(widthBox.Text, out double w) && w > 0)
                    {
                        // Re-use the existing Calculate Price logic without showing validation popups.
                        calcButton.PerformClick();
                    }
                }
                catch
                {
                    // Ignore auto-calc failures; user can still click Calculate.
                }
            }

            repairCheckBox.CheckedChanged += (s, e) =>
            {
                try
                {
                    var sel = stickerTypeCombo.SelectedItem?.ToString() ?? "";
                    if (sel == "Glass")
                        AutoRecalculateIfPossible();
                }
                catch { }
            };

            thicknessCombo.SelectedIndexChanged += (s, e) =>
            {
                try
                {
                    var sel = stickerTypeCombo.SelectedItem?.ToString() ?? "";
                    if (sel == "Glass")
                        AutoRecalculateIfPossible();
                }
                catch { }
            };

            // Add thickness controls and wire-up visibility change based on sticker type
            stickerTypeCombo.SelectedIndexChanged += (s, e) =>
            {
                try
                {
                    var sel = stickerTypeCombo.SelectedItem?.ToString() ?? "";
                    bool showThickness = sel == "Rubber Matting" || sel == "Glass";
                    thicknessLabel.Visible = showThickness;
                    thicknessCombo.Visible = showThickness;

                    bool showRepair = sel == "Glass";
                    repairCheckBox.Visible = showRepair;
                    if (!showRepair)
                        repairCheckBox.Checked = false;

                    AutoRecalculateIfPossible();
                }
                catch { }
            };

            // Ensure initial visibility matches default selection
            try
            {
                var sel = stickerTypeCombo.SelectedItem?.ToString() ?? "";
                bool showThickness = sel == "Rubber Matting" || sel == "Glass";
                thicknessLabel.Visible = showThickness;
                thicknessCombo.Visible = showThickness;

                bool showRepair = sel == "Glass";
                repairCheckBox.Visible = showRepair;
                if (!showRepair)
                    repairCheckBox.Checked = false;
            }
            catch { }

            f.Controls.AddRange(new Control[] { titleLabel, unitLabel, unitCombo, stickerTypeLabel, stickerTypeCombo, thicknessLabel, thicknessCombo, repairCheckBox, lengthLabel, lengthBox, widthLabel, widthBox, calcButton, resultLabel, priceLabel, addButton, close });
            f.ShowDialog(this);
        }

        private string ExtractFirstImageReference(string? imagesValue)
        {
            if (string.IsNullOrWhiteSpace(imagesValue))
                return string.Empty;

            var trimmed = imagesValue.Trim();

            try
            {
                if (trimmed.StartsWith("[", StringComparison.Ordinal) || trimmed.StartsWith("{", StringComparison.Ordinal))
                {
                    using var doc = JsonDocument.Parse(trimmed);
                    if (doc.RootElement.ValueKind == JsonValueKind.Array)
                    {
                        foreach (var element in doc.RootElement.EnumerateArray())
                        {
                            if (element.ValueKind == JsonValueKind.String)
                            {
                                var s = element.GetString() ?? string.Empty;
                                if (!string.IsNullOrWhiteSpace(s)) return s.Trim();
                            }
                            else if (element.ValueKind == JsonValueKind.Object)
                            {
                                foreach (var propName in new[] { "url", "src", "path", "image", "Image" })
                                {
                                    if (element.TryGetProperty(propName, out var prop) && prop.ValueKind == JsonValueKind.String)
                                    {
                                        var s = prop.GetString() ?? string.Empty;
                                        if (!string.IsNullOrWhiteSpace(s)) return s.Trim();
                                    }
                                }
                            }
                        }
                    }
                    else if (doc.RootElement.ValueKind == JsonValueKind.String)
                    {
                        return doc.RootElement.GetString() ?? string.Empty;
                    }
                    else if (doc.RootElement.ValueKind == JsonValueKind.Object)
                    {
                        foreach (var propName in new[] { "url", "src", "path", "image", "Image" })
                        {
                            if (doc.RootElement.TryGetProperty(propName, out var prop) && prop.ValueKind == JsonValueKind.String)
                            {
                                var s = prop.GetString() ?? string.Empty;
                                if (!string.IsNullOrWhiteSpace(s)) return s.Trim();
                            }
                        }
                    }
                }
            }
            catch
            {
                // Fall back to delimiter-based parsing below.
            }

            var first = trimmed
                .Split(new[] { ',', ';', '|', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(x => x.Trim())
                .FirstOrDefault(x => !string.IsNullOrWhiteSpace(x));

            return first ?? trimmed;
        }

        private void UpdateProductPreview(PictureBox pictureBox, Label statusLabel, string? imagesValue)
        {
            try
            {
                pictureBox.Image = null;
                pictureBox.ImageLocation = null;

                var imageRef = ExtractFirstImageReference(imagesValue);
                if (string.IsNullOrWhiteSpace(imageRef))
                {
                    statusLabel.Text = "No image available";
                    return;
                }

                statusLabel.Text = "Loading image...";

                if (Uri.TryCreate(imageRef, UriKind.Absolute, out var uri)
                    && (uri.Scheme == Uri.UriSchemeHttp || uri.Scheme == Uri.UriSchemeHttps))
                {
                    pictureBox.LoadAsync(imageRef);
                    return;
                }

                var path = imageRef;
                if (!Path.IsPathRooted(path))
                {
                    path = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, imageRef);
                }

                if (File.Exists(path))
                {
                    using var fs = new FileStream(path, FileMode.Open, FileAccess.Read);
                    pictureBox.Image = Image.FromStream(fs);
                    statusLabel.Text = Path.GetFileName(path);
                }
                else
                {
                    statusLabel.Text = "Image not found";
                }
            }
            catch
            {
                statusLabel.Text = "Unable to load image";
            }
        }

        private void LoadProductsByCategory(string categoryCode)
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    // Check if Items table exists
                    var checkTable = new SqlCommand("SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Items'", connection);
                    int tableExists = (int)checkTable.ExecuteScalar();

                    if (tableExists == 0)
                    {
                        MessageBox.Show("Items table not found. Please add some items first.", "No Items", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    // Get category description for form title
                    string categoryDescription = categoryCode;
                    var categoryQuery = new SqlCommand("SELECT Description FROM Category WHERE Code = @code", connection);
                    categoryQuery.Parameters.AddWithValue("@code", categoryCode);
                    var categoryResult = categoryQuery.ExecuteScalar();
                    if (categoryResult != null)
                    {
                        categoryDescription = categoryResult.ToString() ?? categoryCode;
                    }

                    bool hasImagesColumn = false;
                    try
                    {
                        using var imgColCmd = new SqlCommand("SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Items' AND COLUMN_NAME = 'Images'", connection);
                        hasImagesColumn = Convert.ToInt32(imgColCmd.ExecuteScalar() ?? 0) > 0;
                    }
                    catch { }

                    // Create product selection form
                    var productForm = new Form
                    {
                        Text = $"{categoryDescription} Products",
                        Size = new Size(1080, 620),
                        StartPosition = FormStartPosition.CenterParent,
                        BackColor = Color.White
                    };

                    var productListView = new ListView
                    {
                        Location = new Point(10, 50),
                        Size = new Size(780, 460),
                        View = View.Details,
                        FullRowSelect = true,
                        GridLines = true,
                        Font = new Font("Arial", 10)
                    };

                    var previewGroup = new GroupBox
                    {
                        Text = "Product Image",
                        Location = new Point(800, 50),
                        Size = new Size(250, 460),
                        Font = new Font("Arial", 10, FontStyle.Bold)
                    };

                    var previewPictureBox = new PictureBox
                    {
                        Location = new Point(10, 25),
                        Size = new Size(230, 360),
                        BorderStyle = BorderStyle.FixedSingle,
                        SizeMode = PictureBoxSizeMode.Zoom,
                        BackColor = Color.WhiteSmoke
                    };

                    var previewStatusLabel = new Label
                    {
                        Text = "Select a product to preview",
                        Location = new Point(10, 395),
                        Size = new Size(230, 50),
                        Font = new Font("Arial", 9, FontStyle.Regular),
                        ForeColor = Color.DimGray
                    };

                    previewPictureBox.LoadCompleted += (s, e) =>
                    {
                        previewStatusLabel.Text = e.Error == null && !e.Cancelled
                            ? "Image loaded"
                            : "Unable to load image";
                    };

                    previewGroup.Controls.Add(previewPictureBox);
                    previewGroup.Controls.Add(previewStatusLabel);

                    productListView.Columns.Add("Name", 200);
                    productListView.Columns.Add("Description", 250);
                    productListView.Columns.Add("Price", 80);
                    productListView.Columns.Add("PromoPrice", 100);
                    productListView.Columns.Add("Stock", 60);
                    productListView.Columns.Add("Brand", 120);

                    // Add a category filter combo box and a search textbox to filter by item name/description
                    var txtSearchFilter = new TextBox
                    {
                        Location = new Point(10, 10),
                        Size = new Size(760, 30),
                        Font = new Font("Arial", 10),
                        PlaceholderText = "Type to search name or description..."
                    };

                    // Make form capture keypresses so typing focuses search
                    productForm.KeyPreview = true;
                    productForm.KeyPress += (s, e) =>
                    {
                        try
                        {
                            if (!txtSearchFilter.Focused && !char.IsControl(e.KeyChar))
                                txtSearchFilter.Focus();
                        }
                        catch { }
                    };

                    // Focus search when shown
                    productForm.Shown += (s, e) => { try { txtSearchFilter.Focus(); } catch { } };

                    // local method to load items into the list view based on selected category code and optional search term
                    Action<string, string> loadItems = (selectedCategory, searchTerm) =>
                    {
                        productListView.Items.Clear();
                        string query;
                        bool hasSearch = !string.IsNullOrWhiteSpace(searchTerm);
                        if (string.IsNullOrWhiteSpace(selectedCategory) || selectedCategory == "ALL")
                        {
                                query = @"SELECT i.Code, i.Name, i.Description, i.Price, i.PromoPrice, i.Brand," +
                                    (hasImagesColumn ? " i.Images AS Images," : " CAST('' AS NVARCHAR(MAX)) AS Images,") + @"
                                         ISNULL(SUM(ile.Quantity), 0) as CalculatedStock
                                     FROM Items i 
                                     LEFT JOIN ItemLedgerEntry ile ON i.Code = ile.ItemCode
                                     WHERE i.IsActive = 1";
                            if (hasSearch) query += " AND (i.Name LIKE @search OR i.Description LIKE @search)";
                                query += @" GROUP BY i.Code, i.Name, i.Description, i.Price, i.PromoPrice, i.Brand" + (hasImagesColumn ? ", i.Images" : "") + @"
                                     ORDER BY i.Name";
                        }
                        else
                        {
                                query = @"SELECT i.Code, i.Name, i.Description, i.Price, i.PromoPrice, i.Brand," +
                                    (hasImagesColumn ? " i.Images AS Images," : " CAST('' AS NVARCHAR(MAX)) AS Images,") + @"
                                         ISNULL(SUM(ile.Quantity), 0) as CalculatedStock
                                     FROM Items i 
                                     LEFT JOIN ItemLedgerEntry ile ON i.Code = ile.ItemCode
                                     WHERE i.CategoryCode = @categoryCode AND i.IsActive = 1";
                            if (hasSearch) query += " AND (i.Name LIKE @search OR i.Description LIKE @search)";
                                query += @" GROUP BY i.Code, i.Name, i.Description, i.Price, i.PromoPrice, i.Brand" + (hasImagesColumn ? ", i.Images" : "") + @"
                                     ORDER BY i.Name";
                        }

                        using (var cmdItems = new SqlCommand(query, connection))
                        {
                            if (!string.IsNullOrWhiteSpace(selectedCategory) && selectedCategory != "ALL")
                                cmdItems.Parameters.AddWithValue("@categoryCode", selectedCategory);
                            if (hasSearch)
                                cmdItems.Parameters.AddWithValue("@search", "%" + searchTerm + "%");

                            using (var reader = cmdItems.ExecuteReader())
                            {
                                while (reader.Read())
                                {
                                    string name = reader["Name"].ToString() ?? "";
                                    string description = reader["Description"].ToString() ?? "";
                                    decimal price = reader["Price"] != DBNull.Value ? Convert.ToDecimal(reader["Price"]) : 0m;
                                    decimal promoPrice = 0m;
                                    try { int promoIdx = reader.GetOrdinal("PromoPrice"); if (promoIdx >= 0 && reader[promoIdx] != DBNull.Value) promoPrice = Convert.ToDecimal(reader[promoIdx]); } catch { }
                                    string images = string.Empty;
                                    try { images = reader["Images"]?.ToString() ?? string.Empty; } catch { }
                                    int stock = reader["CalculatedStock"] != DBNull.Value ? Convert.ToInt32(reader["CalculatedStock"]) : 0;
                                    string brand = reader["Brand"].ToString() ?? "";

                                    var item = new ListViewItem(name);
                                    item.SubItems.Add(description);
                                    item.SubItems.Add($"{price:F2}");
                                    item.SubItems.Add($"{promoPrice:F2}");
                                    item.SubItems.Add(stock.ToString());
                                    item.SubItems.Add(brand);
                                    item.Tag = new { Name = name, Price = price, PromoPrice = promoPrice, Images = images };

                                    productListView.Items.Add(item);
                                }
                            }
                        }
                    };

                    // initial load (use provided categoryCode)
                    loadItems(categoryCode ?? "ALL", "");

                    // search box: filter as user types (within the provided category)
                    txtSearchFilter.TextChanged += (s, e) =>
                    {
                        try
                        {
                            loadItems(categoryCode ?? "ALL", txtSearchFilter.Text);
                            UpdateProductPreview(previewPictureBox, previewStatusLabel, null);
                        }
                        catch { }
                    };

                    productListView.SelectedIndexChanged += (s, e) =>
                    {
                        if (productListView.SelectedItems.Count == 0)
                        {
                            UpdateProductPreview(previewPictureBox, previewStatusLabel, null);
                            return;
                        }

                        var selectedItem = productListView.SelectedItems[0];
                        var productData = selectedItem.Tag as dynamic;
                        if (productData != null)
                            UpdateProductPreview(previewPictureBox, previewStatusLabel, productData.Images);
                    };

                    productForm.Controls.Add(txtSearchFilter);

                    // Add product to sale on double-click
                    productListView.DoubleClick += (s, e) =>
                    {
                        if (productListView.SelectedItems.Count > 0)
                        {
                            var selectedItem = productListView.SelectedItems[0];
                            var productData = selectedItem.Tag as dynamic;
                            if (productData != null)
                            {
                                    if (AddProductToSale(productData.Name, productData.Price, 1))
                                    {
                                        productForm.Close();
                                    }
                            }
                        }
                    };

                    var addButton = new Button
                    {
                        Text = "Add to Sale",
                        Location = new Point(300, 520),
                        Size = new Size(100, 35),
                        BackColor = Color.Green,
                        ForeColor = Color.White,
                        Font = new Font("Arial", 10, FontStyle.Bold)
                    };

                    addButton.Click += (s, e) =>
                    {
                        if (productListView.SelectedItems.Count > 0)
                        {
                            var selectedItem = productListView.SelectedItems[0];
                            var productData = selectedItem.Tag as dynamic;
                            if (productData != null)
                            {
                                if (AddProductToSale(productData.Name, productData.Price, 1))
                                {
                                    productForm.Close();
                                }
                            }
                        }
                        else
                        {
                            MessageBox.Show("Please select a product to add.", "Selection Required", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        }
                    };

                    var closeButton = new Button
                    {
                        Text = "Close",
                        Location = new Point(410, 520),
                        Size = new Size(100, 35),
                        BackColor = Color.Gray,
                        ForeColor = Color.White,
                        Font = new Font("Arial", 10, FontStyle.Bold)
                    };
                    closeButton.Click += (s, e) => productForm.Close();

                    productForm.Controls.AddRange(new Control[] { productListView, previewGroup, addButton, closeButton });
                    productForm.ShowDialog();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error loading products: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

