                           string query = @"
                            SELECT i.Code, i.Name, i.Description, i.Price," +
                                (hasImagesColumn ? " i.Images AS Images," : " CAST('' AS NVARCHAR(MAX)) AS Images,") + @"
                                c.Description as CategoryName
                            FROM Items i 
                            LEFT JOIN Category c ON i.CategoryCode = c.Code 
                            WHERE i.IsActive = 1";

                        var parameters = new List<SqlParameter>();

                        if (!string.IsNullOrWhiteSpace(searchFilter))
                        {
                            query += " AND (i.Name LIKE @search OR i.Description LIKE @search OR i.Code LIKE @search)";
                            parameters.Add(new SqlParameter("@search", $"%{searchFilter}%"));
                        }

                        if (!string.IsNullOrWhiteSpace(selectedCategory))
                        {
                            query += " AND i.CategoryCode = @category";
                            parameters.Add(new SqlParameter("@category", selectedCategory));
                        }

                        query += " ORDER BY i.Name";

                        var cmd = new SqlCommand(query, connection);
                        cmd.Parameters.AddRange(parameters.ToArray());

                        using (var reader = cmd.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                string code = reader["Code"].ToString() ?? "";
