                                itemsListView.Items.Add(item);
                                itemCount++;
                            }
                        }

                        itemCountLabel.Text = $"Total Items: {itemCount}";
                    };

                    // Event handlers
                    searchButton.Click += (s, e) => LoadItems();
                    searchTextBox.KeyPress += (s, e) => { if (e.KeyChar == (char)Keys.Enter) LoadItems(); };

