                        var selectedItem = itemsListView.SelectedItems[0];
                        dynamic itemData = selectedItem.Tag;
                        UpdateProductPreview(previewPictureBox, previewStatusLabel, itemData?.Images);
                    };

                    // Add LoadItems call to category filter buttons
                    foreach (Control ctrl in categoryFilterPanel.Controls)
