                    bool TryResolveSaleSelection(string baseItemCode, string baseItemName, decimal basePrice, IWin32Window owner,
                        out string saleDisplayName, out decimal salePrice, out string saleCategory, out string saleItemCode,
                        out string saleVariationId, out string saleDescription)
                    {
                        saleDisplayName = baseItemName;
                        salePrice = basePrice;
                        saleCategory = string.Empty;
                        saleItemCode = baseItemCode;
                        saleVariationId = string.Empty;
                        saleDescription = baseItemName;

                        var variantChoice = PromptForSaleVariantSelection(baseItemCode, baseItemName, basePrice, owner);
                        if (variantChoice == SaleVariantSelection.Cancelled)
                            return false;

                        if (variantChoice != null)
                        {
                            saleDisplayName = string.IsNullOrWhiteSpace(variantChoice.DisplayText) ? baseItemName : variantChoice.DisplayText;
                            salePrice = variantChoice.Price > 0 ? variantChoice.Price : basePrice;
                            saleCategory = variantChoice.CategoryCode ?? string.Empty;
                            saleItemCode = string.IsNullOrWhiteSpace(variantChoice.ItemCode) ? baseItemCode : variantChoice.ItemCode;
                            saleVariationId = variantChoice.VariationId ?? string.Empty;
                            saleDescription = string.IsNullOrWhiteSpace(variantChoice.Description) ? saleDisplayName : variantChoice.Description;
                        }

                        return true;
                    }

                    // Double-click to add to sale
                    itemsListView.DoubleClick += (s, e) =>
                    {
                        if (itemsListView.SelectedItems.Count == 0)
                            return;

                        var selectedItem = itemsListView.SelectedItems[0];
                        string baseItemCode = selectedItem.SubItems[0].Text ?? string.Empty;
                        string baseItemName = selectedItem.SubItems[1].Text ?? string.Empty;
                        decimal basePrice = 0m;
                        decimal.TryParse(selectedItem.SubItems[3].Text, out basePrice);

                        if (!TryResolveSaleSelection(baseItemCode, baseItemName, basePrice, salesForm,
                            out var saleDisplayName, out var salePrice, out var saleCategory, out var saleItemCode,
                            out var saleVariationId, out var saleDescription))
                        {
                            return;
                        }

                        AddToSale(saleDisplayName, 1, salePrice, saleCategory, saleItemCode, saleVariationId, saleDescription);
                        MessageBox.Show($"Added '{saleDisplayName}' to sale!", "Item Added", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    };

                    // Action buttons
                    var addToSaleButton = new Button
                    {
                        Text = "Add to Sale",
                        Location = new Point(300, 570),
                        Size = new Size(120, 35),
                        BackColor = Color.Green,
