                                    Size = new Size(220, 150),
                                    BorderStyle = BorderStyle.FixedSingle,
                                    SizeMode = PictureBoxSizeMode.Zoom,
                                    BackColor = Color.WhiteSmoke
                                };

                                var qtyPreviewLabel = new Label
                                {
                                    Text = "Loading image...",
                                    Location = new Point(300, 175),
                                    Size = new Size(220, 20),
                                    Font = new Font("Arial", 9, FontStyle.Regular),
                                    ForeColor = Color.DimGray
                                };

                                qtyPreviewBox.LoadCompleted += (ls, le) =>
                                {
                                    qtyPreviewLabel.Text = le.Error == null && !le.Cancelled
                                        ? "Image loaded"
                                        : "Unable to load image";
                                };

                                UpdateProductPreview(qtyPreviewBox, qtyPreviewLabel, itemData.Images);

                                var addButton = new Button
                                {
                                    Text = "Add",
                                    Location = new Point(100, 110),
                                    Size = new Size(70, 30),
                                    BackColor = Color.Green,
                                    ForeColor = Color.White,
                                    Font = new Font("Arial", 10, FontStyle.Bold)
                                };

                                var cancelButton = new Button
                                {
                                    Text = "Cancel",
                                    Location = new Point(180, 110),
                                    Size = new Size(70, 30),
                                    BackColor = Color.Gray,
                                    ForeColor = Color.White,
                                    Font = new Font("Arial", 10, FontStyle.Bold)
                                };

                                addButton.Click += (qs, qe) =>
                                {
                                    int quantity = (int)qtyUpDown.Value;
                                    string baseItemCode = selectedItem.SubItems[0].Text ?? string.Empty;
                                    string baseItemName = selectedItem.SubItems[1].Text ?? string.Empty;
                                    decimal basePrice = 0m;
                                    decimal.TryParse(selectedItem.SubItems[3].Text, out basePrice);

                                    if (!TryResolveSaleSelection(baseItemCode, baseItemName, basePrice, qtyForm,
                                        out var saleDisplayName, out var salePrice, out var saleCategory, out var saleItemCode,
                                        out var saleVariationId, out var saleDescription))
                                    {
                                        return;
                                    }

                                    AddToSale(saleDisplayName, quantity, salePrice, saleCategory, saleItemCode, saleVariationId, saleDescription);
                                    MessageBox.Show($"Added {quantity} x '{saleDisplayName}' to sale!", "Items Added", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                    qtyForm.Close();
                                };

                                cancelButton.Click += (qs, qe) => qtyForm.Close();

                                qtyForm.Controls.AddRange(new Control[] { itemLabel, priceLabel, qtyLabel, qtyUpDown, qtyPreviewBox, qtyPreviewLabel, addButton, cancelButton });
                                qtyForm.ShowDialog();
                            }
                        }
                        else
                        {
                            MessageBox.Show("Please select an item to add to sale.", "No Item Selected", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        }
                    };

                    var closeButton = new Button
                    {
                        Text = "Close",
                        Location = new Point(430, 570),
                        Size = new Size(100, 35),
                        BackColor = Color.DarkBlue,
                        ForeColor = Color.White,
                        Font = new Font("Arial", 11, FontStyle.Bold)
                    };
                    closeButton.Click += (s, e) => salesForm.Close();

                    // Add controls to form
                    salesForm.Controls.AddRange(new Control[] {
                        searchLabel, searchTextBox, categoryLabel, categoryFilterPanel, searchButton,
                        itemsListView, previewGroup, itemCountLabel, addToSaleButton, closeButton
                    });

                    // Load initial data
                    LoadItems();
                    salesForm.ShowDialog();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error loading sales items: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private Color GetCategoryColor(string category)
        {
            return category switch
            {
                "Fish" => Color.DarkOrange,
                "Stones" => Color.SaddleBrown,
                "Woods" => Color.Sienna,
                "Aquariums" => Color.DarkSlateBlue,
                "Accessories" => Color.DarkCyan,
                "Tanks" => Color.DarkSlateBlue, // For backward compatibility
                "Food" => Color.DarkGreen,
                "Chemicals" => Color.DarkRed,
                "Testing" => Color.Purple,
                "Equipment" => Color.DarkCyan,
                "Substrate" => Color.SaddleBrown,
                "Decorations" => Color.DarkMagenta,
                _ => Color.Gray
            };
        }

        private void ShowItemsButton_Click(object? sender, EventArgs e)
        {
            // Search box (declared here so the nested RefreshItemsGrid can read its value)
            TextBox? searchBox = null;

            void RefreshItemsGrid(DataGridView grid, Label countLabel)
            {
                grid.Rows.Clear();
                int rowCount = 0;
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var sql = @"
               SELECT i.Code, i.Name, i.Description, i.Cost, i.Price, i.WholesalePrice, i.RetailPrice, i.PromoPrice, 
                   c.Description as CategoryName, i.CategoryCode, i.Brand, i.SKU, i.VariationId,
                   i.MinimumStock, i.IsActive,
                   ISNULL(SUM(ile.Quantity), 0) as CalculatedStock
               FROM Items i 
               LEFT JOIN Category c ON i.CategoryCode = c.Code 
               LEFT JOIN ItemLedgerEntry ile ON i.Code = ile.ItemCode
               ";

                    // Apply search filter if a search box exists and has text
                    if (searchBox != null && !string.IsNullOrWhiteSpace(searchBox.Text))
                    {
                        sql += " WHERE (i.Code LIKE @filter OR i.Name LIKE @filter OR i.Description LIKE @filter) ";
                    }

                    sql += @" GROUP BY i.Code, i.Name, i.Description, i.Cost, i.Price, i.WholesalePrice, i.RetailPrice, i.PromoPrice, 
                          c.Description, i.CategoryCode, i.Brand, i.SKU, i.VariationId, i.MinimumStock, i.IsActive
                       ORDER BY c.Description, i.Name";

                    var command = new SqlCommand(sql, connection);
                    if (searchBox != null && !string.IsNullOrWhiteSpace(searchBox.Text))
                    {
                        command.Parameters.AddWithValue("@filter", "%" + searchBox.Text.Trim() + "%");
                    }
                    using (var reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string code = reader["Code"].ToString() ?? "";
                            string name = reader["Name"].ToString() ?? "";
                            string description = reader["Description"].ToString() ?? "";
                            decimal cost = reader["Cost"] != DBNull.Value ? Convert.ToDecimal(reader["Cost"]) : 0m;
                            decimal price = reader["Price"] != DBNull.Value ? Convert.ToDecimal(reader["Price"]) : 0m;
                            decimal wholesalePrice = reader["WholesalePrice"] != DBNull.Value ? Convert.ToDecimal(reader["WholesalePrice"]) : 0m;
                            decimal retailPrice = reader["RetailPrice"] != DBNull.Value ? Convert.ToDecimal(reader["RetailPrice"]) : 0m;
                            string categoryName = reader["CategoryName"].ToString() ?? "";
                            string categoryCode = reader["CategoryCode"].ToString() ?? "";
                            string brand = reader["Brand"].ToString() ?? "";
                            string sku = reader["SKU"].ToString() ?? "";

                            // Safely read VariationId (older databases may not have this column yet).
                            string variationId = "";
                            try
                            {
                                int variationIndex = reader.GetOrdinal("VariationId");
                                if (variationIndex >= 0 && reader[variationIndex] != DBNull.Value)
                                    variationId = reader[variationIndex].ToString() ?? "";
                            }
                            catch (IndexOutOfRangeException)
                            {
                                variationId = "";
                            }

                            int stock = reader["CalculatedStock"] != DBNull.Value ? Convert.ToInt32(reader["CalculatedStock"]) : 0;
                            int minStock = reader["MinimumStock"] != DBNull.Value ? Convert.ToInt32(reader["MinimumStock"]) : 0;
                            bool isActive = reader["IsActive"] != DBNull.Value ? Convert.ToBoolean(reader["IsActive"]) : true;

                            string status = stock <= minStock ? "LOW STOCK" : "OK";
                            string activeStatus = isActive ? "Active" : "Inactive";

                            // Safely read PromoPrice: some databases may not have this column yet.
                            decimal promoPrice = 0m;
                            int promoIndex = -1;
                            try
                            {
                                promoIndex = reader.GetOrdinal("PromoPrice");
                            }
                            catch (IndexOutOfRangeException)
                            {
                                promoIndex = -1; // column missing, keep default 0
                            }
                            if (promoIndex >= 0 && reader[promoIndex] != DBNull.Value)
                            {
                                promoPrice = Convert.ToDecimal(reader[promoIndex]);
                            }

                            int rowIndex = grid.Rows.Add(code, name, description, cost, price, promoPrice, wholesalePrice, retailPrice,
                                         categoryName, brand, sku, variationId, stock, minStock, status, activeStatus,
                                         "Edit", "Delete");

                            // Color low stock items red
                            if (stock <= minStock)
                            {
                                grid.Rows[rowIndex].DefaultCellStyle.BackColor = Color.LightCoral;
                                grid.Rows[rowIndex].DefaultCellStyle.ForeColor = Color.DarkRed;
                            }

                            rowCount++;
                        }
                    }
                }
                countLabel.Text = $"Total Items: {rowCount}";
            }

            try
            {
                // Ensure Items table exists with correct schema
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var createTableCmd = new SqlCommand(@"
                        -- Check if old table structure exists and recreate with new schema
                        IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Items')
                        BEGIN
                            -- Check if table has old ID structure
                            IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Items' AND COLUMN_NAME = 'ID' AND IS_NULLABLE = 'NO')
                            BEGIN
                                -- Drop existing table and recreate with new structure
                                IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE CONSTRAINT_NAME = 'FK_ItemLedgerEntry_Items')
                                BEGIN
                                    ALTER TABLE ItemLedgerEntry DROP CONSTRAINT FK_ItemLedgerEntry_Items
                                END
                                DROP TABLE Items
                                
                                CREATE TABLE Items (
                                    Code NVARCHAR(50) PRIMARY KEY,
                                    Name NVARCHAR(255) NOT NULL,
                                    Description NVARCHAR(MAX),
                                    Cost DECIMAL(10,2) DEFAULT 0,
                                    Price DECIMAL(10,2) NOT NULL DEFAULT 0,
                                    PromoPrice DECIMAL(10,2) DEFAULT 0,
                                    WholesalePrice DECIMAL(10,2) DEFAULT 0,
                                    RetailPrice DECIMAL(10,2) DEFAULT 0,
                                    Images NVARCHAR(MAX),
                                    CategoryCode NVARCHAR(50),
                                    Brand NVARCHAR(100),
                                    SKU NVARCHAR(100),
                                    VariationId NVARCHAR(50),
                                    QuantityInStock INT DEFAULT 0,
                                    MinimumStock INT DEFAULT 0,
                                    IsActive BIT DEFAULT 1,
                                    CreatedDate DATETIME2 DEFAULT GETDATE(),
                                    UpdatedDate DATETIME2 DEFAULT GETDATE(),
                                    CONSTRAINT FK_Items_Category FOREIGN KEY (CategoryCode) REFERENCES Category(Code)
                                )
                                
                                -- Recreate ItemLedgerEntry foreign key if table exists
                                IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'ItemLedgerEntry')
                                BEGIN
                                    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'ItemCode')
                                    BEGIN
                                        ALTER TABLE ItemLedgerEntry ADD ItemCode NVARCHAR(50)
                                        ALTER TABLE ItemLedgerEntry ADD CONSTRAINT FK_ItemLedgerEntry_Items FOREIGN KEY (ItemCode) REFERENCES Items(Code)
                                    END
                                END
                            END
                        END
                        ELSE
                        BEGIN
                            CREATE TABLE Items (
                                Code NVARCHAR(50) PRIMARY KEY,
                                Name NVARCHAR(255) NOT NULL,
                                Description NVARCHAR(MAX),
                                Cost DECIMAL(10,2) DEFAULT 0,
                                Price DECIMAL(10,2) NOT NULL DEFAULT 0,
                                PromoPrice DECIMAL(10,2) DEFAULT 0,
                                WholesalePrice DECIMAL(10,2) DEFAULT 0,
                                RetailPrice DECIMAL(10,2) DEFAULT 0,
                                Images NVARCHAR(MAX),
                                CategoryCode NVARCHAR(50),
                                Brand NVARCHAR(100),
                                SKU NVARCHAR(100),
                                VariationId NVARCHAR(50),
                                QuantityInStock INT DEFAULT 0,
                                MinimumStock INT DEFAULT 0,
                                IsActive BIT DEFAULT 1,
                                CreatedDate DATETIME2 DEFAULT GETDATE(),
                                UpdatedDate DATETIME2 DEFAULT GETDATE(),
                                CONSTRAINT FK_Items_Category FOREIGN KEY (CategoryCode) REFERENCES Category(Code)
                            )
                        END

                        -- Add columns if missing (safe for existing databases)
                        IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Items')
                        BEGIN
                            IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Items' AND COLUMN_NAME = 'PromoPrice')
                                ALTER TABLE Items ADD PromoPrice DECIMAL(10,2) DEFAULT 0
                            IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Items' AND COLUMN_NAME = 'VariationId')
                                ALTER TABLE Items ADD VariationId NVARCHAR(50)
                            IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Items' AND COLUMN_NAME = 'Images')
                                ALTER TABLE Items ADD Images NVARCHAR(MAX)
                            IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Variant')
                            BEGIN
                                CREATE TABLE [Variant] (
                                    VariantEntryNo INT IDENTITY(1,1) PRIMARY KEY,
                                    VariationId NVARCHAR(50) NOT NULL,
                                    MainItemCode NVARCHAR(50) NOT NULL,
                                    ItemCode NVARCHAR(50) NULL,
                                    SKU NVARCHAR(100) NULL,
                                    VariantName NVARCHAR(255) NULL,
                                    Price DECIMAL(18,2) NULL,
                                    CategoryCode NVARCHAR(50) NULL,
                                    Images NVARCHAR(MAX) NULL,
                                    CreatedDate DATETIME2 DEFAULT GETDATE(),
                                    UpdatedDate DATETIME2 DEFAULT GETDATE()
                                )
                                CREATE UNIQUE INDEX UX_Variant_VariationId ON [Variant](VariationId)
                                CREATE INDEX IX_Variant_MainItemCode ON [Variant](MainItemCode)
                            END
                            ELSE
                            BEGIN
                                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Variant' AND COLUMN_NAME = 'MainItemCode')
                                    ALTER TABLE [Variant] ADD MainItemCode NVARCHAR(50) NOT NULL CONSTRAINT DF_Variant_MainItemCode_MainForm DEFAULT ''
                                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Variant' AND COLUMN_NAME = 'ItemCode')
                                    ALTER TABLE [Variant] ADD ItemCode NVARCHAR(50) NULL
                                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Variant' AND COLUMN_NAME = 'SKU')
                                    ALTER TABLE [Variant] ADD SKU NVARCHAR(100) NULL
                                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Variant' AND COLUMN_NAME = 'VariantName')
                                    ALTER TABLE [Variant] ADD VariantName NVARCHAR(255) NULL
                                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Variant' AND COLUMN_NAME = 'Price')
                                    ALTER TABLE [Variant] ADD Price DECIMAL(18,2) NULL
                                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Variant' AND COLUMN_NAME = 'CategoryCode')
                                    ALTER TABLE [Variant] ADD CategoryCode NVARCHAR(50) NULL
                                IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Variant' AND COLUMN_NAME = 'Images')
                                    ALTER TABLE [Variant] ADD Images NVARCHAR(MAX) NULL
                            END
                        END", connection);
                    createTableCmd.ExecuteNonQuery();
                }

                var itemsForm = new Form
                {
                    Text = "Item Management",
                    Size = new Size(1400, 700),
                    StartPosition = FormStartPosition.CenterParent,
                    BackColor = Color.White
                };

                // We'll create the search box after the grid and count label are created so we can reference them in the TextChanged handler.

                var dataGridView = new DataGridView
                {
                    Location = new Point(10, 40),
                    Size = new Size(1360, 420),
                    ReadOnly = true,
                    AllowUserToAddRows = false,
                    AllowUserToDeleteRows = false,
                    AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.None,
                    ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                    SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                    BackgroundColor = Color.White,
                    BorderStyle = BorderStyle.Fixed3D,
                    RowHeadersVisible = false
                };

                // Add columns
                dataGridView.Columns.Add("Code", "Code");
                dataGridView.Columns.Add("Name", "Name");
                dataGridView.Columns.Add("Description", "Description");
                dataGridView.Columns.Add("Cost", "Cost");
                dataGridView.Columns.Add("Price", "Price");
                // Expose promotional price
                dataGridView.Columns.Add("PromoPrice", "Promo Price");
                dataGridView.Columns.Add("WholesalePrice", "Wholesale");
                dataGridView.Columns.Add("RetailPrice", "Retail");
                dataGridView.Columns.Add("Category", "Category");
                dataGridView.Columns.Add("Brand", "Brand");
                dataGridView.Columns.Add("SKU", "SKU");
                dataGridView.Columns.Add("VariationId", "Variation ID");
                dataGridView.Columns.Add("Stock", "Stock");
                dataGridView.Columns.Add("MinStock", "Min Stock");
                dataGridView.Columns.Add("Status", "Status");
                dataGridView.Columns.Add("Active", "Active");

                var editButtonColumn = new DataGridViewButtonColumn
                {
                    Name = "Edit",
                    HeaderText = "Edit",
                    Text = "Edit",
                    UseColumnTextForButtonValue = true,
                    Width = 60
                };
                dataGridView.Columns.Add(editButtonColumn);

                var deleteButtonColumn = new DataGridViewButtonColumn
                {
                    Name = "Delete",
                    HeaderText = "Delete",
                    Text = "Delete",
                    UseColumnTextForButtonValue = true,
                    Width = 60
                };
                dataGridView.Columns.Add(deleteButtonColumn);

                // Set column widths
                dataGridView.Columns["Code"].Width = 100;
                dataGridView.Columns["Name"].Width = 150;
                dataGridView.Columns["Description"].Width = 200;
                dataGridView.Columns["Cost"].Width = 80;
                dataGridView.Columns["Price"].Width = 80;
                dataGridView.Columns["PromoPrice"].Width = 80;
                dataGridView.Columns["WholesalePrice"].Width = 80;
                dataGridView.Columns["RetailPrice"].Width = 80;
                dataGridView.Columns["Category"].Width = 100;
                dataGridView.Columns["Brand"].Width = 80;
                dataGridView.Columns["SKU"].Width = 80;
                dataGridView.Columns["VariationId"].Width = 90;
                dataGridView.Columns["Stock"].Width = 60;
                dataGridView.Columns["MinStock"].Width = 70;
                dataGridView.Columns["Status"].Width = 80;
                dataGridView.Columns["Active"].Width = 60;

                // Format price columns
                dataGridView.Columns["Cost"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["Price"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["PromoPrice"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["WholesalePrice"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["RetailPrice"].DefaultCellStyle.Format = "C2";

                var countLabel = new Label
                {
                    Text = "Total Items: 0",
                    Location = new Point(10, 470),
                    Size = new Size(250, 20),
                    Font = new Font("Arial", 10, FontStyle.Bold),
                    ForeColor = Color.DarkBlue
                };

                // Action buttons
                var addItemButton = new Button
                {
                    Text = "Add New Item",
                    Location = new Point(10, 500),
                    Size = new Size(120, 35),
                    BackColor = Color.Green,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                addItemButton.Click += (s, args) => ShowItemEditForm("", () => RefreshItemsGrid(dataGridView, countLabel));

                var refreshButton = new Button
                {
                    Text = "Refresh",
                    Location = new Point(140, 500),
                    Size = new Size(80, 35),
                    BackColor = Color.Blue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                refreshButton.Click += (s, args) => RefreshItemsGrid(dataGridView, countLabel);

                var excelExportButton = new Button
                {
                    Text = "Export Excel",
                    Location = new Point(230, 500),
                    Size = new Size(120, 35),
                    BackColor = Color.DarkGreen,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                excelExportButton.Click += (s, args) => ExcelExportButton_Click(s, args);

                var excelImportButton = new Button
                {
                    Text = "Import Excel",
                    Location = new Point(360, 500),
                    Size = new Size(120, 35),
                    BackColor = Color.Orange,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                excelImportButton.Click += (s, args) =>
                {
                    ExcelImportButton_Click(s, args);
                    RefreshItemsGrid(dataGridView, countLabel);
                };

                var inventoryLedgerButton = new Button
                {
                    Text = "Inventory Ledger",
                    Location = new Point(490, 500),
                    Size = new Size(130, 35),
                    BackColor = Color.Purple,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                inventoryLedgerButton.Click += (s, args) =>
                {
                    string selectedItemCode = "";
                    if (dataGridView.SelectedRows.Count > 0)
                    {
                        selectedItemCode = dataGridView.SelectedRows[0].Cells["Code"].Value?.ToString() ?? "";
                    }
                    ShowInventoryLedger(selectedItemCode);
                };

                var stockAdjustmentButton = new Button
                {
                    Text = "Stock Adjustment",
                    Location = new Point(630, 500),
                    Size = new Size(130, 35),
                    BackColor = Color.Crimson,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                stockAdjustmentButton.Click += (s, args) => ShowStockAdjustment(() => RefreshItemsGrid(dataGridView, countLabel));

                // Tool to reset all inventory quantities to zero by inserting offsetting ledger entries (keeps history)
                var resetInventoryButton = new Button
                {
                    Text = "Reset Inventory",
                    Location = new Point(770, 540),
                    Size = new Size(130, 35),
                    BackColor = Color.DarkRed,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                resetInventoryButton.Click += (s, args) =>
                {
                    var confirm = MessageBox.Show(
                        "This will reset inventory for ALL items to zero by inserting stock adjustment entries.\n\n" +
                        "Existing ItemLedgerEntry records will NOT be deleted, only offset.\n\n" +
                        "Are you sure you want to continue?",
                        "Confirm Inventory Reset",
                        MessageBoxButtons.YesNo,
                        MessageBoxIcon.Warning);

                    if (confirm != DialogResult.Yes)
                        return;

                    try
                    {
                        // For each item, compute current net quantity and insert an offsetting ItemLedgerEntry
                        using (var connection = new SqlConnection(connectionString))
                        {
                            connection.Open();

                            var sql = @"SELECT Code, ISNULL(SUM(Quantity),0) AS NetQty
                                         FROM Items i
                                         LEFT JOIN ItemLedgerEntry ile ON ile.ItemCode = i.Code
                                         GROUP BY Code";

                            using (var cmd = new SqlCommand(sql, connection))
                            using (var rdr = cmd.ExecuteReader())
                            {
                                while (rdr.Read())
                                {
                                    string code = rdr["Code"]?.ToString() ?? string.Empty;
                                    if (string.IsNullOrWhiteSpace(code))
                                        continue;

                                    long net = 0;
                                    if (rdr["NetQty"] != DBNull.Value)
                                        net = Convert.ToInt64(rdr["NetQty"]);

                                    if (net != 0)
                                    {
                                        int qty = (int)Math.Abs(net);
                                        bool increase = net < 0; // if net negative, we need to increase; if positive, decrease

                                        // Use existing helper so all inserts go through one path
                                        var userName = string.IsNullOrWhiteSpace(CurrentUser.Username) ? "SYSTEM" : CurrentUser.Username;
                                        FunctionEvents.offsetaquariuminventory(code, qty, increase, "RESET_ALL", userName, this);
                                    }
                                }
                            }

                            // Also reset Items.QuantityInStock to zero for all items
                            using (var upd = new SqlCommand("UPDATE Items SET QuantityInStock = 0", connection))
                            {
                                upd.ExecuteNonQuery();
                            }
                        }

                        RefreshItemsGrid(dataGridView, countLabel);
                        MessageBox.Show("Inventory and QuantityInStock have been reset to zero for all items using offset entries.", "Inventory Reset", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Failed to reset inventory: {ex.Message}", "Inventory Reset Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                };

                var floatEntryButton = new Button
                {
                    Text = "Float Entry",
                    Location = new Point(770, 500),
                    Size = new Size(110, 35),
                    BackColor = Color.DarkOrange,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                floatEntryButton.Click += (s, args) => ShowCashFloatHistory();

                var syncButton = new Button
                {
                    Text = "Sync",
                    Location = new Point(890, 500),
                    Size = new Size(90, 35),
                    BackColor = Color.MidnightBlue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                syncButton.Click += async (s, args) => await RunManualProductSyncAsync(syncButton, () => RefreshItemsGrid(dataGridView, countLabel));

                var customerSyncButton = new Button
                {
                    Text = "Customers",
                    Location = new Point(985, 500),
                    Size = new Size(110, 35),
                    BackColor = Color.SteelBlue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                customerSyncButton.Click += async (s, args) => await RunManualCustomerSyncAsync(customerSyncButton);

                var syncUpButton = new Button
                {
                    Text = "Sync Up",
                    Location = new Point(1100, 500),
                    Size = new Size(110, 35),
                    BackColor = Color.SteelBlue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                syncUpButton.Click += async (s, args) =>
                {
                    if (_isOnlineSyncRunning)
                    {
                        MessageBox.Show("Sync is already running.", "Sync Up", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    _isOnlineSyncRunning = true;
                    var originalText = syncUpButton.Text;
                    syncUpButton.Enabled = false;
                    syncButton.Enabled = false;
                    syncUpButton.Text = "Syncing...";

                    try
                    {
                        int updated;
                        try
                        {
                            updated = await OnlinefunctionsEvents.SyncUpProductsAsync(TimeSpan.FromSeconds(90));
                        }
                        catch (Exception ex)
                        {
                            MessageBox.Show($"Sync Up failed: {ex.Message}", "Sync Up", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            return;
                        }

                        RefreshItemsGrid(dataGridView, countLabel);
                        MessageBox.Show($"Sync Up completed. Items updated with VariationId: {updated}", "Sync Up", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                    finally
                    {
                        _isOnlineSyncRunning = false;
                        syncUpButton.Text = originalText;
                        syncUpButton.Enabled = true;
                        syncButton.Enabled = true;
                    }
                };

                var closeButton = new Button
                {
                    Text = "Close",
                    Location = new Point(1295, 500),
                    Size = new Size(80, 35),
                    BackColor = Color.DarkBlue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                closeButton.Click += (s, args) => itemsForm.Close();

                // Handle grid button clicks
                dataGridView.CellClick += (gridSender, gridE) =>
                {
                    if (gridE.RowIndex >= 0)
                    {
                        var row = dataGridView.Rows[gridE.RowIndex];
                        string itemCode = row.Cells["Code"].Value?.ToString() ?? "";

                        if (gridE.ColumnIndex == dataGridView.Columns["Edit"].Index)
                        {
                            ShowItemEditForm(itemCode, () => RefreshItemsGrid(dataGridView, countLabel));
                        }
                        else if (gridE.ColumnIndex == dataGridView.Columns["Delete"].Index)
                        {
                            string itemName = row.Cells["Name"].Value?.ToString() ?? "";
                            var result = MessageBox.Show($"Are you sure you want to delete '{itemName}' (Code: {itemCode})?",
                                                       "Confirm Delete", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);

                            if (result == DialogResult.Yes)
                            {
                                try
                                {
                                    using (var connection = new SqlConnection(connectionString))
                                    {
                                        connection.Open();
                                        var cmd = new SqlCommand("DELETE FROM Items WHERE Code = @code", connection);
                                        cmd.Parameters.AddWithValue("@code", itemCode);
                                        int affected = cmd.ExecuteNonQuery();

                                        if (affected > 0)
                                        {
                                            RefreshItemsGrid(dataGridView, countLabel);
                                            MessageBox.Show("Item deleted successfully!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                        }
                                        else
                                        {
                                            MessageBox.Show("Failed to delete item.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                                        }
                                    }
                                }
                                catch (Exception ex)
                                {
                                    MessageBox.Show($"Error deleting item: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                                }
                            }
                        }
                    }
                };

                // Double-click row to open edit form
                dataGridView.DoubleClick += (gridSender, gridE) =>
                {
                    try
                    {
                        if (dataGridView.SelectedRows.Count > 0)
                        {
                            var sel = dataGridView.SelectedRows[0];
                            string itemCode = sel.Cells["Code"].Value?.ToString() ?? "";
                            if (!string.IsNullOrWhiteSpace(itemCode))
                            {
                                ShowItemEditForm(itemCode, () => RefreshItemsGrid(dataGridView, countLabel));
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Failed to open item for edit: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                };

                // Initialize search box now that dataGridView and countLabel are defined
                searchBox = new TextBox
                {
                    Location = new Point(10, 10),
                    Size = new Size(400, 25),
                    Font = new Font("Arial", 10),
                    PlaceholderText = "Search by code, name or description..."
                };
                searchBox.TextChanged += (s, args) => RefreshItemsGrid(dataGridView, countLabel);

                itemsForm.Controls.AddRange(new Control[] {
                    searchBox, dataGridView, countLabel, addItemButton, refreshButton,
                    excelExportButton, excelImportButton, inventoryLedgerButton, stockAdjustmentButton, resetInventoryButton, floatEntryButton, syncButton, customerSyncButton, syncUpButton, closeButton
                });

                RefreshItemsGrid(dataGridView, countLabel);
                itemsForm.ShowDialog();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to open Item Management: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private sealed class SaleVariantSelection
        {
            public static SaleVariantSelection Cancelled { get; } = new SaleVariantSelection { IsCancelled = true };

            public bool IsCancelled { get; private set; }
            public string ItemCode { get; set; } = string.Empty;
            public string VariationId { get; set; } = string.Empty;
            public string VariantName { get; set; } = string.Empty;
            public string DisplayText { get; set; } = string.Empty;
            public string Description { get; set; } = string.Empty;
            public string CategoryCode { get; set; } = string.Empty;
            public string Images { get; set; } = string.Empty;
            public int Stock { get; set; }
            public bool IsActive { get; set; } = true;
            public decimal Price { get; set; }
        }

        private List<SaleVariantSelection> LoadSaleVariants(string mainItemCode, decimal defaultPrice)
        {
            var variants = new List<SaleVariantSelection>();
            if (string.IsNullOrWhiteSpace(mainItemCode))
                return variants;

            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                using var cmd = new SqlCommand(@"
SELECT
    ISNULL(NULLIF(v.ItemCode, ''), v.MainItemCode) AS ItemCode,
    ISNULL(v.VariationId, '') AS VariationId,
    ISNULL(NULLIF(v.VariantName, ''), ISNULL(NULLIF(variantItem.Name, ''), ISNULL(NULLIF(variantItem.Description, ''), ''))) AS VariantName,
    ISNULL(NULLIF(variantItem.Description, ''), ISNULL(NULLIF(mainItem.Description, ''), ISNULL(NULLIF(v.VariantName, ''), ISNULL(NULLIF(variantItem.Name, ''), ISNULL(v.MainItemCode, ''))))) AS VariantDescription,
    ISNULL(v.Price, ISNULL(variantItem.Price, ISNULL(mainItem.Price, @defaultPrice))) AS Price,
    ISNULL(NULLIF(v.CategoryCode, ''), ISNULL(NULLIF(variantItem.CategoryCode, ''), ISNULL(mainItem.CategoryCode, ''))) AS CategoryCode,
    ISNULL(NULLIF(v.Images, ''), ISNULL(NULLIF(variantItem.Images, ''), ISNULL(mainItem.Images, ''))) AS Images,
    ISNULL(variantItem.QuantityInStock, ISNULL(mainItem.QuantityInStock, 0)) AS Stock,
    ISNULL(variantItem.IsActive, ISNULL(mainItem.IsActive, 1)) AS IsActive
FROM dbo.[Variant] v
LEFT JOIN Items variantItem ON variantItem.Code = ISNULL(NULLIF(v.ItemCode, ''), v.MainItemCode)
LEFT JOIN Items mainItem ON mainItem.Code = v.MainItemCode
WHERE v.MainItemCode = @mainItemCode
ORDER BY VariantName, ItemCode", connection);
                cmd.Parameters.AddWithValue("@mainItemCode", mainItemCode);
                cmd.Parameters.AddWithValue("@defaultPrice", defaultPrice);

                using var reader = cmd.ExecuteReader();
                while (reader.Read())
                {
                    string variantName = reader["VariantName"]?.ToString() ?? string.Empty;
                    string itemCode = reader["ItemCode"]?.ToString() ?? string.Empty;
                    decimal variantPrice = reader["Price"] != DBNull.Value ? Convert.ToDecimal(reader["Price"]) : defaultPrice;

                    variants.Add(new SaleVariantSelection
                    {
                        ItemCode = itemCode,
                        VariationId = reader["VariationId"]?.ToString() ?? string.Empty,
                        VariantName = variantName,
                        DisplayText = string.IsNullOrWhiteSpace(variantName) ? itemCode : variantName,
                        Description = reader["VariantDescription"]?.ToString()?.Trim() ?? string.Empty,
                        CategoryCode = reader["CategoryCode"]?.ToString() ?? string.Empty,
                        Images = reader["Images"]?.ToString() ?? string.Empty,
                        Stock = reader["Stock"] != DBNull.Value ? Convert.ToInt32(reader["Stock"]) : 0,
                        IsActive = reader["IsActive"] == DBNull.Value || Convert.ToBoolean(reader["IsActive"]),
                        Price = variantPrice
                    });
                }
            }

            return variants
                .GroupBy(v => string.IsNullOrWhiteSpace(v.VariationId) ? v.ItemCode : v.VariationId, StringComparer.OrdinalIgnoreCase)
                .Select(g => g.First())
                .ToList();
        }

        private SaleVariantSelection? PromptForSaleVariantSelection(string mainItemCode, string mainItemName, decimal defaultPrice, IWin32Window? owner = null)
        {
            var variants = LoadSaleVariants(mainItemCode, defaultPrice);
            if (variants.Count == 0)
                return null;

            SaleVariantSelection? selected = null;

            using var form = new Form
            {
                Text = "Choose Variant",
                Size = new Size(820, 520),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false,
                MinimizeBox = false
            };

            var titleLabel = new Label
            {
                Text = $"Select variant for: {BuildVariantDialogHeaderText(mainItemCode, mainItemName)}",
                Location = new Point(20, 15),
                Size = new Size(760, 30),
                Font = new Font("Arial", 12, FontStyle.Bold)
            };

            var infoLabel = new Label
            {
                Text = "Choose the exact variant being sold.",
                Location = new Point(20, 45),
                Size = new Size(760, 22),
                Font = new Font("Arial", 9, FontStyle.Regular),
                ForeColor = Color.DimGray
            };

            var flow = new FlowLayoutPanel
            {
                Location = new Point(20, 80),
                Size = new Size(760, 350),
                AutoScroll = true,
                WrapContents = true,
                FlowDirection = FlowDirection.LeftToRight,
                BackColor = Color.WhiteSmoke,
                Padding = new Padding(10)
            };

            var cancelButton = new Button
            {
                Text = "Cancel",
                Location = new Point(680, 440),
                Size = new Size(100, 35),
                BackColor = Color.DimGray,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            cancelButton.Click += (s, e) => form.Close();

            foreach (var variant in variants)
            {
                string buttonText = BuildVariantSelectionButtonText(variant);

                var button = new Button
                {
                    Text = buttonText,
                    Size = new Size(220, 110),
                    Margin = new Padding(8),
                    BackColor = variant.IsActive ? Color.MediumSlateBlue : Color.Gray,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold),
                    Tag = variant,
                    UseVisualStyleBackColor = false,
                    Enabled = variant.IsActive,
                    TextAlign = ContentAlignment.MiddleCenter
                };

                if (variant.Stock <= 0)
                    button.BackColor = Color.DarkOrange;

                button.Click += (s, e) =>
                {
                    selected = (SaleVariantSelection?)button.Tag;
                    form.DialogResult = DialogResult.OK;
                    form.Close();
                };

                flow.Controls.Add(button);
            }

            form.Controls.Add(titleLabel);
            form.Controls.Add(infoLabel);
            form.Controls.Add(flow);
            form.Controls.Add(cancelButton);

            var result = owner is Form ownerForm ? form.ShowDialog(ownerForm) : form.ShowDialog();
            if (result != DialogResult.OK || selected == null)
                return SaleVariantSelection.Cancelled;

            if (!string.IsNullOrWhiteSpace(selected.DisplayText) && !selected.DisplayText.Contains(mainItemName, StringComparison.OrdinalIgnoreCase))
                selected.DisplayText = $"{mainItemName} - {selected.DisplayText}";

            selected.Description = BuildVariantSaleDescription(
                mainItemName,
                string.IsNullOrWhiteSpace(selected.Description) ? null : selected.Description,
                string.IsNullOrWhiteSpace(selected.DisplayText) ? null : selected.DisplayText);

            return selected;
        }

        private string BuildVariantDialogHeaderText(string mainItemCode, string mainItemName)
        {
            string code = mainItemCode?.Trim() ?? string.Empty;
            string description = mainItemName?.Trim() ?? string.Empty;

            if (string.IsNullOrWhiteSpace(code))
            {
                return description;
            }

            if (string.IsNullOrWhiteSpace(description)
                || string.Equals(code, description, StringComparison.OrdinalIgnoreCase))
            {
                return code;
            }

            return $"{code} - {description}";
        }

        private string BuildAquariumVariantPickerText(SaleVariantSelection variant)
        {
            string itemCode = variant.ItemCode?.Trim() ?? string.Empty;
            string variantName = variant.VariantName?.Trim() ?? string.Empty;
            string description = variant.Description?.Trim() ?? string.Empty;
            string displayText = variant.DisplayText?.Trim() ?? string.Empty;

            if (string.IsNullOrWhiteSpace(itemCode))
            {
                if (!string.IsNullOrWhiteSpace(variantName))
                {
                    return variantName;
                }

                return string.IsNullOrWhiteSpace(displayText) ? description : displayText;
            }

            string preferredDescription = variantName;
            if (string.IsNullOrWhiteSpace(preferredDescription)
                || string.Equals(preferredDescription, itemCode, StringComparison.OrdinalIgnoreCase))
            {
                preferredDescription = description;
            }

            if (string.IsNullOrWhiteSpace(preferredDescription)
                || string.Equals(preferredDescription, itemCode, StringComparison.OrdinalIgnoreCase))
            {
                preferredDescription = displayText;
            }

            if (string.IsNullOrWhiteSpace(preferredDescription)
                || string.Equals(preferredDescription, itemCode, StringComparison.OrdinalIgnoreCase))
            {
                return itemCode;
            }

            return $"{itemCode} - {preferredDescription}";
        }

        private string BuildVariantSelectionButtonText(SaleVariantSelection variant)
        {
            string title = string.IsNullOrWhiteSpace(variant.DisplayText) ? variant.ItemCode : variant.DisplayText;
            string description = variant.Description?.Trim() ?? string.Empty;

            if (string.IsNullOrWhiteSpace(description)
                || string.Equals(description, title, StringComparison.OrdinalIgnoreCase)
                || string.Equals(description, variant.ItemCode, StringComparison.OrdinalIgnoreCase))
            {
                return $"{title}\nP{variant.Price:F2}".ToUpperInvariant();
            }

            if (description.Length > 36)
            {
                description = description.Substring(0, 33).TrimEnd() + "...";
            }

            return $"{title}\n{description}\nP{variant.Price:F2}".ToUpperInvariant();
        }

        private bool IsManagedAquariumSetItem(string? categoryCode, string? itemCode, string? variationId, string? itemName)
        {
            if (string.Equals(categoryCode?.Trim(), "AQUARIUM SET", StringComparison.OrdinalIgnoreCase))
                return false;

            var normalizedCategory = categoryCode?.Trim() ?? string.Empty;
            if (string.Equals(normalizedCategory, "SET", StringComparison.OrdinalIgnoreCase))
                return true;

            var packageHeaders = CompleteAquariumSetData.GetPackageHeaders(connectionString);
            if (!string.IsNullOrWhiteSpace(variationId) && packageHeaders.Any(header => string.Equals(header.VariantID, variationId, StringComparison.OrdinalIgnoreCase)))
                return true;

            if (!string.IsNullOrWhiteSpace(itemName) && packageHeaders.Any(header => string.Equals(header.PackageName, itemName, StringComparison.OrdinalIgnoreCase)))
                return true;

            return false;
        }

        private void ShowAquariumSetEntryPointMessage()
        {
            MessageBox.Show(this,
                "This SET item must be added using the Aquarium Set button.",
                "Aquarium Set",
                MessageBoxButtons.OK,
                MessageBoxIcon.Information);
        }

        private void ProductButton_Click(object? sender, EventArgs e)
        {
            if (sender is Button button && button.Tag != null)
            {
                dynamic product = button.Tag;
                string category = string.Empty;
                string itemCode = string.Empty;
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var cmd = new SqlCommand("SELECT TOP 1 Code, CategoryCode FROM Items WHERE Name = @itemName", connection);
                    cmd.Parameters.AddWithValue("@itemName", product.Name);
                    using var reader = cmd.ExecuteReader();
                    if (reader.Read())
                    {
                        itemCode = reader["Code"]?.ToString() ?? string.Empty;
                        category = reader["CategoryCode"]?.ToString() ?? string.Empty;
                    }
                }

                if (IsManagedAquariumSetItem(category, itemCode, null, product.Name))
                {
                    ShowAquariumSetEntryPointMessage();
                    return;
                }

                var variantChoice = PromptForSaleVariantSelection(itemCode, product.Name, product.Price, this);
                if (variantChoice == SaleVariantSelection.Cancelled)
                    return;

                if (variantChoice != null)
                {
                    if (IsManagedAquariumSetItem(variantChoice.CategoryCode, variantChoice.ItemCode, variantChoice.VariationId, product.Name))
                    {
                        ShowAquariumSetEntryPointMessage();
                        return;
                    }

                    AddToSale(variantChoice.DisplayText, 1, variantChoice.Price, variantChoice.CategoryCode, variantChoice.ItemCode, variantChoice.VariationId, variantChoice.Description);
                    return;
                }

                AddToSale(product.Name, 1, product.Price, category, itemCode);
            }
        }

        private bool AddProductToSale(string productName, decimal price, int quantity)
        {
            string category = string.Empty;
            string itemCode = string.Empty;
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                var cmd = new SqlCommand("SELECT TOP 1 Code, CategoryCode FROM Items WHERE Name = @itemName", connection);
                cmd.Parameters.AddWithValue("@itemName", productName);
                using var reader = cmd.ExecuteReader();
                if (reader.Read())
                {
                    itemCode = reader["Code"]?.ToString() ?? string.Empty;
                    category = reader["CategoryCode"]?.ToString() ?? string.Empty;
                }
            }

            if (IsManagedAquariumSetItem(category, itemCode, null, productName))
            {
                ShowAquariumSetEntryPointMessage();
                return false;
            }

            var variantChoice = PromptForSaleVariantSelection(itemCode, productName, price, this);
            if (variantChoice == SaleVariantSelection.Cancelled)
                return false;

            if (variantChoice != null)
            {
                if (IsManagedAquariumSetItem(variantChoice.CategoryCode, variantChoice.ItemCode, variantChoice.VariationId, productName))
                {
                    ShowAquariumSetEntryPointMessage();
                    return false;
                }

                AddToSale(variantChoice.DisplayText, quantity, variantChoice.Price, variantChoice.CategoryCode, variantChoice.ItemCode, variantChoice.VariationId, variantChoice.Description);
                return true;
            }

            AddToSale(productName, quantity, price, category, itemCode);
            return true;
        }

        private void AddToSale(string itemName, int quantity, decimal price, string category,
            string? itemCodeOverride = null, string? variationIdOverride = null, string? itemDescriptionOverride = null,
            bool preserveProvidedPrice = false)
        {
            // Compute total after resolving price (promo or regular) below

            string finalCategory = category;
            if (string.IsNullOrWhiteSpace(category))
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    SqlCommand cmd;
                    if (!string.IsNullOrWhiteSpace(itemCodeOverride))
                    {
                        cmd = new SqlCommand("SELECT CategoryCode FROM Items WHERE Code = @itemCode", connection);
                        cmd.Parameters.AddWithValue("@itemCode", itemCodeOverride);
                    }
                    else
                    {
                        cmd = new SqlCommand("SELECT CategoryCode FROM Items WHERE Name = @itemName", connection);
                        cmd.Parameters.AddWithValue("@itemName", itemName);
                    }
                    var result = cmd.ExecuteScalar();
                    if (result != null)
                        finalCategory = result.ToString() ?? "";
                }
            }
            //MessageBox.Show($"1category = {category} finalCategory = {finalCategory}");
            // Fetch item description, code and prices from database. Prefer PromoPrice when available (>0).
            string itemDescription = string.IsNullOrWhiteSpace(itemDescriptionOverride) ? itemName : itemDescriptionOverride;
            string itemCode = string.IsNullOrWhiteSpace(itemCodeOverride) ? "CUSTOM" : itemCodeOverride;
            string variationId = variationIdOverride ?? string.Empty;
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    SqlCommand cmd;
                    if (!string.IsNullOrWhiteSpace(itemCodeOverride))
                    {
                        cmd = new SqlCommand("SELECT Code, Description, Price, PromoPrice, VariationId FROM Items WHERE Code = @itemCode", connection);
                        cmd.Parameters.AddWithValue("@itemCode", itemCodeOverride);
                    }
                    else
                    {
                        cmd = new SqlCommand("SELECT Code, Description, Price, PromoPrice, VariationId FROM Items WHERE Name = @itemName", connection);
                        cmd.Parameters.AddWithValue("@itemName", itemName);
                    }
                    using (var reader = cmd.ExecuteReader())
                    {
                        if (reader.Read())
                        {
                            itemCode = reader["Code"].ToString() ?? "";
                            if (string.IsNullOrWhiteSpace(itemDescriptionOverride))
                                itemDescription = reader["Description"].ToString() ?? "";
                            if (string.IsNullOrWhiteSpace(variationId))
                                variationId = reader["VariationId"]?.ToString() ?? string.Empty;

                            // Determine price to use: prefer PromoPrice if present and > 0, otherwise use db Price if > 0, otherwise fallback to provided price
                            decimal dbPrice = reader["Price"] != DBNull.Value ? Convert.ToDecimal(reader["Price"]) : 0m;
                            decimal dbPromo = 0m;
                            try
                            {
                                int promoIdx = reader.GetOrdinal("PromoPrice");
                                if (promoIdx >= 0 && reader[promoIdx] != DBNull.Value)
                                    dbPromo = Convert.ToDecimal(reader[promoIdx]);
                            }
                            catch { /* PromoPrice column may not exist in older DBs - ignore */ }

                            if (!preserveProvidedPrice)
                            {
                                if (dbPromo > 0)
                                    price = dbPromo;
                                else if (dbPrice > 0)
                                    price = dbPrice;
                            }
                        }
                    }
                }
            }
            catch
            {
                // If DB read fails, fall back to supplied price parameter
            }

            bool shouldResolveCustomCatalogVariation = ShouldResolveCustomAquariumCatalogVariation(finalCategory);
            if (shouldResolveCustomCatalogVariation)
            {
                string resolvedCustomVariationId = ResolveCustomAquariumCatalogVariationId(finalCategory);
                if (!string.IsNullOrWhiteSpace(resolvedCustomVariationId))
                {
                    variationId = resolvedCustomVariationId;
                }
            }

            if (string.IsNullOrWhiteSpace(variationId) && !shouldResolveCustomCatalogVariation)
            {
                if ((itemDescription ?? string.Empty).IndexOf("Sticker Background", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    variationId = ResolveItemMasterVariationIdByAliases(
                        "CUSTOM-STICKER",
                        "CUSTOM STICKER",
                        "MANUAL-STICKER",
                        "Manual Sticker");
                }
                else if ((itemDescription ?? string.Empty).IndexOf("Sticker Bottom", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    variationId = ResolveItemMasterVariationIdByAliases(
                        "CUSTOM-STICKER",
                        "CUSTOM STICKER",
                        "MANUAL-STICKER",
                        "Manual Sticker");
                }
            }

            if (string.IsNullOrWhiteSpace(variationId) && !shouldResolveCustomCatalogVariation)
            {
                variationId = ResolveSaleLineVariationFallback(itemCode, itemName, itemDescription);
            }

            // Compute total now that price may have been updated from DB (PromoPrice)
            decimal total = quantity * price;

            // Convert values to ASCII-only strings for printing/display
            string displayDescription = FunctionEvents.ToAscii(itemDescription ?? string.Empty);
            string displayCategory = FunctionEvents.ToAscii(finalCategory ?? "");
            string displayCode = FunctionEvents.ToAscii(itemCode ?? "");
            string displayVariationId = FunctionEvents.ToAscii(variationId ?? string.Empty);

            if (IsManagedAquariumSetItem(finalCategory, itemCode, variationId, itemName))
            {
                ShowAquariumSetEntryPointMessage();
                return;
            }

            if (ShouldRequireAquariumSerialSelection(finalCategory, itemCode))
            {
                string serialTrackedItemCode = itemCode ?? string.Empty;
                var selectedSerials = PromptForAquariumSaleSerials(serialTrackedItemCode, variationId, itemDescription, quantity);
                if (selectedSerials == null)
                {
                    return;
                }

                if (selectedSerials.Count == 0)
                {
                    AddSaleLine(itemName, quantity, price, finalCategory, itemCode, variationId, itemDescription, string.Empty);
                    return;
                }

                AddSaleLine(itemName, quantity, price, finalCategory, itemCode, variationId, itemDescription, JoinSaleSerialNumbers(selectedSerials.Select(serial => serial.SerialNo)));

                return;
            }

            AddSaleLine(itemName, quantity, price, finalCategory, itemCode, variationId, itemDescription, string.Empty);
        }

        private bool ShouldRequireAquariumSerialSelection(string? categoryCode, string? itemCode)
        {
            string normalizedCategory = categoryCode?.Trim() ?? string.Empty;
            string normalizedItemCode = itemCode?.Trim() ?? string.Empty;

            if (string.IsNullOrWhiteSpace(normalizedItemCode))
            {
                return false;
            }

            // Item-code prefixes stay as a safety net for items whose Category field is blank or
            // mismatched but are still clearly aquarium-type builds. The category name allowlist
            // this used to be (AQUARIUM/STAND/SUMP only) is now driven by the same
            // Category.IsProductionCategory flag Stock Counts and Transfer Order Ship-time serial
            // tagging already use (toggled from the Web Portal's Category Setup screen) - as of
            // this fix, all three surfaces agree on which categories are serial-tracked, instead
            // of this one being stuck on a separate hardcoded list that never picked up categories
            // like Divider added after the fact.
            return normalizedItemCode.StartsWith("AQ-", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("CUSTOM-", StringComparison.OrdinalIgnoreCase)
                || normalizedItemCode.StartsWith("CUSTOM_", StringComparison.OrdinalIgnoreCase)
                || IsProductionCategoryCode(normalizedCategory);
        }

        private bool IsProductionCategoryCode(string? categoryCode)
        {
            string normalizedCategory = categoryCode?.Trim() ?? string.Empty;
            if (string.IsNullOrWhiteSpace(normalizedCategory))
            {
                return false;
            }

            try
            {
                using var connection = new SqlConnection(connectionString);
                connection.Open();
                using var command = new SqlCommand(
                    "SELECT ISNULL(IsProductionCategory, 0) FROM dbo.Category WHERE Code = @Code", connection);
                command.Parameters.AddWithValue("@Code", normalizedCategory);
                object? result = command.ExecuteScalar();
                return result != null && result != DBNull.Value && Convert.ToBoolean(result);
            }
            catch
            {
                return false;
            }
        }

        private bool ShouldResolveCustomAquariumCatalogVariation(string? categoryCode)
        {
            string normalizedCategory = categoryCode?.Trim() ?? string.Empty;
            if (string.IsNullOrWhiteSpace(normalizedCategory))
            {
                return false;
            }

            return string.Equals(normalizedCategory, "CUSTOM-AQUARIUM", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalizedCategory, "CUSTOM-SUMP", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalizedCategory, "CUSTOM-MEDIAS", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalizedCategory, "CUSTOM-OVERFLOWBOX", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalizedCategory, "CUSTOM-PIPINGS", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalizedCategory, "CUSTOM-STAND", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalizedCategory, "CUSTOM-TOPCOVER", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalizedCategory, "CUSTOM-STICKER", StringComparison.OrdinalIgnoreCase);
        }

        private string ResolveCustomAquariumCatalogVariationId(string? categoryCode)
        {
            string mappedItemName = ResolveCustomAquariumCatalogItemName(categoryCode);
            if (string.IsNullOrWhiteSpace(mappedItemName))
            {
                return string.Empty;
            }

            try
            {
                using var connection = new SqlConnection(connectionString);
                connection.Open();
                                string categoryAlias = (categoryCode ?? string.Empty).Trim().Replace('-', ' ');

                                using var command = new SqlCommand(@"
SELECT TOP 1 ISNULL(VariationId, '')
FROM dbo.Items
WHERE ISNULL(VariationId, '') <> ''
    AND (
                CategoryCode = @CategoryCode
                OR CategoryCode = 'CUSTOMIZED ITEM'
                OR CategoryCode = 'CUSTOMIZED-ITEM'
            )
  AND (
        Name = @MappedItemName
        OR Description = @MappedItemName
                OR Name = @CategoryCode
                OR Description = @CategoryCode
                OR Name = @CategoryAlias
                OR Description = @CategoryAlias
        OR Code = @CategoryCode
      )
ORDER BY
    CASE
                WHEN CategoryCode = @CategoryCode THEN 0
                WHEN CategoryCode = 'CUSTOMIZED ITEM' THEN 1
                WHEN CategoryCode = 'CUSTOMIZED-ITEM' THEN 2
        WHEN Name = @MappedItemName THEN 0
                WHEN Description = @MappedItemName THEN 1
                WHEN Name = @CategoryCode THEN 2
                WHEN Description = @CategoryCode THEN 3
                WHEN Name = @CategoryAlias THEN 4
                WHEN Description = @CategoryAlias THEN 5
                WHEN Code = @CategoryCode THEN 6
                ELSE 7
    END,
    Code", connection);

                command.Parameters.AddWithValue("@CategoryCode", categoryCode?.Trim() ?? string.Empty);
                command.Parameters.AddWithValue("@MappedItemName", mappedItemName);
                                command.Parameters.AddWithValue("@CategoryAlias", categoryAlias);

                var result = command.ExecuteScalar();
                string resolvedFromItems = result == null || result == DBNull.Value ? string.Empty : (result.ToString()?.Trim() ?? string.Empty);
                if (!string.IsNullOrWhiteSpace(resolvedFromItems))
                {
                    return resolvedFromItems;
                }

                using var variantCommand = new SqlCommand(@"
SELECT TOP 1 ISNULL(VariationId, '')
FROM dbo.[Variant]
WHERE ISNULL(VariationId, '') <> ''
  AND (
        MainItemCode = @CategoryCode
        OR ItemCode = @CategoryCode
        OR CategoryCode = @CategoryCode
      )
ORDER BY
    CASE
        WHEN MainItemCode = @CategoryCode THEN 0
        WHEN ItemCode = @CategoryCode THEN 1
        WHEN CategoryCode = @CategoryCode THEN 2
            ELSE 3
    END,
    VariationId", connection);

                variantCommand.Parameters.AddWithValue("@CategoryCode", categoryCode?.Trim() ?? string.Empty);
                variantCommand.Parameters.AddWithValue("@MappedItemName", mappedItemName);
                variantCommand.Parameters.AddWithValue("@CategoryAlias", categoryAlias);

                var variantResult = variantCommand.ExecuteScalar();
                return variantResult == null || variantResult == DBNull.Value ? string.Empty : (variantResult.ToString()?.Trim() ?? string.Empty);
            }
            catch
            {
                return string.Empty;
            }
        }

        private string ResolveSaleLineVariationFallback(string? itemCode, string? itemName, string? itemDescription)
        {
            string normalizedItemCode = itemCode?.Trim() ?? string.Empty;
            string normalizedItemName = itemName?.Trim() ?? string.Empty;
            string normalizedItemDescription = itemDescription?.Trim() ?? string.Empty;

            try
            {
                using var connection = new SqlConnection(connectionString);
                connection.Open();

                string resolvedItemName = string.Empty;
                string codeAlias = normalizedItemCode.Replace('-', ' ');

                // Step 1: Use Item Master Code to resolve canonical Item Name.
                if (!string.IsNullOrWhiteSpace(normalizedItemCode))
                {
                    using var nameCommand = new SqlCommand(@"
SELECT TOP 1 ISNULL(Name, '')
FROM dbo.Items
WHERE Code = @Code", connection);
                    nameCommand.Parameters.AddWithValue("@Code", normalizedItemCode);

                    var nameResult = nameCommand.ExecuteScalar();
                    if (nameResult != null && nameResult != DBNull.Value)
                    {
                        resolvedItemName = nameResult.ToString()?.Trim() ?? string.Empty;
                    }
                }

                if (string.IsNullOrWhiteSpace(resolvedItemName))
                {
                    resolvedItemName = !string.IsNullOrWhiteSpace(normalizedItemName)
                        ? normalizedItemName
                        : normalizedItemDescription;
                }

                // Step 2: Use resolved Item Name to find VariationId.
                if (!string.IsNullOrWhiteSpace(resolvedItemName))
                {
                    using var variationByNameCommand = new SqlCommand(@"
SELECT TOP 1 ISNULL(VariationId, '')
FROM dbo.Items
WHERE ISNULL(VariationId, '') <> ''
  AND (
        Name = @ResolvedName
        OR Description = @ResolvedName
                                OR Name = @CodeAlias
                                OR Description = @CodeAlias
                                OR Name = @CodeAliasSpace
                                OR Description = @CodeAliasSpace
        OR Code = @ResolvedName
      )
ORDER BY
    CASE
        WHEN Name = @ResolvedName THEN 0
        WHEN Description = @ResolvedName THEN 1
                                WHEN Name = @CodeAlias THEN 2
                                WHEN Description = @CodeAlias THEN 3
                                WHEN Name = @CodeAliasSpace THEN 4
                                WHEN Description = @CodeAliasSpace THEN 5
                                WHEN Code = @ResolvedName THEN 6
                                ELSE 7
    END,
    Code", connection);
                    variationByNameCommand.Parameters.AddWithValue("@ResolvedName", resolvedItemName);
                                        variationByNameCommand.Parameters.AddWithValue("@CodeAlias", normalizedItemCode);
                                        variationByNameCommand.Parameters.AddWithValue("@CodeAliasSpace", codeAlias);

                    var variationByName = variationByNameCommand.ExecuteScalar();
                    if (variationByName != null && variationByName != DBNull.Value)
                    {
                        string resolvedVariation = variationByName.ToString()?.Trim() ?? string.Empty;
                        if (!string.IsNullOrWhiteSpace(resolvedVariation))
                        {
                            return resolvedVariation;
                        }
                    }
                }

                // Fallback: direct lookup by code if name-based resolution fails.
                if (!string.IsNullOrWhiteSpace(normalizedItemCode))
                {
                    using var variationByCodeCommand = new SqlCommand(@"
SELECT TOP 1 ISNULL(VariationId, '')
FROM dbo.Items
WHERE Code = @Code
  AND ISNULL(VariationId, '') <> ''", connection);
                    variationByCodeCommand.Parameters.AddWithValue("@Code", normalizedItemCode);

                    var variationByCode = variationByCodeCommand.ExecuteScalar();
                    if (variationByCode != null && variationByCode != DBNull.Value)
                    {
                        string resolvedVariation = variationByCode.ToString()?.Trim() ?? string.Empty;
                        if (!string.IsNullOrWhiteSpace(resolvedVariation))
                        {
                            return resolvedVariation;
                        }
                    }
                }

                // Final fallback: Variant table by resolved item identity or code.
                using var variantFallbackCommand = new SqlCommand(@"
SELECT TOP 1 ISNULL(VariationId, '')
FROM dbo.[Variant]
WHERE ISNULL(VariationId, '') <> ''
  AND (
        MainItemCode = @Code
        OR ItemCode = @Code
        OR CategoryCode = @Code
        OR VariantName = @Code
        OR VariantName = @CodeAliasSpace
        OR VariantName = @ResolvedName
      )
ORDER BY
    CASE
        WHEN MainItemCode = @Code THEN 0
        WHEN ItemCode = @Code THEN 1
        WHEN CategoryCode = @Code THEN 2
        WHEN VariantName = @Code THEN 3
        WHEN VariantName = @CodeAliasSpace THEN 4
        WHEN VariantName = @ResolvedName THEN 5
        ELSE 6
    END,
    VariationId", connection);
                variantFallbackCommand.Parameters.AddWithValue("@Code", normalizedItemCode);
        variantFallbackCommand.Parameters.AddWithValue("@CodeAliasSpace", codeAlias);
                variantFallbackCommand.Parameters.AddWithValue("@ResolvedName", resolvedItemName);

                var variantFallback = variantFallbackCommand.ExecuteScalar();
                if (variantFallback != null && variantFallback != DBNull.Value)
                {
                    return variantFallback.ToString()?.Trim() ?? string.Empty;
                }
            }
            catch
            {
                // Keep sale flow resilient if fallback lookup fails.
            }

            return string.Empty;
        }

        private string ResolveItemMasterVariationIdByAliases(params string[] aliases)
        {
            var normalizedAliases = aliases
                .Where(alias => !string.IsNullOrWhiteSpace(alias))
                .Select(alias => alias.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (normalizedAliases.Count == 0)
            {
                return string.Empty;
            }

            try
            {
                using var connection = new SqlConnection(connectionString);
                connection.Open();

                using var command = new SqlCommand();
                command.Connection = connection;

                var aliasParameters = new List<string>();
                for (int index = 0; index < normalizedAliases.Count; index++)
                {
                    string parameterName = $"@Alias{index}";
                    aliasParameters.Add(parameterName);
                    command.Parameters.AddWithValue(parameterName, normalizedAliases[index]);
                }

                command.CommandText = $@"
SELECT TOP 1 ISNULL(VariationId, '')
FROM dbo.Items
WHERE ISNULL(VariationId, '') <> ''
  AND (
        Code IN ({string.Join(", ", aliasParameters)})
        OR Name IN ({string.Join(", ", aliasParameters)})
        OR Description IN ({string.Join(", ", aliasParameters)})
      )
ORDER BY Code";

                var result = command.ExecuteScalar();
                if (result != null && result != DBNull.Value)
                {
                    return result.ToString()?.Trim() ?? string.Empty;
                }
            }
            catch
            {
                // Leave fallback empty so the normal resolution path can continue.
            }

            return string.Empty;
        }

        private static string ResolveCustomAquariumCatalogItemName(string? categoryCode)
        {
            string normalizedCategory = categoryCode?.Trim() ?? string.Empty;
            if (string.IsNullOrWhiteSpace(normalizedCategory))
            {
                return string.Empty;
            }

            if (string.Equals(normalizedCategory, "CUSTOM-AQUARIUM", StringComparison.OrdinalIgnoreCase))
                return "Custom Aquarium";

            if (string.Equals(normalizedCategory, "CUSTOM-SUMP", StringComparison.OrdinalIgnoreCase))
                return "Custom Sump";

            if (string.Equals(normalizedCategory, "CUSTOM-MEDIAS", StringComparison.OrdinalIgnoreCase))
                return "Custom Medias";

            if (string.Equals(normalizedCategory, "CUSTOM-OVERFLOWBOX", StringComparison.OrdinalIgnoreCase))
                return "Custom Overflow Box";

            if (string.Equals(normalizedCategory, "CUSTOM-PIPINGS", StringComparison.OrdinalIgnoreCase))
                return "Custom Pipings";

            if (string.Equals(normalizedCategory, "CUSTOM-STAND", StringComparison.OrdinalIgnoreCase))
                return "Custom Stand";

            if (string.Equals(normalizedCategory, "CUSTOM-TOPCOVER", StringComparison.OrdinalIgnoreCase))
                return "Custom TopCover";

            if (string.Equals(normalizedCategory, "CUSTOM-STICKER", StringComparison.OrdinalIgnoreCase))
                return "Custom Sticker";

            return string.Empty;
        }

        private string ResolveCustomAquariumCalculatorCategory(string? description, string? itemCode)
        {
            EnsureCustomAquariumCalculatorCategories();

            string upperDescription = (description ?? string.Empty).Trim().ToUpperInvariant();
            string normalizedItemCode = (itemCode ?? string.Empty).Trim().ToUpperInvariant();
            bool containsSumpHint = upperDescription.Contains("SUMP")
                || normalizedItemCode.Contains("SUMP")
                || string.Equals(normalizedItemCode, "CUSTOM-SUMP", StringComparison.OrdinalIgnoreCase)
                || string.Equals(normalizedItemCode, "CUSTOM_SUMP", StringComparison.OrdinalIgnoreCase);
            bool containsMediasHint = upperDescription.Contains("MEDIAS")
                || upperDescription.Contains("MEDIA")
                || normalizedItemCode.Contains("MEDIAS")
                || normalizedItemCode.Contains("MEDIA")
                || string.Equals(normalizedItemCode, "CUSTOM-MEDIAS", StringComparison.OrdinalIgnoreCase);
            bool isFilterMediasLine = upperDescription.Contains("FILTER MEDIAS") || upperDescription.Contains("FILTER MEDIA");
            bool isOverflowLine = upperDescription.Contains("OVERFLOW BOX") || upperDescription.Contains("OVERFLOWBOX")
                || upperDescription.Contains("OVERFLOX BOX") || upperDescription.Contains("OVERFLOXBOX");
            bool isPipingLine = upperDescription.Contains("SET OF PIPING") || upperDescription.Contains("SET OF PIPINGS");

            if (upperDescription.Contains("AQUARIUM BUILD"))
            {
                return "CUSTOM-AQUARIUM";
            }

            if (upperDescription.Contains("STAND"))
            {
                return "CUSTOM-STAND";
            }

            if (containsSumpHint && isFilterMediasLine)
            {
                return "CUSTOM-MEDIAS";
            }

            if (containsSumpHint && isPipingLine)
            {
                return "CUSTOM-PIPINGS";
            }

            if ((containsMediasHint || upperDescription.Contains("OVERFLO")) && isOverflowLine)
            {
                return "CUSTOM-OVERFLOWBOX";
            }

            if (containsSumpHint)
            {
                return "CUSTOM-SUMP";
            }

            if (upperDescription.Contains("ALLUM TOP COVER") || upperDescription.Contains("ALLUM TOPCOVER")
                || upperDescription.Contains("TOP COVER") || upperDescription.Contains("TOPCOVER"))
            {
                return "CUSTOM-TOPCOVER";
            }

            if (upperDescription.Contains("STICKER BOTTOM"))
            {
                return "CUSTOM-STICKER";
            }

            if (upperDescription.Contains("STICKER"))
            {
                return "CUSTOM-STICKER";
            }

            if (isFilterMediasLine)
            {
                return "CUSTOM-MEDIAS";
            }

            if (isOverflowLine)
            {
                return "CUSTOM-OVERFLOWBOX";
            }

            if (isPipingLine)
            {
                return "CUSTOM-PIPINGS";
            }

            return string.IsNullOrWhiteSpace(normalizedItemCode) ? "AQUARIUM" : string.Empty;
        }

        private void EnsureCustomAquariumCalculatorCategories()
        {
            try
            {
                using var connection = new SqlConnection(connectionString);
                connection.Open();

                using (var createTableCmd = new SqlCommand(@"
IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'Category')
BEGIN
    CREATE TABLE Category (
        Code NVARCHAR(50) PRIMARY KEY,
        Description NVARCHAR(255) NOT NULL,
        WholeSale BIT NOT NULL CONSTRAINT DF_Category_WholeSale_CustomAquarium DEFAULT(0),
        DisableChangePrice BIT NOT NULL CONSTRAINT DF_Category_DisableChangePrice_CustomAquarium DEFAULT(0),
        IsProductionCategory BIT NOT NULL CONSTRAINT DF_Category_IsProductionCategory_CustomAquarium DEFAULT(0),
        ShowInMainPos BIT NOT NULL CONSTRAINT DF_Category_ShowInMainPos_CustomAquarium DEFAULT(1),
        ExcludeOnInventoryReport BIT NOT NULL CONSTRAINT DF_Category_ExcludeOnInventoryReport_CustomAquarium DEFAULT(0),
        CreatedDate DATETIME2 DEFAULT GETDATE(),
        UpdatedDate DATETIME2 DEFAULT GETDATE()
    )
END", connection))
                {
                    createTableCmd.ExecuteNonQuery();
                }

                var categories = new (string Code, string Description)[]
                {
                    ("CUSTOM-AQUARIUM", "Custom Aquarium"),
                    ("CUSTOM-SUMP", "Custom Sump"),
                    ("CUSTOM-MEDIAS", "Custom Medias"),
                    ("CUSTOM-OVERFLOWBOX", "Custom Overflow Box"),
                    ("CUSTOM-PIPINGS", "Custom Pipings"),
                    ("CUSTOM-STAND", "Custom Stand"),
                    ("CUSTOM-TOPCOVER", "Custom TopCover"),
                    ("CUSTOM-STICKER", "Custom Sticker")
                };

                foreach (var category in categories)
                {
                    using var ensureCmd = new SqlCommand(@"
IF NOT EXISTS (SELECT 1 FROM Category WHERE Code = @code)
BEGIN
    INSERT INTO Category (Code, Description) VALUES (@code, @description)
END", connection);
                    ensureCmd.Parameters.AddWithValue("@code", category.Code);
                    ensureCmd.Parameters.AddWithValue("@description", category.Description);
                    ensureCmd.ExecuteNonQuery();
                }
            }
            catch
            {
                // Keep calculator flow usable even if category maintenance is unavailable.
            }
        }

        private List<ProductSerialTrackingForm.AvailableSerialRecord>? PromptForAquariumSaleSerials(string itemCode, string? variantCode, string? itemDescription, int quantity, IEnumerable<string>? additionalExcludedSerialNumbers = null)
        {
            // Previously skipped entirely at non-production warehouses (borrowing the same gate
            // label printing uses) - but a non-production store can genuinely have real, available
            // serials sitting locally now that Transfer Order receiving moves them to
            // Status='IN_STOCK' at the destination store (see releaseReceivedSerials in
            // transferOrders.js / SyncItemSerialTrackingFromSupabaseAsync). Skipping the picker
            // there meant a sold unit's serial never got marked SOLD. Per direct instruction,
            // non-production stores now go through the exact same required picker as production
            // warehouses - GetAvailableSerials below already only looks at *this* item/variant's
            // locally-known serials, not a warehouse-scoped view, so this doesn't risk offering a
            // serial that's still sitting at a different store.
            int requiredQuantity = Math.Max(1, quantity);
            var serialsAlreadyInSale = GetSelectedSaleSerialNumbers();
            foreach (string excludedSerialNo in additionalExcludedSerialNumbers ?? Enumerable.Empty<string>())
            {
                string normalizedExcludedSerialNo = excludedSerialNo?.Trim() ?? string.Empty;
                if (!string.IsNullOrWhiteSpace(normalizedExcludedSerialNo))
                {
                    serialsAlreadyInSale.Add(normalizedExcludedSerialNo);
                }
            }

            string normalizedVariantCode = variantCode?.Trim() ?? string.Empty;
            var availableSerials = ProductSerialTrackingForm.GetAvailableSerials(itemCode, normalizedVariantCode, serialsAlreadyInSale);

            // Non-production stores never mint new serials (CreateSerialRecords is production-only),
            // so there's no shortfall fallback for them - per "every normal sale needs a serial 1:1;
            // if there aren't enough, that means there's no stock, and the customer should be routed
            // to an Advance Order instead." Made-to-order custom builds already only ever go through
            // Advance Order at non-production stores (never a regular sale there), so this can't block
            // a build that hasn't been made yet - it only blocks selling more real catalog stock than
            // is actually on hand and tagged. Production warehouses are unaffected - unchanged below.
            if (availableSerials.Count < requiredQuantity && !IsCurrentWarehouseProductionForLabels())
            {
                MessageBox.Show(this,
                    string.IsNullOrWhiteSpace(normalizedVariantCode)
                        ? $"Only {availableSerials.Count} serial-tracked unit(s) are available for {itemCode}, but {requiredQuantity} were requested. This store can't sell more than what's physically in stock and tagged - place an Advance Order for the shortfall instead."
                        : $"Only {availableSerials.Count} serial-tracked unit(s) are available for {itemCode} variant {normalizedVariantCode}, but {requiredQuantity} were requested. This store can't sell more than what's physically in stock and tagged - place an Advance Order for the shortfall instead.",
                    "Insufficient Stock",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Warning);
                return null;
            }

            if (availableSerials.Count == 0)
            {
                return new List<ProductSerialTrackingForm.AvailableSerialRecord>();
            }

            if (availableSerials.Count < requiredQuantity)
            {
                MessageBox.Show(this,
                    string.IsNullOrWhiteSpace(normalizedVariantCode)
                        ? $"Only {availableSerials.Count} serial-tracked unit(s) are available for {itemCode}, but {requiredQuantity} were requested. The remaining quantity will be auto-generated after posting."
                        : $"Only {availableSerials.Count} serial-tracked unit(s) are available for {itemCode} variant {normalizedVariantCode}, but {requiredQuantity} were requested. The remaining quantity will be auto-generated after posting.",
                    "Serial Tracking",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Warning);
                requiredQuantity = availableSerials.Count;
            }

            var selectedSerials = new List<ProductSerialTrackingForm.AvailableSerialRecord>();
            for (int index = 0; index < requiredQuantity; index++)
            {
                var remainingOptions = availableSerials
                    .Where(option => !selectedSerials.Any(selected => string.Equals(selected.SerialNo, option.SerialNo, StringComparison.OrdinalIgnoreCase)))
                    .ToList();

                var selectedSerial = PromptForAquariumSaleSerial(itemCode, normalizedVariantCode, itemDescription, index + 1, requiredQuantity, remainingOptions);
                if (selectedSerial == null)
                {
                    return null;
                }

                selectedSerials.Add(selectedSerial);
            }

            return selectedSerials;
        }

        private ProductSerialTrackingForm.AvailableSerialRecord? PromptForAquariumSaleSerial(
            string itemCode,
            string? variantCode,
            string? itemDescription,
            int selectionIndex,
            int totalSelections,
            List<ProductSerialTrackingForm.AvailableSerialRecord> availableSerials)
        {
            if (availableSerials == null || availableSerials.Count == 0)
            {
                return null;
            }

            using var dialog = new Form
            {
                Text = "Select Item Serial",
                StartPosition = FormStartPosition.CenterParent,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MinimizeBox = false,
                MaximizeBox = false,
                ShowInTaskbar = false,
                Size = new Size(720, 520),
                BackColor = Color.White
            };

            var titleLabel = new Label
            {
                Text = totalSelections > 1
                    ? $"Select item {selectionIndex} of {totalSelections}"
                    : "Select the item to sell",
                Location = new Point(20, 20),
                Size = new Size(660, 28),
                Font = new Font("Arial", 12, FontStyle.Bold),
                ForeColor = Color.DarkBlue
            };

            var infoLabel = new Label
            {
                Text = string.IsNullOrWhiteSpace(itemDescription)
                    ? (string.IsNullOrWhiteSpace(variantCode)
                        ? $"Choose an available serial-tracked item for {itemCode}."
                        : $"Choose an available serial-tracked item for {itemCode} variant {variantCode}.")
                    : (string.IsNullOrWhiteSpace(variantCode)
                        ? $"Choose an available serial-tracked item for {itemDescription} ({itemCode})."
                        : $"Choose an available serial-tracked item for {itemDescription} ({itemCode} / {variantCode})."),
                Location = new Point(20, 54),
                Size = new Size(660, 34),
                Font = new Font("Arial", 9, FontStyle.Regular),
                ForeColor = Color.DimGray
            };

            var listBox = new ListBox
            {
                Location = new Point(20, 96),
                Size = new Size(660, 320),
                Font = new Font("Arial", 10, FontStyle.Regular),
                DisplayMember = nameof(ProductSerialTrackingForm.AvailableSerialRecord.SerialNo)
            };

            foreach (var availableSerial in availableSerials)
            {
                listBox.Items.Add(availableSerial);
            }

            if (listBox.Items.Count > 0)
            {
                listBox.SelectedIndex = 0;
            }

            var okButton = new Button
            {
                Text = "Select",
                Location = new Point(430, 430),
                Size = new Size(120, 38),
                BackColor = Color.Green,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var cancelButton = new Button
            {
                Text = "Cancel",
                Location = new Point(560, 430),
                Size = new Size(120, 38),
                BackColor = Color.Gray,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            ProductSerialTrackingForm.AvailableSerialRecord? selectedSerial = null;
            okButton.Click += (_, _) =>
            {
                if (listBox.SelectedItem is not ProductSerialTrackingForm.AvailableSerialRecord choice)
                {
                    MessageBox.Show(dialog,
                        "Select an available serial first.",
                        "Serial Tracking",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Information);
                    return;
                }

                selectedSerial = choice;
                dialog.DialogResult = DialogResult.OK;
                dialog.Close();
            };

            cancelButton.Click += (_, _) =>
            {
                dialog.DialogResult = DialogResult.Cancel;
                dialog.Close();
            };

            listBox.DoubleClick += (_, _) =>
            {
                okButton.PerformClick();
            };

            dialog.AcceptButton = okButton;
            dialog.CancelButton = cancelButton;
            dialog.Controls.Add(titleLabel);
            dialog.Controls.Add(infoLabel);
            dialog.Controls.Add(listBox);
            dialog.Controls.Add(okButton);
            dialog.Controls.Add(cancelButton);

            return dialog.ShowDialog(this) == DialogResult.OK ? selectedSerial : null;
        }

        private static string RemoveSerialTagFromSaleDescription(string? itemDescription)
        {
            string description = itemDescription?.Trim() ?? string.Empty;
            if (string.IsNullOrWhiteSpace(description))
            {
                return string.Empty;
            }

            int serialTagIndex = description.IndexOf("| Serial No:", StringComparison.OrdinalIgnoreCase);
            if (serialTagIndex >= 0)
            {
                return description.Substring(0, serialTagIndex).Trim();
            }

            return description;
        }

        private static List<string> ParseSaleSerialNumbers(string? serialNumbersText)
        {
            return (serialNumbersText ?? string.Empty)
                .Split(new[] { SaleSerialDelimiter }, StringSplitOptions.RemoveEmptyEntries)
                .Select(serialNo => serialNo.Trim())
                .Where(serialNo => !string.IsNullOrWhiteSpace(serialNo))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static string JoinSaleSerialNumbers(IEnumerable<string>? serialNumbers)
        {
            return string.Join(SaleSerialDelimiter, (serialNumbers ?? Enumerable.Empty<string>())
                .Select(serialNo => serialNo?.Trim() ?? string.Empty)
                .Where(serialNo => !string.IsNullOrWhiteSpace(serialNo))
                .Distinct(StringComparer.OrdinalIgnoreCase));
        }

        private HashSet<string> GetSelectedSaleSerialNumbers()
        {
            var serialNumbers = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (salesListView == null)
            {
                return serialNumbers;
            }

            foreach (ListViewItem saleItem in salesListView.Items)
            {
                if (saleItem.SubItems.Count <= 7)
                {
                    continue;
                }

                foreach (string serialNo in ParseSaleSerialNumbers(saleItem.SubItems[7].Text))
                {
                    serialNumbers.Add(serialNo);
                }
            }

            return serialNumbers;
        }

        private List<(string ItemCode, string VariationId, string Description, int Count)> GetSaleLinesMissingAquariumSerials()
        {
            var lines = new List<(string ItemCode, string VariationId, string Description, int Count)>();
            if (salesListView == null)
            {
                return lines;
            }

            foreach (ListViewItem saleItem in salesListView.Items)
            {
                string tag = saleItem.Tag?.ToString() ?? string.Empty;
                if (string.Equals(tag, "PAYMENT", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, "EXPENSE", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, "INCOME", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, AquariumSetDiscountTag, StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, AquariumSetAccessoryTag, StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, ReturnLineTag, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                string category = saleItem.SubItems.Count > 4 ? saleItem.SubItems[4].Text?.Trim() ?? string.Empty : string.Empty;
                string itemCode = saleItem.SubItems.Count > 5 ? saleItem.SubItems[5].Text?.Trim() ?? string.Empty : string.Empty;
                string serialNo = saleItem.SubItems.Count > 7 ? saleItem.SubItems[7].Text?.Trim() ?? string.Empty : string.Empty;
                int assignedSerialCount = ParseSaleSerialNumbers(serialNo).Count;

                if (!ShouldRequireAquariumSerialSelection(category, itemCode))
                {
                    continue;
                }

                int quantity = 0;
                _ = int.TryParse(saleItem.SubItems.Count > 1 ? saleItem.SubItems[1].Text?.Trim() ?? string.Empty : string.Empty, out quantity);
                if (quantity <= 0)
                {
                    quantity = 1;
                }

                int missingSerialCount = Math.Max(0, quantity - assignedSerialCount);
                if (missingSerialCount <= 0)
                {
                    continue;
                }

                string description = saleItem.Text?.Trim() ?? itemCode;
                if (string.IsNullOrWhiteSpace(itemCode))
                {
                    continue;
                }

                string variationId = saleItem.SubItems.Count > 6 ? saleItem.SubItems[6].Text?.Trim() ?? string.Empty : string.Empty;
                lines.Add((itemCode, variationId, description, missingSerialCount));
            }

            return lines;
        }

        private void EnsureSaleMetadataColumns()
        {
            if (salesListView == null)
            {
                return;
            }

            ColumnHeader? categoryColumn = salesListView.Columns.ContainsKey("Category")
                ? salesListView.Columns["Category"]
                : salesListView.Columns
                    .Cast<ColumnHeader>()
                    .FirstOrDefault(column => string.Equals(column.Text, "Category", StringComparison.OrdinalIgnoreCase));

            if (categoryColumn == null)
            {
                categoryColumn = salesListView.Columns.Add("Category", "Category");
                categoryColumn.Width = 140;
            }
            else
            {
                categoryColumn.Name = "Category";
                categoryColumn.Width = 140;
            }

            ColumnHeader? codeColumn = salesListView.Columns.ContainsKey("Code")
                ? salesListView.Columns["Code"]
                : salesListView.Columns
                    .Cast<ColumnHeader>()
                    .FirstOrDefault(column => string.Equals(column.Text, "Code", StringComparison.OrdinalIgnoreCase));

            if (codeColumn == null)
            {
                codeColumn = salesListView.Columns.Add("Code", "Code");
                codeColumn.Width = 0;
            }
            else
            {
                codeColumn.Name = "Code";
                codeColumn.Width = 0;
            }

            ColumnHeader? variationColumn = salesListView.Columns.ContainsKey("VariationId")
                ? salesListView.Columns["VariationId"]
                : salesListView.Columns
                    .Cast<ColumnHeader>()
                    .FirstOrDefault(column => string.Equals(column.Text, "VariationId", StringComparison.OrdinalIgnoreCase)
                        || string.Equals(column.Text, "Variation ID", StringComparison.OrdinalIgnoreCase));

            if (variationColumn == null)
            {
                variationColumn = salesListView.Columns.Add("VariationId", "Variation ID");
                variationColumn.Width = 0;
            }
            else
            {
                variationColumn.Name = "VariationId";
                variationColumn.Width = 0;
            }
        }

        private void AddSaleLine(string itemName, int quantity, decimal price, string? category, string? itemCode, string? variationId, string? itemDescription, string? serialNo)
        {
            decimal total = quantity * price;

            string displayDescription = FunctionEvents.ToAscii(itemDescription ?? string.Empty);
            string displayCategory = FunctionEvents.ToAscii(category ?? string.Empty);
            string displayCode = FunctionEvents.ToAscii(itemCode ?? string.Empty);
            string displayVariationId = FunctionEvents.ToAscii(variationId ?? string.Empty);
            string displaySerialNo = FunctionEvents.ToAscii(serialNo ?? string.Empty);

            ListViewItem item = new ListViewItem(displayDescription);
            item.SubItems.Add(quantity.ToString());
            item.SubItems.Add($"{price:F2}");
            item.SubItems.Add($"{total:F2}");
            item.SubItems.Add(displayCategory);
            item.SubItems.Add(displayCode);
            item.SubItems.Add(displayVariationId);
            item.SubItems.Add(displaySerialNo);
            item.Tag = total;

            EnsureSaleMetadataColumns();
            if (!salesListView.Columns.ContainsKey(SaleSerialNoColumnName))
            {
                var serialColumn = salesListView.Columns.Add(SaleSerialNoColumnName, "Serial No");
                serialColumn.Width = 0;
            }

            salesListView.Items.Add(item);
            currentTotal += total;
            UpdateTotal();
        }

        private static string NormalizeSaleDetailText(string? value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return string.Empty;
            }

            var parts = value
                .Replace("\r\n", "\n")
                .Replace('\r', '\n')
                .Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(part => FunctionEvents.ToAscii(part).Trim())
                .Where(part => !string.IsNullOrWhiteSpace(part))
                .ToList();

            string normalized = parts.Count > 0
                ? string.Join(" | ", parts)
                : FunctionEvents.ToAscii(value).Trim();

            while (normalized.Contains("  "))
            {
                normalized = normalized.Replace("  ", " ");
            }

            return normalized.Trim(' ', '|');
        }

        private static string BuildDetailedSaleDescription(string baseDescription, params string?[] details)
        {
            var parts = new List<string>();

            var normalizedBase = NormalizeSaleDetailText(baseDescription);
            if (!string.IsNullOrWhiteSpace(normalizedBase))
            {
                parts.Add(normalizedBase);
            }

            foreach (var detail in details)
            {
                var normalizedDetail = NormalizeSaleDetailText(detail);
                if (string.IsNullOrWhiteSpace(normalizedDetail))
                {
                    continue;
                }

                if (!parts.Any(existing => string.Equals(existing, normalizedDetail, StringComparison.OrdinalIgnoreCase)))
                {
                    parts.Add(normalizedDetail);
                }
            }

            return string.Join(" | ", parts);
        }

        private static string BuildVariantSaleDescription(string baseDescription, params string?[] variantDetails)
        {
            var parts = new List<string>();

            var normalizedBase = NormalizeSaleDetailText(baseDescription);
            if (!string.IsNullOrWhiteSpace(normalizedBase))
            {
                parts.Add(normalizedBase);
            }

            foreach (var detail in variantDetails)
            {
                var normalizedDetail = NormalizeSaleDetailText(detail);
                if (string.IsNullOrWhiteSpace(normalizedDetail))
                {
                    continue;
                }

                if (!string.IsNullOrWhiteSpace(normalizedBase))
                {
                    if (string.Equals(normalizedDetail, normalizedBase, StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    int baseIndex = normalizedDetail.IndexOf(normalizedBase, StringComparison.OrdinalIgnoreCase);
                    if (baseIndex >= 0)
                    {
                        string beforeBase = normalizedDetail.Substring(0, baseIndex).Trim(' ', '-', '|', ':');
                        string afterBase = normalizedDetail.Substring(baseIndex + normalizedBase.Length).Trim(' ', '-', '|', ':');

                        normalizedDetail = string.IsNullOrWhiteSpace(afterBase)
                            ? beforeBase
                            : (string.IsNullOrWhiteSpace(beforeBase) ? afterBase : $"{beforeBase} - {afterBase}");

                        normalizedDetail = NormalizeSaleDetailText(normalizedDetail);
                        if (string.IsNullOrWhiteSpace(normalizedDetail)
                            || string.Equals(normalizedDetail, normalizedBase, StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }
                    }
                }

                if (!parts.Any(existing => string.Equals(existing, normalizedDetail, StringComparison.OrdinalIgnoreCase)))
                {
                    parts.Add(normalizedDetail);
                }
            }

            return string.Join(" - ", parts);
        }

        private string BuildPostedSaleDetailsSummary(int maxLines = 8)
        {
            if (salesListView == null || salesListView.Items.Count == 0)
            {
                return string.Empty;
            }

            var lines = salesListView.Items.Cast<ListViewItem>()
                .Where(item =>
                {
                    var tag = item.Tag?.ToString() ?? string.Empty;
                    return !string.Equals(tag, "PAYMENT", StringComparison.OrdinalIgnoreCase)
                        && !string.Equals(tag, CardProcessingFeeTag, StringComparison.OrdinalIgnoreCase)
                        && !string.Equals(tag, "EXPENSE", StringComparison.OrdinalIgnoreCase)
                        && !string.Equals(tag, "INCOME", StringComparison.OrdinalIgnoreCase);
                })
                .Select(item => NormalizeSaleDetailText(item.Text))
                .Where(text => !string.IsNullOrWhiteSpace(text))
                .Take(maxLines)
                .ToList();

            return string.Join(" || ", lines);
        }

        private bool HasCustomAquariumSaleItems()
        {
            if (salesListView == null || salesListView.Items.Count == 0)
            {
                return false;
            }

            foreach (ListViewItem item in salesListView.Items)
            {
                string tag = item.Tag?.ToString() ?? string.Empty;
                if (string.Equals(tag, "PAYMENT", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, CardProcessingFeeTag, StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, "EXPENSE", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, "INCOME", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, ReturnLineTag, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                string category = item.SubItems.Count > 4 ? (item.SubItems[4].Text ?? string.Empty).Trim() : string.Empty;
                string code = item.SubItems.Count > 5 ? (item.SubItems[5].Text ?? string.Empty).Trim() : string.Empty;
                string description = item.Text?.Trim() ?? string.Empty;

                if (string.Equals(category, "AQUARIUM", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(code, "CUSTOM", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(code, "CUSTOM_STAND", StringComparison.OrdinalIgnoreCase)
                    || description.IndexOf("Custom Aquarium", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return true;
                }
            }

            return false;
        }

        private void QueueOnlineOrderSend(string receiptNo, string context)
        {
            if (string.IsNullOrWhiteSpace(receiptNo))
            {
                return;
            }

            _ = Task.Run(() =>
            {
                try
                {
                    var createResp = OnlinefunctionsEvents.CreateInstoreOnlineOrder(receiptNo);
                    System.Diagnostics.Debug.WriteLine($"CreateInstoreOnlineOrder ({context}) response: {createResp}");
                }
                catch (Exception ex)
                {
                    System.Diagnostics.Debug.WriteLine($"CreateInstoreOnlineOrder ({context}) failed for receipt {receiptNo}: {ex.Message}");
                }
            });
        }

        private static string AppendSaleDetailsToOrderDescription(string baseOrderDescription, string saleDetails, int maxLength = 1000)
        {
            string normalizedBase = NormalizeSaleDetailText(baseOrderDescription);
            string normalizedDetails = NormalizeSaleDetailText(saleDetails);

            if (string.IsNullOrWhiteSpace(normalizedDetails))
            {
                return normalizedBase;
            }

            string combined = string.IsNullOrWhiteSpace(normalizedBase)
                ? normalizedDetails
                : $"{normalizedBase} | Details: {normalizedDetails}";

            if (combined.Length > maxLength)
            {
                combined = combined.Substring(0, maxLength);
            }

            return combined;
        }

        private string BuildPostedOrderDescription(string baseOrderDescription)
        {
            return AppendSaleDetailsToOrderDescription(baseOrderDescription, BuildPostedSaleDetailsSummary());
        }

        private void UpdateTotal()
        {
            // If totals changed since salesperson was chosen, reset salesperson.
            // (Call early so UI updates happen in the same refresh.)
            ResetSalesPersonIfTotalsChanged();

            // Calculate discount (for now, we'll use a simple 5% discount if total > ?1000)
            // if (currentTotal > 1000)
            // {
            //     currentDiscount = currentTotal * 0.05m; // 5% discount
            // }
            // else
            // {
            //     currentDiscount = 0;
            // }

            // Calculate grand total after discount and payments
            decimal subtotalAfterDiscount = currentTotal - currentDiscount;
            grandTotal = subtotalAfterDiscount - totalPaid;

            // Update all labels
            totalLabel.Text = $"Total: {currentTotal:F2}";
            discountLabel.Text = $"Discount: -{currentDiscount:F2}";
            paymentsLabel.Text = $"Payments: -{totalPaid:F2}";
            paymentsLabel.Visible = true;
            grandTotalLabel.Text = $"Grand Total: {grandTotal:F2}";
            grandTotalLabel.ForeColor = Color.DarkRed;
            // If there are expense lines pending, change Checkout button to POST and tag accordingly
            bool hasExpense = salesListView.Items.Cast<ListViewItem>().Any(i => i.Tag?.ToString() == "EXPENSE");
            bool hasIncome = salesListView.Items.Cast<ListViewItem>().Any(i => i.Tag?.ToString() == "INCOME");
            bool hasReturn = salesListView.Items.Cast<ListViewItem>().Any(i => string.Equals(i.Tag?.ToString(), ReturnLineTag, StringComparison.OrdinalIgnoreCase));
            if (hasExpense || hasIncome)
            {
                checkoutButton.Text = "POST";
                // Only set EXPENSE_PENDING if not already a downpayment flow
                if (checkoutButton.Tag?.ToString() != "DOWNPAYMENT")
                {
                    checkoutButton.Tag = hasExpense ? "EXPENSE_PENDING" : "INCOME_PENDING";
                    checkoutButton.BackColor = hasExpense ? Color.OrangeRed : Color.DarkGreen;
                }
            }
            else
            {
                // Restore default when no expense lines
                if (checkoutButton.Tag?.ToString() != "DOWNPAYMENT")
                {
                    if (isReturnExchangeMode || hasReturn)
                    {
                        checkoutButton.Text = "CHECKOUT EXCHANGE";
                        checkoutButton.Tag = "EXCHANGE";
                        checkoutButton.BackColor = Color.Firebrick;
                    }
                    else
                    {
                        checkoutButton.Text = "CHECKOUT";
                        checkoutButton.Tag = "SALES";
                        checkoutButton.BackColor = Color.Green;
                    }
                }
            }
        }

        // Helper to safely read the numeric total from a ListViewItem (handles older numeric tags and new string tags)
        private decimal GetListViewItemTotal(ListViewItem item)
        {
            // Prefer numeric Tag when available
            if (item.Tag is decimal d)
                return d;

            if (decimal.TryParse(item.Tag?.ToString(), out decimal parsed))
                return parsed;

            // Fallback to SubItems[3] (total column) if present
            if (item.SubItems.Count > 3 && decimal.TryParse(item.SubItems[3].Text.Replace("?", ""), out decimal subTotal))
                return subTotal;

            return 0m;
        }

        private decimal GetAquariumSetPromotionTotal()
        {
            if (salesListView == null || salesListView.Items.Count == 0)
            {
                return 0m;
            }

            return salesListView.Items.Cast<ListViewItem>()
                .Where(item => string.Equals(item.Tag?.ToString(), AquariumSetDiscountTag, StringComparison.OrdinalIgnoreCase))
                .Sum(item => Math.Abs(GetListViewItemTotal(item)));
        }

        private string GetAquariumSetPromotionPackageSummary()
        {
            if (salesListView == null || salesListView.Items.Count == 0)
            {
                return string.Empty;
            }

            var packageNames = salesListView.Items.Cast<ListViewItem>()
                .Where(item => string.Equals(item.Tag?.ToString(), AquariumSetDiscountTag, StringComparison.OrdinalIgnoreCase))
                .Select(item => item.Text?.Trim() ?? string.Empty)
                .Where(text => !string.IsNullOrWhiteSpace(text))
                .Select(text => text.EndsWith(" Promotion", StringComparison.OrdinalIgnoreCase)
                    ? text.Substring(0, text.Length - " Promotion".Length).Trim()
                    : text)
                .Where(text => !string.IsNullOrWhiteSpace(text))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            return packageNames.Count == 0 ? string.Empty : string.Join(", ", packageNames);
        }

