        private void ClearButton_Click(object? sender, EventArgs e)
        {
            salesListView.Items.Clear();
            currentTotal = 0;
            currentDiscount = 0;
            currentDiscountDescription = string.Empty;
            grandTotal = 0;
            currentCustomerName = DefaultWalkInCustomerName;  // Reset customer name when clearing sale
            isReturnExchangeMode = false;
            returnExchangeOriginalReceiptNo = string.Empty;

            // Clear salesperson when clearing the sale
            currentSalesPersonCode = null;
            currentSalesPersonName = null;
            UpdateSalesPersonDisplay();

            UpdateTotal();
        }

        private void RemoveItemButton_Click(object? sender, EventArgs e)
        {
            if (salesListView.SelectedItems.Count == 0)
            {
                MessageBox.Show("Please select an item to remove.", "No Item Selected", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            ListViewItem selectedItem = salesListView.SelectedItems[0];
            if (string.Equals(selectedItem.Tag?.ToString(), CardProcessingFeeTag, StringComparison.OrdinalIgnoreCase))
            {
                MessageBox.Show("Card Processing Fee lines are managed automatically and cannot be removed manually.", "Protected Line", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            decimal itemTotal = GetListViewItemTotal(selectedItem);

            currentTotal -= itemTotal;
            salesListView.Items.Remove(selectedItem);
            UpdateTotal();
        }

        private void ChangeQuantity()
        {
            if (salesListView.SelectedItems.Count == 0)
            {
                MessageBox.Show("Please select an item to change quantity.", "No Item Selected", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            ListViewItem selectedItem = salesListView.SelectedItems[0];
            if (string.Equals(selectedItem.Tag?.ToString(), CardProcessingFeeTag, StringComparison.OrdinalIgnoreCase))
            {
                MessageBox.Show("Card Processing Fee lines are managed automatically and quantity cannot be changed.", "Protected Line", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            string itemName = selectedItem.Text;
            int currentQty = int.Parse(selectedItem.SubItems[1].Text);
            decimal unitPrice = decimal.Parse(selectedItem.SubItems[2].Text.Replace("?", ""));
            decimal currentItemTotal = GetListViewItemTotal(selectedItem);
            string categoryCode = selectedItem.SubItems.Count > 4 ? selectedItem.SubItems[4].Text?.Trim() ?? string.Empty : string.Empty;
            string itemCode = selectedItem.SubItems.Count > 5 ? selectedItem.SubItems[5].Text?.Trim() ?? string.Empty : string.Empty;
            string variationId = selectedItem.SubItems.Count > 6 ? selectedItem.SubItems[6].Text?.Trim() ?? string.Empty : string.Empty;
            string existingSerialNo = selectedItem.SubItems.Count > 7 ? selectedItem.SubItems[7].Text?.Trim() ?? string.Empty : string.Empty;
            var existingSerialNumbers = ParseSaleSerialNumbers(existingSerialNo);
            string baseDescription = RemoveSerialTagFromSaleDescription(selectedItem.Text);

            // Create quantity change dialog
            var qtyForm = new Form
            {
                Text = "Change Quantity",
                Size = new Size(350, 200),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false,
                MinimizeBox = false
            };

            var itemLabel = new Label
            {
                Text = $"Item: {itemName}",
                Location = new Point(20, 20),
                Size = new Size(300, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var currentQtyLabel = new Label
            {
                Text = $"Current Quantity: {currentQty}",
                Location = new Point(20, 50),
                Size = new Size(150, 20),
                Font = new Font("Arial", 10)
            };

            var newQtyLabel = new Label
            {
                Text = "New Quantity:",
                Location = new Point(20, 80),
                Size = new Size(100, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var qtyUpDown = new NumericUpDown
            {
                Location = new Point(130, 78),
                Size = new Size(80, 25),
                Font = new Font("Arial", 10),
                Minimum = 1, // Prevent quantity from going to 0
                Maximum = 1000,
                Value = currentQty
            };

            var updateButton = new Button
            {
                Text = "Update",
                Location = new Point(130, 120),
                Size = new Size(80, 35),
                BackColor = Color.Green,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var cancelButton = new Button
            {
                Text = "Cancel",
                Location = new Point(220, 120),
                Size = new Size(80, 35),
                BackColor = Color.Gray,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            updateButton.Click += (s, args) =>
            {
                int newQty = (int)qtyUpDown.Value;

                if (newQty == currentQty)
                {
                    qtyForm.Close();
                    return;
                }

                if (ShouldRequireAquariumSerialSelection(categoryCode, itemCode))
                {
                    if (existingSerialNumbers.Count > 0)
                    {
                        if (newQty <= existingSerialNumbers.Count)
                        {
                            decimal reducedLineTotal = newQty * unitPrice;
                            selectedItem.SubItems[1].Text = newQty.ToString();
                            selectedItem.SubItems[3].Text = $"{reducedLineTotal:F2}";
                            selectedItem.SubItems[7].Text = JoinSaleSerialNumbers(existingSerialNumbers.Take(newQty));
                            if (selectedItem.Tag is decimal || decimal.TryParse(selectedItem.Tag?.ToString(), out _))
                            {
                                selectedItem.Tag = reducedLineTotal;
                            }

                            currentTotal = currentTotal - currentItemTotal + reducedLineTotal;
                            UpdateTotal();
                            qtyForm.Close();
                            MessageBox.Show($"Quantity updated to {newQty}", "Quantity Changed", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            return;
                        }

                        int additionalQtyNeeded = Math.Max(0, newQty - existingSerialNumbers.Count);
                        if (additionalQtyNeeded > 0)
                        {
                            var selectedSerials = PromptForAquariumSaleSerials(itemCode, variationId, baseDescription, additionalQtyNeeded, existingSerialNumbers);
                            if (selectedSerials == null)
                            {
                                return;
                            }

                            decimal expandedLineTotal = newQty * unitPrice;
                            selectedItem.SubItems[1].Text = newQty.ToString();
                            selectedItem.SubItems[3].Text = $"{expandedLineTotal:F2}";
                            selectedItem.SubItems[7].Text = JoinSaleSerialNumbers(existingSerialNumbers.Concat(selectedSerials.Select(serial => serial.SerialNo)));
                            if (selectedItem.Tag is decimal || decimal.TryParse(selectedItem.Tag?.ToString(), out _))
                            {
                                selectedItem.Tag = expandedLineTotal;
                            }

                            currentTotal = currentTotal - currentItemTotal + expandedLineTotal;
                        }

                        UpdateTotal();
                        qtyForm.Close();
                        MessageBox.Show($"Quantity updated to {newQty}", "Quantity Changed", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    var rebuiltSerials = PromptForAquariumSaleSerials(itemCode, variationId, baseDescription, newQty);
                    if (rebuiltSerials == null)
                    {
                        return;
                    }

                    if (rebuiltSerials.Count > 0)
                    {
                        decimal rebuiltLineTotal = newQty * unitPrice;
                        selectedItem.SubItems[1].Text = newQty.ToString();
                        selectedItem.SubItems[3].Text = $"{rebuiltLineTotal:F2}";
                        selectedItem.SubItems[7].Text = JoinSaleSerialNumbers(rebuiltSerials.Select(serial => serial.SerialNo));
                        if (selectedItem.Tag is decimal || decimal.TryParse(selectedItem.Tag?.ToString(), out _))
                        {
                            selectedItem.Tag = rebuiltLineTotal;
                        }

                        currentTotal = currentTotal - currentItemTotal + rebuiltLineTotal;
                        UpdateTotal();

                        qtyForm.Close();
                        MessageBox.Show($"Quantity updated to {newQty}", "Quantity Changed", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }
                }

                // Calculate quantity difference for inventory adjustment
                int qtyDifference = newQty - currentQty;

                // Update the item in the list
                selectedItem.SubItems[1].Text = newQty.ToString();
                decimal newItemTotal = newQty * unitPrice;
                selectedItem.SubItems[3].Text = $"{newItemTotal:F2}";
                // Update Tag only if previously numeric; if it's an expense tag, keep tag but update subitems
                if (selectedItem.Tag is decimal || decimal.TryParse(selectedItem.Tag?.ToString(), out _))
                {
                    selectedItem.Tag = newItemTotal;
                }
                else
                {
                    // preserve special tag (e.g., "EXPENSE" or "PAYMENT") but update displayed price/total
                    selectedItem.SubItems[2].Text = unitPrice.ToString("F2");
                    selectedItem.SubItems[3].Text = newItemTotal.ToString("F2");
                }

                // Update the running total
                currentTotal = currentTotal - currentItemTotal + newItemTotal;
                UpdateTotal();

                // Note: Inventory will be updated at checkout, not here

                qtyForm.Close();
                MessageBox.Show($"Quantity updated to {newQty}", "Quantity Changed", MessageBoxButtons.OK, MessageBoxIcon.Information);
            };

            cancelButton.Click += (s, args) => qtyForm.Close();

            qtyForm.Controls.AddRange(new Control[] {
                itemLabel, currentQtyLabel, newQtyLabel, qtyUpDown, updateButton, cancelButton
            });

            qtyForm.ShowDialog();
        }

        private void ChangePrice()
