            decimal currentItemTotal = GetListViewItemTotal(selectedItem);

            var priceForm = new Form
            {
                Text = "Change Price",
                Size = new Size(380, 220),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false,
                MinimizeBox = false
            };

            var itemLabel = new Label
            {
                Text = $"Item: {itemName}",
                Location = new Point(20, 20),
                Size = new Size(320, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var currentPriceLabel = new Label
            {
                Text = $"Current Unit Price: {unitPrice:F2}",
                Location = new Point(20, 50),
                Size = new Size(320, 20),
                Font = new Font("Arial", 10)
            };

            var newPriceLabel = new Label
            {
                Text = "New Unit Price:",
                Location = new Point(20, 80),
                Size = new Size(120, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var priceNumeric = new NumericUpDown
            {
                Location = new Point(150, 78),
                Size = new Size(120, 25),
                Font = new Font("Arial", 10),
                DecimalPlaces = 2,
                Maximum = 9999999,
                Minimum = 0,
                Value = unitPrice
            };

            var updateButton = new Button
            {
                Text = "Update",
                Location = new Point(80, 130),
                Size = new Size(100, 35),
                BackColor = Color.Green,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var cancelButton = new Button
            {
                Text = "Cancel",
                Location = new Point(200, 130),
                Size = new Size(100, 35),
                BackColor = Color.Gray,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            updateButton.Click += (s, args) =>
            {
                decimal newUnitPrice = priceNumeric.Value;

                // If unchanged, close
                if (newUnitPrice == unitPrice)
                {
                    priceForm.Close();
                    return;
                }

                // Update displayed unit price and total
                selectedItem.SubItems[2].Text = newUnitPrice.ToString("F2");
                decimal newItemTotal = newUnitPrice * currentQty;
                selectedItem.SubItems[3].Text = newItemTotal.ToString("F2");

                // Update Tag only if previously numeric
                if (selectedItem.Tag is decimal || decimal.TryParse(selectedItem.Tag?.ToString(), out _))
                {
                    selectedItem.Tag = newItemTotal;
                }

                // Recalculate totals
                currentTotal = salesListView.Items.Cast<ListViewItem>().Sum(i => GetListViewItemTotal(i));
                UpdateTotal();

                priceForm.Close();
                MessageBox.Show($"Unit price updated to {newUnitPrice:F2}", "Price Changed", MessageBoxButtons.OK, MessageBoxIcon.Information);
            };

            cancelButton.Click += (s, args) => priceForm.Close();

            priceForm.Controls.AddRange(new Control[] { itemLabel, currentPriceLabel, newPriceLabel, priceNumeric, updateButton, cancelButton });
            priceForm.ShowDialog();
        }

        private bool IsChangePriceDisabledForCategory(string? categoryCode)
        {
            string normalizedCategoryCode = categoryCode?.Trim() ?? string.Empty;
            if (string.IsNullOrWhiteSpace(normalizedCategoryCode))
            {
                return false;
            }

            try
            {
                using var connection = new SqlConnection(connectionString);
                connection.Open();
                EnsureCategoryTableSchema(connection);

                using var command = new SqlCommand("SELECT ISNULL(DisableChangePrice, 0) FROM Category WHERE Code = @code", connection);
                command.Parameters.AddWithValue("@code", normalizedCategoryCode);

                object? result = command.ExecuteScalar();
                return result != null && result != DBNull.Value && Convert.ToBoolean(result);
            }
            catch
            {
                return false;
            }
        }

        private void CheckoutButton_Click(object? sender, EventArgs e)
        {
            if (salesListView.Items.Count == 0)
            {
                MessageBox.Show("No items in sale!", "Checkout", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            // Prevent checkout when any non-payment item has a zero or invalid price
            try
            {
                foreach (ListViewItem it in salesListView.Items)
                {
                    var tag = it.Tag?.ToString() ?? string.Empty;
                    if (string.Equals(tag, "PAYMENT", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(tag, CardProcessingFeeTag, StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(tag, AquariumSetDiscountTag, StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(tag, "EXPENSE", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(tag, "INCOME", StringComparison.OrdinalIgnoreCase))
                        continue;

                    if (string.Equals(it.Name, AquariumSetComponentLineMarker, StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    decimal price = 0m;
                    if (it.SubItems.Count > 2)
                    {
                        var txt = (it.SubItems[2].Text ?? string.Empty).Replace("?", "").Trim();
                        decimal.TryParse(txt, out price);
                    }

                    if (price <= 0m)
                    {
                        MessageBox.Show("Cannot checkout: one or more items have zero or invalid price. Please set a valid price before checkout.", "Invalid Item Price", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        return;
                    }
                }
            }
            catch { }

            if (isReturnExchangeMode && grandTotal <= 0m)
            {
                string message = grandTotal < 0m
                    ? $"Return credit is greater than the replacement items by {Math.Abs(grandTotal):F2}.\n\nFinalize this exchange/refund now?"
                    : "This is an even exchange.\n\nFinalize it now?";

                if (MessageBox.Show(message, "Finalize Exchange", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
                    return;

                if (string.IsNullOrWhiteSpace(currentReceiptNo))
                {
                    currentReceiptNo = GenerateCentralizedReceiptNumber();
                    currentTransNo = GetNextTransactionNoPlusOne();
                }

                CompleteSale();
                return;
            }

            // Switch to tender type selection mode
            // Force tender buttons to render even if the flag was left true by a previous flow.
            try { isInCheckoutMode = false; } catch { }
            ShowTenderTypeBottomButtons();
        }

        private void ShowTenderTypeButtons()
        {
            if (isInCheckoutMode) return;

            isInCheckoutMode = true;

            // Hide all original header buttons
            foreach (var button in originalHeaderButtons)
            {
                button.Visible = false;
            }

            // Show back button
            backButton.Visible = true;

            // Clear existing tender type buttons
            foreach (var button in tenderTypeButtons)
            {
                headerPanel.Controls.Remove(button);
            }
            tenderTypeButtons.Clear();

            // Load tender types from database and create buttons
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var command = new SqlCommand("SELECT Code, Description FROM TenderTypes ORDER BY Code", connection);
                    using (var reader = command.ExecuteReader())
                    {
                        int buttonIndex = 0;
                        int startX = 490; // Start after back button
                        int buttonWidth = 120;
                        int spacing = 10;

                        while (reader.Read())
                        {
                            string code = reader["Code"].ToString() ?? "";
                            string description = reader["Description"].ToString() ?? "";

                            var tenderButton = new Button
                            {
                                Text = description,
                                Tag = code,
                                Location = new Point(startX + buttonIndex * (buttonWidth + spacing), 10),
                                Size = new Size(buttonWidth, 35),
                                BackColor = Color.DarkGreen,
                                ForeColor = Color.White,
                                Font = new Font("Arial", 9, FontStyle.Bold)
                            };

                            // tenderButton.Click += TenderTypeButton_Click;
                            headerPanel.Controls.Add(tenderButton);
                            tenderTypeButtons.Add(tenderButton);
                            buttonIndex++;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error loading tender types: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                // Fallback to original buttons if error
                RestoreOriginalButtons();
            }
        }

        private void RestoreOriginalButtons()
        {
            if (!isInCheckoutMode) return;

            isInCheckoutMode = false;

            // Hide back button
            backButton.Visible = false;

            // Hide and remove tender type buttons
            foreach (var button in tenderTypeButtons)
            {
                headerPanel.Controls.Remove(button);
            }
            tenderTypeButtons.Clear();

            // Show original header buttons
            foreach (var button in originalHeaderButtons)
            {
                button.Visible = true;
            }
        }

        private void BackButton_Click(object? sender, EventArgs e)
        {
            RestoreOriginalBottomButtons();
            try
            {
                // Pass the owner (if any) so RevertCheckoutToSales can detect MainForm directly
                FunctionEvents.RevertCheckoutToSales(this.Owner);
            }
            catch
            {
                // swallow any UI errors to avoid breaking report printing
            }
        }

        private void ShowTenderTypeBottomButtons()
        {
            isInCheckoutMode = true;

            // Clear the button panel
            try { buttonPanel.SuspendLayout(); } catch { }
            buttonPanel.Controls.Clear();

            // Reset scroll so new buttons (placed at the top) are visible.
            try { buttonPanel.AutoScrollPosition = new Point(0, 0); } catch { }

            // Add BACK button first
            var backBtn = new Button
            {
                Text = "BACK",
                Location = new Point(10, 10),
                Size = new Size(160, 50),
                BackColor = Color.Gray,
                ForeColor = Color.White,
                Font = new Font("Arial", 12, FontStyle.Bold)
            };
            backBtn.Click += BackButton_Click;
            buttonPanel.Controls.Add(backBtn);

            // Load tender types from database and create buttons
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var command = new SqlCommand("SELECT Code, Description FROM TenderTypes ORDER BY Code", connection);
                    using (var reader = command.ExecuteReader())
                    {
                        int buttonIndex = 1; // Start from 1 since BACK button is at index 0
                        int buttonsPerRow = 7;
                        int buttonWidth = 160;
                        int buttonHeight = 50;
                        int spacing = 5;
                        int startX = 10;
                        int startY = 10;

                        while (reader.Read())
                        {
                            string code = reader["Code"].ToString() ?? "";
                            string description = reader["Description"].ToString() ?? "";

                            int row = buttonIndex / buttonsPerRow;
                            int col = buttonIndex % buttonsPerRow;

                            var tenderButton = new Button
                            {
                                Text = description,
                                Tag = code,
                                Location = new Point(startX + col * (buttonWidth + spacing), startY + row * (buttonHeight + spacing)),
                                Size = new Size(buttonWidth, buttonHeight),
                                BackColor = Color.DarkGreen,
                                ForeColor = Color.White,
                                Font = new Font("Arial", 10, FontStyle.Bold),
                                TextAlign = ContentAlignment.MiddleCenter,
                                UseVisualStyleBackColor = false
                            };

                            tenderButton.Click += TenderTypeBottomButton_Click;
                            buttonPanel.Controls.Add(tenderButton);
                            buttonIndex++;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error loading tender types: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                // Fallback to original buttons if error
                RestoreOriginalBottomButtons();
            }

            try { buttonPanel.ResumeLayout(true); } catch { }
        }

        private void RestoreOriginalBottomButtons()
        {
            if (!isInCheckoutMode) return;

            isInCheckoutMode = false;

            // Recreate the category buttons
            CreateCategoryButtons();

            // Ensure we return to the top of the grid.
            try { buttonPanel.AutoScrollPosition = new Point(0, 0); } catch { }

        }

        private void TenderTypeBottomButton_Click(object? sender, EventArgs e)
        {
            if (sender is Button button && button.Tag is string tenderCode)
            {
                if (tenderCode.Equals("ADVANCEORDERS", StringComparison.OrdinalIgnoreCase))
                {
                    using (var advanceOrdersForm = new AdvanceOrdersHeaderForm())
                    {
                        //ADVANCEORDERS EDIT
                    }
                    return;
                }

                // Show payment entry form
                decimal defaultPaymentAmount = grandTotal;
                decimal cardMarkupPercent = 0m;
                bool isCardTender = IsCreditCardTender(tenderCode, button.Text);
                if (isCardTender)
                {
                    cardMarkupPercent = LoadCardMarkupPercent();
                    defaultPaymentAmount = ApplyMarkupPercent(grandTotal, cardMarkupPercent);
                }

                using (var paymentForm = new PaymentEntryForm(button.Text, defaultPaymentAmount, isCardTender ? cardMarkupPercent : 0m))
                {
                    if (paymentForm.ShowDialog(this) == DialogResult.OK)
                    {
                        RestoreOriginalBottomButtons();

                        if (isCardTender && cardMarkupPercent > 0m)
                        {
                            decimal feeAmount = CalculateCardProcessingFeeFromChargedAmount(paymentForm.Amount, cardMarkupPercent);
                            AddOrIncreaseCardProcessingFeeLine(feeAmount);
                        }

                        // Process the checkout with entered payment details
                        ProcessCheckout(paymentForm.TenderType, tenderCode, paymentForm.Amount);
                    }
                }
            }
        }

