        private void ProcessCheckout(string tenderDescription, string tenderCode, decimal paymentAmount)
        {
            // If not in payment mode yet, initialize payment tracking
            if (!isInPaymentMode)
            {
                isInPaymentMode = true;
                currentReceiptNo = GenerateCentralizedReceiptNumber();
                currentTransNo = GetNextTransactionNoPlusOne();
                payments.Clear();
                totalPaid = 0;
                //ShowPaymentMode();
            }

            // Add this payment to the payment tracking
            AddPayment(tenderDescription, tenderCode, paymentAmount);

            // Check if payment is complete (compare against original grand total before payments)
            decimal originalGrandTotal = currentTotal - currentDiscount;
            decimal remainingBalance = originalGrandTotal - totalPaid;

            if (remainingBalance > 0)
            {
                // Partial payment - show remaining balance and allow more payments


                // MessageBox.Show(
                //     $"Partial payment recorded: ?{paymentAmount:F2}\n" +
                //     $"Total paid so far: ?{totalPaid:F2}\n" +
                //     $"Remaining balance: ?{remainingBalance:F2}\n" +
                //     $"Please select another payment method to continue.",
                //     "Partial Payment",
                //     MessageBoxButtons.OK,
                //     MessageBoxIcon.Information);

                // Payment mode continues - tender buttons will show automatically from TenderTypeButton_Click
                UpdateTotal();
                // UpdatePaymentDisplay();
                return;
            }
            else
            {
                // Full payment or overpayment - complete the sale
                // string discountText = currentDiscount > 0 ? $"\nDiscount: ?{currentDiscount:F2}" : "";
                // string changeText = remainingBalance < 0 ? $"\nChange: ?{Math.Abs(remainingBalance):F2}" : "";

                // DialogResult result = MessageBox.Show(
                //     $"Payment complete! Sale for ?{originalGrandTotal:F2}?\n" +
                //     $"Total paid: ?{totalPaid:F2}{changeText}{discountText}",
                //     "Complete Sale");

                // if (result != DialogResult.Yes)
                // {
                //     // User cancelled - remove the last payment and continue
                //     if (payments.Count > 0)
                //     {
                //         var lastPayment = payments.Last();
                //         payments.Remove(lastPayment);
                //         totalPaid -= lastPayment.Amount;

                //         // Remove from ListView
                //         if (paymentsListView.Items.Count > 0)
                //         {
                //             paymentsListView.Items.RemoveAt(paymentsListView.Items.Count - 1);
                //         }

                //         // Remove last payment from salesListView (find the last payment item and remove it)
                //         for (int i = salesListView.Items.Count - 1; i >= 0; i--)
                //         {
                //             if (salesListView.Items[i].Tag?.ToString() == "PAYMENT")
                //             {
                //                 salesListView.Items.RemoveAt(i);
                //                 break;
                //             }
                //         }

                //         UpdatePaymentDisplay();
                //     }
                //     // Payment mode continues - no need to show tender buttons explicitly
                //     return;
                // }

                // Complete the sale with all payments
                CompleteSale();
                return;
            }
        }

        private void ShowPaymentMode()
        {
            // Show payment tracking UI elements
            paymentsListView.Visible = true;
            remainingBalanceLabel.Visible = true;
            UpdatePaymentDisplay();
        }

        private void AddPayment(string tenderType, string tenderCode, decimal amount)
        {
            var payment = new PaymentEntry
            {
                TenderType = tenderType,
                TenderCode = tenderCode,
                Amount = amount,
                PaymentTime = DateTime.Now
            };

            // Add payment to the payments list
            payments.Add(payment);

            // Only add payment details to salesListView (shared for sales and payments)
            var salesPaymentItem = new ListViewItem(tenderCode); // Description = Tender Type Code
            salesPaymentItem.SubItems.Add("1"); // Qty = 1
            salesPaymentItem.SubItems.Add($"{0:F2}"); // Price = Amount Tendered 
            salesPaymentItem.SubItems.Add($"-{amount:F2}");//Total
            salesPaymentItem.ForeColor = Color.DarkGreen; // Different color for payments
            salesPaymentItem.Tag = "PAYMENT"; // Tag to identify as payment
            salesListView.Items.Add(salesPaymentItem);
            totalPaid += amount; // Use += to accumulate total paid
            UpdateTotal();

            // Note: Payment recording will happen when transaction is fully settled
        }


        /// <summary>
        /// Public wrapper used by integration code to stage a payment line on the POS UI only.
        /// This will add a PAYMENT-tagged line to the salesListView and update totals, but
        /// will not immediately persist a TransPaymentEntry row to the database.
        /// Caller should invoke this on the UI thread (or we will Invoke if called off-thread).
        /// </summary>
        /// <param name="tenderCode">Tender code to show (e.g. "ONLINE")</param>
        /// <param name="amount">Amount paid</param>
        public void StagePaymentOnUI(string tenderCode, decimal amount)
        {
            try
            {
                // If this method is called off the UI thread, marshal to UI thread
                if (this.IsHandleCreated && !this.InvokeRequired)
                {
                    AddPayment("ONLINE", tenderCode, amount);
                }
                else if (this.IsHandleCreated)
                {
                    this.Invoke(new Action(() => AddPayment("ONLINE", tenderCode, amount)));
                }
                else
                {
                    // If handle not created (unlikely), try to add directly
                    AddPayment("ONLINE", tenderCode, amount);
                }
            }
            catch { }
        }

        private void UpdatePaymentDisplay()
        {
            decimal originalGrandTotal = currentTotal - currentDiscount;
            decimal remainingBalance = originalGrandTotal - totalPaid;
            remainingBalanceLabel.Text = $"Remaining Balance: {remainingBalance:F2}";
            remainingBalanceLabel.ForeColor = remainingBalance > 0 ? Color.Red : Color.Green;

            if (remainingBalance <= 0)
            {
                remainingBalanceLabel.Text = "FULLY PAID!";
            }

            // Update the payments label in the total panel
            UpdateTotal();
        }

        private void CompleteSale()
        {
            // // Prevent checkout/post when Grand Total is zero or negative
            // if (grandTotal == 0)
            // {
            //     MessageBox.Show("Cannot complete checkout or post a sale with a Grand Total of 0.", "Invalid Total", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            //     return;
            // }
            string customerName;
            string orderDescription;
            if (isReturnExchangeMode)
            {
                customerName = string.IsNullOrWhiteSpace(currentCustomerName) ? "RETURN / EXCHANGE" : currentCustomerName;
                currentCustomerName = customerName;
                orderDescription = $"Exchange from Receipt {returnExchangeOriginalReceiptNo}";
            }
            else
            {
                customerName = FunctionEvents.PromptForCustomerName(
                    this,
                    string.IsNullOrWhiteSpace(currentCustomerName)
                        ? DefaultWalkInCustomerName
                        : currentCustomerName.Trim());

                if (string.IsNullOrEmpty(customerName))
                {
                    return;
                }

                currentCustomerName = customerName;

                // Prompt for order description after customer name
                string initialOrderDescription = string.IsNullOrWhiteSpace(pendingCustomAquariumSpecialNote)
                    ? string.Empty
                    : $"Special note: {pendingCustomAquariumSpecialNote}";
                orderDescription = FunctionEvents.PromptForOrderDescription(this, initialOrderDescription);
                if (string.IsNullOrEmpty(orderDescription))
                {
                    // Cancelled or empty
                    return;
                }
            }

            // If there's an overpayment (change) show a prominent popup so cashier acknowledges it
            try
            {
                decimal originalGrandTotal = currentTotal - currentDiscount;
                decimal remainingBalancePreview = originalGrandTotal - totalPaid;
                if (remainingBalancePreview < 0)
                {
                    decimal changeAmount = Math.Abs(remainingBalancePreview);

                    // Only show the Change Due popup when there is at least one CASH tender recorded.
                    bool hasCashPayment = false;

                    // Check payments list (in-memory tracked payments)
                    try
                    {
                        hasCashPayment = payments.Any(p => string.Equals((p.TenderCode ?? p.TenderType)?.Trim(), "CASH", StringComparison.OrdinalIgnoreCase));
                    }
                    catch { hasCashPayment = false; }

                    // Also check salesListView for any PAYMENT items that are CASH
                    if (!hasCashPayment)
                    {
                        try
                        {
                            hasCashPayment = salesListView.Items.Cast<ListViewItem>()
                                .Any(it => it.Tag?.ToString() == "PAYMENT" && string.Equals((it.Text ?? "").Trim(), "CASH", StringComparison.OrdinalIgnoreCase));
                        }
                        catch { hasCashPayment = false; }
                    }

                    if (hasCashPayment)
                    {
                        var changeForm = new Form
                        {
                            Text = "Change Due",
                            Size = new Size(560, 260),
                            StartPosition = FormStartPosition.CenterParent,
                            BackColor = Color.White,
                            FormBorderStyle = FormBorderStyle.FixedDialog,
                            MaximizeBox = false,
                            MinimizeBox = false
                        };

                        var changeLabel = new Label
                        {
                            Text = $"CHANGE DUE: P{changeAmount:F2}",
                            Dock = DockStyle.Fill,
                            TextAlign = ContentAlignment.MiddleCenter,
                            Font = new Font("Arial", 32, FontStyle.Bold),
                            ForeColor = Color.DarkRed
                        };

                        var okButton = new Button
                        {
                            Text = "ACKNOWLEDGE",
                            Dock = DockStyle.Bottom,
                            Height = 64,
                            BackColor = Color.Green,
                            ForeColor = Color.White,
                            Font = new Font("Arial", 14, FontStyle.Bold)
                        };
                        okButton.Click += (s, e) => changeForm.Close();

                        changeForm.Controls.Add(changeLabel);
                        changeForm.Controls.Add(okButton);
                        changeForm.TopMost = true;

                        changeForm.ShowDialog(this);
                    }
                }
            }
            catch
            {
                // Ignore popup failures and continue to complete sale
            }

            try
            {
                // Record all payments in database now that transaction is settled
                RecordPaymentEntry();

                // Use the actual sale total (excluding change) for the TransactionHeader
                decimal saleNetTotal = currentTotal - currentDiscount;
                string effectiveOrderDescription = isReturnExchangeMode
                    ? orderDescription
                    : BuildPostedOrderDescription(orderDescription);
                decimal cardProcessingFeeTotal = GetCurrentCardProcessingFeeTotal();
                // Save customer name and order description into the TransactionHeader.Description field
                string txDescription = isReturnExchangeMode
                    ? $"Exchange from Receipt: {returnExchangeOriginalReceiptNo} | Customer: {currentCustomerName}"
                    : $"Customer: {currentCustomerName} | Order: {effectiveOrderDescription}";
                if (!isReturnExchangeMode && cardProcessingFeeTotal > 0m)
                {
                    txDescription += $" | CardFee: {cardProcessingFeeTotal:F2}";
                }
                WriteSalesTransactionHeader(currentReceiptNo, isReturnExchangeMode ? "EXCHANGE" : "SALES", saleNetTotal, "", txDescription);

                // Process inventory entries for all items (finish SALES posting first)
                ProcessInventoryEntries();
                LogCardProcessingFee(cardProcessingFeeTotal, saleNetTotal);

                string mappedOnlineOrderId = OnlinefunctionsEvents.GetMappedOnlineOrderIdForReceipt(currentReceiptNo);

                // Attempt to create an instore online order before printing so the receipt can show the mapped online ID.
                try
                {
                    var flowType = checkoutButton?.Tag?.ToString() ?? string.Empty;
                    bool shouldSendToOnline = !isReturnExchangeMode &&
                                              (string.Equals(flowType, "SALES", StringComparison.OrdinalIgnoreCase)
                                               || HasCustomAquariumSaleItems());

                    if (shouldSendToOnline)
                    {
                        string receiptToSend = currentReceiptNo;
                        var createResp = OnlinefunctionsEvents.CreateInstoreOnlineOrder(receiptToSend);
                        System.Diagnostics.Debug.WriteLine($"CreateInstoreOnlineOrder ({(HasCustomAquariumSaleItems() ? "custom-aquarium-checkout" : "checkout")}) response: {createResp}");
                        mappedOnlineOrderId = OnlinefunctionsEvents.GetMappedOnlineOrderIdForReceipt(currentReceiptNo);
                    }
                    else
                    {
                        System.Diagnostics.Debug.WriteLine($"Skipped CreateInstoreOnlineOrder for flow '{flowType}' (receipt: {currentReceiptNo})");
                    }
                }
                catch (Exception ex)
                {
                    System.Diagnostics.Debug.WriteLine($"CreateInstoreOnlineOrder failed for receipt {currentReceiptNo}: {ex.Message}");
                }

                try
                {
                    ProductSerialTrackingForm.MarkSerialsSold(GetSelectedSaleSerialNumbers(), currentReceiptNo, mappedOnlineOrderId);
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Sale posted, but the selected serial-tracked items could not be marked as sold: {ex.Message}", "Serial Tracking Warning", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                }

                // Then post commission as a separate EXPENSE line (second)
                // Commission = sum((effectiveRetail - WholesalePrice) for Aquarium/Stand items) + Change.
                if (HasSalesPersonSelected())
                {
                    decimal changeDue = Math.Max(0m, totalPaid - (currentTotal - currentDiscount));
                    // Avoid creating a $0 commission EXPENSE receipt.
                    decimal commission = CalculateCommissionExpenseAmount(changeDue);
                    if (commission > 0m)
                    {
                        PostCommissionExpenseAsSeparateLine(changeDue, currentReceiptNo);
                    }
                }

                // Write summary to Prod_Order_Header
                var prodOrdersForm = new ProductionOrdersForm();


                int nonPaymentItemCount = FunctionEvents.GetNonPaymentItemCount(salesListView);
                string prodStatusCode = FunctionEvents.Get1stProductionStatusCode();
                string prodOrderNo = FunctionEvents.GenerateNextProdOrderNo();

                // Calculate total value of AQUARIUM category Items
                decimal aquariumTotal = FunctionEvents.GetAquariumCategoryTotal(salesListView, connectionString);




                // Use PostingEvents to post production orders (header and lines)
                PostingEvents.PostProductionOrders(
                    connectionString,
                    storeNo: "1", // Replace with actual store number
                    posTerminalNo: "1", // Replace with actual POS terminal number
                    transactionNo: currentTransNo,
                    receiptNo: currentReceiptNo,
                    prodOrderNo: prodOrderNo,
                    type: "SALES",
                    noOfItems: nonPaymentItemCount,
                    date: DateTime.Now.Date,
                    time: DateTime.Now.TimeOfDay,
                    customerName: customerName,
                    orderDescription: effectiveOrderDescription,
                    eodid: "", // Replace with actual EODID if available
                    status: prodStatusCode,
                    aquariumTotal: aquariumTotal,
                    salesListView: salesListView
                );

                // Ask if user wants to print receipt
                // DialogResult printResult = MessageBox.Show(
                //     "Would you like to print a receipt?",
                //     "Print Receipt",
                //     MessageBoxButtons.YesNo,
                //     MessageBoxIcon.Question);

                // if (printResult == DialogResult.Cancel)
                // {
                //     return; // Cancel completion
                // }

                // Build payment details for receipt
                string paymentDetails = string.Join("\n", payments.Select(p => $"{p.TenderType}: {p.Amount:F2}"));

                string saleDetails = $"Sale completed!\n" +
                                   $"Receipt #: {currentReceiptNo}\n" +
                                   $"Payment Methods:\n{paymentDetails}\n" +
                                   $"Subtotal: {currentTotal:F2}\n" +
                                   $"Discount: {currentDiscount:F2}\n" +
                                   $"Grand Total: {grandTotal:F2}\n" +
                                   $"Total Paid: {totalPaid:F2}\n" +
                                   $"Thank you!";

                // Print receipt if requested
                // if (printResult == DialogResult.Yes)
                // {
                try
                {
                    PrintReceiptDirect(currentReceiptNo);
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Sale completed but printing failed: {ex.Message}", "Print Warning", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                }

                try
                {
                    var pendingAquariumSerialLines = GetSaleLinesMissingAquariumSerials();
                    if (pendingAquariumSerialLines.Count > 0)
                    {
                        var generatedSerialLabels = new List<(string SerialNo, string ItemCode, string Description)>();
                        using var serialConn = new SqlConnection(connectionString);
                        serialConn.Open();

                        foreach (var pendingLine in pendingAquariumSerialLines)
                        {
                            generatedSerialLabels.AddRange(ProductSerialTrackingForm.CreateSoldSerialRecords(
                                serialConn,
                                null,
                                pendingLine.ItemCode,
                                pendingLine.VariationId,
                                pendingLine.Description,
                                currentReceiptNo,
                                mappedOnlineOrderId,
                                CurrentUser.GetEffectiveUsername("POS_SYSTEM"),
                                pendingLine.Count));
                        }

                        if (generatedSerialLabels.Count > 0)
                        {
                            PrintSerialNumberLabels(generatedSerialLabels);
                        }
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Sale completed but fallback aquarium serial tracking/label printing failed: {ex.Message}", "Label Print Warning", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                }
                // }

                // MessageBox.Show(
                //     saleDetails,
                //     "Sale Complete",
                //     MessageBoxButtons.OK,
                //     MessageBoxIcon.Information);

                // Clear the sale
                ClearSaleAndPayments();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error completing sale: {ex.Message}", "Sale Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void TriggerCloudInventoryDeductionForCurrentSale()
        {
            // Run in background so checkout is never blocked by network/API issues.
            try
            {
                var shopId = GlobalSettings.OnlineOrdersShopId ?? string.Empty;
                var receiptNo = currentReceiptNo ?? string.Empty;
                if (string.IsNullOrWhiteSpace(shopId) || string.IsNullOrWhiteSpace(receiptNo))
                    return;

                _ = System.Threading.Tasks.Task.Run(async () =>
                {
                    try
                    {
                        using var conn = new SqlConnection(connectionString);
                        await conn.OpenAsync().ConfigureAwait(false);

                        var qtyByVariationId = new System.Collections.Generic.Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase);
                        using (var cmd = new SqlCommand(@"
SELECT
    LTRIM(RTRIM(ISNULL(VariationId, ''))) AS VariationId,
    SUM(CASE WHEN Quantity < 0 THEN CAST(-Quantity AS DECIMAL(18,2)) ELSE CAST(Quantity AS DECIMAL(18,2)) END) AS QtyToDeduct
FROM ItemLedgerEntry
WHERE (DocumentNo = @receiptNo OR ReceiptNo = @receiptNo)
    AND DocumentType IN ('SALES', 'EXPENSE', 'INCOME')
  AND ISNULL(LTRIM(RTRIM(VariationId)), '') <> ''
GROUP BY LTRIM(RTRIM(ISNULL(VariationId, '')))", conn))
                        {
                            cmd.Parameters.AddWithValue("@receiptNo", receiptNo);
                            using var reader = await cmd.ExecuteReaderAsync().ConfigureAwait(false);
                            while (await reader.ReadAsync().ConfigureAwait(false))
                            {
                                string variationId = reader["VariationId"]?.ToString()?.Trim() ?? string.Empty;
                                if (string.IsNullOrWhiteSpace(variationId))
            pendingCustomAquariumSpecialNote = string.Empty;
                                decimal qty = reader["QtyToDeduct"] != DBNull.Value ? Convert.ToDecimal(reader["QtyToDeduct"]) : 0m;
                                if (qty <= 0m)
                                    continue;

                                if (qtyByVariationId.TryGetValue(variationId, out var existing))
                                    qtyByVariationId[variationId] = existing + qty;
                                else
                                    qtyByVariationId[variationId] = qty;
                            }
                        }

                        foreach (var kv in qtyByVariationId)
                        {
                            string variationId = kv.Key;
                            decimal qty = kv.Value;

                            try
                            {
                                await OnlinefunctionsEvents.DeductCloudInventoryAsync(shopId, variationId.Trim(), qty, TimeSpan.FromSeconds(30))
                                    .ConfigureAwait(false);
                            }
                            catch (Exception ex)
                            {
                                try { System.Diagnostics.Trace.TraceError($"Cloud inventory deduct failed for variation '{variationId}': {ex.Message}"); } catch { }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        try { System.Diagnostics.Trace.TraceError($"Cloud inventory deduct background task failed: {ex}"); } catch { }
                    }
                });
            }
            catch
            {
                // Ignore
            }
        }

