        private void RecordPaymentEntry()
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    // Record all payments from both the payments list and salesListView
                    var allPayments = new List<PaymentEntry>();

                    // First, add payments from the payments list
                    allPayments.AddRange(payments);

                    // Also check salesListView for any payment entries that might not be in the payments list
                    foreach (ListViewItem item in salesListView.Items)
                    {


                        // Show all data in the ListView item
                        var itemData = new System.Text.StringBuilder();
                        itemData.AppendLine($"Item Index: {item.Index}");
                        itemData.AppendLine($"Tag: {item.Tag}");
                        for (int i = 0; i < item.SubItems.Count; i++)
                        {
                            itemData.AppendLine($"SubItem[{i}]: {item.SubItems[i].Text}");
                        }
                        // MessageBox.Show(itemData.ToString(), "ListView Item Data")






                        if (item.Tag?.ToString() == "PAYMENT")
                        {
                            string tenderCode = item.Text; // Description column contains tender code
                            string amountText = item.SubItems[3].Text; // Total column contains amount

                            // Parse amount (remove currency symbol and negative sign)
                            string cleanAmount = amountText.Replace("?", "").Replace("-", "").Trim();
                            if (decimal.TryParse(cleanAmount, out decimal amount))
                            {
                                // Check if this payment is not already in the payments list
                                bool alreadyExists = allPayments.Any(p =>
                                    p.TenderCode == tenderCode &&
                                    Math.Abs(p.Amount - amount) < 0.01m);

                                if (!alreadyExists)
                                {
                                    allPayments.Add(new PaymentEntry
                                    {
                                        TenderType = tenderCode, // Use tender code as type for now
                                        TenderCode = tenderCode,
                                        Amount = amount,
                                        PaymentTime = DateTime.Now
                                    });
                                }
                            }
                        }
                    }

                    // Before recording, if payments exceed the sale total, deduct change
                    decimal originalGrandTotal = currentTotal - currentDiscount;
                    decimal totalPaid = allPayments.Sum(p => p.Amount);
                    decimal change = Math.Max(0, totalPaid - originalGrandTotal);

                    if (change > 0 && allPayments.Count > 0)
                    {
                        // Only apply change deduction to CASH tender entries (case-insensitive).
                        // Distribute the change deduction starting from the last payment backwards,
                        // but skip non-CASH tenders.
                        decimal remainingChange = change;
                        for (int i = allPayments.Count - 1; i >= 0 && remainingChange > 0; i--)
                        {
                            var p = allPayments[i];
                            // Use TenderCode (fall back to TenderType if TenderCode is null) for comparison
                            string tenderCode = p.TenderCode ?? p.TenderType;
                            if (!string.Equals(tenderCode?.Trim(), "CASH", StringComparison.OrdinalIgnoreCase))
                            {
                                // Skip non-cash tenders
                                continue;
                            }

                            decimal deduct = Math.Min(p.Amount, remainingChange);
                            p.Amount -= deduct;
                            remainingChange -= deduct;
                        }

                        // Remove any payments that are now zero or negative
                        allPayments = allPayments.Where(p => p.Amount > 0.0001m).ToList();
                    }

                    // Record each payment entry in the database
                    int lineno = 1;
                    foreach (var payment in allPayments)
                    {

                        var cmd = new SqlCommand(@"
                            INSERT INTO TransPaymentEntry (StoreNo, POSTerminalNo, TransactionNo, TenderTypeCode, [LineNo], 
                                             ReceiptNo, Description, Amount, UserID, Date, Time, CreatedDate)
                                VALUES (@storeNo, @posTerminalNo, @transactionNo, @tenderTypeCode, @lineNo,
                                    @receiptNo, @description, @amount, @userID, @date, @time, @createdDate)", connection);

                        // Get next line number for this receipt



                        cmd.Parameters.AddWithValue("@storeNo", "001");
                        cmd.Parameters.AddWithValue("@posTerminalNo", "001");
                        cmd.Parameters.AddWithValue("@transactionNo", currentTransNo);
                        cmd.Parameters.AddWithValue("@tenderTypeCode", payment.TenderCode);
                        cmd.Parameters.AddWithValue("@lineNo", lineno);
                        cmd.Parameters.AddWithValue("@receiptNo", currentReceiptNo);
                        cmd.Parameters.AddWithValue("@description", currentReceiptNo ?? (object)DBNull.Value);
                        cmd.Parameters.AddWithValue("@amount", payment.Amount);
                        cmd.Parameters.AddWithValue("@userID", CurrentUser.Username ?? "POS_SYSTEM");
                        cmd.Parameters.AddWithValue("@date", payment.PaymentTime.Date);
                        cmd.Parameters.AddWithValue("@time", payment.PaymentTime.TimeOfDay);
                        cmd.Parameters.AddWithValue("@createdDate", DateTime.Now);

                        cmd.ExecuteNonQuery();
                        lineno++;
                    }

                    if (allPayments.Count > 0)
                    {
                        // Log successful recording
                        Console.WriteLine($"Successfully recorded {allPayments.Count} payment entries for receipt {currentReceiptNo}");
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Warning: Could not record payment entries: {ex.Message}", "Payment Recording Warning", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        private bool HasSalesPersonSelected()
        {
            return !string.IsNullOrWhiteSpace(currentSalesPersonCode) || !string.IsNullOrWhiteSpace(currentSalesPersonName);
        }

        private string GetSalesPersonDisplayValue()
        {
            return !string.IsNullOrWhiteSpace(currentSalesPersonName)
                ? currentSalesPersonName!
                : (currentSalesPersonCode ?? string.Empty);
        }

        private decimal CalculateCommissionExpenseAmount(decimal changeAmount)
        {
            // Commission computation:
            // - Aquarium, Stand, and Sump (wholesale vs retail) difference
            // - plus Change
            // Notes/assumptions:
            // 1) We treat items with Category == "AQUARIUM" (from ListView subitem[4] in this app) as commissionable.
            // 2) We also treat items whose description/name contains "STAND" or "SUMP" as commissionable.
            // 3) We use Items.WholesalePrice and Items.RetailPrice; missing values default to 0.

            decimal commission = 0m;

            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    foreach (ListViewItem li in salesListView.Items)
                    {
                        // Skip non-sale lines
                        if (li.Tag?.ToString() == "PAYMENT") continue;
                        if (li.Tag?.ToString() == "EXPENSE") continue;
                        if (li.Tag?.ToString() == "INCOME") continue;
                        if (li.Tag?.ToString() == ReturnLineTag) continue;

                        string category = li.SubItems.Count > 4 ? (li.SubItems[4].Text ?? string.Empty) : string.Empty;
                        string code = li.SubItems.Count > 5 ? (li.SubItems[5].Text ?? string.Empty) : string.Empty;
                        string name = li.Text ?? string.Empty;

                        bool isAquarium = string.Equals(category?.Trim(), "AQUARIUM", StringComparison.OrdinalIgnoreCase);
                        bool isStand = name.IndexOf("STAND", StringComparison.OrdinalIgnoreCase) >= 0;
                        bool isSump = name.IndexOf("SUMP", StringComparison.OrdinalIgnoreCase) >= 0;

                        if (!isAquarium && !isStand && !isSump) continue;
                        if (string.IsNullOrWhiteSpace(code)) continue;

                        int qty = 1;
                        if (li.SubItems.Count > 1)
                            int.TryParse(li.SubItems[1].Text, out qty);
                        // If qty is zero/invalid, do not show it on the commission receipt.
                        if (qty <= 0) continue;

                        decimal wholesale = 0m;
                        decimal retail = 0m;

                        using (var cmd = new SqlCommand(@"SELECT WholesalePrice, RetailPrice FROM Items WHERE Code = @code", connection))
                        {
                            cmd.Parameters.AddWithValue("@code", code);
                            using (var r = cmd.ExecuteReader())
                            {
                                if (r.Read())
                                {
                                    wholesale = r["WholesalePrice"] != DBNull.Value ? Convert.ToDecimal(r["WholesalePrice"]) : 0m;
                                    retail = r["RetailPrice"] != DBNull.Value ? Convert.ToDecimal(r["RetailPrice"]) : 0m;
                                }
                            }
                        }

                        if (wholesale <= 0m) continue;

                        // Commission base: RetailPrice minus WholesalePrice
                        decimal diff = (retail - wholesale) * qty;
                        if (diff > 0)
                            commission += diff;
                    }
                }
            }
            catch (Exception ex)
            {
                // Don't block posting if commission calculation fails. Log and continue with any change-only commission.
                System.Diagnostics.Debug.WriteLine($"Commission calculation warning: {ex.Message}");
            }

            if (changeAmount > 0)
                commission += changeAmount;

            return decimal.Round(commission, 2);
        }

        private List<ListViewItem> BuildCommissionExpensePrintLines(decimal changeAmount, string salespersonDisplayValue)
        {
            // Build receipt lines for the commission EXPENSE printout.
            // Each line represents a commissionable sale item (Aquarium/Stand/Sump) and its commission contribution.
            // We also include a separate line for CHANGE (if any).

            var lines = new List<ListViewItem>();

            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    foreach (ListViewItem li in salesListView.Items)
                    {
                        // Skip non-sale lines
                        if (li.Tag?.ToString() == "PAYMENT") continue;
                        if (li.Tag?.ToString() == "EXPENSE") continue;
                        if (li.Tag?.ToString() == "INCOME") continue;
                        if (li.Tag?.ToString() == ReturnLineTag) continue;

                        string category = li.SubItems.Count > 4 ? (li.SubItems[4].Text ?? string.Empty) : string.Empty;
                        string code = li.SubItems.Count > 5 ? (li.SubItems[5].Text ?? string.Empty) : string.Empty;
                        string name = li.Text ?? string.Empty;

                        bool isAquarium = string.Equals(category?.Trim(), "AQUARIUM", StringComparison.OrdinalIgnoreCase);
                        bool isStand = name.IndexOf("STAND", StringComparison.OrdinalIgnoreCase) >= 0;
                        bool isSump = name.IndexOf("SUMP", StringComparison.OrdinalIgnoreCase) >= 0;
                        if (!isAquarium && !isStand && !isSump) continue;
                        if (string.IsNullOrWhiteSpace(code)) continue;

                        int qty = 1;
                        if (li.SubItems.Count > 1)
                            int.TryParse(li.SubItems[1].Text, out qty);
                        if (qty <= 0) qty = 1;

                        decimal wholesale = 0m;
                        decimal retail = 0m;

                        using (var cmd = new SqlCommand(@"SELECT WholesalePrice, RetailPrice FROM Items WHERE Code = @code", connection))
                        {
                            cmd.Parameters.AddWithValue("@code", code);
                            using (var r = cmd.ExecuteReader())
                            {
                                if (r.Read())
                                {
                                    wholesale = r["WholesalePrice"] != DBNull.Value ? Convert.ToDecimal(r["WholesalePrice"]) : 0m;
                                    retail = r["RetailPrice"] != DBNull.Value ? Convert.ToDecimal(r["RetailPrice"]) : 0m;
                                }
                            }
                        }

                        if (wholesale <= 0m) continue;

                        decimal itemCommission = (retail - wholesale) * qty;
                        if (itemCommission <= 0m) continue;

                        // Keep descriptions short for 58mm print; include code so it can be audited.
                        string desc = $"{code} {name} (Retail-WS)";

                        var lvi = new ListViewItem(desc);
                        lvi.SubItems.Add(qty.ToString());
                        lvi.SubItems.Add($"{decimal.Round(itemCommission, 2):F2}");
                        lvi.SubItems.Add($"{decimal.Round(itemCommission, 2):F2}");
                        lvi.SubItems.Add("EXPENSE");
                        // For printing, show the actual originating item code in the Code column.
                        // (Posting still uses INC_EXP in ItemLedgerEntry to avoid depending on an Items row.)
                        lvi.SubItems.Add(code);
                        lvi.Tag = "EXPENSE";
                        lines.Add(lvi);
                    }
                }
            }
            catch (Exception ex)
            {
                // If breakdown fails, don't block printing; fallback to summary-only.
                System.Diagnostics.Debug.WriteLine($"Commission breakdown warning: {ex.Message}");
            }

            if (changeAmount > 0m)
            {
                decimal chg = decimal.Round(changeAmount, 2);
                var changeLine = new ListViewItem("CHANGE");
                changeLine.SubItems.Add("1");
                changeLine.SubItems.Add($"{chg:F2}");
                changeLine.SubItems.Add($"{chg:F2}");
                changeLine.SubItems.Add("EXPENSE");
                // Ensure the Code column prints as CHANGE.
                changeLine.SubItems.Add("CHANGE");
                changeLine.Tag = "EXPENSE";
                lines.Add(changeLine);
            }

            // Always include a total line for clarity (helps auditing even when there are multiple lines).
            decimal total = lines.Sum(l =>
            {
                if (l.SubItems.Count > 3 && decimal.TryParse(l.SubItems[3].Text, out var t)) return t;
                return 0m;
            });
            if (total > 0m)
            {
                var totalLine = new ListViewItem($"TOTAL COMMISSION - {salespersonDisplayValue}");
                totalLine.SubItems.Add("");
                totalLine.SubItems.Add($"{total:F2}");
                totalLine.SubItems.Add($"{total:F2}");
                totalLine.SubItems.Add("EXPENSE");
                totalLine.SubItems.Add("INC_EXP");
                totalLine.Tag = "EXPENSE";
                lines.Add(totalLine);
            }

            return lines;
        }

        private void EnsureCommissionExpenseLine(decimal changeAmount)
        {
            // Make it idempotent within the UI list.
            foreach (ListViewItem existing in salesListView.Items)
            {
                if (existing.Tag?.ToString() == CommissionExpenseTag)
                    return;
            }

            decimal commission = CalculateCommissionExpenseAmount(changeAmount);
            if (commission <= 0m)
                return;

            string sp = GetSalesPersonDisplayValue();
            string desc = $"Commission - {sp}";

            var expenseItem = new ListViewItem(desc);
            expenseItem.SubItems.Add("1");
            expenseItem.SubItems.Add($"{commission:F2}");
            expenseItem.SubItems.Add($"{commission:F2}");
            expenseItem.SubItems.Add("EXPENSE");
            expenseItem.SubItems.Add("COMMISSION");
            expenseItem.Tag = CommissionExpenseTag;

            salesListView.Items.Add(expenseItem);

            // Recompute totals so the UI reflects the added expense immediately.
            UpdateTotal();
        }

        private void PostCommissionExpenseAsSeparateLine(decimal changeAmount, string originatingSalesReceiptNo)
        {
            // Persist commission as its own EXPENSE posting line.
            // This writes a separate TransactionHeader (Type=EXPENSE) and a single ItemLedgerEntry row.
            // NOTE: We intentionally do not mix this into the SALES header; this is a separate posting.

            if (!HasSalesPersonSelected())
                return;

            decimal commission = CalculateCommissionExpenseAmount(changeAmount);
            if (commission <= 0m)
                return;

            string sp = GetSalesPersonDisplayValue();
            string headerDescription = $"Commission - {sp} (Sales Receipt: {originatingSalesReceiptNo})";

            // Give commission its own receipt/document number so it's clearly a separate transaction.
            string commissionReceiptNo = GenerateCentralizedReceiptNumber();

            // Create TransactionHeader of Type = EXPENSE
            WriteSalesTransactionHeader(commissionReceiptNo, "EXPENSE", commission, "", headerDescription);

            // Post as a single ledger line.
            // IMPORTANT: PostInventoryEntry updates the Items table (QuantityInStock) and assumes the item exists.
            // The COMMISSION code is not a real inventory item in most setups, so treat it like an incidental expense.
            // Using INC_EXP ensures the ledger entry is created without depending on an Items row.
            PostInventoryEntry(
                itemCode: "INC_EXP",
                itemName: headerDescription,
                documentType: "EXPENSE",
                documentNo: commissionReceiptNo,
                quantity: 1,
                unitCost: 0m,
                description: headerDescription,
                price: commission,
                discount: 0m,
                grossAmount: commission,
                netAmount: commission,
                variationid: "",
                userID: CurrentUser.Username ?? "POS_SYSTEM");

            // Print the commission EXPENSE receipt (do not block posting on print errors)
            try
            {
                var printLines = BuildCommissionExpensePrintLines(changeAmount, sp);
                if (printLines.Count == 0)
                {
                    // Fallback to a single summary line
                    var commissionItem = new ListViewItem(headerDescription);
                    commissionItem.SubItems.Add("1");
                    commissionItem.SubItems.Add($"{commission:F2}");
                    commissionItem.SubItems.Add($"{commission:F2}");
                    commissionItem.SubItems.Add("EXPENSE");
                    commissionItem.SubItems.Add("INC_EXP");
                    commissionItem.Tag = "EXPENSE";
                    printLines.Add(commissionItem);
                }

                FunctionEvents.PrintExpenseReceipt(
                    commissionReceiptNo,
                    CurrentUser.Username ?? "",
                    printLines,
                    commission,
                    headerDescription);
            }
            catch
            {
                // Ignore print errors so sale completion continues.
            }
        }

        private int GetNextPaymentLineNumber(string receiptNo)
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var cmd = new SqlCommand("SELECT ISNULL(MAX(LineNo), 0) + 1 FROM TransPaymentEntry WHERE ReceiptNo = @receiptNo", connection);
                    cmd.Parameters.AddWithValue("@receiptNo", receiptNo);
                    return Convert.ToInt32(cmd.ExecuteScalar());
                }
            }
            catch
            {
                return 1; // Default to 1 if error
            }
        }

        private int GetNextPaymentLineNumberForTransaction(SqlConnection connection, string storeNo, string posTerminalNo, string transactionNo)
        {
            try
            {
                var cmd = new SqlCommand(@"SELECT ISNULL(MAX([LineNo]), 0) + 1
FROM TransPaymentEntry
WHERE StoreNo = @storeNo AND POSTerminalNo = @posTerminalNo AND TransactionNo = @transactionNo", connection);
                cmd.Parameters.AddWithValue("@storeNo", storeNo);
                cmd.Parameters.AddWithValue("@posTerminalNo", posTerminalNo);
                cmd.Parameters.AddWithValue("@transactionNo", transactionNo);
                return Convert.ToInt32(cmd.ExecuteScalar());
            }
            catch
            {
                return 1;
            }
        }

        // Record a single payment entry specifically for fully-paid Advance Orders.
        // This avoids scanning the salesListView/payments list and writes a dedicated TransPaymentEntry row.
        public void RecordAdvanceOrderPayment(string receiptNo, string transactionNo, string tenderTypeCode, decimal amount, string? description = null, DateTime? paymentTime = null, int? lineNo = null)
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    // If caller didn't provide a transactionNo, use the currentTransNo that was set when staging the order
                    string transactionToUse = string.IsNullOrWhiteSpace(transactionNo) ? currentTransNo : transactionNo;

                    // Ensure a TransactionHeader exists for this receipt/transaction. If transactionToUse is not numeric
                    // or header does not exist, create a new TransactionHeader and use that TransactionNo.
                    int txNoInt = 0;
                    if (!int.TryParse(transactionToUse, out txNoInt) || txNoInt <= 0)
                    {
                        var nextCmd = new SqlCommand("SELECT ISNULL(MAX(TransactionNo), 0) + 1 FROM TransactionHeader WHERE StoreNo = @storeNo AND POSTerminalNo = @posTerminalNo", connection);
                        nextCmd.Parameters.AddWithValue("@storeNo", "001");
                        nextCmd.Parameters.AddWithValue("@posTerminalNo", "001");
                        txNoInt = Convert.ToInt32(nextCmd.ExecuteScalar());
                        transactionToUse = txNoInt.ToString();

                        // Insert a minimal TransactionHeader row for this payment
                        var insHdr = new SqlCommand(@"
                            INSERT INTO TransactionHeader (StoreNo, POSTerminalNo, TransactionNo, ReceiptNo, Type, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, UserID, Description)
                            VALUES (@StoreNo, @POSTerminalNo, @TransactionNo, @ReceiptNo, @Type, @Quantity, @Price, @Discount, @GrossAmount, @NetAmount, @Date, @Time, @UserID, @Description)", connection);
                        insHdr.Parameters.AddWithValue("@StoreNo", "001");
                        insHdr.Parameters.AddWithValue("@POSTerminalNo", "001");
                        insHdr.Parameters.AddWithValue("@TransactionNo", txNoInt);
                        insHdr.Parameters.AddWithValue("@ReceiptNo", receiptNo ?? (object)DBNull.Value);
                        insHdr.Parameters.AddWithValue("@Type", "SALES");
                        insHdr.Parameters.AddWithValue("@Quantity", 1);
                        insHdr.Parameters.AddWithValue("@Price", amount);
                        insHdr.Parameters.AddWithValue("@Discount", 0);
                        insHdr.Parameters.AddWithValue("@GrossAmount", amount);
                        insHdr.Parameters.AddWithValue("@NetAmount", amount);
                        insHdr.Parameters.AddWithValue("@Date", DateTime.Now);
                        insHdr.Parameters.AddWithValue("@Time", DateTime.Now.ToString("HH:mm:ss"));
                        insHdr.Parameters.AddWithValue("@UserID", CurrentUser.Username ?? "POS_SYSTEM");
                        insHdr.Parameters.AddWithValue("@Description", (object?)(description ?? receiptNo) ?? DBNull.Value);
                        try { insHdr.ExecuteNonQuery(); } catch { }
                    }
                    else
                    {
                        // Check if header exists, create if missing
                        var chk = new SqlCommand("SELECT COUNT(1) FROM TransactionHeader WHERE StoreNo = @storeNo AND POSTerminalNo = @posTerminalNo AND TransactionNo = @transactionNo", connection);
                        chk.Parameters.AddWithValue("@storeNo", "001");
                        chk.Parameters.AddWithValue("@posterminalno", "001");
                        chk.Parameters.AddWithValue("@transactionNo", txNoInt);
                        int exists = Convert.ToInt32(chk.ExecuteScalar());
                        if (exists == 0)
                        {
                            var insHdr2 = new SqlCommand(@"
                                INSERT INTO TransactionHeader (StoreNo, POSTerminalNo, TransactionNo, ReceiptNo, Type, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, UserID, Description)
                                VALUES (@StoreNo, @POSTerminalNo, @TransactionNo, @ReceiptNo, @Type, @Quantity, @Price, @Discount, @GrossAmount, @NetAmount, @Date, @Time, @UserID, @Description)", connection);
                            insHdr2.Parameters.AddWithValue("@StoreNo", "001");
                            insHdr2.Parameters.AddWithValue("@POSTerminalNo", "001");
                            insHdr2.Parameters.AddWithValue("@TransactionNo", txNoInt);
                            insHdr2.Parameters.AddWithValue("@ReceiptNo", receiptNo ?? (object)DBNull.Value);
                            insHdr2.Parameters.AddWithValue("@Type", "SALES");
                            insHdr2.Parameters.AddWithValue("@Quantity", 1);
                            insHdr2.Parameters.AddWithValue("@Price", amount);
                            insHdr2.Parameters.AddWithValue("@Discount", 0);
                            insHdr2.Parameters.AddWithValue("@GrossAmount", amount);
                            insHdr2.Parameters.AddWithValue("@NetAmount", amount);
                            insHdr2.Parameters.AddWithValue("@Date", DateTime.Now);
                            insHdr2.Parameters.AddWithValue("@Time", DateTime.Now.ToString("HH:mm:ss"));
                            insHdr2.Parameters.AddWithValue("@UserID", CurrentUser.Username ?? "POS_SYSTEM");
                            insHdr2.Parameters.AddWithValue("@Description", (object?)(description ?? receiptNo) ?? DBNull.Value);
                            try { insHdr2.ExecuteNonQuery(); } catch { }
                        }
                    }

                    // Important: LineNo must be unique per transaction (some installs use PK (StoreNo, POSTerminalNo, TransactionNo, LineNo)).
                    // Allocate next line number by transaction, not by receipt.
                    int lineNoToUse = lineNo ?? GetNextPaymentLineNumberForTransaction(connection, "001", "001", transactionToUse ?? "");

                    var dt = paymentTime ?? DateTime.Now;

                    // Retry a couple of times in case another payment line was inserted concurrently.
                    for (int attempt = 0; attempt < 3; attempt++)
                    {
                        try
                        {
                            var cmd = new SqlCommand(@"
                                INSERT INTO TransPaymentEntry (StoreNo, POSTerminalNo, TransactionNo, TenderTypeCode, [LineNo], ReceiptNo, Description, Amount, UserID, Date, Time, CreatedDate)
                                VALUES (@storeNo, @posTerminalNo, @transactionNo, @tenderTypeCode, @lineNo, @receiptNo, @description, @amount, @userID, @date, @time, @createdDate)", connection);

                            cmd.Parameters.AddWithValue("@storeNo", "001");
                            cmd.Parameters.AddWithValue("@posTerminalNo", "001");
                            cmd.Parameters.AddWithValue("@transactionNo", transactionToUse ?? "");
                            cmd.Parameters.AddWithValue("@tenderTypeCode", tenderTypeCode ?? "");
                            cmd.Parameters.AddWithValue("@lineNo", lineNoToUse);
                            cmd.Parameters.AddWithValue("@receiptNo", receiptNo ?? "");
                            cmd.Parameters.AddWithValue("@amount", amount);
                            cmd.Parameters.AddWithValue("@description", (object?)description ?? DBNull.Value);
                            cmd.Parameters.AddWithValue("@userID", CurrentUser.Username ?? "POS_SYSTEM");
                            cmd.Parameters.AddWithValue("@date", dt.Date);
                            cmd.Parameters.AddWithValue("@time", dt.TimeOfDay);
                            cmd.Parameters.AddWithValue("@createdDate", DateTime.Now);

                            cmd.ExecuteNonQuery();
                            break;
                        }
                        catch (SqlException sqlEx) when (sqlEx.Number == 2627 || sqlEx.Number == 2601)
                        {
                            // Duplicate key - allocate a new line number and retry.
                            lineNoToUse = GetNextPaymentLineNumberForTransaction(connection, "001", "001", transactionToUse ?? "");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Warning: Could not record advance order payment entry: {ex.Message}", "Payment Recording Warning", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        private void ClearSaleAndPayments()
        {
            // Clear payment tracking
            isInPaymentMode = false;
            payments.Clear();
            totalPaid = 0;
            currentReceiptNo = "";
            pendingCustomAquariumSpecialNote = string.Empty;

            // Hide payment UI elements (only remaining balance label and payments label)
            // remainingBalanceLabel.Visible = false;
            //paymentsLabel.Visible = false;
            // Preserve DOWNPAYMENT flow: don't reset the Checkout button if we're in a downpayment flow
            if (checkoutButton.Tag?.ToString() != "DOWNPAYMENT")
            {
                checkoutButton.Text = "CHECKOUT";
            }

            // Clear the sale normally
            ClearButton_Click(null, EventArgs.Empty);
        }

        private void DiscountButton_Click(object? sender, EventArgs e)
        {
            if (salesListView.Items.Count == 0)
            {
                MessageBox.Show("No items in sale to apply discount!", "Discount", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (currentDiscount > 0m)
            {
                MessageBox.Show("Cannot apply more discount an existing discount has been applied", "Discount", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            // Show discount options
            var discountForm = new Form
            {
                Text = "Apply Discount",
                Size = new Size(380, 300),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false,
                MinimizeBox = false
            };

            // ...existing code...
            var instructionLabel = new Label
            {
                Text = "Select discount type:",
                Location = new Point(20, 20),
                Size = new Size(150, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            // Percentage discount option
            var percentRadio = new RadioButton
            {
                Text = "Percentage (%)",
                Location = new Point(20, 50),
                Size = new Size(120, 25),
                Checked = true
            };

            var percentBox = new NumericUpDown
            {
                Location = new Point(150, 50),
                Size = new Size(80, 25),
                Minimum = 0,
                Maximum = 50,
                DecimalPlaces = 1,
                // Display blank by default; Value will remain the control default (0) but the textbox is empty
                Text = ""
            };

            var percentSymbol = new Label
            {
                Text = "%",
                Location = new Point(240, 52),
                Size = new Size(20, 20)
            };

            // Fixed amount discount option
            var amountRadio = new RadioButton
            {
                Text = "Fixed Amount (?)",
                Location = new Point(20, 85),
                Size = new Size(120, 25)
            };

            var amountBox = new NumericUpDown
            {
                Location = new Point(150, 85),
                Size = new Size(80, 25),
                Minimum = 0,
                Maximum = currentTotal,
                DecimalPlaces = 2,
                Text = ""
            };

            var wholesaleRadio = new RadioButton
            {
                Text = "Wholesale",
                Location = new Point(20, 120),
                Size = new Size(120, 25)
            };

            var wholesaleHintLabel = new Label
            {
                Text = "Uses item wholesale prices for eligible lines",
                Location = new Point(150, 122),
                Size = new Size(200, 20),
                Font = new Font("Arial", 8, FontStyle.Italic),
                ForeColor = Color.DimGray
            };

            // Apply button
            var applyButton = new Button
            {
                Text = "Apply",
                Location = new Point(150, 180),
                Size = new Size(80, 35),
                BackColor = Color.Green,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            applyButton.Click += (s, args) =>
            {
                if (percentRadio.Checked)
                {
                    currentDiscount = currentTotal * (percentBox.Value / 100);
                    currentDiscountDescription = string.Empty;
                }
                else if (wholesaleRadio.Checked)
                {
                    var (wholesaleDiscount, message, matchedWholesaleCategories) = CalculateWholesaleDiscountForCurrentSale();
                    if (wholesaleDiscount <= 0m)
                    {
                        MessageBox.Show(message, "Wholesale Discount", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    currentDiscount = wholesaleDiscount;
                    currentDiscountDescription = "Wholesale Discount";
                }
                else
                {
                    currentDiscount = amountBox.Value;
                    currentDiscountDescription = string.Empty;
                }

                UpdateTotal();
                discountForm.Close();
                MessageBox.Show($"Discount of {currentDiscount:F2} applied!", "Discount Applied", MessageBoxButtons.OK, MessageBoxIcon.Information);
            };

            // Cancel button
            var cancelButton = new Button
            {
                Text = "Cancel",
                Location = new Point(240, 180),
                Size = new Size(80, 35),
                BackColor = Color.Gray,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            cancelButton.Click += (s, args) => discountForm.Close();

            discountForm.Controls.AddRange(new Control[] {
                instructionLabel, percentRadio, percentBox, percentSymbol,
                amountRadio, amountBox, wholesaleRadio, wholesaleHintLabel, applyButton, cancelButton
            });

            discountForm.ShowDialog();
        }

        private (decimal Discount, string Message, string MatchedWholesaleCategories) CalculateWholesaleDiscountForCurrentSale()
        {
            if (salesListView == null || salesListView.Items.Count == 0)
            {
                return (0m, "No items in sale to apply wholesale discount.", string.Empty);
            }

            var wholesalePricesByCode = new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase);
            var wholesaleCategories = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var itemCodes = salesListView.Items
                .Cast<ListViewItem>()
                .Where(item => item.SubItems.Count > 5)
                .Select(item => item.SubItems[5].Text?.Trim() ?? string.Empty)
                .Where(code => !string.IsNullOrWhiteSpace(code))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            var categoryCodes = salesListView.Items
                .Cast<ListViewItem>()
                .Where(item => item.SubItems.Count > 4)
                .Select(item => item.SubItems[4].Text?.Trim() ?? string.Empty)
                .Where(code => !string.IsNullOrWhiteSpace(code))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (itemCodes.Count == 0)
            {
                return (0m, "No eligible sale lines with item codes were found.", string.Empty);
            }

            decimal minimumWholesaleOrderTotal = LoadMinimumWholesalesPrice();
            if (minimumWholesaleOrderTotal <= 0m)
            {
                minimumWholesaleOrderTotal = 5000m;
            }

            try
            {
                using var connection = new SqlConnection(connectionString);
                connection.Open();

                using var command = new SqlCommand();
                command.Connection = connection;

                var codeParameters = new List<string>();
                for (int index = 0; index < itemCodes.Count; index++)
                {
                    string parameterName = $"@Code{index}";
                    codeParameters.Add(parameterName);
                    command.Parameters.AddWithValue(parameterName, itemCodes[index]);
                }

                command.CommandText = $@"
SELECT Code, ISNULL(WholesalePrice, 0) AS WholesalePrice
FROM dbo.Items
WHERE Code IN ({string.Join(", ", codeParameters)})";

                {
                    using var reader = command.ExecuteReader();
                    while (reader.Read())
                    {
                        string code = reader["Code"]?.ToString()?.Trim() ?? string.Empty;
                        decimal wholesalePrice = reader["WholesalePrice"] != DBNull.Value ? Convert.ToDecimal(reader["WholesalePrice"]) : 0m;
                        if (!string.IsNullOrWhiteSpace(code))
                        {
                            wholesalePricesByCode[code] = wholesalePrice;
                        }
                    }
                }

                if (categoryCodes.Count > 0)
                {
                    using var categoryCommand = new SqlCommand();
                    categoryCommand.Connection = connection;

                    var categoryParameters = new List<string>();
                    for (int index = 0; index < categoryCodes.Count; index++)
                    {
                        string parameterName = $"@Category{index}";
                        categoryParameters.Add(parameterName);
                        categoryCommand.Parameters.AddWithValue(parameterName, categoryCodes[index]);
                    }

                    categoryCommand.CommandText = $@"
SELECT Code
FROM Category
WHERE ISNULL(WholeSale, 0) = 1
  AND Code IN ({string.Join(", ", categoryParameters)})";

                    using var categoryReader = categoryCommand.ExecuteReader();
                    while (categoryReader.Read())
                    {
                        string categoryCode = categoryReader["Code"]?.ToString()?.Trim() ?? string.Empty;
                        if (!string.IsNullOrWhiteSpace(categoryCode))
                        {
                            wholesaleCategories.Add(categoryCode);
                        }
                    }
                }
            }
            catch
            {
                return (0m, "Failed to load wholesale pricing setup.", string.Empty);
            }

            decimal wholesaleDiscount = 0m;
            decimal qualifyingWholesaleBaseTotal = 0m;
            bool hasWholesaleCategoryLines = false;
            var matchedWholesaleCategoryCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var missingWholesalePriceItemCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (ListViewItem saleItem in salesListView.Items)
            {
                string tag = saleItem.Tag?.ToString() ?? string.Empty;
                if (string.Equals(tag, "PAYMENT", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, "EXPENSE", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, "INCOME", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, AquariumSetDiscountTag, StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, AquariumSetAccessoryTag, StringComparison.OrdinalIgnoreCase)
                    || string.Equals(tag, ReturnLineTag, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                if (saleItem.SubItems.Count <= 5)
                {
                    continue;
                }

                string categoryCode = saleItem.SubItems[4].Text?.Trim() ?? string.Empty;
                string itemCode = saleItem.SubItems[5].Text?.Trim() ?? string.Empty;
                if (string.IsNullOrWhiteSpace(categoryCode) || !wholesaleCategories.Contains(categoryCode))
                {
                    continue;
                }

                hasWholesaleCategoryLines = true;
                matchedWholesaleCategoryCodes.Add(categoryCode);

                int quantity = 0;
                decimal lineTotal = 0m;
                _ = int.TryParse(saleItem.SubItems.Count > 1 ? saleItem.SubItems[1].Text?.Trim() ?? string.Empty : string.Empty, out quantity);
                _ = decimal.TryParse(saleItem.SubItems.Count > 3 ? saleItem.SubItems[3].Text?.Trim() ?? string.Empty : string.Empty, out lineTotal);

                if (quantity <= 0 || lineTotal <= 0m)
                {
                    continue;
                }

                decimal wholesalePrice = 0m;
                if (!string.IsNullOrWhiteSpace(itemCode)
                    && wholesalePricesByCode.TryGetValue(itemCode, out decimal loadedWholesalePrice)
                    && loadedWholesalePrice > 0m)
                {
                    wholesalePrice = loadedWholesalePrice;
                }
                else if (!string.IsNullOrWhiteSpace(itemCode))
                {
                    missingWholesalePriceItemCodes.Add(itemCode);
                }

                decimal wholesaleLineTotal = wholesalePrice * quantity;
                if (wholesalePrice > 0m)
                {
                    qualifyingWholesaleBaseTotal += wholesaleLineTotal;
                }

                if (wholesalePrice > 0m && lineTotal > wholesaleLineTotal)
                {
                    wholesaleDiscount += lineTotal - wholesaleLineTotal;
                }
            }

            string matchedWholesaleCategories = string.Join(", ", matchedWholesaleCategoryCodes.OrderBy(code => code, StringComparer.OrdinalIgnoreCase));

            if (!hasWholesaleCategoryLines)
            {
                return (0m, "No sale lines belong to categories marked as Wholesale.", string.Empty);
            }

            if (missingWholesalePriceItemCodes.Count > 0 && wholesaleDiscount <= 0m)
            {
                string missingItems = string.Join(", ", missingWholesalePriceItemCodes.OrderBy(code => code, StringComparer.OrdinalIgnoreCase));
                return (0m, $"Wholesale price is not set for eligible item(s): {missingItems}", matchedWholesaleCategories);
            }

            if (qualifyingWholesaleBaseTotal < minimumWholesaleOrderTotal)
            {
                decimal remainingWholesaleAmount = minimumWholesaleOrderTotal - qualifyingWholesaleBaseTotal;
                return (0m, $"Order insuficient for selected category please add more products. Wholesale price already punched in: {qualifyingWholesaleBaseTotal:F2}. Add {remainingWholesaleAmount:F2} more to get wholesale pricing.", matchedWholesaleCategories);
            }

            if (wholesaleDiscount <= 0m)
            {
                return (0m, "Eligible wholesale items do not produce any discount against their wholesale prices.", matchedWholesaleCategories);
            }

            return (decimal.Round(wholesaleDiscount, 2), string.Empty, matchedWholesaleCategories);
        }

        // Inventory Management Methods

        private void CreateInventoryTables()
        {
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();

                // Check if old ItemLedgerEntry table exists and drop it to recreate with new schema
                var dropOldTableCmd = new SqlCommand(@"
                    IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'ItemLedgerEntry')
                    BEGIN
                        -- Check if it has old structure with ItemID
                        IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'ItemID')
                        BEGIN
                            DROP TABLE ItemLedgerEntry
                        END
                    END", connection);
                dropOldTableCmd.ExecuteNonQuery();

                // Create Item Ledger Entry table for inventory tracking with new schema
                var createLedgerTableCmd = new SqlCommand(@"
                    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'ItemLedgerEntry')
                    BEGIN
                        CREATE TABLE ItemLedgerEntry (
                            ID INT IDENTITY(1,1) PRIMARY KEY,
                            EntryDate DATETIME2 DEFAULT GETDATE(),
                            ItemCode NVARCHAR(50) NOT NULL,
                            DocumentType NVARCHAR(50) NOT NULL, -- 'POSITIVE_ADJ', 'NEGATIVE_ADJ', 'SALES', 'REFUND', 'INITIAL'
                            DocumentNo NVARCHAR(100),
                            ReceiptNo NVARCHAR(50), -- Running receipt number like RS0000000001
                            StoreNo NVARCHAR(20) DEFAULT '001', -- Store number
                            PosTerminalNo NVARCHAR(20) DEFAULT '001', -- POS terminal number
                            Quantity INT NOT NULL, -- Positive for increases, Negative for decreases
                            UnitCost DECIMAL(10,2) DEFAULT 0,
                            TotalCost DECIMAL(10,2) DEFAULT 0,
                            Price DECIMAL(10,2) DEFAULT 0, -- Selling price
                            Discount DECIMAL(10,2) DEFAULT 0, -- Discount amount
                            GrossAmount DECIMAL(10,2) DEFAULT 0, -- Quantity * Price before discount
                            NetAmount DECIMAL(10,2) DEFAULT 0, -- GrossAmount - Discount
                            Description NVARCHAR(500),
                            UserID NVARCHAR(100) DEFAULT 'SYSTEM',
                            CONSTRAINT FK_ItemLedgerEntry_Items FOREIGN KEY (ItemCode) REFERENCES Items(Code) ON DELETE CASCADE
                        )
                        
                        CREATE INDEX IX_ItemLedgerEntry_ItemCode ON ItemLedgerEntry(ItemCode)
                        CREATE INDEX IX_ItemLedgerEntry_DocumentType ON ItemLedgerEntry(DocumentType)
                        CREATE INDEX IX_ItemLedgerEntry_EntryDate ON ItemLedgerEntry(EntryDate)
                    END
                    ELSE
                    BEGIN
                        -- Add new columns if they don't exist
                        IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'Price')
                            ALTER TABLE ItemLedgerEntry ADD Price DECIMAL(10,2) DEFAULT 0
                        
                        IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'Discount')
                            ALTER TABLE ItemLedgerEntry ADD Discount DECIMAL(10,2) DEFAULT 0
                        
                        IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'GrossAmount')
                            ALTER TABLE ItemLedgerEntry ADD GrossAmount DECIMAL(10,2) DEFAULT 0
                        
                        IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'NetAmount')
                            ALTER TABLE ItemLedgerEntry ADD NetAmount DECIMAL(10,2) DEFAULT 0
                        
                        IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'UserID')
                            ALTER TABLE ItemLedgerEntry ADD UserID NVARCHAR(100) DEFAULT 'SYSTEM'
                        
                        IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'ReceiptNo')
                            ALTER TABLE ItemLedgerEntry ADD ReceiptNo NVARCHAR(50)
                        
                        IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'StoreNo')
                            ALTER TABLE ItemLedgerEntry ADD StoreNo NVARCHAR(20) DEFAULT '001'
                        
                        IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'ItemLedgerEntry' AND COLUMN_NAME = 'PosTerminalNo')
                            ALTER TABLE ItemLedgerEntry ADD PosTerminalNo NVARCHAR(20) DEFAULT '001'
                    END
                    
                    -- Create Receipt Number sequence table
                    IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'ReceiptNumberSequence')
                    BEGIN
                        CREATE TABLE ReceiptNumberSequence (
                            ID INT IDENTITY(1,1) PRIMARY KEY,
                            LastReceiptNumber BIGINT DEFAULT 0
                        )
                        
                        -- Initialize with starting number (RS0000000000)
                        INSERT INTO ReceiptNumberSequence (LastReceiptNumber) VALUES (0)
                    END", connection);
                createLedgerTableCmd.ExecuteNonQuery();
            }
        }

        private string GenerateNextReceiptNumber(SqlConnection connection, SqlTransaction transaction)
        {
            using (var ensureRowCmd = new SqlCommand(@"
IF NOT EXISTS (SELECT 1 FROM ReceiptNumberSequence)
BEGIN
    INSERT INTO ReceiptNumberSequence (LastReceiptNumber) VALUES (0)
END", connection, transaction))
            {
                ensureRowCmd.ExecuteNonQuery();
            }

            long headerMax = 0;
            using (var getLastFromHeader = new SqlCommand(@"
SELECT ISNULL(MAX(TRY_CONVERT(BIGINT, SUBSTRING(ReceiptNo, 4, 100))), 0)
FROM TransactionHeader
WHERE ReceiptNo LIKE 'RS-%'", connection, transaction))
            {
                var result = getLastFromHeader.ExecuteScalar();
                if (result != null && result != DBNull.Value)
                {
                    headerMax = Convert.ToInt64(result);
                }
            }

            using (var syncCmd = new SqlCommand(@"
UPDATE ReceiptNumberSequence
SET LastReceiptNumber = CASE
    WHEN LastReceiptNumber < @HeaderMax THEN @HeaderMax
    ELSE LastReceiptNumber
END", connection, transaction))
            {
                syncCmd.Parameters.AddWithValue("@HeaderMax", headerMax);
                syncCmd.ExecuteNonQuery();
            }

            using (var updateCmd = new SqlCommand(@"
;WITH SequenceRow AS
(
    SELECT TOP (1) ID, LastReceiptNumber
    FROM ReceiptNumberSequence WITH (UPDLOCK, HOLDLOCK)
    ORDER BY ID
)
UPDATE SequenceRow
SET LastReceiptNumber = LastReceiptNumber + 1
OUTPUT INSERTED.LastReceiptNumber;", connection, transaction))
            {
                long nextNumber = Convert.ToInt64(updateCmd.ExecuteScalar());
                return $"RS-{nextNumber:D10}";
            }
        }

        private void TryRollbackTransaction(SqlTransaction? transaction)
        {
            if (transaction == null)
            {
                return;
            }

            try
            {
                if (transaction.Connection != null)
                {
                    transaction.Rollback();
                }
            }
            catch (InvalidOperationException)
            {
                // The transaction has already been completed or detached.
            }
            catch (SqlException)
            {
                // Preserve the original failure when SQL Server has already aborted the transaction.
            }
        }


        // Returns the latest TransactionNo from TransactionHeader plus one
        private string GetNextTransactionNoPlusOne()
        {
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                var cmd = new SqlCommand("SELECT TOP 1 TransactionNo FROM TransactionHeader ORDER BY TransactionNo DESC", connection);
                var result = cmd.ExecuteScalar();
                long nextNumber = 1;
                if (result != null && long.TryParse(result.ToString(), out long lastNumber))
                {
                    nextNumber = lastNumber + 1;
                }
                return nextNumber.ToString(); // Format as 0000000001, 0000000002, etc.
            }
        }

        // Generates the next EODID by sorting the transaction header EOD field
        private string GetNextEODID()
        {
            string defaultEODID = "EOD-RS000000001";
            string? lastEODID = null;
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                // Replace TransactionHeader with your actual transaction header table name
                string sql = "SELECT TOP 1 EODID FROM TransactionHeader WHERE EODID IS NOT NULL AND EODID <> '' ORDER BY EODID DESC";
                using (var cmd = new SqlCommand(sql, connection))
                {
                    var result = cmd.ExecuteScalar();
                    if (result != null && result != DBNull.Value)
                    {
                        lastEODID = result.ToString();
                    }
                }
            }

            if (string.IsNullOrEmpty(lastEODID))
            {
                return defaultEODID;
            }

            // Extract numeric part and increment
            var match = System.Text.RegularExpressions.Regex.Match(lastEODID, @"EOD-RS(\d{9})");
            if (match.Success)
            {
                long lastNum = long.Parse(match.Groups[1].Value);
                string nextEODID = $"EOD-RS{(lastNum + 1):D9}";
                return nextEODID;
            }
            // If format is unexpected, fallback to default
            return defaultEODID;
        }


        // Centralized method to generate receipt numbers for all transactions
        private string GenerateCentralizedReceiptNumber()
        {
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                using (var transaction = connection.BeginTransaction())
                {
                    try
                    {
                        string receiptNumber = GenerateNextReceiptNumber(connection, transaction);
                        transaction.Commit();
                        return receiptNumber;
                    }
                    catch
                    {
                        TryRollbackTransaction(transaction);
                        throw;
                    }
                }
            }
        }

        private string GenerateItemCode(string itemName)
        {
            // Generate a unique item code based on the item name
            // Remove special characters and spaces, keep only alphanumeric
            string baseCode = new string(itemName.Where(c => char.IsLetterOrDigit(c)).ToArray()).ToUpper();

            // Limit to 20 characters
            if (baseCode.Length > 20)
                baseCode = baseCode.Substring(0, 20);

            // If empty after cleanup, use AUTO prefix
            if (string.IsNullOrEmpty(baseCode))
                baseCode = "AUTO";

            // Check if this code already exists and add a suffix if needed
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                string finalCode = baseCode;
                int suffix = 1;

                while (true)
                {
                    var checkCmd = new SqlCommand("SELECT COUNT(*) FROM Items WHERE Code = @code", connection);
                    checkCmd.Parameters.AddWithValue("@code", finalCode);
                    int count = Convert.ToInt32(checkCmd.ExecuteScalar());

                    if (count == 0)
                        break;

                    // Add numeric suffix if code already exists
                    finalCode = $"{baseCode}{suffix:D3}"; // e.g., ITEM001, ITEM002
                    suffix++;

                    // Prevent infinite loop
                    if (suffix > 999)
                    {
                        finalCode = $"AUTO{DateTime.Now.Ticks % 100000:D5}";
                        break;
                    }
                }

                return finalCode;
            }
        }

        private void PostInventoryEntry(string itemCode, string itemName, string documentType, string documentNo,
                          int quantity, decimal unitCost, string description, decimal price = 0,
                          decimal discount = 0, decimal grossAmount = 0, decimal netAmount = 0, string variationid = "",
                          string userID = "SYSTEM", string storeNo = "001", string posTerminalNo = "001")
        {
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                using (var transaction = connection.BeginTransaction())
                {
                    try
                    {
                        // Get current stock from Items table


                        var getCurrentStockCmd = new SqlCommand("SELECT QuantityInStock FROM Items WHERE Code = @itemCode", connection, transaction);
                        getCurrentStockCmd.Parameters.AddWithValue("@itemCode", itemCode);
                        int currentStock = Convert.ToInt32(getCurrentStockCmd.ExecuteScalar() ?? 0);

                        // Calculate new stock level
                        int newStock = currentStock + quantity; // quantity can be negative for decreases
                        decimal totalCost = quantity * unitCost;

                        // Update Items table
                        var updateItemCmd = new SqlCommand("UPDATE Items SET QuantityInStock = @newStock, UpdatedDate = GETDATE() WHERE Code = @itemCode", connection, transaction);
                        updateItemCmd.Parameters.AddWithValue("@newStock", newStock);
                        updateItemCmd.Parameters.AddWithValue("@itemCode", itemCode);
                        updateItemCmd.ExecuteNonQuery();

                        // Use the provided document number as receipt number, or generate one if not provided
                        string receiptNumber = !string.IsNullOrEmpty(documentNo) ? documentNo : GenerateNextReceiptNumber(connection, transaction);

                        // Insert ledger entry
                        var insertLedgerCmd = new SqlCommand(@"
                            INSERT INTO ItemLedgerEntry (EntryDate, ItemCode, VariationId, DocumentType, DocumentNo, ReceiptNo, StoreNo, PosTerminalNo, Quantity, UnitCost, TotalCost, 
                                            Price, Discount, GrossAmount, NetAmount, Description, UserID)
                            VALUES (GETDATE(), @itemCode, @variationId, @documentType, @documentNo, @receiptNo, @storeNo, @posTerminalNo, @quantity, @unitCost, @totalCost, 
                                @price, @discount, @grossAmount, @netAmount, @description, @userID)",
                         connection, transaction);
                        //MessageBox.Show($"Inside process inventory Itemcode {itemCode} documentType = {documentType} description = {description}");
                        insertLedgerCmd.Parameters.AddWithValue("@itemCode", itemCode);
                        insertLedgerCmd.Parameters.AddWithValue("@variationId", variationid ?? string.Empty);
                        insertLedgerCmd.Parameters.AddWithValue("@documentType", documentType);
                        insertLedgerCmd.Parameters.AddWithValue("@documentNo", documentNo ?? "");
                        insertLedgerCmd.Parameters.AddWithValue("@receiptNo", receiptNumber);
                        insertLedgerCmd.Parameters.AddWithValue("@storeNo", storeNo);
                        insertLedgerCmd.Parameters.AddWithValue("@posTerminalNo", posTerminalNo);
                        insertLedgerCmd.Parameters.AddWithValue("@quantity", quantity);
                        insertLedgerCmd.Parameters.AddWithValue("@unitCost", unitCost);
                        insertLedgerCmd.Parameters.AddWithValue("@totalCost", totalCost);
                        insertLedgerCmd.Parameters.AddWithValue("@price", price);
                        insertLedgerCmd.Parameters.AddWithValue("@discount", discount);
                        insertLedgerCmd.Parameters.AddWithValue("@grossAmount", grossAmount);
                        insertLedgerCmd.Parameters.AddWithValue("@netAmount", netAmount);
                        insertLedgerCmd.Parameters.AddWithValue("@description", description ?? "");
                        insertLedgerCmd.Parameters.AddWithValue("@userID", userID);
                        insertLedgerCmd.ExecuteNonQuery();

                        transaction.Commit();
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Inventory posting failed for ItemCode: {itemCode}\nDocumentType: {documentType}\nDescription: {description}\nError: {ex.Message}", "Inventory Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        TryRollbackTransaction(transaction);
                        throw;
                    }
                }
            }
        }

        // Post pending expense lines that were previously recorded in the salesListView with Tag = "EXPENSE"
        private void PostPendingExpenses()
        {
            var expenseItems = salesListView.Items.Cast<ListViewItem>().Where(i => i.Tag?.ToString() == "EXPENSE").ToList();
            if (expenseItems.Count == 0)
            {
                MessageBox.Show("No expense lines to post.", "Post Expenses", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            // Prevent posting if total amount is zero or negative
            decimal expenseTotal = expenseItems.Sum(it => GetListViewItemTotal(it));
            if (expenseTotal <= 0)
            {
                MessageBox.Show("Cannot post expenses with total amount of 0.", "Invalid Total", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            try
            {
                // Ensure we have a receipt number
                // if (string.IsNullOrEmpty(currentReceiptNo))
                currentReceiptNo = GenerateCentralizedReceiptNumber();
                //MessageBox.Show($"Using Receipt No: {currentReceiptNo} for posting expenses.", "Receipt Number", MessageBoxButtons.OK, MessageBoxIcon.Information);
                // Ensure we have a transaction number for payment recording
                currentTransNo = GetNextTransactionNoPlusOne();
                // Create TransactionHeader of Type = EXPENSE
                // Build a header-level description from the expense items (join distinct item descriptions)
                string headerDescription = string.Join("; ", expenseItems.Select(it => it.Text).Where(s => !string.IsNullOrWhiteSpace(s)).Distinct());
                string expenseCategory = string.Join(", ", expenseItems.Select(GetExpenseCategoryForHeader).Where(s => !string.IsNullOrWhiteSpace(s)).Distinct(StringComparer.OrdinalIgnoreCase));
                if (string.IsNullOrWhiteSpace(headerDescription)) headerDescription = "Expense Posting";
                WriteSalesTransactionHeader(currentReceiptNo, "EXPENSE", expenseItems.Sum(it => GetListViewItemTotal(it)), "", headerDescription, expenseCategory);
                RecordPaymentEntry();
                // Post each expense line into ItemLedgerEntry (use PostInventoryEntry)
                foreach (var item in expenseItems)
                {
                    string description = item.Text;
                    int qty = int.Parse(item.SubItems[1].Text);
                    decimal price = decimal.Parse(item.SubItems[2].Text.Replace("?", ""));
                    decimal total = GetListViewItemTotal(item);
                    string code = item.SubItems.Count > 5 ? item.SubItems[5].Text : "";
                    string variationId = item.SubItems.Count > 6 ? item.SubItems[6].Text : string.Empty;

                    // Check if the item code exists in Items table; if not, mark as INC_EXP and use sales list description
                    bool itemExists = false;
                    try
                    {
                        using (var conn = new SqlConnection(connectionString))
                        {
                            conn.Open();
                            if (!string.IsNullOrWhiteSpace(code))
                            {
                                var chkCmd = new SqlCommand("SELECT COUNT(*) FROM Items WHERE Code = @code", conn);
                                chkCmd.Parameters.AddWithValue("@code", code);
                                var res = chkCmd.ExecuteScalar();
                                itemExists = res != null && Convert.ToInt32(res) > 0;
                            }
                        }
                    }
                    catch
                    {
                        // If the check fails for any reason, treat as not found so we still record the expense
                        itemExists = false;
                    }

                    if (!itemExists)
                    {
                        // tag as incidental expense item
                        code = "INC_EXP";
                        // ensure the salesListView shows the INC_EXP code in the Code column
                        if (item.SubItems.Count > 5)
                            item.SubItems[5].Text = code;
                        else
                        {
                            // add Code column if missing and set value
                            EnsureSaleMetadataColumns();
                            while (item.SubItems.Count <= 5)
                                item.SubItems.Add("");
                            item.SubItems[5].Text = code;
                        }

                        // Use salesListView description as ledger description
                        string ledgerDesc = description;

                        // For incidental expenses we record an ItemLedgerEntry with 1 qty but record the cost
                        PostInventoryEntry(code, ledgerDesc, "EXPENSE", currentReceiptNo, 1, 0m, ledgerDesc, price, 0, total, total, variationId, CurrentUser.Username ?? "POS_SYSTEM");
                    }
                    else
                    {
                        // For inventory-tracked items, reduce stock by qty
                        PostInventoryEntry(code, description, "EXPENSE", currentReceiptNo, -qty, 0m, description, price, 0, total, total, variationId, CurrentUser.Username ?? "POS_SYSTEM");
                    }
                }

                // Print expense receipt for the posted expense items (do not block posting on print errors)
                try
                {
                    // Print expense receipt using the header description written to TransactionHeader
                    FunctionEvents.PrintExpenseReceipt(currentReceiptNo, CurrentUser.Username ?? "", expenseItems, expenseItems.Sum(it => GetListViewItemTotal(it)), headerDescription);
                }
                catch
                {
                    // Ignore print errors so posting completes
                }

                try { TriggerCloudInventoryDeductionForCurrentSale(); } catch { }

                // Send this posted Expense Entry to Supabase (ExpenseEntryHeader/ExpenseEntryLines -
                // see supabase_expense_entry_tables.sql). Run in the background, same as
                // TriggerCloudInventoryDeductionForCurrentSale above, so a slow/unreachable Supabase
                // can never block or fail the POST button itself - local posting has already
                // succeeded by this point regardless of whether this sync succeeds.
                try
                {
                    string expenseReceiptNoForSync = currentReceiptNo;
                    string expenseWarehouseNameForSync = TransferOrderData.GetCurrentWarehouse(GlobalSettings.ConnectionString)?.Name ?? string.Empty;
                    _ = Task.Run(async () =>
                    {
                        try
                        {
                            await OnlinefunctionsEvents.SyncExpenseEntryToSupabaseAsync(expenseReceiptNoForSync, expenseWarehouseNameForSync).ConfigureAwait(false);
                        }
                        catch (Exception ex)
                        {
                            try { System.Diagnostics.Trace.TraceError($"Failed to sync expense entry {expenseReceiptNoForSync} to Supabase: {ex}"); } catch { }
                            // Trace.TraceError has no listener configured in this app, so it's normally
                            // invisible outside a debugger - dump the real error to disk too (same
                            // "last_..._payload" debug-file convention OnlinefunctionsEvents.cs already
                            // uses for the Advance Order cloud sync) so a sync failure is actually
                            // diagnosable after the fact.
                            try
                            {
                                string errorDumpPath = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, $"last_expense_entry_sync_error_{expenseReceiptNoForSync}.txt");
                                System.IO.File.WriteAllText(errorDumpPath, ex.ToString(), System.Text.Encoding.UTF8);
                            }
                            catch { }
                        }
                    });
                }
                catch { }

                // Remove expense items from salesListView after posting
                foreach (var item in expenseItems)
                    salesListView.Items.Remove(item);

                // Reset checkout button state (but preserve DOWNPAYMENT flow)
                if (checkoutButton.Tag?.ToString() != "DOWNPAYMENT")
                {
                    checkoutButton.Text = "CHECKOUT";
                    checkoutButton.Tag = "SALES";
                    checkoutButton.BackColor = Color.Green;
                }

                // Recalculate totals
                currentTotal = salesListView.Items.Cast<ListViewItem>().Sum(i => GetListViewItemTotal(i));
                totalPaid = 0; // Payments unaffected but keep simple for now
                UpdateTotal();
                // Clear the entire sale and reset payments after posting Expense
                ClearSaleAndPayments();

                // MessageBox.Show("Expenses posted successfully.", "Post Expenses", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to post expenses: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        // Post pending income lines that were previously recorded in the salesListView with Tag = "INCOME"
        private void PostPendingIncomes()
        {
            var incomeItems = salesListView.Items.Cast<ListViewItem>().Where(i => i.Tag?.ToString() == "INCOME").ToList();
            if (incomeItems.Count == 0)
            {
                MessageBox.Show("No income lines to post.", "Post Incomes", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            // Prevent posting if total amount is zero or negative
            decimal incomeTotal = incomeItems.Sum(it => GetListViewItemTotal(it));
            if (incomeTotal <= 0)
            {
                MessageBox.Show("Cannot post incomes with total amount of 0.", "Invalid Total", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            try
            {
                // Ensure we have a receipt number
                currentReceiptNo = GenerateCentralizedReceiptNumber();
                //MessageBox.Show($"Using Receipt No: {currentReceiptNo} for posting incomes.", "Receipt Number", MessageBoxButtons.OK, MessageBoxIcon.Information);

                // Create TransactionHeader of Type = INCOME
                // Ensure we have a transaction number for payment recording
                currentTransNo = GetNextTransactionNoPlusOne();
                // Build a header-level description from the income items (join distinct item descriptions)
                string headerDescription = string.Join("; ", incomeItems.Select(it => it.Text).Where(s => !string.IsNullOrWhiteSpace(s)).Distinct());
                if (string.IsNullOrWhiteSpace(headerDescription)) headerDescription = "Income Posting";
                WriteSalesTransactionHeader(currentReceiptNo, "INCOME", incomeItems.Sum(it => GetListViewItemTotal(it)), "", headerDescription);

                // Record any recorded payments for these incomes
                RecordPaymentEntry();

                // Post each income line into ItemLedgerEntry (use PostInventoryEntry)
                foreach (var item in incomeItems)
                {
                    string description = item.Text;
                    int qty = int.Parse(item.SubItems[1].Text);
                    decimal price = decimal.Parse(item.SubItems[2].Text.Replace("?", ""));
                    decimal total = GetListViewItemTotal(item);
                    string code = item.SubItems.Count > 5 ? item.SubItems[5].Text : "";

                    bool itemExists = false;
                    try
                    {
                        using (var conn = new SqlConnection(connectionString))
                        {
                            conn.Open();
                            if (!string.IsNullOrWhiteSpace(code))
                            {
                                var chkCmd = new SqlCommand("SELECT COUNT(*) FROM Items WHERE Code = @code", conn);
                                chkCmd.Parameters.AddWithValue("@code", code);
                                var res = chkCmd.ExecuteScalar();
                                itemExists = res != null && Convert.ToInt32(res) > 0;
                            }
                        }
                    }
                    catch
                    {
                        itemExists = false;
                    }

                    if (!itemExists)
                    {
                        // Treat as incidental income - create INC_INC code
                        code = "INC_EXP";
                        if (item.SubItems.Count > 5)
                            item.SubItems[5].Text = code;
                        else
                        {
                            EnsureSaleMetadataColumns();
                            while (item.SubItems.Count <= 5)
                                item.SubItems.Add("");
                            item.SubItems[5].Text = code;
                        }

                        string ledgerDesc = description;
                        // For incidental incomes we record an ItemLedgerEntry with 1 qty but record the amount
                        PostInventoryEntry(code, ledgerDesc, "INCOME", currentReceiptNo, 1, 0m, ledgerDesc, price, 0, total, total, "", CurrentUser.Username ?? "POS_SYSTEM");
                    }
                    else
                    {
                        // For inventory-tracked items, increase stock by qty
                        PostInventoryEntry(code, description, "INCOME", currentReceiptNo, qty, 0m, description, price, 0, total, total, "", CurrentUser.Username ?? "POS_SYSTEM");
                    }
                }

                // Print income receipt for the posted income items
                try
                {
                    // Use the header-level description written to TransactionHeader instead of a hard-coded string
                    FunctionEvents.PrintIncomeReceipt(currentReceiptNo, CurrentUser.Username ?? "", incomeItems, incomeItems.Sum(it => GetListViewItemTotal(it)), headerDescription);
                }
                catch
                {
                }

                try { TriggerCloudInventoryDeductionForCurrentSale(); } catch { }


                // Clear the entire sale and reset payments after posting incomes
                ClearSaleAndPayments();
                // Ensure UI cleared
                salesListView.Items.Clear();
                // Restore checkout button state if not in downpayment flow
                if (checkoutButton.Tag?.ToString() != "DOWNPAYMENT")
                {
                    checkoutButton.Text = "CHECKOUT";
                    checkoutButton.Tag = "SALES";
                    checkoutButton.BackColor = Color.Green;
                }

                // Recalculate totals/UI
                UpdateTotal();

                //  MessageBox.Show("Incomes posted successfully.", "Post Incomes", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to post incomes: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

