                    Size = new Size(1760, 550),
                    ReadOnly = true,
                    AllowUserToAddRows = false,
                    AllowUserToDeleteRows = false,
                    AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.None,
                    ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.AutoSize,
                    SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                    BackgroundColor = Color.White,
                    BorderStyle = BorderStyle.Fixed3D,
                    RowHeadersVisible = false
                };

                // Add columns
                dataGridView.Columns.Add("EntryNo", "Entry #");
                dataGridView.Columns.Add("EntryDate", "Date");
                dataGridView.Columns.Add("EntryTime", "Time");
                dataGridView.Columns.Add("StoreNo", "Store #");
                dataGridView.Columns.Add("PosTerminalNo", "POS #");
                dataGridView.Columns.Add("ReceiptNo", "Receipt No.");
                dataGridView.Columns.Add("ItemCode", "Item Code");
                dataGridView.Columns.Add("ItemName", "Item Name");
                dataGridView.Columns.Add("DocumentType", "Document Type");
                dataGridView.Columns.Add("DocumentNo", "Document #");
                dataGridView.Columns.Add("Quantity", "Quantity");
                dataGridView.Columns.Add("UnitCost", "Unit Cost");
                dataGridView.Columns.Add("TotalCost", "Total Cost");
                dataGridView.Columns.Add("Price", "Price");
                dataGridView.Columns.Add("Discount", "Discount");
                dataGridView.Columns.Add("GrossAmount", "Gross Amount");
                dataGridView.Columns.Add("NetAmount", "Net Amount");
                dataGridView.Columns.Add("RemainingQuantity", "Balance");
                dataGridView.Columns.Add("UserID", "User ID");
                dataGridView.Columns.Add("Description", "Description");

                // Set column widths
                dataGridView.Columns["EntryNo"].Width = 60;
                dataGridView.Columns["EntryDate"].Width = 80;
                dataGridView.Columns["EntryTime"].Width = 70;
                dataGridView.Columns["StoreNo"].Width = 60;
                dataGridView.Columns["PosTerminalNo"].Width = 60;
                dataGridView.Columns["ReceiptNo"].Width = 100;
                dataGridView.Columns["ItemCode"].Width = 80;
                dataGridView.Columns["ItemName"].Width = 120;
                dataGridView.Columns["DocumentType"].Width = 90;
                dataGridView.Columns["DocumentNo"].Width = 90;
                dataGridView.Columns["Quantity"].Width = 60;
                dataGridView.Columns["UnitCost"].Width = 70;
                dataGridView.Columns["TotalCost"].Width = 80;
                dataGridView.Columns["Price"].Width = 70;
                dataGridView.Columns["Discount"].Width = 70;
                dataGridView.Columns["GrossAmount"].Width = 80;
                dataGridView.Columns["NetAmount"].Width = 80;
                dataGridView.Columns["RemainingQuantity"].Width = 60;
                dataGridView.Columns["UserID"].Width = 80;
                dataGridView.Columns["Description"].Width = 150;

                // Format columns
                dataGridView.Columns["UnitCost"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["TotalCost"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["Price"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["Discount"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["GrossAmount"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["NetAmount"].DefaultCellStyle.Format = "C2";
                dataGridView.Columns["Quantity"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleCenter;
                dataGridView.Columns["RemainingQuantity"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleCenter;

                var countLabel = new Label
                {
                    Text = "Total Entries: 0",
                    Location = new Point(10, 610),
                    Size = new Size(200, 20),
                    Font = new Font("Arial", 10, FontStyle.Bold),
                    ForeColor = Color.DarkBlue
                };

                Action RefreshLedger = () =>
                {
                    dataGridView.Rows.Clear();
                    int rowCount = 0;

                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();

                        // Load items for combo box if empty
                        if (itemComboBox.Items.Count == 1)
                        {
                            var itemCmd = new SqlCommand("SELECT Code, Name FROM Items ORDER BY Name", connection);
                            using (var reader = itemCmd.ExecuteReader())
                            {
                                while (reader.Read())
                                {
                                    itemComboBox.Items.Add($"{reader["Code"]}");
                                }
                            }
                        }

                        // Build query with filters - join with Items table to get item name and calculate running balance
                        var query = @"
                            SELECT 
                                ile.ID as EntryNo,
                                ile.EntryDate,
                                ile.ItemCode,
                                i.Name as ItemName,
                                ile.DocumentType,
                                ile.DocumentNo,
                                ISNULL(ile.ReceiptNo, '') as ReceiptNo,
                                ISNULL(ile.StoreNo, '001') as StoreNo,
                                ISNULL(ile.PosTerminalNo, '001') as PosTerminalNo,
                                ile.Quantity,
                                ile.UnitCost,
                                ile.TotalCost,
                                ISNULL(ile.Price, 0) as Price,
                                ISNULL(ile.Discount, 0) as Discount,
                                ISNULL(ile.GrossAmount, 0) as GrossAmount,
                                ISNULL(ile.NetAmount, 0) as NetAmount,
                                (SELECT ISNULL(SUM(ile2.Quantity), 0) FROM ItemLedgerEntry ile2 WHERE ile2.ItemCode = ile.ItemCode) as RemainingQuantity,
                                ile.UserID,
                                ISNULL(ile.Description, '') as Description
                            FROM ItemLedgerEntry ile
                            LEFT JOIN Items i ON i.Code = ile.ItemCode
                            WHERE 1 = 1";

                        var parameters = new List<SqlParameter>();

                        if (itemComboBox.SelectedIndex > 0)
                        {
                            query += " AND ile.ItemCode = @itemCode";
                            parameters.Add(new SqlParameter("@itemCode", itemComboBox.SelectedItem?.ToString() ?? string.Empty));
                        }

                        if (docTypeComboBox.SelectedIndex > 0)
                        {
                            query += " AND ile.DocumentType = @docType";
                            parameters.Add(new SqlParameter("@docType", docTypeComboBox.SelectedItem?.ToString() ?? string.Empty));
                        }

                        if (!string.IsNullOrWhiteSpace(receiptTextBox.Text))
                        {
                            query += " AND ile.ReceiptNo = @receiptNo";
                            parameters.Add(new SqlParameter("@receiptNo", receiptTextBox.Text.Trim()));
                        }

                        query += " AND CAST(ile.EntryDate AS date) BETWEEN @fromDate AND @toDate";
                        parameters.Add(new SqlParameter("@fromDate", fromDatePicker.Value.Date));
                        parameters.Add(new SqlParameter("@toDate", toDatePicker.Value.Date));

                        query += " ORDER BY ile.ID DESC";

                        var command = new SqlCommand(query, connection);
                        command.Parameters.AddRange(parameters.ToArray());

                        using (var reader = command.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                int entryNo = Convert.ToInt32(reader["EntryNo"]);
                                DateTime entryDate = Convert.ToDateTime(reader["EntryDate"]);
                                string itemCode = reader["ItemCode"].ToString() ?? "";
                                string itemName = reader["ItemName"].ToString() ?? "";
                                string docType = reader["DocumentType"].ToString() ?? "";
                                string docNo = reader["DocumentNo"].ToString() ?? "";
                                string receiptNo = reader["ReceiptNo"].ToString() ?? "";
                                string storeNo = reader["StoreNo"].ToString() ?? "";
                                string posTerminalNo = reader["PosTerminalNo"].ToString() ?? "";
                                int quantity = Convert.ToInt32(reader["Quantity"]);
                                decimal unitCost = Convert.ToDecimal(reader["UnitCost"]);
                                decimal totalCost = Convert.ToDecimal(reader["TotalCost"]);
                                decimal price = Convert.ToDecimal(reader["Price"]);
                                decimal discount = Convert.ToDecimal(reader["Discount"]);
                                decimal grossAmount = Convert.ToDecimal(reader["GrossAmount"]);
                                decimal netAmount = Convert.ToDecimal(reader["NetAmount"]);
                                int balance = Convert.ToInt32(reader["RemainingQuantity"]);
                                string userID = reader["UserID"].ToString() ?? "";
                                string description = reader["Description"].ToString() ?? "";

                                var row = dataGridView.Rows.Add(entryNo, entryDate.ToString("MM/dd/yyyy"), entryDate.ToString("HH:mm:ss"),
                                                              storeNo, posTerminalNo, receiptNo, itemCode, itemName, docType, docNo, quantity, unitCost,
                                                              totalCost, price, discount, grossAmount, netAmount, balance, userID, description);

                                // Color code rows based on document type
                                switch (docType)
                                {
                                    case "POSITIVE_ADJ":
                                        dataGridView.Rows[row].DefaultCellStyle.BackColor = Color.LightGreen;
                                        break;
                                    case "NEGATIVE_ADJ":
                                        dataGridView.Rows[row].DefaultCellStyle.BackColor = Color.LightCoral;
                                        break;
                                    case "SALES":
                                        dataGridView.Rows[row].DefaultCellStyle.BackColor = Color.LightBlue;
                                        break;
                                    case "REFUND":
                                        dataGridView.Rows[row].DefaultCellStyle.BackColor = Color.LightYellow;
                                        break;
                                    case "INITIAL":
                                        dataGridView.Rows[row].DefaultCellStyle.BackColor = Color.LightGray;
                                        break;
                                }

                                rowCount++;
                            }
                        }
                    }

                    countLabel.Text = $"Total Entries: {rowCount}";
                };

                refreshButton.Click += (s, args) => RefreshLedger();

                var closeButton = new Button
                {
                    Text = "Close",
                    Location = new Point(1350, 610),
                    Size = new Size(80, 30),
                    BackColor = Color.DarkBlue,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold)
                };
                closeButton.Click += (s, args) => ledgerForm.Close();

                ledgerForm.Controls.AddRange(new Control[] {
                    itemLabel, itemComboBox, docTypeLabel, docTypeComboBox,
                    receiptLabel, receiptTextBox, fromDateLabel, fromDatePicker,
                    toDateLabel, toDatePicker, refreshButton,
                    dataGridView, countLabel, closeButton
                });

                // First refresh to populate items
                RefreshLedger();

                // Pre-select item if selectedItemCode is provided
                if (!string.IsNullOrWhiteSpace(selectedItemCode))
                {
                    for (int i = 1; i < itemComboBox.Items.Count; i++)
                    {
                        string itemText = itemComboBox.Items[i].ToString() ?? "";
                        if (itemText.StartsWith(selectedItemCode + " -"))
                        {
                            itemComboBox.SelectedIndex = i;
                            RefreshLedger(); // Refresh with the selected item filter
                            break;
                        }
                    }
                }

                ledgerForm.ShowDialog();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to open Inventory Ledger: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

