        // Update AddToSale method to post inventory entries
        private void UpdateAddToSaleForInventory(string itemName, int quantity, decimal price)
        {
            try
            {
                // Find item ID
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var cmd = new SqlCommand("SELECT Code, Cost FROM Items WHERE Name = @name", connection);
                    cmd.Parameters.AddWithValue("@name", itemName);
                    using (var reader = cmd.ExecuteReader())
                    {
                        if (reader.Read())
                        {
                            string itemCode = reader["Code"].ToString() ?? "";
                            decimal cost = reader["Cost"] != DBNull.Value ? Convert.ToDecimal(reader["Cost"]) : 0;

                            // Post negative inventory entry for sale
                            PostInventoryEntry(itemCode, itemName, "SALES", $"SALE-{DateTime.Now:yyyyMMdd-HHmmss}",
                                             -quantity, cost, $"Sale - {quantity} unit(s) at {price:N2} each", price, 0, price * quantity, price * quantity, "", CurrentUser.Username ?? "SYSTEM");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                // Don't let inventory errors break the sale process
                MessageBox.Show($"Warning: Could not update inventory ledger: {ex.Message}", "Inventory Warning",
                              MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        // Record sales inventory movements when checkout is completed
        private void RecordSalesInventoryMovements(string receiptNo)
        {
            if (salesListView.Items.Count == 0) return;

            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    using (var transaction = connection.BeginTransaction())
                    {
                        try
                        {
                            var processedItemCodes = new HashSet<string>();

                            // Process each item in the sale
                            foreach (ListViewItem saleItem in salesListView.Items)
                            {
                                string itemName = saleItem.Text;

                                int quantity = int.Parse(saleItem.SubItems[1].Text);
                                decimal unitPrice = decimal.Parse(saleItem.SubItems[2].Text.Replace("?", ""));

                                // Use item name directly as item code
                                string itemCode = itemName;
                                decimal cost = unitPrice * 0.7m; // Estimate cost as 70% of selling price

                                // Always create inventory ledger entry (for both database items and custom items)
                                {
                                    // Calculate sales amounts
                                    decimal itemTotal = unitPrice * quantity;
                                    decimal itemDiscountRate = currentDiscount > 0 && currentTotal > 0 ? currentDiscount / currentTotal : 0; // Proportional discount
                                    decimal itemDiscount = itemTotal * itemDiscountRate;
                                    decimal grossAmount = itemTotal;
                                    decimal netAmount = itemTotal - itemDiscount;

                                    // Create detailed inventory ledger entry for each item sale - Type = SALES
                                    var ledgerCmd = new SqlCommand(@"
                                        INSERT INTO ItemLedgerEntry (EntryDate, ItemCode, DocumentType, ReceiptNo, DocumentNo, Quantity, UnitCost, TotalCost, 
                                                                    Price, Discount, GrossAmount, NetAmount, Description, UserID, StoreNo, PosTerminalNo)
                                        VALUES (GETDATE(), @itemCode, 'SALES', @receiptNo, @docNo, @quantity, @unitCost, @totalCost, 
                                               @price, @discount, @grossAmount, @netAmount, @description, @userID, '001', '001')",
                                        connection, transaction);
                                    //MessageBox.Show($"2Inside process inventory Itemcode {itemCode}");
                                    ledgerCmd.Parameters.AddWithValue("@itemCode", itemCode);
                                    ledgerCmd.Parameters.AddWithValue("@receiptNo", receiptNo);
                                    ledgerCmd.Parameters.AddWithValue("@docNo", receiptNo);
                                    ledgerCmd.Parameters.AddWithValue("@quantity", -quantity); // Negative quantity for sales (inventory deduction)
                                    ledgerCmd.Parameters.AddWithValue("@unitCost", cost);
                                    ledgerCmd.Parameters.AddWithValue("@totalCost", cost * quantity);
                                    ledgerCmd.Parameters.AddWithValue("@price", unitPrice);
                                    ledgerCmd.Parameters.AddWithValue("@discount", itemDiscount);
                                    ledgerCmd.Parameters.AddWithValue("@grossAmount", grossAmount);
                                    ledgerCmd.Parameters.AddWithValue("@netAmount", netAmount);
                                    ledgerCmd.Parameters.AddWithValue("@userID", CurrentUser.Username ?? "POS_SYSTEM");
                                    ledgerCmd.Parameters.AddWithValue("@description",
                                        $"SALES - {itemName}: Sold {quantity} unit(s) @ {unitPrice:N2} each | Receipt: {receiptNo} | Gross: {grossAmount:N2} | Discount: {itemDiscount:N2} | Net: {netAmount:N2} | Cost: {cost:N2}");

                                    ledgerCmd.ExecuteNonQuery();

                                    // Log inventory movement for debugging/audit trail
                                    System.Diagnostics.Debug.WriteLine($"Inventory Ledger Entry Created: {itemCode} - SALES - Qty: -{quantity} - Receipt: {receiptNo}");

                                    // Only recalculate stock for actual database items (not custom items)
                                    if (!itemCode.StartsWith("CUSTOM_") && !processedItemCodes.Contains(itemCode))
                                    {
                                        // Recalculate stock from ItemLedgerEntry (SALES and REFUND)
                                        var recalcStockCmd = new SqlCommand(@"
                                            SELECT ISNULL(SUM(CASE WHEN DocumentType IN ('SALES', 'REFUND') THEN Quantity ELSE 0 END), 0)
                                            FROM ItemLedgerEntry WHERE ItemCode = @itemCode", connection, transaction);
                                        recalcStockCmd.Parameters.AddWithValue("@itemCode", itemCode);
                                        int recalculatedStock = Convert.ToInt32(recalcStockCmd.ExecuteScalar());

                                        // Update Items.QuantityInStock to recalculated value
                                        var updateStockCmd = new SqlCommand(
                                            "UPDATE Items SET QuantityInStock = @stock, UpdatedDate = GETDATE() WHERE Code = @code", connection, transaction);
                                        updateStockCmd.Parameters.AddWithValue("@stock", recalculatedStock);
                                        updateStockCmd.Parameters.AddWithValue("@code", itemCode);
                                        updateStockCmd.ExecuteNonQuery();

                                        processedItemCodes.Add(itemCode);
                                    }
                                }
                            }

                            // Commit the transaction
                            transaction.Commit();
                        }
                        catch
                        {
                            TryRollbackTransaction(transaction);
                            throw;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                throw new Exception($"Failed to record sales inventory movements: {ex.Message}", ex);
            }
        }

        // Write sales transaction header entry when checkout is completed
        public void WriteSalesTransactionHeader(string receiptNo, string type = "SALES", decimal? amount = null, string eodID = "", string TransDescription = "", string expenseCategory = "")
        {
            try
            {
                string connectionString = GlobalSettings.ConnectionString;
                using (SqlConnection conn = new SqlConnection(connectionString))
                {
                    conn.Open();

                    // Get the next transaction number
                    int storeNo = 1; // Default store number
                    int posTerminalNo = 1; // Default POS terminal number

                    var transCmd = new SqlCommand(@"SELECT ISNULL(MAX(TransactionNo), 0) + 1 FROM TransactionHeader WHERE StoreNo = @storeNo AND POSTerminalNo = @posTerminalNo", conn);
                    transCmd.Parameters.AddWithValue("@storeNo", storeNo);
                    transCmd.Parameters.AddWithValue("@posTerminalNo", posTerminalNo);
                    int nextTransactionNo = (int)transCmd.ExecuteScalar();

                    // Calculate total sales items count (only for SALES type)
                    int totalQuantity = 0;
                    decimal totalAmount = 0;
                    if (amount.HasValue && amount.Value != 0)
                    {
                        totalAmount = amount.Value;
                    }
                    string description;
                    if (!string.IsNullOrWhiteSpace(TransDescription))
                    {
                        description = TransDescription;
                    }
                    else
                    {
                        if (type == "SALES" && salesListView != null)
                        {
                            foreach (ListViewItem item in salesListView.Items)
                            {
                                totalQuantity += int.Parse(item.SubItems[1].Text);
                            }
                            if (totalAmount == 0)
                            {
                                totalAmount = currentTotal;
                            }
                            description = $"Sales transaction with {salesListView.Items.Count} item(s), Total Qty: {totalQuantity}";
                        }
                        else if (type == "TenderDecl")
                        {
                            totalQuantity = 1;
                            totalAmount = amount ?? 0; // Use passed amount or default to 0
                            description = "Tender Declaration";
                        }
                        else
                        {
                            description = "";
                            totalAmount = amount ?? 0; // Use passed amount or default to 0
                        }
                    }

                    decimal aquariumSetPromotionTotal = string.Equals(type, "SALES", StringComparison.OrdinalIgnoreCase)
                        ? GetAquariumSetPromotionTotal()
                        : 0m;
                    string aquariumSetPackages = string.Equals(type, "SALES", StringComparison.OrdinalIgnoreCase)
                        ? GetAquariumSetPromotionPackageSummary()
                        : string.Empty;

                    if (!string.IsNullOrWhiteSpace(aquariumSetPackages))
                    {
                        string aquariumPackageNote = $"Aquarium Package: {aquariumSetPackages}";
                        if (aquariumSetPromotionTotal > 0m)
                        {
                            aquariumPackageNote += $" | Promotion: {aquariumSetPromotionTotal:F2}";
                        }

                        if (string.IsNullOrWhiteSpace(description))
                        {
                            description = aquariumPackageNote;
                        }
                        else if (description.IndexOf(aquariumPackageNote, StringComparison.OrdinalIgnoreCase) < 0)
                        {
                            description = $"{description} | {aquariumPackageNote}";
                        }
                    }

                    // Insert the sales transaction header
                    string query = @"INSERT INTO TransactionHeader (
                            StoreNo, POSTerminalNo, TransactionNo, ReceiptNo, Type, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, UserID, Description, DiscountDescription, EODID, SalesPerson, ExpenseCategory
                        ) VALUES (
                            @StoreNo, @POSTerminalNo, @TransactionNo, @ReceiptNo, @Type, @Quantity, @Price, @Discount, @GrossAmount, @NetAmount, @Date, @Time, @UserID, @Description, @DiscountDescription, @EODID, @SalesPerson, @ExpenseCategory
                        )";

                    using (SqlCommand cmd = new SqlCommand(query, conn))
                    {

                        cmd.Parameters.AddWithValue("@StoreNo", storeNo);
                        cmd.Parameters.AddWithValue("@POSTerminalNo", posTerminalNo);
                        cmd.Parameters.AddWithValue("@TransactionNo", nextTransactionNo);
                        cmd.Parameters.AddWithValue("@ReceiptNo", receiptNo);
                        cmd.Parameters.AddWithValue("@Type", type);
                        cmd.Parameters.AddWithValue("@Quantity", 1);
                        // If a totalAmount was explicitly provided (non-zero), prefer that in printouts/records.
                        decimal usedPrice = (totalAmount != 0m) ? totalAmount : (type == "SALES" ? currentTotal : totalAmount);
                        decimal headerDiscount = type == "SALES" ? currentDiscount + aquariumSetPromotionTotal : 0m;
                        decimal usedNet = (totalAmount != 0m) ? totalAmount : (type == "SALES" ? grandTotal : totalAmount);
                        decimal usedGross = type == "SALES" ? usedNet + headerDiscount : usedPrice;

                        cmd.Parameters.AddWithValue("@Price", usedPrice);
                        cmd.Parameters.AddWithValue("@Discount", headerDiscount);
                        cmd.Parameters.AddWithValue("@GrossAmount", usedGross);
                        cmd.Parameters.AddWithValue("@NetAmount", usedNet);
                        cmd.Parameters.AddWithValue("@Date", DateTime.Now);
                        cmd.Parameters.AddWithValue("@Time", DateTime.Now.ToString("HH:mm:ss"));
                        cmd.Parameters.AddWithValue("@UserID", CurrentUser.Username ?? "POS_SYSTEM");
                        // Ensure description fits TransactionHeader.Description NVARCHAR(255)
                        string safeDescription = description ?? string.Empty;
                        if (safeDescription.Length > 255)
                        {
                            // Truncate to avoid SQL exception. Log the truncation for diagnostics.
                            System.Diagnostics.Debug.WriteLine($"TransactionHeader.Description truncated from {safeDescription.Length} to 255 chars. Original: {safeDescription}");
                            safeDescription = safeDescription.Substring(0, 255);
                        }
                        cmd.Parameters.AddWithValue("@Description", safeDescription);
                        cmd.Parameters.AddWithValue("@DiscountDescription", type == "SALES" && currentDiscount > 0m && !string.IsNullOrWhiteSpace(currentDiscountDescription)
                            ? currentDiscountDescription
                            : (object)DBNull.Value);
                        cmd.Parameters.AddWithValue("@EODID", eodID);

                        // Persist selected salesperson at post-time (TransactionHeader.SalesPerson NVARCHAR(50)).
                        // Prefer the human-readable name if available, otherwise the code.
                        string salesPersonValue = !string.IsNullOrWhiteSpace(currentSalesPersonName)
                            ? currentSalesPersonName!
                            : (!string.IsNullOrWhiteSpace(currentSalesPersonCode) ? currentSalesPersonCode! : string.Empty);
                        if (salesPersonValue.Length > 50)
                            salesPersonValue = salesPersonValue.Substring(0, 50);
                        cmd.Parameters.AddWithValue("@SalesPerson", salesPersonValue);

                        string safeExpenseCategory = expenseCategory ?? string.Empty;
                        if (safeExpenseCategory.Length > 100)
                        {
                            safeExpenseCategory = safeExpenseCategory.Substring(0, 100);
                        }
                        cmd.Parameters.AddWithValue("@ExpenseCategory", string.Equals(type, "EXPENSE", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(safeExpenseCategory)
                            ? safeExpenseCategory
                            : (object)DBNull.Value);

                        cmd.ExecuteNonQuery();
                    }

                    // Insert payment entry into TransPaymentEntry table
                    // First, get the next LineNo for this receipt
                    string getNextLineNoQuery = @"
                        SELECT ISNULL(MAX([LineNo]), 0) + 1 
                        FROM TransPaymentEntry 
                        WHERE (EODID IS NULL OR LTRIM(RTRIM(EODID)) = '')";

                    int nextLineNo = 1;
                    using (SqlCommand lineNoCmd = new SqlCommand(getNextLineNoQuery, conn))
                    {
                        lineNoCmd.Parameters.AddWithValue("@ReceiptNo", receiptNo);
                        var result = lineNoCmd.ExecuteScalar();
                        if (result != null && result != DBNull.Value)
                        {
                            nextLineNo = Convert.ToInt32(result);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                throw new Exception($"Failed to write sales transaction header: {ex.Message}", ex);
            }
        }

        // Printing Methods

        public void PrintTenderDeclReceipt(string receiptNo)
        {
            // Generate only the tender declaration receipt content
            var receipt = new System.Text.StringBuilder();
            string line = new string('-', 40);

            receipt.AppendLine("         RS PET STOP");
            receipt.AppendLine("    AQUARIUM PRODUCTS & SOLUTIONS");
            receipt.AppendLine(line);
            receipt.AppendLine($"Date: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
            receipt.AppendLine($"Receipt #: {receiptNo}");
            receipt.AppendLine($"Cashier: {username}");
            receipt.AppendLine(line);
            receipt.AppendLine("     TENDER DECLARATION");
            receipt.AppendLine(line);
            try
            {
                string connectionString = GlobalSettings.ConnectionString;
                using (var conn = new SqlConnection(connectionString))
                {
                    conn.Open();
                    decimal declaredCash = 0;
                    string query = @"SELECT Denomination, Qty, TotalAmount FROM TenderDeclLines WHERE ReceiptNo = @ReceiptNo ORDER BY Denomination DESC";
                    var declLines = new System.Collections.Generic.List<(decimal Denom, int Qty, decimal Total)>();
                    using (var cmd = new SqlCommand(query, conn))
                    {
                        cmd.Parameters.AddWithValue("@ReceiptNo", receiptNo);
                        using (var reader = cmd.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                decimal denom = reader["Denomination"] != DBNull.Value ? Convert.ToDecimal(reader["Denomination"]) : 0;
                                int qty = reader["Qty"] != DBNull.Value ? Convert.ToInt32(reader["Qty"]) : 0;
                                decimal total = reader["TotalAmount"] != DBNull.Value ? Convert.ToDecimal(reader["TotalAmount"]) : 0;
                                declLines.Add((denom, qty, total));
                                declaredCash += total;
                            }
                        }
                    }

                    // Group into coins and notes. Treat denominations < 20 as coins, >= 20 as notes.
                    var coins = declLines.Where(d => d.Denom < 20m).OrderByDescending(d => d.Denom).ToList();
                    var notes = declLines.Where(d => d.Denom >= 20m).OrderByDescending(d => d.Denom).ToList();

                    // Print coins group if any
                    if (coins.Count > 0)
                    {
                        receipt.AppendLine("COINS:");
                        receipt.AppendLine($"{"Denomination",-12} {"Qty",-5} {"Total",-12}");
                        decimal coinsTotal = 0m;
                        foreach (var c in coins)
                        {
                            receipt.AppendLine($"P{c.Denom,-10:F2} {c.Qty,-5} P{c.Total,-10:F2}");
                            coinsTotal += c.Total;
                        }
                        // Limit the label area for Coins Total to 11 characters
                        string coinsLabel = "Coins Total:";
                        if (coinsLabel.Length > 11) coinsLabel = coinsLabel.Substring(0, 11);
                        receipt.AppendLine($"{coinsLabel,-11} P{coinsTotal,10:F2}");
                        receipt.AppendLine();
                    }

                    // Print notes group if any
                    if (notes.Count > 0)
                    {
                        receipt.AppendLine("NOTES:");
                        receipt.AppendLine($"{"Denomination",-12} {"Qty",-5} {"Total",-12}");
                        decimal notesTotal = 0m;
                        foreach (var n in notes)
                        {
                            receipt.AppendLine($"P{n.Denom,-10:F2} {n.Qty,-5} P{n.Total,-10:F2}");
                            notesTotal += n.Total;
                        }
                        receipt.AppendLine($"{"Notes Total:",-11} P{notesTotal,10:F2}");
                        receipt.AppendLine();
                    }

                    // Show total sales by tender type (source: TransPaymentEntry only)
                    receipt.AppendLine();
                    receipt.AppendLine("SALES BY TENDER TYPE:");
                    receipt.AppendLine(line);
                    // Query direct totals from TransPaymentEntry (do not join TransactionHeader)
                    string tenderTypeQuery = @"
                        SELECT TenderTypeCode, SUM(Amount) AS Total
                        FROM TransPaymentEntry
                        WHERE (EODID IS NULL OR EODID = '')
                        GROUP BY TenderTypeCode";
                    decimal totalSalesCash = 0;
                    using (var tenderCmd = new SqlCommand(tenderTypeQuery, conn))
                    {
                        using (var tenderReader = tenderCmd.ExecuteReader())
                        {
                            receipt.AppendLine($"{"Tender Type",-11} {"Total",-15}");
                            while (tenderReader.Read())
                            {
                                string tenderType = tenderReader["TenderTypeCode"].ToString() ?? "";
                                decimal tenderTotal = tenderReader["Total"] != DBNull.Value ? Convert.ToDecimal(tenderReader["Total"]) : 0;
                                if (tenderType.Equals("CASH", StringComparison.OrdinalIgnoreCase))
                                {
                                    totalSalesCash += tenderTotal;
                                }

                                receipt.AppendLine($"{tenderType,-8} P{tenderTotal,-14:F2}");
                            }
                        }
                    }

                    receipt.AppendLine();
                    receipt.AppendLine("ADVANCE ORDER COLLECTIONS:");
                    receipt.AppendLine(line);

                    string advanceCollectionQuery = @"
                        SELECT te.TenderTypeCode, SUM(te.Amount) AS Total
                        FROM TransPaymentEntry te
                        WHERE (te.EODID IS NULL OR te.EODID = '')
                          AND EXISTS (
                              SELECT 1
                              FROM AdvanceOrderHeader ah
                              WHERE ah.ReceiptNo = te.ReceiptNo
                          )
                        GROUP BY te.TenderTypeCode
                        ORDER BY te.TenderTypeCode";
                    decimal totalAdvanceCollections = 0m;
                    using (var advanceCmd = new SqlCommand(advanceCollectionQuery, conn))
                    {
                        using (var advanceReader = advanceCmd.ExecuteReader())
                        {
                            receipt.AppendLine($"{"Tender Type",-11} {"Total",-15}");
                            while (advanceReader.Read())
                            {
                                string tenderType = advanceReader["TenderTypeCode"].ToString() ?? "";
                                decimal tenderTotal = advanceReader["Total"] != DBNull.Value ? Convert.ToDecimal(advanceReader["Total"]) : 0m;
                                totalAdvanceCollections += tenderTotal;
                                receipt.AppendLine($"{tenderType,-8} P{tenderTotal,-14:F2}");
                            }
                        }
                    }
                    receipt.AppendLine($"ADV COLLECT P{totalAdvanceCollections,-14:F2}");

                    // Only count expenses that were paid with CASH (check TransPaymentEntry for TenderTypeCode = 'CASH')
                    string expenseQuery = @"
                        SELECT SUM(th.Price)
                        FROM TransactionHeader th
                        INNER JOIN TransPaymentEntry te ON te.ReceiptNo = th.ReceiptNo
                        WHERE th.Type = 'EXPENSE'
                        AND (th.EODID IS NULL OR th.EODID = '')
                        AND (te.EODID IS NULL OR te.EODID = '')
                        AND te.TenderTypeCode = 'CASH'";
                    decimal totalExpense = 0;
                    using (var expenseCmd = new SqlCommand(expenseQuery, conn))
                    {
                        var result = expenseCmd.ExecuteScalar();
                        if (result != null && result != DBNull.Value)
                        {
                            totalExpense = Convert.ToDecimal(result);
                        }
                    }


                    // Show discrepancy
                    // Calculate total Float_Entry
                    decimal totalFloatEntry = 0;
                    string floatEntryQuery = @"SELECT SUM(TotalAmount) FROM CashFloatLines WHERE (EODID IS NULL OR EODID = '')";
                    using (var floatCmd = new SqlCommand(floatEntryQuery, conn))
                    {
                        var result = floatCmd.ExecuteScalar();
                        if (result != null && result != DBNull.Value)
                        {
                            totalFloatEntry = Convert.ToDecimal(result);
                        }
                    }

                    //MessageBox.Show($"Print Tender types declared {totalFloatEntry}");
                    receipt.AppendLine(line);
                    receipt.AppendLine("TOTALS");
                    receipt.AppendLine(line);
                    receipt.AppendLine(string.Format("{0,-12} P{1:F2}", "Float:", totalFloatEntry));
                    receipt.AppendLine(string.Format("{0,-12} P{1:F2}", "Sales by Cash:", totalSalesCash - totalExpense));
                    // Income should come from TransPaymentEntry (TenderTypeCode='CASH') where the TransactionHeader.Type = 'INCOME'
                    decimal income = 0m;
                    try
                    {
                        string incomeQuery = @"
                            SELECT SUM(te.Amount)
                            FROM TransPaymentEntry te
                            INNER JOIN TransactionHeader th ON th.ReceiptNo = te.ReceiptNo
                            WHERE te.TenderTypeCode = 'CASH' AND th.Type = 'INCOME'
                            AND (te.EODID IS NULL OR te.EODID = '')
                            AND (th.EODID IS NULL OR th.EODID = '')";
                        using (var incomeCmd = new SqlCommand(incomeQuery, conn))
                        {
                            var incRes = incomeCmd.ExecuteScalar();
                            if (incRes != null && incRes != DBNull.Value)
                                income = Convert.ToDecimal(incRes);
                        }
                    }
                    catch
                    {
                        income = 0m; // fallback on error
                    }

                    receipt.AppendLine(string.Format("{0,-12} P{1:F2}", "INCOME:", income));
                    // Show expense and declared as negative values (print the negative sign with the number)
                    receipt.AppendLine(string.Format("{0,-12} P{1:F2}", "Expense:", -totalExpense));
                    receipt.AppendLine(string.Format("{0,-12} P{1:F2}", "Cash Declared:", -declaredCash));
                    // receipt.AppendLine(string.Format("{0,-25} ?{1:N2}", "Discrepancy:", discrepancy));
                    // Compute discrepancy after income has been retrieved
                    decimal discrepancy = totalFloatEntry + totalSalesCash - totalExpense + income - totalExpense - declaredCash;

                    // Debug: show intermediate values so the user can trace calculations (formatted for readability)
                    string discrepancyWord = discrepancy < 0 ? "Over" : (discrepancy > 0 ? "Short" : "");
                    receipt.AppendLine(string.Format("{0,-0} P{1:F2} {2}", ":", discrepancy, discrepancyWord));
                }
            }
            catch { }

            // receipt.AppendLine(line);
            // receipt.AppendLine();
            // receipt.AppendLine("        THANK YOU!");
            // receipt.AppendLine("     COME AGAIN SOON!");
            // receipt.AppendLine();
            // receipt.AppendLine(line);
            // receipt.AppendLine();

            receiptContent = receipt.ToString();
            printDocument.Print();
        }

        public void PrintAdvanceOrderReceipt(string receiptNo, string customerName, string orderDescription, decimal downpayment, decimal balance)
        {
            // Generate advance order receipt content
            var receipt = new System.Text.StringBuilder();
            string line = new string('-', GlobalSettings.ReceiptWidth);
            string onlineOrderId = OnlinefunctionsEvents.GetMappedOnlineOrderIdForReceipt(receiptNo);
            //MessageBox.Show($"inside printing balance {balance}");
            // Header - centered for 58mm
            receipt.AppendLine("      RS PET STOP");
            receipt.AppendLine("  AQUARIUM PRODUCTS");
            receipt.AppendLine("   & SOLUTIONS");
            receipt.AppendLine(line);
            receipt.AppendLine($"Date: {DateTime.Now:yyyy-MM-dd HH:mm}");
            receipt.AppendLine($"Receipt #: {receiptNo}");
            if (!string.IsNullOrWhiteSpace(onlineOrderId))
            {
                receipt.AppendLine($"Online Order ID: {onlineOrderId}");
            }
            receipt.AppendLine($"Cashier: {CurrentUser.Username ?? username}");
            receipt.AppendLine(line);
            receipt.AppendLine("    ADVANCE ORDER");
            receipt.AppendLine(line);

            // Customer information
            receipt.AppendLine($"Customer: {customerName}");
            receipt.AppendLine($"Order: {orderDescription}");
            receipt.AppendLine(line);

            // Items header
            receipt.AppendLine($"{"Item",-12} {"Qty",-3} {"Amount",-8}");
            receipt.AppendLine(line);

            foreach (ListViewItem item in salesListView.Items)
            {
                string description = item.Text;
                string qty = item.SubItems[1].Text;
                string price = item.SubItems[2].Text.Replace("P", "");
                string total = item.SubItems[3].Text.Replace("P", "");

                // Wrap description to fit 58mm width (14 chars for description)
                int wrapWidth = 14;
                for (int i = 0; i < description.Length; i += wrapWidth)
                {
                    if (i == 0)
                    {
                        // First line with quantity and total
                        string descPart = description.Substring(i, Math.Min(wrapWidth, description.Length - i));
                        receipt.AppendLine($"{descPart,-12} {qty,-3} P{total,-7}");
                    }
                    else
                    {
                        // Continuation lines
                        string descPart = description.Substring(i, Math.Min(wrapWidth, description.Length - i));
                        receipt.AppendLine($"{descPart,-12}");
                    }
                }
            }

            receipt.AppendLine(line);
            receipt.AppendLine();

            // Order totals
            decimal orderTotal = currentTotal - currentDiscount;
            receipt.AppendLine($"{"Order Total:"} P{currentTotal:F2}");
            if (currentDiscount > 0)
            {
                receipt.AppendLine($"{"Discount:"} P{currentDiscount:F2}");
            }
            receipt.AppendLine($"{"Net Amount:"} P{orderTotal:F2}");
            receipt.AppendLine(line);

            // Payment breakdown
            receipt.AppendLine("PAYMENT BREAKDOWN:");
            receipt.AppendLine($"{"Downpayment:"} P{downpayment:F2}");
            receipt.AppendLine($"{"Balance Due:"} P{balance:F2}");
            receipt.AppendLine(line);
            receipt.AppendLine();

            // Terms and conditions
            receipt.AppendLine("TERMS & CONDITIONS:");
            receipt.AppendLine("- Balance must be paid");
            receipt.AppendLine("  upon order completion");
            receipt.AppendLine("- Present this receipt");
            receipt.AppendLine("  for order pickup");
            receipt.AppendLine("  Fabrication time");
            receipt.AppendLine("  Standard sizes 2-5 Days");
            receipt.AppendLine("  10mm glass and bigger will");
            receipt.AppendLine("  Take longer,Appreciate your");
            receipt.AppendLine("  Patience. :) ");
            receipt.AppendLine(line);

            // Footer - centered for 58mm
            receipt.AppendLine("    THANK YOU!");
            receipt.AppendLine("  FOR YOUR ORDER!");
            receipt.AppendLine(line);

            receiptContent = receipt.ToString();
            printDocument.Print();
        }

        // Print a receipt specifically for fully-paid advance orders.
        // This retrieves items from AdvanceOrderLines and header info from AdvanceOrderHeader.
        public void PrintFullyPaidAdvanceOrderReceipt(string receiptNo)
        {
            try
            {
                var receipt = new System.Text.StringBuilder();
                string line = new string('-', GlobalSettings.ReceiptWidth);
                string onlineOrderId = OnlinefunctionsEvents.GetMappedOnlineOrderIdForReceipt(receiptNo);

                string advanceOrderReceiptNo = receiptNo;
                string customerName = "";
                string orderDescription = "";
                decimal downpayment = 0m;
                decimal netAmount = 0m;
                decimal headerDiscount = 0m;

                string connectionString = GlobalSettings.ConnectionString;
                using (var conn = new SqlConnection(connectionString))
                {
                    conn.Open();
                    // Read header info
                    var headerCmd = new SqlCommand(@"
                        SELECT ReceiptNo, CustomerName, Order_Description, Downpayment, NetAmount, Discount
                        FROM AdvanceOrderHeader
                        WHERE ReceiptNo = @ReceiptNo", conn);
                    headerCmd.Parameters.AddWithValue("@ReceiptNo", receiptNo);
                    using (var hr = headerCmd.ExecuteReader())
                    {
                        if (hr.Read())
                        {
                            advanceOrderReceiptNo = hr["ReceiptNo"]?.ToString() ?? receiptNo;
                            customerName = hr["CustomerName"]?.ToString() ?? "";
                            orderDescription = hr["Order_Description"]?.ToString() ?? "";
                            downpayment = hr["Downpayment"] != DBNull.Value ? Convert.ToDecimal(hr["Downpayment"]) : 0m;
                            netAmount = hr["NetAmount"] != DBNull.Value ? Convert.ToDecimal(hr["NetAmount"]) : 0m;
                            // Discount column may be null or missing in some schemas
                            try { headerDiscount = hr["Discount"] != DBNull.Value ? Convert.ToDecimal(hr["Discount"]) : 0m; } catch { headerDiscount = 0m; }
                        }
                    }

                    // Read line items from AdvanceOrderLines
                    var linesCmd = new SqlCommand(@"
                        SELECT [LineNo], [Type], [No.], [Description], [Quantity], [Price], [GrossAmount], [NetAmount]
                        FROM AdvanceOrderLines
                        WHERE ReceiptNo = @ReceiptNo
                        ORDER BY [LineNo]", conn);
                    linesCmd.Parameters.AddWithValue("@ReceiptNo", receiptNo);

                    var items = new System.Collections.Generic.List<(string desc, int qty, decimal price, decimal lineTotal, string type)>();
                    using (var lr = linesCmd.ExecuteReader())
                    {
                        while (lr.Read())
                        {
                            string type = lr["Type"]?.ToString() ?? "";
                            string desc = lr["Description"]?.ToString() ?? lr["No."]?.ToString() ?? "";
                            int qty = lr["Quantity"] != DBNull.Value ? Convert.ToInt32(lr["Quantity"]) : 0;
                            decimal price = lr["Price"] != DBNull.Value ? Convert.ToDecimal(lr["Price"]) : 0m;
                            decimal lineTotal = lr["NetAmount"] != DBNull.Value ? Convert.ToDecimal(lr["NetAmount"]) : (lr["GrossAmount"] != DBNull.Value ? Convert.ToDecimal(lr["GrossAmount"]) : price * qty);
                            items.Add((desc, qty, price, lineTotal, type));
                        }
                    }

                    // Build receipt
                    receipt.AppendLine("      RS PET STOP");
                    receipt.AppendLine("  AQUARIUM PRODUCTS");
                    receipt.AppendLine("   & SOLUTIONS");
                    receipt.AppendLine(line);
                    receipt.AppendLine($"Date: {DateTime.Now:yyyy-MM-dd HH:mm}");
                    receipt.AppendLine($"Receipt #: {receiptNo}");
                    if (!string.IsNullOrWhiteSpace(onlineOrderId))
                    {
                        receipt.AppendLine($"Online Order ID: {onlineOrderId}");
                    }
                    receipt.AppendLine($"Cashier: {CurrentUser.Username ?? username}");
                    receipt.AppendLine(line);
                    receipt.AppendLine("  ADVANCE ORDER - PAID");
                    receipt.AppendLine(line);
                    if (!string.IsNullOrWhiteSpace(advanceOrderReceiptNo))
                    {
                        receipt.AppendLine($"Advance Ref: {advanceOrderReceiptNo}");
                    }
                    receipt.AppendLine($"Customer: {customerName}");
                    receipt.AppendLine($"Order: {orderDescription}");
                    receipt.AppendLine(line);
                    receipt.AppendLine($"{"Item",-10} {"Qty",3} {"Amount",10}");
                    receipt.AppendLine(line);

                    decimal total = 0m;
                    foreach (var it in items)
                    {
                        // show first line with qty and amount, wrap desc if long
                        string desc = it.desc ?? "";
                        int wrap = 10; // limit description to 10 chars to ensure Qty and Amount columns fit
                        if (desc.Length <= wrap)
                        {
                            receipt.AppendLine($"{desc,-10} {it.qty,3} P{it.lineTotal,9:F2}");
                        }
                        else
                        {
                            for (int i = 0; i < desc.Length; i += wrap)
                            {
                                string part = desc.Substring(i, Math.Min(wrap, desc.Length - i));
                                if (i == 0)
                                    receipt.AppendLine($"{part,-10} {it.qty,3} P{it.lineTotal,9:F2}");
                                else
                                    receipt.AppendLine($"{part,-10}");
                            }
                        }

                        // Only include lines of type ITEM in the order total
                        if (!string.IsNullOrEmpty(it.type) && it.type.Equals("ITEM", StringComparison.OrdinalIgnoreCase))
                        {
                            total += it.lineTotal;
                        }
                    }

                    receipt.AppendLine(line);
                    receipt.AppendLine($"Order Total: P{total,10:F2}");
                    if (headerDiscount > 0)
                        receipt.AppendLine($"Discount: P{headerDiscount,10:F2}");
                    if (downpayment > 0)
                        receipt.AppendLine($"Downpayment: P{downpayment,10:F2}");
                    // netAmount is expected to be total - discount; balance is netAmount - downpayment
                    decimal balance = netAmount - downpayment;
                    receipt.AppendLine($"Balance Due: P{balance,10:F2}");
                    receipt.AppendLine(line);
                    receipt.AppendLine("    THANK YOU!");
                    receipt.AppendLine(line);
                }

                receiptContent = receipt.ToString();
                printDocument.Print();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error printing fully-paid advance order receipt: {ex.Message}", "Print Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void InitializePrinting()
        {
            printDocument = new PrintDocument();
            printDocument.BeginPrint += (_, _) => receiptPrintLineIndex = 0;
            printDocument.EndPrint += (_, _) => receiptPrintLineIndex = 0;
            printDocument.PrintPage += PrintDocument_PrintPage;
            printFont = new Font(GlobalSettings.ReceiptFont, GlobalSettings.ReceiptFontSize, GlobalSettings.ReceiptFontStyle); // Monospace font for receipt printing (configurable style)

            // Configure for 58mm thermal printer
            printDocument.DefaultPageSettings.PaperSize = new PaperSize("58mm",
                (int)(GlobalSettings.PaperWidthInches * 100),
                (int)(GlobalSettings.PaperHeightInches * 100));
            printDocument.DefaultPageSettings.Margins = new Margins(
                (int)(GlobalSettings.LeftMarginInches * 100),
                (int)(GlobalSettings.LeftMarginInches * 100),
                (int)(GlobalSettings.TopMarginInches * 100),
                (int)(GlobalSettings.TopMarginInches * 100));

            var savedPrinterPreferences = LoadPrinterPreferences();

            selectedReceiptPrinterName = !string.IsNullOrWhiteSpace(savedPrinterPreferences.ReceiptPrinterName)
                ? savedPrinterPreferences.ReceiptPrinterName
                : !string.IsNullOrWhiteSpace(GlobalSettings.PosPrinterName)
                    ? GlobalSettings.PosPrinterName
                : printDocument.PrinterSettings.PrinterName;
            if (!string.IsNullOrWhiteSpace(selectedReceiptPrinterName))
            {
                printDocument.PrinterSettings.PrinterName = selectedReceiptPrinterName;
            }

            selectedLabelPrinterName = !string.IsNullOrWhiteSpace(savedPrinterPreferences.LabelPrinterName)
                ? savedPrinterPreferences.LabelPrinterName
                : string.Empty;
        }

        private static PrinterPreferences LoadPrinterPreferences()
        {
            try
            {
                if (!File.Exists(PrinterPreferencesFilePath))
                    return new PrinterPreferences();

                string json = File.ReadAllText(PrinterPreferencesFilePath);
                return JsonSerializer.Deserialize<PrinterPreferences>(json) ?? new PrinterPreferences();
            }
            catch
            {
                return new PrinterPreferences();
            }
        }

        private void SavePrinterPreferences()
        {
            try
            {
                string? folderPath = Path.GetDirectoryName(PrinterPreferencesFilePath);
                if (!string.IsNullOrWhiteSpace(folderPath))
                    Directory.CreateDirectory(folderPath);

                var preferences = new PrinterPreferences
                {
                    ReceiptPrinterName = selectedReceiptPrinterName ?? string.Empty,
                    LabelPrinterName = selectedLabelPrinterName ?? string.Empty
                };

                string json = JsonSerializer.Serialize(preferences, new JsonSerializerOptions { WriteIndented = true });
                File.WriteAllText(PrinterPreferencesFilePath, json);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to save printer defaults: {ex.Message}", "Printer Settings", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        private void PrintReceipt()
        {
            if (salesListView.Items.Count == 0)
            {
                MessageBox.Show("No items to print!", "Print Receipt", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            try
            {
                // Generate receipt content with temporary receipt number (fallback for manual print)
                string tempReceiptNo = $"PRINT-{DateTime.Now:yyyyMMdd-HHmmss}";
                GenerateReceiptContent(tempReceiptNo);

                // Show print dialog to select printer
                PrintDialog printDialog = new PrintDialog
                {
                    Document = printDocument,
                    UseEXDialog = true
                };

                if (printDialog.ShowDialog() == DialogResult.OK)
                {
                    printDocument.Print();
                    MessageBox.Show("Receipt printed successfully!", "Print Complete", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Print error: {ex.Message}", "Print Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        public void PrintReceiptDirect(string receiptNo)
        {
            if (salesListView.Items.Count == 0)
            {
                MessageBox.Show("No items to print!", "Print Receipt", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            try
            {
                // Generate receipt content
                GenerateReceiptContent(receiptNo);

                // Print directly to default printer
                printDocument.Print();
                MessageBox.Show("Receipt printed successfully!", "Print Complete", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Print error: {ex.Message}", "Print Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void GenerateReceiptContent(string receiptNo)
        {
            var receipt = new StringBuilder();
            string line = new string('-', GlobalSettings.ReceiptWidth);
            string onlineOrderId = OnlinefunctionsEvents.GetMappedOnlineOrderIdForReceipt(receiptNo);

            bool isOnlineReceipt = false;
            try
            {
                isOnlineReceipt = !string.IsNullOrWhiteSpace(receiptNo)
                    && receiptNo.StartsWith("ONL-", StringComparison.OrdinalIgnoreCase);

                if (!isOnlineReceipt)
                {
                    foreach (ListViewItem it in salesListView.Items)
                    {
                        var tag = it?.Tag?.ToString() ?? string.Empty;
                        if (tag.StartsWith("ONLINE_STAGED|", StringComparison.OrdinalIgnoreCase)) { isOnlineReceipt = true; break; }
                    }
                }
            }
            catch { isOnlineReceipt = false; }

            decimal onlinePaid = 0m;
            decimal upstreamAmountPaid = 0m;
            string onlinePaidLabel = "Online Paid";
            if (isOnlineReceipt)
            {
                // Total actually paid in POS for this online receipt
                try
                {
                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();
                        using (var cmdPaid = new SqlCommand("SELECT ISNULL(SUM(Amount), 0) FROM TransPaymentEntry WHERE ReceiptNo = @receiptNo", connection))
                        {
                            cmdPaid.Parameters.AddWithValue("@receiptNo", receiptNo ?? string.Empty);
                            var objPaid = cmdPaid.ExecuteScalar();
                            if (objPaid != null && objPaid != DBNull.Value) onlinePaid = Convert.ToDecimal(objPaid);
                        }

                        // If there is exactly one tender type for this receipt, use its description in the label
                        try
                        {
                            using var cmdTender = new SqlCommand(@"SELECT DISTINCT TenderTypeCode FROM TransPaymentEntry WHERE ReceiptNo = @receiptNo", connection);
                            cmdTender.Parameters.AddWithValue("@receiptNo", receiptNo ?? string.Empty);
                            var tenderCodes = new System.Collections.Generic.List<string>();
                            using (var rdr = cmdTender.ExecuteReader())
                            {
                                while (rdr.Read())
                                {
                                    var code = rdr["TenderTypeCode"]?.ToString() ?? string.Empty;
                                    if (!string.IsNullOrWhiteSpace(code)) tenderCodes.Add(code);
                                }
                            }

                            if (tenderCodes.Count == 1)
                            {
                                var singleCode = tenderCodes[0];
                                using var cmdDesc = new SqlCommand("SELECT TOP 1 Description FROM TenderTypes WHERE Code = @Code", connection);
                                cmdDesc.Parameters.AddWithValue("@Code", singleCode);
                                var objDesc = cmdDesc.ExecuteScalar();
                                var desc = objDesc?.ToString();
                                // For a single tender, show just the tender name/code as the label
                                if (!string.IsNullOrWhiteSpace(desc))
                                {
                                    onlinePaidLabel = desc;
                                }
                                else
                                {
                                    onlinePaidLabel = singleCode;
                                }
                            }
                        }
                        catch { onlinePaidLabel = "Online Paid"; }
                    }
                }
                catch { onlinePaid = 0m; }

                // Upstream AmountPaid field from OnlineOrderHeader (prepaid amount captured online)
                try
                {
                    var orderIdFromReceipt = (!string.IsNullOrWhiteSpace(receiptNo) && receiptNo.StartsWith("ONL-", StringComparison.OrdinalIgnoreCase))
                        ? receiptNo.Substring(4)
                        : string.Empty;
                    if (!string.IsNullOrWhiteSpace(orderIdFromReceipt))
                    {
                        using (var cn = new SqlConnection(connectionString))
                        {
                            cn.Open();
                            using var cmdAp = new SqlCommand("SELECT AmountPaid FROM dbo.OnlineOrderHeader WHERE OrderID = @OrderID", cn);
                            cmdAp.Parameters.AddWithValue("@OrderID", orderIdFromReceipt);
                            var objAp = cmdAp.ExecuteScalar();
                            if (objAp != null && objAp != DBNull.Value) upstreamAmountPaid = Convert.ToDecimal(objAp);
                        }
                    }
                }
                catch { upstreamAmountPaid = 0m; }
            }

            // Header - centered for 58mm
            receipt.AppendLine("      RS PET STOP");
            receipt.AppendLine("  AQUARIUM PRODUCTS");
            receipt.AppendLine("   & SOLUTIONS");
            receipt.AppendLine(line);
            receipt.AppendLine($"Date: {DateTime.Now:yyyy-MM-dd HH:mm}");
            receipt.AppendLine($"Receipt #: {receiptNo}");
            if (!string.IsNullOrWhiteSpace(onlineOrderId))
            {
                receipt.AppendLine($"Online Order ID: {onlineOrderId}");
            }
            receipt.AppendLine($"Cashier: {CurrentUser.Username ?? username}");
            receipt.AppendLine(line);

            // Customer information
            if (!string.IsNullOrEmpty(currentCustomerName))
            {
                receipt.AppendLine($"Customer: {currentCustomerName}");
                receipt.AppendLine(line);

            }

            // Items header
            receipt.AppendLine("ITEMS:");
            receipt.AppendLine($"{"Item",-12} {"Qty",-3} {"Amount",-8}");
            receipt.AppendLine(line);

            foreach (ListViewItem item in salesListView.Items)
            {
                string description = item.Text;
                string qty = item.SubItems[1].Text;
                string price = item.SubItems[2].Text.Replace("?", "");
                string total = item.SubItems[3].Text.Replace("?", "");

                // Wrap description to fit 58mm width (14 chars for description)
                int wrapWidth = 14;
                for (int i = 0; i < description.Length; i += wrapWidth)
                {
                    string descLine = description.Substring(i, Math.Min(wrapWidth, description.Length - i));
                    if (i == 0)
                        receipt.AppendLine($"{descLine,-12} {qty,-3} {total:N2,-8}");
                    else
                        receipt.AppendLine($"{descLine,-12}");
                }
            }

            receipt.AppendLine(line);
            receipt.AppendLine();
            AppendWrappedReceiptNote(receipt, pendingCustomAquariumSpecialNote, GlobalSettings.ReceiptWidth);

            // Totals
            grandTotal = currentTotal - currentDiscount;
            receipt.AppendLine($"{"Subtotal:"} {currentTotal:N2}");
            if (currentDiscount > 0)
            {
                receipt.AppendLine($"{GetReceiptDiscountLabel(currentDiscountDescription)}: {currentDiscount:N2}");
            }
            receipt.AppendLine($"{"GRAND TOTAL:"} {grandTotal:N2}");
            receipt.AppendLine(line);
            receipt.AppendLine();

            if (isOnlineReceipt)
            {
                // Online receipt: show only what matters (avoid duplicated remaining/balance fields)
                receipt.AppendLine($"{onlinePaidLabel}: {onlinePaid:N2}");
                receipt.AppendLine($"{"Previous Payment:"} {upstreamAmountPaid:N2}");

                // Compute remaining balance based on both upstream AmountPaid and POS Online Paid
                var totalPaidCombined = onlinePaid + upstreamAmountPaid;
                var remainingBalance = grandTotal - totalPaidCombined;
                if (remainingBalance < 0m) remainingBalance = 0m;

                // Only print Balance when there is something still to pay
                if (remainingBalance > 0m)
                {
                    receipt.AppendLine($"{"Balance:"} {remainingBalance:N2}");
                }

                // Print bank_transfer payload (if captured) for online receipts
                try
                {
                    void AppendWrapped(string text)
                    {
                        if (text == null) text = string.Empty;
                        int width = Math.Max(20, GlobalSettings.ReceiptWidth);
                        text = text.TrimEnd();
                        if (text.Length == 0) { receipt.AppendLine(string.Empty); return; }

                        bool first = true;
                        while (text.Length > width)
                        {
                            receipt.AppendLine(text.Substring(0, width));
                            text = text.Substring(width);
                            if (first) first = false;
                        }
                        if (text.Length > 0) receipt.AppendLine(text);
                    }

                    string? bankTransferJson = null;
                    try
                    {
                        var orderIdFromReceipt = (!string.IsNullOrWhiteSpace(receiptNo) && receiptNo.StartsWith("ONL-", StringComparison.OrdinalIgnoreCase))
                            ? receiptNo.Substring(4)
                            : string.Empty;
                        if (!string.IsNullOrWhiteSpace(orderIdFromReceipt))
                        {
                            using (var cn = new SqlConnection(connectionString))
                            {
                                cn.Open();
                                using var cmdBt = new SqlCommand("SELECT BankTransferJson FROM dbo.OnlineOrderHeader WHERE OrderID = @OrderID", cn);
                                cmdBt.Parameters.AddWithValue("@OrderID", orderIdFromReceipt);
                                var objBt = cmdBt.ExecuteScalar();
                                if (objBt != null && objBt != DBNull.Value) bankTransferJson = objBt.ToString();
                            }
                        }
                    }
                    catch { bankTransferJson = null; }

                    if (!string.IsNullOrWhiteSpace(bankTransferJson))
                    {
                        receipt.AppendLine(line);
                        receipt.AppendLine("BANK TRANSFER:");

                        bool printedAny = false;
                        try
                        {
                            using var doc = System.Text.Json.JsonDocument.Parse(bankTransferJson);
                            var el = doc.RootElement;

                            if (el.ValueKind == System.Text.Json.JsonValueKind.String)
                            {
                                var s = el.GetString() ?? string.Empty;
                                if (!string.IsNullOrWhiteSpace(s))
                                {
                                    AppendWrapped($"Reference: {s}");
                                    printedAny = true;
                                }
                            }
                            else if (el.ValueKind == System.Text.Json.JsonValueKind.Object)
                            {
                                string? GetProp(params string[] names)
                                {
                                    foreach (var n in names)
                                    {
                                        if (el.TryGetProperty(n, out var p))
                                        {
                                            try
                                            {
                                                if (p.ValueKind == System.Text.Json.JsonValueKind.String) return p.GetString();
                                                if (p.ValueKind == System.Text.Json.JsonValueKind.Number) return p.GetRawText();
                                                if (p.ValueKind == System.Text.Json.JsonValueKind.True) return "true";
                                                if (p.ValueKind == System.Text.Json.JsonValueKind.False) return "false";
                                                if (p.ValueKind == System.Text.Json.JsonValueKind.Object || p.ValueKind == System.Text.Json.JsonValueKind.Array) return p.GetRawText();
                                            }
                                            catch { }
                                        }
                                    }
                                    return null;
                                }

                                var reference = GetProp("reference", "ref", "transaction_ref", "transaction_reference", "transaction_id", "id");
                                var bank = GetProp("bank", "bank_name", "bankName");
                                var accountName = GetProp("account_name", "accountName", "name");
                                var accountNo = GetProp("account_no", "account_number", "accountNo", "accountNumber");
                                var amount = GetProp("amount", "paid", "value");
                                var date = GetProp("date", "paid_at", "paidAt", "timestamp", "time");

                                if (!string.IsNullOrWhiteSpace(reference)) { AppendWrapped($"Reference: {reference}"); printedAny = true; }
                                if (!string.IsNullOrWhiteSpace(bank)) { AppendWrapped($"Bank: {bank}"); printedAny = true; }
                                if (!string.IsNullOrWhiteSpace(accountName)) { AppendWrapped($"Account: {accountName}"); printedAny = true; }
                                if (!string.IsNullOrWhiteSpace(accountNo)) { AppendWrapped($"Acc No: {accountNo}"); printedAny = true; }
                                if (!string.IsNullOrWhiteSpace(amount)) { AppendWrapped($"Amount: {amount}"); printedAny = true; }
                                if (!string.IsNullOrWhiteSpace(date)) { AppendWrapped($"Date: {date}"); printedAny = true; }

                                if (!printedAny)
                                {
                                    // Fallback: print a truncated raw JSON
                                    var raw = bankTransferJson.Trim();
                                    if (raw.Length > 220) raw = raw.Substring(0, 220) + "...";
                                    AppendWrapped(raw);
                                    printedAny = true;
                                }
                            }
                            else
                            {
                                var raw = bankTransferJson.Trim();
                                if (raw.Length > 220) raw = raw.Substring(0, 220) + "...";
                                AppendWrapped(raw);
                                printedAny = true;
                            }
                        }
                        catch
                        {
                            var raw = bankTransferJson.Trim();
                            if (raw.Length > 220) raw = raw.Substring(0, 220) + "...";
                            AppendWrapped(raw);
                            printedAny = true;
                        }

                        if (!printedAny)
                        {
                            AppendWrapped("(no bank transfer details)");
                        }
                    }
                }
                catch { }
            }
            else
            {
                // In-store receipt: show amount tendered and change (if any)
                decimal amountTendered = totalPaid;
                decimal change = amountTendered - grandTotal;

                receipt.AppendLine($"{"Amount Tendered:"} {amountTendered:N2}");
                if (change >= 0)
                {
                    receipt.AppendLine($"{"Change:"} {change:N2}");
                }
                else
                {
                    // Negative change means remaining balance
                    receipt.AppendLine($"{"Remaining:"} {Math.Abs(change):N2}");
                }
            }

            receipt.AppendLine();

            // Footer - centered for 58mm
            receipt.AppendLine("    THANK YOU!");
            receipt.AppendLine("  COME AGAIN SOON!");
            receipt.AppendLine(line);

            receiptContent = receipt.ToString();
        }

        private void PrintDocument_PrintPage(object sender, PrintPageEventArgs e)
        {
            if (e.Graphics == null) return;

            // Print settings for 58mm receipt
            float yPos = e.MarginBounds.Top;
            float leftMargin = e.MarginBounds.Left;
            float lineHeight = printFont.GetHeight(e.Graphics);
            float printableWidth = e.MarginBounds.Width;

            // Continue from the last printed line so multi-page receipts terminate correctly.
            string[] lines = receiptContent.Replace("\r\n", "\n").Split('\n');

            while (receiptPrintLineIndex < lines.Length)
            {
                string line = lines[receiptPrintLineIndex];
                if (yPos + lineHeight > e.MarginBounds.Bottom)
                {
                    e.HasMorePages = true;
                    return;
                }

                // Handle text wrapping for 58mm width
                string processedLine = line;
                if (line.Length > GlobalSettings.ReceiptWidth)
                {
                    processedLine = line.Substring(0, GlobalSettings.ReceiptWidth);
                }

                e.Graphics.DrawString(FunctionEvents.ToAscii(processedLine), printFont, Brushes.Black, leftMargin, yPos);
                yPos += lineHeight;
                receiptPrintLineIndex++;
            }

            receiptPrintLineIndex = 0;
            e.HasMorePages = false;
        }

