                    {
                        BackColor = Color.White
                    };

                    var sectionTitleLabel = new Label
                    {
                        Text = sectionTitle,
                        Location = new Point(16, 18),
                        Size = new Size(220, 24),
                        Font = new Font("Arial", 12, FontStyle.Bold),
                        ForeColor = Color.FromArgb(20, 72, 120)
                    };

                    var sectionDescriptionLabel = new Label
                    {
                        Text = sectionDescription,
                        Location = new Point(16, 46),
                        Size = new Size(780, 34),
                        Font = new Font("Arial", 9, FontStyle.Regular),
                        ForeColor = Color.DimGray
                    };

                    var printerListLabel = new Label
                    {
                        Text = "Available Printers:",
                        Location = new Point(16, 92),
                        Size = new Size(160, 20),
                        Font = new Font("Arial", 10, FontStyle.Bold)
                    };

                    var printerListBox = new ListBox
                    {
                        Location = new Point(16, 118),
                        Size = new Size(800, 180),
                        Font = new Font("Arial", 10)
                    };
                    PopulatePrinterList(printerListBox, getSelectedPrinter());

                    var selectedPrinterLabel = new Label
                    {
                        Text = string.IsNullOrWhiteSpace(getSelectedPrinter()) ? "Current Selection: (none)" : $"Current Selection: {getSelectedPrinter()}",
                        Location = new Point(16, 316),
                        Size = new Size(800, 20),
                        Font = new Font("Arial", 9, FontStyle.Italic),
                        ForeColor = Color.DarkSlateGray
                    };

                    void UpdateSelectedPrinterLabel(string printerName)
                    {
                        selectedPrinterLabel.Text = string.IsNullOrWhiteSpace(printerName)
                            ? "Current Selection: (none)"
                            : $"Current Selection: {printerName}";
                    }

                    printerListBox.SelectedIndexChanged += (_, _) =>
                    {
                        UpdateSelectedPrinterLabel(printerListBox.SelectedItem?.ToString() ?? string.Empty);
                    };

                    var testPrintButton = new Button
                    {
                        Text = "Test Print",
                        Location = new Point(16, 356),
                        Size = new Size(150, 40),
                        BackColor = Color.Blue,
                        ForeColor = Color.White,
                        Font = new Font("Arial", 10, FontStyle.Bold)
                    };

                    testPrintButton.Click += (_, _) =>
                    {
                        if (printerListBox.SelectedItem == null)
                        {
                            MessageBox.Show("Please select a printer first.", "No Printer Selected", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                            return;
                        }

                        string selectedPrinter = printerListBox.SelectedItem.ToString() ?? string.Empty;
                        try
                        {
                            setSelectedPrinter(selectedPrinter);
                            if (applyToReceiptDocument)
                            {
                                printDocument.PrinterSettings.PrinterName = selectedPrinter;
                            }

                            testPrintAction(selectedPrinter);
                            UpdateSelectedPrinterLabel(selectedPrinter);
                            MessageBox.Show($"Test print sent to '{selectedPrinter}'.", "Test Print", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }
                        catch (Exception ex)
                        {
                            MessageBox.Show($"Test print failed: {ex.Message}", "Print Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        }
                    };

                    var setDefaultButton = new Button
                    {
                        Text = "Set as Default",
                        Location = new Point(176, 356),
                        Size = new Size(170, 40),
                        BackColor = Color.Green,
                        ForeColor = Color.White,
                        Font = new Font("Arial", 10, FontStyle.Bold)
                    };

                    setDefaultButton.Click += (_, _) =>
                    {
                        if (printerListBox.SelectedItem == null)
                        {
                            MessageBox.Show("Please select a printer first.", "No Printer Selected", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                            return;
                        }

                        string selectedPrinter = printerListBox.SelectedItem.ToString() ?? string.Empty;
                        setSelectedPrinter(selectedPrinter);
                        if (applyToReceiptDocument)
                        {
                            printDocument.PrinterSettings.PrinterName = selectedPrinter;
                        }

                        SavePrinterPreferences();

                        UpdateSelectedPrinterLabel(selectedPrinter);
                        MessageBox.Show($"'{selectedPrinter}' is now the saved default {tabTitle.ToLowerInvariant()} printer.", "Printer Settings", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    };

                    tabPage.Controls.AddRange(new Control[]
                    {
                        sectionTitleLabel,
                        sectionDescriptionLabel,
                        printerListLabel,
                        printerListBox,
                        selectedPrinterLabel,
                        testPrintButton,
                        setDefaultButton
                    });

                    return tabPage;
                }

                tabControl.TabPages.Add(CreatePrinterTab(
                    "Receipt Printer",
                    "Receipt Printer Setup",
                    "Use this printer for 58mm receipts, sales slips, and direct POS receipt printing.",
                    () => string.IsNullOrWhiteSpace(selectedReceiptPrinterName) ? printDocument.PrinterSettings.PrinterName : selectedReceiptPrinterName,
                    printerName => selectedReceiptPrinterName = printerName,
                    _ =>
                    {
                        receiptContent = GenerateTestReceipt();
                        printDocument.Print();
                    },
                    applyToReceiptDocument: true));

                tabControl.TabPages.Add(CreatePrinterTab(
                    "Label Printer",
                    "Label Printer Setup",
                    "Reserve this printer for product labels and sticker output without changing the receipt printer.",
                    () => selectedLabelPrinterName,
                    printerName => selectedLabelPrinterName = printerName,
                    printerName => PrintLabelTest(printerName),
                    applyToReceiptDocument: false));

                var closeButton = new Button
                {
                    Text = "Close",
                    Location = new Point(760, 540),
                    Size = new Size(120, 40),
                    BackColor = Color.Gray,
                    ForeColor = Color.White,
                    Font = new Font("Arial", 10, FontStyle.Bold),
                    Anchor = AnchorStyles.Bottom | AnchorStyles.Right
                };
                closeButton.Click += (_, _) => settingsForm.Close();

                settingsForm.Controls.AddRange(new Control[] {
                    titleLabel, subtitleLabel, tabControl, closeButton
                });

                settingsForm.ShowDialog();
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to open printer settings: {ex.Message}", "Settings Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

