        private static int MillimetersToHundredthsOfInch(float millimeters)
        {
            return (int)Math.Round(millimeters / 25.4f * 100f);
        }

        private static Bitmap CreateCode128BarcodeBitmap(string value, int width, int height)
        {
            var writer = new BarcodeWriterPixelData
            {
                Format = BarcodeFormat.CODE_128,
                Options = new EncodingOptions
                {
                    Width = Math.Max(120, width),
                    Height = Math.Max(40, height),
                    Margin = 0,
                    PureBarcode = true
                }
            };

            var pixelData = writer.Write(value);
            var bitmap = new Bitmap(pixelData.Width, pixelData.Height, PixelFormat.Format32bppRgb);
            var bitmapData = bitmap.LockBits(
                new Rectangle(0, 0, bitmap.Width, bitmap.Height),
                ImageLockMode.WriteOnly,
                PixelFormat.Format32bppRgb);

            try
            {
                Marshal.Copy(pixelData.Pixels, 0, bitmapData.Scan0, pixelData.Pixels.Length);
            }
            finally
            {
                bitmap.UnlockBits(bitmapData);
            }

            return bitmap;
        }

        private static float DrawWrappedLabelText(Graphics graphics, string text, Font font, Brush brush, RectangleF bounds, StringFormat format, int maxLines)
        {
            if (graphics == null || string.IsNullOrWhiteSpace(text) || bounds.Width <= 0 || bounds.Height <= 0 || maxLines <= 0)
            {
                return 0f;
            }

            using var layoutFormat = (StringFormat)format.Clone();
            layoutFormat.Trimming = StringTrimming.None;
            layoutFormat.FormatFlags &= ~StringFormatFlags.NoWrap;

            string remaining = text.Trim();
            float yPos = bounds.Top;
            float consumedHeight = 0f;

            for (int lineIndex = 0; lineIndex < maxLines && !string.IsNullOrWhiteSpace(remaining); lineIndex++)
            {
                int charsFitted;
                int linesFilled;
                SizeF measured = graphics.MeasureString(
                    remaining,
                    font,
                    new SizeF(bounds.Width, bounds.Height - consumedHeight),
                    layoutFormat,
                    out charsFitted,
                    out linesFilled);

                if (charsFitted <= 0)
                {
                    break;
                }

                int splitIndex = charsFitted;
                if (splitIndex < remaining.Length)
                {
                    int lastWhitespace = remaining.LastIndexOfAny(new[] { ' ', '-', '/', ',' }, Math.Max(0, splitIndex - 1), splitIndex);
                    if (lastWhitespace > 0)
                    {
                        splitIndex = lastWhitespace;
                    }
                }

                string lineText = remaining.Substring(0, splitIndex).Trim();
                if (string.IsNullOrWhiteSpace(lineText))
                {
                    lineText = remaining.Substring(0, Math.Min(charsFitted, remaining.Length)).Trim();
                    splitIndex = Math.Min(charsFitted, remaining.Length);
                }

                SizeF lineSize = graphics.MeasureString(lineText, font, new SizeF(bounds.Width, bounds.Height), layoutFormat);
                float lineHeight = Math.Max(font.GetHeight(graphics), lineSize.Height);
                graphics.DrawString(lineText, font, brush, new RectangleF(bounds.Left, yPos, bounds.Width, lineHeight + 1f), layoutFormat);

                yPos += lineHeight;
                consumedHeight += lineHeight;
                remaining = splitIndex >= remaining.Length ? string.Empty : remaining.Substring(splitIndex).TrimStart(' ', '-', '/', ',');
            }

            return consumedHeight;
        }

        public static string ResolveReceiptPrinterName()
        {
            try
            {
                foreach (Form form in Application.OpenForms)
                {
                    if (form is MainForm mainForm)
                    {
                        if (!string.IsNullOrWhiteSpace(mainForm.selectedReceiptPrinterName))
                            return mainForm.selectedReceiptPrinterName;

                        if (!string.IsNullOrWhiteSpace(mainForm.printDocument?.PrinterSettings?.PrinterName))
                            return mainForm.printDocument.PrinterSettings.PrinterName;
                    }
                }
            }
            catch { }

            try
            {
                var savedPreferences = LoadPrinterPreferences();
                if (!string.IsNullOrWhiteSpace(savedPreferences.ReceiptPrinterName))
                    return savedPreferences.ReceiptPrinterName;
            }
            catch { }

            return !string.IsNullOrWhiteSpace(GlobalSettings.PosPrinterName)
                ? GlobalSettings.PosPrinterName
                : string.Empty;
        }

        private static string ResolveLabelPrinterName()
        {
            try
            {
                foreach (Form form in Application.OpenForms)
                {
                    if (form is MainForm mainForm)
                    {
                        if (!string.IsNullOrWhiteSpace(mainForm.selectedLabelPrinterName))
                            return mainForm.selectedLabelPrinterName;

                        if (!string.IsNullOrWhiteSpace(mainForm.printDocument?.PrinterSettings?.PrinterName))
                        {
                            var savedPreferences = LoadPrinterPreferences();
                            if (!string.IsNullOrWhiteSpace(savedPreferences.LabelPrinterName))
                                return savedPreferences.LabelPrinterName;
                        }
                    }
                }
            }
            catch { }

            try
            {
                var savedPreferences = LoadPrinterPreferences();
                if (!string.IsNullOrWhiteSpace(savedPreferences.LabelPrinterName))
                    return savedPreferences.LabelPrinterName;

                return new PrinterSettings().PrinterName;
            }
            catch
            {
                return string.Empty;
            }
        }

        private static bool IsCurrentWarehouseProductionForLabels()
        {
            try
            {
                using var conn = new SqlConnection(GlobalSettings.ConnectionString);
                conn.Open();

                using var colCmd = new SqlCommand(@"SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Warehouses'", conn);
                using var colRdr = colCmd.ExecuteReader();

                bool hasCurrentWarehouse = false;
                bool hasProductionFlag = false;
                while (colRdr.Read())
                {
                    string columnName = colRdr[0]?.ToString() ?? string.Empty;
                    if (columnName.Equals("Current_Warehouse", StringComparison.OrdinalIgnoreCase)) hasCurrentWarehouse = true;
                    if (columnName.Equals("Is_Production_Warehouse", StringComparison.OrdinalIgnoreCase)) hasProductionFlag = true;
                }

                colRdr.Close();
                if (!hasCurrentWarehouse || !hasProductionFlag)
                    return false;

                using var cmd = new SqlCommand(@"
SELECT TOP 1 ISNULL(CAST([Is_Production_Warehouse] AS INT), 0)
FROM dbo.Warehouses
WHERE ISNULL([Current_Warehouse], 0) = 1
ORDER BY [Name]", conn);

                var result = cmd.ExecuteScalar();
                return result != null && result != DBNull.Value && Convert.ToInt32(result) != 0;
            }
            catch
            {
                return false;
            }
        }

        public static void PrintStockCountLabels(IEnumerable<(string Code, string Description, int Count)> lines)
        {
            if (lines == null) return;
            if (!IsCurrentWarehouseProductionForLabels()) return;

            string printerName = ResolveLabelPrinterName();
            if (string.IsNullOrWhiteSpace(printerName))
                throw new InvalidOperationException("No label printer is configured.");

            foreach (var line in lines)
            {
                string itemCode = (line.Code ?? string.Empty).Trim();
                string description = (line.Description ?? string.Empty).Trim();
                int copies = Math.Max(0, line.Count);

                if (copies <= 0 || string.IsNullOrWhiteSpace(itemCode))
                    continue;

                for (int copy = 0; copy < copies; copy++)
                {
                    PrintItemCodeLabel(printerName, itemCode, description);
                }
            }
        }

        public static void PrintSerialNumberLabels(IEnumerable<(string SerialNo, string ItemCode, string Description)> lines)
        {
            if (lines == null) return;
            if (!IsCurrentWarehouseProductionForLabels()) return;

            string printerName = ResolveLabelPrinterName();
            if (string.IsNullOrWhiteSpace(printerName))
                throw new InvalidOperationException("No label printer is configured.");

            var labelLines = lines
                .Select(line => (
                    SerialNo: (line.SerialNo ?? string.Empty).Trim(),
                    ItemCode: (line.ItemCode ?? string.Empty).Trim(),
                    Description: (line.Description ?? string.Empty).Trim()))
                .Where(line => !string.IsNullOrWhiteSpace(line.SerialNo))
                .ToList();

            if (labelLines.Count == 0)
                return;

            const int batchSize = 10;
            for (int batchStartIndex = 0; batchStartIndex < labelLines.Count; batchStartIndex += batchSize)
            {
                int currentBatchStartIndex = batchStartIndex;
                int currentBatchEndIndex = Math.Min(batchStartIndex + batchSize, labelLines.Count);

                using var labelDocument = new PrintDocument();
                labelDocument.PrinterSettings.PrinterName = printerName;
                labelDocument.DefaultPageSettings.PaperSize = new PaperSize(
                    "100x30mm",
                    MillimetersToHundredthsOfInch(LabelPaperWidthMm),
                    MillimetersToHundredthsOfInch(LabelPaperHeightMm));
                labelDocument.DefaultPageSettings.Margins = new Margins(8, 8, 6, 6);
                labelDocument.OriginAtMargins = true;

                int labelIndex = currentBatchStartIndex;
                labelDocument.PrintPage += (_, e) =>
                {
                    if (e.Graphics == null || labelIndex >= currentBatchEndIndex)
                    {
                        e.HasMorePages = false;
                        return;
                    }

                    var currentLabel = labelLines[labelIndex];
                    DrawSerialNumberLabel(e.Graphics, e.MarginBounds, currentLabel.SerialNo, currentLabel.ItemCode, currentLabel.Description);

                    labelIndex++;
                    e.HasMorePages = labelIndex < currentBatchEndIndex;
                };

                labelDocument.Print();
            }
        }

        private static void PrintItemCodeLabel(string printerName, string itemCode, string description)
        {
            using var labelDocument = new PrintDocument();
            labelDocument.PrinterSettings.PrinterName = printerName;
            labelDocument.DefaultPageSettings.PaperSize = new PaperSize(
                "100x30mm",
                MillimetersToHundredthsOfInch(LabelPaperWidthMm),
                MillimetersToHundredthsOfInch(LabelPaperHeightMm));
            labelDocument.DefaultPageSettings.Margins = new Margins(8, 8, 6, 6);
            labelDocument.OriginAtMargins = true;

            labelDocument.PrintPage += (_, e) =>
            {
                if (e.Graphics == null) return;

                using var codeFont = new Font("Arial", 9, FontStyle.Bold);
                using var descriptionFont = new Font("Arial", 6.5f, FontStyle.Regular);
                using var centeredFormat = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Near };

                var bounds = e.MarginBounds;
                float yPos = bounds.Top;

                e.Graphics.DrawString(itemCode, codeFont, Brushes.Black, new RectangleF(bounds.Left, yPos, bounds.Width, 14), centeredFormat);
                yPos += 14;

                if (!string.IsNullOrWhiteSpace(description))
                {
                    float descriptionHeight = DrawWrappedLabelText(
                        e.Graphics,
                        description,
                        descriptionFont,
                        Brushes.Black,
                        new RectangleF(bounds.Left, yPos, bounds.Width, 24),
                        centeredFormat,
                        maxLines: 3);
                    yPos += Math.Max(9f, descriptionHeight) + 1f;
                }

                int barcodeWidth = Math.Max(180, bounds.Width - 10);
                int barcodeHeight = Math.Max(28, bounds.Height - (int)(yPos - bounds.Top) - 8);
                using var barcodeBitmap = CreateCode128BarcodeBitmap(itemCode, barcodeWidth, barcodeHeight);

                var barcodeRect = new Rectangle(bounds.Left + 5, (int)yPos, bounds.Width - 10, barcodeHeight);
                e.Graphics.DrawImage(barcodeBitmap, barcodeRect);
                e.HasMorePages = false;
            };

            labelDocument.Print();
        }

        private static void PrintSerialNumberLabel(string printerName, string serialNo, string itemCode, string description)
        {
            using var labelDocument = new PrintDocument();
            labelDocument.PrinterSettings.PrinterName = printerName;
            labelDocument.DefaultPageSettings.PaperSize = new PaperSize(
                "100x30mm",
                MillimetersToHundredthsOfInch(LabelPaperWidthMm),
                MillimetersToHundredthsOfInch(LabelPaperHeightMm));
            labelDocument.DefaultPageSettings.Margins = new Margins(8, 8, 6, 6);
            labelDocument.OriginAtMargins = true;

            labelDocument.PrintPage += (_, e) =>
            {
                if (e.Graphics == null) return;

                DrawSerialNumberLabel(e.Graphics, e.MarginBounds, serialNo, itemCode, description);
                e.HasMorePages = false;
            };

            labelDocument.Print();
        }

        private static void DrawSerialNumberLabel(Graphics graphics, Rectangle bounds, string serialNo, string itemCode, string description)
        {
            using var serialFont = new Font("Arial", 9, FontStyle.Bold);
            using var itemCodeFont = new Font("Arial", 7, FontStyle.Bold);
            using var descriptionFont = new Font("Arial", 6.5f, FontStyle.Regular);
            using var centeredFormat = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Near };

            float yPos = bounds.Top;

            graphics.DrawString(serialNo, serialFont, Brushes.Black, new RectangleF(bounds.Left, yPos, bounds.Width, 14), centeredFormat);
            yPos += 14;

            if (!string.IsNullOrWhiteSpace(itemCode))
            {
                graphics.DrawString(itemCode, itemCodeFont, Brushes.Black, new RectangleF(bounds.Left, yPos, bounds.Width, 9), centeredFormat);
                yPos += 10;
            }

            if (!string.IsNullOrWhiteSpace(description))
            {
                float descriptionHeight = DrawWrappedLabelText(
                    graphics,
                    description,
                    descriptionFont,
                    Brushes.Black,
                    new RectangleF(bounds.Left, yPos, bounds.Width, 22),
                    centeredFormat,
                    maxLines: 2);
                yPos += Math.Max(8f, descriptionHeight) + 1f;
            }

            int barcodeWidth = Math.Max(180, bounds.Width - 10);
            int barcodeHeight = Math.Max(24, bounds.Height - (int)(yPos - bounds.Top) - 4);
            using var barcodeBitmap = CreateCode128BarcodeBitmap(serialNo, barcodeWidth, barcodeHeight);

            var barcodeRect = new Rectangle(bounds.Left + 5, (int)yPos, bounds.Width - 10, barcodeHeight);
            graphics.DrawImage(barcodeBitmap, barcodeRect);
        }

        private void PrintLabelTest(string printerName)
        {
            using var labelDocument = new PrintDocument();
            labelDocument.PrinterSettings.PrinterName = printerName;
            labelDocument.DefaultPageSettings.PaperSize = new PaperSize(
