                yPos += 12;

                int barcodeWidth = Math.Max(180, bounds.Width - 10);
                int barcodeHeight = Math.Max(44, bounds.Height - (int)(yPos - bounds.Top) - 16);
                using var barcodeBitmap = CreateCode128BarcodeBitmap(TestLabelBarcodeValue, barcodeWidth, barcodeHeight);

                var barcodeRect = new Rectangle(bounds.Left + 5, (int)yPos, bounds.Width - 10, barcodeHeight);
                e.Graphics.DrawImage(barcodeBitmap, barcodeRect);
                yPos += barcodeRect.Height + 2;

                e.Graphics.DrawString(TestLabelBarcodeValue, barcodeTextFont, Brushes.Black, new RectangleF(bounds.Left, yPos, bounds.Width, 10), centeredFormat);

