        private static void PopulatePrinterList(ListBox listBox, string selectedPrinterName)
        {
            listBox.Items.Clear();
            foreach (string printerName in PrinterSettings.InstalledPrinters)
            {
                listBox.Items.Add(printerName);
            }

            if (!string.IsNullOrWhiteSpace(selectedPrinterName))
            {
                int selectedIndex = listBox.Items.IndexOf(selectedPrinterName);
                if (selectedIndex >= 0)
                {
                    listBox.SelectedIndex = selectedIndex;
                    return;
                }
            }

            if (listBox.Items.Count > 0)
            {
                listBox.SelectedIndex = 0;
            }
        }

        // Helper method to update static stock quantities in Items table based on ItemLedgerEntry calculations
        private void UpdateCalculatedStockQuantities()
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var updateCmd = new SqlCommand(@"
                        UPDATE Items 
                        SET QuantityInStock = ISNULL((
                            SELECT SUM(ile.Quantity) 
                            FROM ItemLedgerEntry ile 
                            WHERE ile.ItemCode = Items.Code
                        ), 0)", connection);

                    int rowsAffected = updateCmd.ExecuteNonQuery();

                    // Optional: Log or show message about update
                    // MessageBox.Show($"Updated stock quantities for {rowsAffected} items.", "Stock Update", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error updating calculated stock quantities: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        // Helper method to get calculated stock for a specific item
        private int GetCalculatedStock(string itemCode)
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var cmd = new SqlCommand("SELECT ISNULL(SUM(Quantity), 0) FROM ItemLedgerEntry WHERE ItemCode = @itemCode", connection);
                    cmd.Parameters.AddWithValue("@itemCode", itemCode);

                    object result = cmd.ExecuteScalar();
                    return result != null ? Convert.ToInt32(result) : 0;
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error calculating stock for item {itemCode}: {ex.Message}", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return 0;
            }
        }

