        private void LoadCashFloatData(DataGridView floatGridView, DataGridView summaryGridView)
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    // Clear existing data
                    floatGridView.Rows.Clear();
                    summaryGridView.Rows.Clear();

                    // Load cash float lines
                    var floatCmd = new SqlCommand(@"
                        SELECT EntryNo, [Date], [Time], UserID, ReceiptNo, [LineNo], Denomination, Qty, TotalAmount
                        FROM CashFloatLines 
                        ORDER BY [Date] DESC, [Time] DESC, [LineNo]", connection);

                    using (var reader = floatCmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            floatGridView.Rows.Add(
                                reader["EntryNo"],
                                Convert.ToDateTime(reader["Date"]).ToString("MM/dd/yyyy"),
                                reader["Time"].ToString(),
                                reader["UserID"],
                                reader["ReceiptNo"],
                                reader["LineNo"],
                                $"{Convert.ToDecimal(reader["Denomination"]):F2}",
                                reader["Qty"],
                                $"{Convert.ToDecimal(reader["TotalAmount"]):F2}"
                            );
                        }
                    }

                    // Load linked item history entries
                    var historyCmd = new SqlCommand(@"
                        SELECT EntryDate, UserID, DocumentType, DocumentNo, ItemCode, Quantity, UnitCost, TotalCost, Description
                        FROM ItemLedgerEntry 
                        WHERE DocumentType = 'Cash Float Entry'
                        ORDER BY EntryDate DESC", connection);

                    using (var reader = historyCmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            summaryGridView.Rows.Add(
                                Convert.ToDateTime(reader["EntryDate"]).ToString("MM/dd/yyyy HH:mm"),
                                reader["UserID"],
                                reader["DocumentType"],
                                reader["DocumentNo"],
                                reader["ItemCode"],
                                reader["Quantity"],
                                $"{Convert.ToDecimal(reader["UnitCost"]):F2}",
                                $"{Convert.ToDecimal(reader["TotalCost"]):F2}",
                                reader["Description"]
                            );
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error loading cash float data: {ex.Message}", "Error",
                              MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void LogoffUser()
        {
            // Confirm logoff
            var result = MessageBox.Show($"Are you sure you want to log off?\n\nUser: {CurrentUser.FullName ?? CurrentUser.Username}",
                                       "Confirm Logoff", MessageBoxButtons.YesNo, MessageBoxIcon.Question);

            if (result == DialogResult.Yes)
            {
                try
                {
                    // Log the logout attempt
                    LogLogoutAttempt();

                    // Clear current user session
                    CurrentUser.Username = null;
                    CurrentUser.FullName = null;
                    CurrentUser.Role = null;
                    CurrentUser.IsManager = false;
                    CurrentUser.IsSuperUser = false;

                    // Close current form and show login form
                    this.Hide();

                    var loginForm = new LoginForm();
                    loginForm.FormClosed += (s, args) => Application.Exit();
                    loginForm.Show();
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error during logoff: {ex.Message}", "Logoff Error",
                                  MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            }
        }

        private void LogLogoutAttempt()
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    var cmd = new SqlCommand(@"
                        UPDATE LoginLogs 
                        SET LogoutTime = GETDATE() 
                        WHERE Username = @username 
                        AND LogoutTime IS NULL 
                        AND LoginTime = (
                            SELECT MAX(LoginTime) 
                            FROM LoginLogs 
                            WHERE Username = @username AND IsSuccessful = 1
                        )", connection);

                    cmd.Parameters.AddWithValue("@username", CurrentUser.Username ?? "UNKNOWN");
                    cmd.ExecuteNonQuery();
                }
            }
            catch (Exception)
            {
                // Silently handle logging errors to avoid disrupting logoff process
            }
        }

