        private void ShowUserSetup()
        {
            try
            {
                using (var ensureConn = new SqlConnection(connectionString))
                {
                    ensureConn.Open();
                    var ensureCmd = new SqlCommand(@"
                        IF OBJECT_ID('dbo.UserSetup', 'U') IS NOT NULL AND COL_LENGTH('dbo.UserSetup', 'WarehouseID') IS NULL
                        BEGIN
                            ALTER TABLE dbo.UserSetup ADD WarehouseID NVARCHAR(100) NULL;
                        END", ensureConn);
                    ensureCmd.ExecuteNonQuery();
                }
            }
            catch
            {
                // Best-effort; the form still works without the column present (Warehouse selection just won't persist).
            }

            var userSetupForm = new Form
            {
                Text = "User Setup Management",
                Size = new Size(1000, 600),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.Sizable,
                MaximizeBox = true,
                MinimizeBox = true
            };

            // Title
            var titleLabel = new Label
            {
                Text = "User Setup Management",
                Location = new Point(20, 20),
                Size = new Size(300, 25),
                Font = new Font("Arial", 16, FontStyle.Bold),
                ForeColor = Color.DarkBlue
            };

            // DataGridView for users
            var usersDataGridView = new DataGridView
            {
                Location = new Point(20, 60),
                Size = new Size(950, 300),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                ReadOnly = true,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                MultiSelect = false,
                AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill,
                BackgroundColor = Color.White,
                BorderStyle = BorderStyle.Fixed3D
            };

            // User details panel
            var detailsPanel = new Panel
            {
                Location = new Point(20, 380),
                Size = new Size(950, 150),
                BackColor = Color.LightGray,
                BorderStyle = BorderStyle.FixedSingle
            };

            var detailsLabel = new Label
            {
                Text = "User Details",
                Location = new Point(10, 10),
                Size = new Size(100, 20),
                Font = new Font("Arial", 12, FontStyle.Bold),
                ForeColor = Color.DarkBlue
            };

            // ID field
            var idLabel = new Label
            {
                Text = "User ID:",
                Location = new Point(20, 40),
                Size = new Size(80, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            var idTextBox = new TextBox
            {
                Location = new Point(100, 38),
                Size = new Size(150, 25),
                Font = new Font("Arial", 10)
            };

            // Password field
            var passwordLabel = new Label
            {
                Text = "Password:",
                Location = new Point(270, 40),
                Size = new Size(80, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            var passwordTextBox = new TextBox
            {
                Location = new Point(350, 38),
                Size = new Size(150, 25),
                Font = new Font("Arial", 10)
            };

            // Name field
            var nameLabel = new Label
            {
                Text = "Name:",
                Location = new Point(520, 40),
                Size = new Size(50, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            var nameTextBox = new TextBox
            {
                Location = new Point(570, 38),
                Size = new Size(200, 25),
                Font = new Font("Arial", 10)
            };

            // Manager checkbox
            var managerCheckBox = new CheckBox
            {
                Text = "Manager",
                Location = new Point(20, 75),
                Size = new Size(100, 25),
                Font = new Font("Arial", 10, FontStyle.Bold),
                ForeColor = Color.DarkGreen
            };

            // Super User checkbox
            var superUserCheckBox = new CheckBox
            {
                Text = "Super User",
                Location = new Point(130, 75),
                Size = new Size(100, 25),
                Font = new Font("Arial", 10, FontStyle.Bold),
                ForeColor = Color.DarkRed
            };

            // Active checkbox
            var activeCheckBox = new CheckBox
            {
                Text = "Active",
                Location = new Point(240, 75),
                Size = new Size(100, 25),
                Font = new Font("Arial", 10, FontStyle.Bold),
                ForeColor = Color.DarkBlue,
                Checked = true
            };

            // Warehouse field
            var warehouseLabel = new Label
            {
                Text = "Warehouse:",
                Location = new Point(20, 110),
                Size = new Size(80, 20),
                Font = new Font("Arial", 10, FontStyle.Bold)
            };
            var warehouseComboBox = new ComboBox
            {
                Location = new Point(100, 108),
                Size = new Size(200, 25),
                Font = new Font("Arial", 10),
                DropDownStyle = ComboBoxStyle.DropDownList
            };
            var warehouseIdByName = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            var warehouseNameById = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            // Buttons
            var addButton = new Button
            {
                Text = "Add User",
                Location = new Point(400, 75),
                Size = new Size(80, 30),
                BackColor = Color.Green,
                ForeColor = Color.White,
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            var editButton = new Button
            {
                Text = "Edit User",
                Location = new Point(490, 75),
                Size = new Size(80, 30),
                BackColor = Color.Orange,
                ForeColor = Color.White,
                Font = new Font("Arial", 9, FontStyle.Bold),
                Enabled = false
            };

            var deleteButton = new Button
            {
                Text = "Delete User",
                Location = new Point(580, 75),
                Size = new Size(80, 30),
                BackColor = Color.Red,
                ForeColor = Color.White,
                Font = new Font("Arial", 9, FontStyle.Bold),
                Enabled = false
            };

            var refreshButton = new Button
            {
                Text = "Refresh",
                Location = new Point(670, 75),
                Size = new Size(80, 30),
                BackColor = Color.Blue,
                ForeColor = Color.White,
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            var closeButton = new Button
            {
                Text = "Close",
                Location = new Point(850, 110),
                Size = new Size(80, 30),
                BackColor = Color.Gray,
                ForeColor = Color.White,
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            // Add controls to details panel
            detailsPanel.Controls.AddRange(new Control[]
            {
                detailsLabel, idLabel, idTextBox, passwordLabel, passwordTextBox,
                nameLabel, nameTextBox, managerCheckBox, superUserCheckBox, activeCheckBox,
                warehouseLabel, warehouseComboBox,
                addButton, editButton, deleteButton, refreshButton
            });

            // Add all controls to form
            userSetupForm.Controls.AddRange(new Control[]
            {
                titleLabel, usersDataGridView, detailsPanel, closeButton
            });

            // Load available warehouses into the combo box (ID stored on UserSetup, Name shown to the user)
            Action loadWarehouseOptions = () =>
            {
                warehouseComboBox.Items.Clear();
                warehouseComboBox.Items.Add("(None)");
                warehouseIdByName.Clear();
                warehouseNameById.Clear();

                try
                {
                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();
                        var cmd = new SqlCommand("SELECT ID, [Name] FROM dbo.Warehouses ORDER BY [Name]", connection);
                        using (var reader = cmd.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                var whId = reader["ID"]?.ToString() ?? "";
                                var whName = reader["Name"]?.ToString() ?? "";
                                if (string.IsNullOrWhiteSpace(whName) || string.IsNullOrWhiteSpace(whId))
                                    continue;

                                if (!warehouseIdByName.ContainsKey(whName))
                                {
                                    warehouseComboBox.Items.Add(whName);
                                    warehouseIdByName[whName] = whId;
                                }
                                warehouseNameById[whId] = whName;
                            }
                        }
                    }
                }
                catch
                {
                    // Best-effort; the combo box will just show "(None)" if warehouses can't be loaded.
                }

                warehouseComboBox.SelectedIndex = 0;
            };

            // Load users data
            Action loadUsers = () =>
            {
                try
                {
                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();
                        var cmd = new SqlCommand(@"
                            SELECT u.ID, u.[Name], u.[Manager], u.[SuperUser], u.IsActive, 
                                   u.CreatedDate, u.LastLoginDate, u.WarehouseID, w.[Name] AS WarehouseName
                            FROM UserSetup u
                            LEFT JOIN dbo.Warehouses w ON w.ID = u.WarehouseID
                            ORDER BY u.ID", connection);

                        var adapter = new SqlDataAdapter(cmd);
                        var dataTable = new DataTable();
                        adapter.Fill(dataTable);

                        usersDataGridView.DataSource = dataTable;

                        // Format columns
                        if (usersDataGridView.Columns.Count > 0)
                        {
                            usersDataGridView.Columns["ID"].HeaderText = "User ID";
                            usersDataGridView.Columns["ID"].Width = 100;
                            usersDataGridView.Columns["Name"].HeaderText = "Full Name";
                            usersDataGridView.Columns["Name"].Width = 200;
                            usersDataGridView.Columns["Manager"].HeaderText = "Manager";
                            usersDataGridView.Columns["Manager"].Width = 80;
                            usersDataGridView.Columns["SuperUser"].HeaderText = "Super User";
                            usersDataGridView.Columns["SuperUser"].Width = 90;
                            usersDataGridView.Columns["IsActive"].HeaderText = "Active";
                            usersDataGridView.Columns["IsActive"].Width = 60;
                            usersDataGridView.Columns["CreatedDate"].HeaderText = "Created";
                            usersDataGridView.Columns["CreatedDate"].Width = 120;
                            usersDataGridView.Columns["LastLoginDate"].HeaderText = "Last Login";
                            usersDataGridView.Columns["LastLoginDate"].Width = 120;
                            if (usersDataGridView.Columns.Contains("WarehouseID"))
                            {
                                usersDataGridView.Columns["WarehouseID"].Visible = false;
                            }
                            if (usersDataGridView.Columns.Contains("WarehouseName"))
                            {
                                usersDataGridView.Columns["WarehouseName"].HeaderText = "Warehouse";
                                usersDataGridView.Columns["WarehouseName"].Width = 120;
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error loading users: {ex.Message}", "Database Error",
                                  MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            // Event handlers
            usersDataGridView.SelectionChanged += (s, e) =>
            {
                if (usersDataGridView.SelectedRows.Count > 0)
                {
                    var row = usersDataGridView.SelectedRows[0];
                    idTextBox.Text = row.Cells["ID"].Value?.ToString() ?? "";
                    passwordTextBox.Text = ""; // Don't show passwords
                    nameTextBox.Text = row.Cells["Name"].Value?.ToString() ?? "";
                    managerCheckBox.Checked = Convert.ToBoolean(row.Cells["Manager"].Value ?? false);
                    superUserCheckBox.Checked = Convert.ToBoolean(row.Cells["SuperUser"].Value ?? false);
                    activeCheckBox.Checked = Convert.ToBoolean(row.Cells["IsActive"].Value ?? true);

                    var selectedWarehouseId = usersDataGridView.Columns.Contains("WarehouseID") ? row.Cells["WarehouseID"].Value?.ToString() ?? "" : "";
                    if (!string.IsNullOrWhiteSpace(selectedWarehouseId) && warehouseNameById.TryGetValue(selectedWarehouseId, out var selectedWarehouseName))
                    {
                        warehouseComboBox.SelectedItem = selectedWarehouseName;
                    }
                    else
                    {
                        warehouseComboBox.SelectedIndex = 0;
                    }

                    editButton.Enabled = true;
                    deleteButton.Enabled = true;
                }
                else
                {
                    editButton.Enabled = false;
                    deleteButton.Enabled = false;
                }
            };

            addButton.Click += (s, e) =>
            {
                if (string.IsNullOrWhiteSpace(idTextBox.Text) ||
                    string.IsNullOrWhiteSpace(passwordTextBox.Text) ||
                    string.IsNullOrWhiteSpace(nameTextBox.Text))
                {
                    MessageBox.Show("Please fill in all required fields (ID, Password, Name).",
                                  "Validation Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                try
                {
                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();

                        // Check if user ID already exists
                        var checkCmd = new SqlCommand("SELECT COUNT(*) FROM UserSetup WHERE ID = @id", connection);
                        checkCmd.Parameters.AddWithValue("@id", idTextBox.Text.Trim());
                        int exists = Convert.ToInt32(checkCmd.ExecuteScalar());

                        if (exists > 0)
                        {
                            MessageBox.Show("User ID already exists. Please choose a different ID.",
                                          "Duplicate ID", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                            return;
                        }

                        string addWarehouseName = warehouseComboBox.SelectedItem?.ToString() ?? "(None)";
                        string? addWarehouseId = (addWarehouseName != "(None)" && warehouseIdByName.TryGetValue(addWarehouseName, out var addWhId)) ? addWhId : null;

                        var cmd = new SqlCommand(@"
                            INSERT INTO UserSetup (ID, Password, [Name], [Manager], [SuperUser], IsActive, WarehouseID)
                            VALUES (@id, @password, @name, @manager, @superUser, @active, @warehouseId)", connection);

                        cmd.Parameters.AddWithValue("@id", idTextBox.Text.Trim());
                        cmd.Parameters.AddWithValue("@password", passwordTextBox.Text);
                        cmd.Parameters.AddWithValue("@name", nameTextBox.Text.Trim());
                        cmd.Parameters.AddWithValue("@manager", managerCheckBox.Checked);
                        cmd.Parameters.AddWithValue("@superUser", superUserCheckBox.Checked);
                        cmd.Parameters.AddWithValue("@active", activeCheckBox.Checked);
                        cmd.Parameters.AddWithValue("@warehouseId", (object?)addWarehouseId ?? DBNull.Value);

                        cmd.ExecuteNonQuery();

                        MessageBox.Show("User added successfully!", "Success",
                                      MessageBoxButtons.OK, MessageBoxIcon.Information);

                        // Clear fields and refresh
                        idTextBox.Clear();
                        passwordTextBox.Clear();
                        nameTextBox.Clear();
                        managerCheckBox.Checked = false;
                        superUserCheckBox.Checked = false;
                        activeCheckBox.Checked = true;
                        warehouseComboBox.SelectedIndex = 0;
                        loadUsers();
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error adding user: {ex.Message}", "Database Error",
                                  MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            editButton.Click += (s, e) =>
            {
                if (usersDataGridView.SelectedRows.Count == 0)
                {
                    MessageBox.Show("Please select a user to edit.", "No Selection",
                                  MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                if (string.IsNullOrWhiteSpace(nameTextBox.Text))
                {
                    MessageBox.Show("Name field cannot be empty.", "Validation Error",
                                  MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                try
                {
                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();

                        string sql = @"
                            UPDATE UserSetup 
                            SET [Name] = @name, [Manager] = @manager, [SuperUser] = @superUser, IsActive = @active, WarehouseID = @warehouseId";

                        // Only update password if it's provided
                        if (!string.IsNullOrWhiteSpace(passwordTextBox.Text))
                        {
                            sql += ", Password = @password";
                        }

                        sql += " WHERE ID = @id";

                        string editWarehouseName = warehouseComboBox.SelectedItem?.ToString() ?? "(None)";
                        string? editWarehouseId = (editWarehouseName != "(None)" && warehouseIdByName.TryGetValue(editWarehouseName, out var editWhId)) ? editWhId : null;

                        var cmd = new SqlCommand(sql, connection);
                        cmd.Parameters.AddWithValue("@id", idTextBox.Text.Trim());
                        cmd.Parameters.AddWithValue("@name", nameTextBox.Text.Trim());
                        cmd.Parameters.AddWithValue("@manager", managerCheckBox.Checked);
                        cmd.Parameters.AddWithValue("@superUser", superUserCheckBox.Checked);
                        cmd.Parameters.AddWithValue("@active", activeCheckBox.Checked);
                        cmd.Parameters.AddWithValue("@warehouseId", (object?)editWarehouseId ?? DBNull.Value);

                        if (!string.IsNullOrWhiteSpace(passwordTextBox.Text))
                        {
                            cmd.Parameters.AddWithValue("@password", passwordTextBox.Text);
                        }

                        int rowsAffected = cmd.ExecuteNonQuery();

                        if (rowsAffected > 0)
                        {
                            MessageBox.Show("User updated successfully!", "Success",
                                          MessageBoxButtons.OK, MessageBoxIcon.Information);
                            loadUsers();
                        }
                        else
                        {
                            MessageBox.Show("No user was updated. Please try again.", "Update Failed",
                                          MessageBoxButtons.OK, MessageBoxIcon.Warning);
                        }
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error updating user: {ex.Message}", "Database Error",
                                  MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            deleteButton.Click += (s, e) =>
            {
                if (usersDataGridView.SelectedRows.Count == 0)
                {
                    MessageBox.Show("Please select a user to delete.", "No Selection",
                                  MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                string userIdToDelete = idTextBox.Text.Trim();

                // Prevent deleting the admin user
                if (userIdToDelete.ToLower() == "admin")
                {
                    MessageBox.Show("Cannot delete the admin user.", "Delete Restricted",
                                  MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }

                var result = MessageBox.Show($"Are you sure you want to delete user '{userIdToDelete}'?\n\nThis action cannot be undone.",
                                           "Confirm Delete", MessageBoxButtons.YesNo, MessageBoxIcon.Question);

                if (result == DialogResult.Yes)
                {
                    try
                    {
                        using (var connection = new SqlConnection(connectionString))
                        {
                            connection.Open();
                            var cmd = new SqlCommand("DELETE FROM UserSetup WHERE ID = @id", connection);
                            cmd.Parameters.AddWithValue("@id", userIdToDelete);

                            int rowsAffected = cmd.ExecuteNonQuery();

                            if (rowsAffected > 0)
                            {
                                MessageBox.Show("User deleted successfully!", "Success",
                                              MessageBoxButtons.OK, MessageBoxIcon.Information);

                                // Clear fields and refresh
                                idTextBox.Clear();
                                passwordTextBox.Clear();
                                nameTextBox.Clear();
                                managerCheckBox.Checked = false;
                                superUserCheckBox.Checked = false;
                                activeCheckBox.Checked = true;
                                warehouseComboBox.SelectedIndex = 0;
                                loadUsers();
                            }
                            else
                            {
                                MessageBox.Show("No user was deleted. Please try again.", "Delete Failed",
                                              MessageBoxButtons.OK, MessageBoxIcon.Warning);
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Error deleting user: {ex.Message}", "Database Error",
                                      MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                }
            };

            refreshButton.Click += (s, e) => loadUsers();
            closeButton.Click += (s, e) => userSetupForm.Close();

            // Load initial data
            loadWarehouseOptions();
            loadUsers();

            // Show the form
            userSetupForm.ShowDialog();
        }

        public void ShowTransPaymentEntryForm(string receiptNo)
        {
            var paymentEntryForm = new Form
            {
                Text = "Transaction Payment Entries",
                Size = new Size(1200, 700),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.Sizable,
                MaximizeBox = true,
                MinimizeBox = true
            };

            // Title
            var titleLabel = new Label
            {
                Text = "Transaction Payment Entries",
                Location = new Point(20, 20),
                Size = new Size(400, 25),
                Font = new Font("Arial", 16, FontStyle.Bold),
                ForeColor = Color.DarkBlue
            };

            // Filter Panel
            var filterPanel = new Panel
            {
                Location = new Point(20, 60),
                Size = new Size(1150, 80),
                BorderStyle = BorderStyle.FixedSingle,
                BackColor = Color.LightGray
            };

            var storeLabel = new Label
            {
                Text = "Store No:",
                Location = new Point(10, 15),
                Size = new Size(70, 20),
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            var storeTextBox = new TextBox
            {
                Location = new Point(10, 35),
                Size = new Size(100, 20)
            };

            var terminalLabel = new Label
            {
                Text = "Terminal No:",
                Location = new Point(120, 15),
                Size = new Size(80, 20),
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            var terminalTextBox = new TextBox
            {
                Location = new Point(120, 35),
                Size = new Size(100, 20)
            };

            var transactionLabel = new Label
            {
                Text = "Transaction No:",
                Location = new Point(230, 15),
                Size = new Size(100, 20),
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            var transactionTextBox = new TextBox
            {
                Location = new Point(230, 35),
                Size = new Size(120, 20)
            };

            var receiptLabel = new Label
            {
                Text = "Receipt No:",
                Location = new Point(360, 15),
                Size = new Size(80, 20),
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            var receiptTextBox = new TextBox
            {
                Location = new Point(360, 35),
                Size = new Size(120, 20)
            };

            var searchButton = new Button
            {
                Text = "Search",
                Location = new Point(490, 33),
                Size = new Size(80, 25),
                BackColor = Color.DarkBlue,
                ForeColor = Color.White,
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            var refreshButton = new Button
            {
                Text = "Refresh",
                Location = new Point(580, 33),
                Size = new Size(80, 25),
                BackColor = Color.DarkGreen,
                ForeColor = Color.White,
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            var exportButton = new Button
            {
                Text = "Export",
                Location = new Point(670, 33),
                Size = new Size(80, 25),
                BackColor = Color.DarkOrange,
                ForeColor = Color.White,
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            // DataGridView for payment entries
            var paymentDataGridView = new DataGridView
            {
                Location = new Point(20, 160),
                Size = new Size(1150, 450),
                AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill,
                ReadOnly = true,
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                SelectionMode = DataGridViewSelectionMode.FullRowSelect,
                MultiSelect = false,
                BackgroundColor = Color.White,
                GridColor = Color.LightGray
            };

            // Close button
            var closeButton = new Button
            {
                Text = "Close",
                Location = new Point(1090, 620),
                Size = new Size(80, 30),
                BackColor = Color.Gray,
                ForeColor = Color.White,
                Font = new Font("Arial", 9, FontStyle.Bold)
            };

            // Load payment entries function
            Action loadPaymentEntries = () =>
            {
                try
                {
                    using (var connection = new SqlConnection(connectionString))
                    {
                        connection.Open();
                        var query = @"
                            SELECT 
                                StoreNo,
                                POSTerminalNo,
                                TransactionNo,
                                ReceiptNo,
                                [LineNo],
                                TenderTypeCode,
                                Amount,
                                UserID,
                                Date,
                                Time
                            FROM TransPaymentEntry 
                            WHERE 1=1";

                        var parameters = new List<SqlParameter>();

                        // Filter by passed receiptNo if provided
                        if (!string.IsNullOrWhiteSpace(receiptNo))
                        {
                            query += " AND ReceiptNo = @receiptNo";
                            parameters.Add(new SqlParameter("@receiptNo", receiptNo));
                        }

                        // Also allow UI filter
                        if (!string.IsNullOrWhiteSpace(storeTextBox.Text))
                        {
                            query += " AND StoreNo = @storeNo";
                            parameters.Add(new SqlParameter("@storeNo", storeTextBox.Text.Trim()));
                        }
                        if (!string.IsNullOrWhiteSpace(terminalTextBox.Text))
                        {
                            query += " AND POSTerminalNo = @terminalNo";
                            parameters.Add(new SqlParameter("@terminalNo", terminalTextBox.Text.Trim()));
                        }
                        if (!string.IsNullOrWhiteSpace(transactionTextBox.Text))
                        {
                            query += " AND TransactionNo = @transactionNo";
                            parameters.Add(new SqlParameter("@transactionNo", transactionTextBox.Text.Trim()));
                        }
                        if (!string.IsNullOrWhiteSpace(receiptTextBox.Text))
                        {
                            query += " AND ReceiptNo = @receiptNoUI";
                            parameters.Add(new SqlParameter("@receiptNoUI", receiptTextBox.Text.Trim()));
                        }

                        query += " ORDER BY Date DESC, Time DESC, ReceiptNo, [LineNo]";

                        var cmd = new SqlCommand(query, connection);
                        foreach (var param in parameters)
                        {
                            cmd.Parameters.Add(param);
                        }

                        var adapter = new SqlDataAdapter(cmd);
                        var dataTable = new DataTable();
                        adapter.Fill(dataTable);

                        paymentDataGridView.DataSource = dataTable;

                        // Format columns (unchanged)
                        if (paymentDataGridView.Columns["StoreNo"] != null)
                            paymentDataGridView.Columns["StoreNo"].HeaderText = "Store No";
                        if (paymentDataGridView.Columns["POSTerminalNo"] != null)
                            paymentDataGridView.Columns["POSTerminalNo"].HeaderText = "Terminal No";
                        if (paymentDataGridView.Columns["TransactionNo"] != null)
                            paymentDataGridView.Columns["TransactionNo"].HeaderText = "Transaction No";
                        if (paymentDataGridView.Columns["ReceiptNo"] != null)
                            paymentDataGridView.Columns["ReceiptNo"].HeaderText = "Receipt No";
                        if (paymentDataGridView.Columns["LineNo"] != null)
                            paymentDataGridView.Columns["LineNo"].HeaderText = "Line No";
                        if (paymentDataGridView.Columns["TenderTypeCode"] != null)
                            paymentDataGridView.Columns["TenderTypeCode"].HeaderText = "Tender Type";
                        if (paymentDataGridView.Columns["Amount"] != null)
                        {
                            paymentDataGridView.Columns["Amount"].HeaderText = "Amount";
                            paymentDataGridView.Columns["Amount"].DefaultCellStyle.Format = "C2";
                            paymentDataGridView.Columns["Amount"].DefaultCellStyle.Alignment = DataGridViewContentAlignment.MiddleRight;
                        }
                        if (paymentDataGridView.Columns["UserID"] != null)
                            paymentDataGridView.Columns["UserID"].HeaderText = "User ID";
                        if (paymentDataGridView.Columns["Date"] != null)
                        {
                            paymentDataGridView.Columns["Date"].HeaderText = "Date";
                            paymentDataGridView.Columns["Date"].DefaultCellStyle.Format = "MM-dd-yyy";
                        }
                        if (paymentDataGridView.Columns["Time"] != null)
                        {
                            paymentDataGridView.Columns["Time"].HeaderText = "Time";
                            paymentDataGridView.CellFormatting += (sender, args) =>
                            {
                                if (args.ColumnIndex == paymentDataGridView.Columns["Time"].Index)
                                {
                                    if (args.Value is TimeSpan timeSpan)
                                    {
                                        DateTime dt = DateTime.Today.Add(timeSpan);
                                        args.Value = dt.ToString("hh:mm:ss tt");
                                        args.FormattingApplied = true;
                                    }
                                    else if (args.Value is string s && TimeSpan.TryParse(s, out TimeSpan ts))
                                    {
                                        DateTime dt = DateTime.Today.Add(ts);
                                        args.Value = dt.ToString("hh:mm:ss tt");
                                        args.FormattingApplied = true;
                                    }
                                }
                            };
                        }
                        if (paymentDataGridView.Columns["EntryDate"] != null)
                        {
                            paymentDataGridView.Columns["EntryDate"].HeaderText = "Entry Date";
                            paymentDataGridView.Columns["EntryDate"].DefaultCellStyle.Format = "yyyy-MM-dd HH:mm:ss";
                        }
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error loading payment entries: {ex.Message}", "Database Error",
                                  MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            // Event handlers
            searchButton.Click += (s, e) => loadPaymentEntries();
            refreshButton.Click += (s, e) =>
            {
                storeTextBox.Clear();
                terminalTextBox.Clear();
                transactionTextBox.Clear();
                receiptTextBox.Clear();
                loadPaymentEntries();
            };

            exportButton.Click += (s, e) =>
            {
                try
                {
                    if (paymentDataGridView.Rows.Count == 0)
                    {
                        MessageBox.Show("No data to export.", "Export", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }

                    var saveDialog = new SaveFileDialog
                    {
                        Filter = "CSV Files (*.csv)|*.csv",
                        FileName = $"PaymentEntries_{DateTime.Now:yyyyMMdd_HHmmss}.csv"
                    };

                    if (saveDialog.ShowDialog() == DialogResult.OK)
                    {
                        var csv = new System.Text.StringBuilder();

                        // Headers
                        var headers = new List<string>();
                        foreach (DataGridViewColumn column in paymentDataGridView.Columns)
                        {
                            headers.Add($"\"{column.HeaderText}\"");
                        }
                        csv.AppendLine(string.Join(",", headers));

                        // Data rows
                        foreach (DataGridViewRow row in paymentDataGridView.Rows)
                        {
                            if (!row.IsNewRow)
                            {
                                var values = new List<string>();
                                foreach (DataGridViewCell cell in row.Cells)
                                {
                                    values.Add($"\"{cell.Value?.ToString() ?? ""}\"");
                                }
                                csv.AppendLine(string.Join(",", values));
                            }
                        }

                        System.IO.File.WriteAllText(saveDialog.FileName, csv.ToString());
                        MessageBox.Show($"Data exported successfully to {saveDialog.FileName}", "Export Complete",
                                      MessageBoxButtons.OK, MessageBoxIcon.Information);
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error exporting data: {ex.Message}", "Export Error",
                                  MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            closeButton.Click += (s, e) => paymentEntryForm.Close();

            // Add controls to filter panel
            filterPanel.Controls.AddRange(new Control[] {
                storeLabel, storeTextBox, terminalLabel, terminalTextBox,
                transactionLabel, transactionTextBox, receiptLabel, receiptTextBox,
                searchButton, refreshButton, exportButton
            });

            // Add all controls to form
            paymentEntryForm.Controls.AddRange(new Control[] {
                titleLabel, filterPanel, paymentDataGridView, closeButton
            });

            // Load initial data
            loadPaymentEntries();

            // Show the form
            paymentEntryForm.ShowDialog();
        }

