        private void ShowCashDeclarationDialog()
        {
            var cashDeclForm = new Form
            {
                Text = "Cash Declaration - End of Day",
                Size = new Size(800, 600),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = Color.White,
                FormBorderStyle = FormBorderStyle.FixedDialog,
                MaximizeBox = false,
                MinimizeBox = false
            };

            // Title
            var titleLabel = new Label
            {
                Text = "CASH DECLARATION BY DENOMINATION",
                Font = new Font("Arial", 14, FontStyle.Bold),
                ForeColor = Color.DarkBlue,
                Location = new Point(20, 20),
                Size = new Size(400, 30),
                TextAlign = ContentAlignment.MiddleLeft
            };

            // EOD ID Display
            var eodIdLabel = new Label
            {
                Text = $"EOD ID: {GetNextEODID()}",
                Font = new Font("Arial", 12, FontStyle.Bold),
                ForeColor = Color.DarkGreen,
                Location = new Point(450, 20),
                Size = new Size(300, 30),
                TextAlign = ContentAlignment.MiddleLeft
            };

            // Date and User info
            var dateTimeLabel = new Label
            {
                Text = $"Date: {DateTime.Now:yyyy-MM-dd HH:mm:ss} | User: {username}",
                Font = new Font("Arial", 10),
                ForeColor = Color.Black,
                Location = new Point(20, 55),
                Size = new Size(500, 25)
            };

            // DataGridView for denomination entry
            var denomGridView = new DataGridView
            {
                Location = new Point(20, 90),
                Size = new Size(740, 350),
                BackColor = Color.White,
                Font = new Font("Arial", 11),
                AllowUserToAddRows = false,
                AllowUserToDeleteRows = false,
                SelectionMode = DataGridViewSelectionMode.CellSelect,
                AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill
            };

            // Add columns
            denomGridView.Columns.Add("Denomination", "Denomination");
            denomGridView.Columns.Add("Quantity", "Quantity");
            denomGridView.Columns.Add("TotalAmount", "Total Amount");

            // Set column properties
            denomGridView.Columns["Denomination"].ReadOnly = true;
            denomGridView.Columns["Quantity"].ValueType = typeof(int);
            denomGridView.Columns["TotalAmount"].ReadOnly = true;

            // Total cash label (declare before use)
            var totalCashLabel = new Label
            {
                Text = "Total Declared Cash: ?0.00",
                Font = new Font("Arial", 12, FontStyle.Bold),
                ForeColor = Color.DarkRed,
                Location = new Point(20, 450),
                Size = new Size(300, 30)
            };

            // Load standard Philippine denominations
            var denominations = new decimal[] { 1000, 500, 200, 100, 50, 20, 10, 5, 1, 0.25m, 0.10m, 0.05m, 0.01m };

            foreach (var denom in denominations)
            {
                var row = new DataGridViewRow();
                row.CreateCells(denomGridView);
                row.Cells[0].Value = $"{denom:F2}";
                row.Cells[1].Value = 0;
                row.Cells[2].Value = $"0.00";
                denomGridView.Rows.Add(row);
            }

            // Handle cell value changes
            denomGridView.CellValueChanged += (s, e) =>
            {
                if (e.ColumnIndex == 1 && e.RowIndex >= 0) // Quantity column
                {
                    var grid = s as DataGridView;
                    if (grid != null)
                    {
                        var denomText = grid.Rows[e.RowIndex].Cells[0].Value?.ToString() ?? "";
                        var quantityText = grid.Rows[e.RowIndex].Cells[1].Value?.ToString() ?? "0";

                        if (decimal.TryParse(denomText.Replace("?", ""), out decimal denomination) &&
                            int.TryParse(quantityText, out int quantity))
                        {
                            decimal total = denomination * quantity;
                            grid.Rows[e.RowIndex].Cells[2].Value = $"{total:F2}";
                        }

                        UpdateTotalCash(denomGridView, totalCashLabel);
                    }
                }
            };

            // Buttons
            var saveButton = new Button
            {
                Text = "Save Declaration",
                Location = new Point(450, 450),
                Size = new Size(120, 35),
                BackColor = Color.Green,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var clearButton = new Button
            {
                Text = "Clear All",
                Location = new Point(580, 450),
                Size = new Size(80, 35),
                BackColor = Color.Orange,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            var closeButton = new Button
            {
                Text = "Close",
                Location = new Point(670, 450),
                Size = new Size(80, 35),
                BackColor = Color.DarkGray,
                ForeColor = Color.White,
                Font = new Font("Arial", 10, FontStyle.Bold)
            };

            // Event handlers
            saveButton.Click += (s, e) =>
            {
                try
                {
                    SaveCashDeclaration(denomGridView, eodIdLabel.Text.Replace("EOD ID: ", ""));
                    MessageBox.Show("Cash declaration saved successfully!", "Success",
                                  MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error saving cash declaration: {ex.Message}", "Error",
                                  MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            clearButton.Click += (s, e) =>
            {
                foreach (DataGridViewRow row in denomGridView.Rows)
                {
                    row.Cells[1].Value = 0;
                    row.Cells[2].Value = "?0.00";
                }
                UpdateTotalCash(denomGridView, totalCashLabel);
            };

            closeButton.Click += (s, e) => cashDeclForm.Close();

            // Add controls to form
            cashDeclForm.Controls.AddRange(new Control[] {
                titleLabel, eodIdLabel, dateTimeLabel, denomGridView, totalCashLabel,
                saveButton, clearButton, closeButton
            });

            cashDeclForm.ShowDialog();
        }

        private void UpdateTotalCash(DataGridView gridView, Label totalLabel)
        {
            decimal total = 0;
            foreach (DataGridViewRow row in gridView.Rows)
            {
                var totalAmountText = row.Cells[2].Value?.ToString()?.Replace("?", "") ?? "0";
                if (decimal.TryParse(totalAmountText, out decimal amount))
                {
                    total += amount;
                }
            }
            totalLabel.Text = $"Total Declared Cash: {total:F2}";
        }


        // Opens the Tender Declaration form
        private void ShowTenderDeclarationDialog()
        {
            if (GlobalSettings.IsTenderDeclarationRestrictedTime(DateTime.Now))
            {
                MessageBox.Show(GlobalSettings.TenderDeclarationRestrictedMessage, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            if (IsCurrentWarehouseProductionForLabels())
            {
                // Ensure stock counts have been performed today before allowing Tender Declaration in production warehouses.
                bool hasCountsToday = false;
                try
                {
                    using (var conn = new SqlConnection(connectionString))
                    {
                        conn.Open();
                        using (var cmd = new SqlCommand("SELECT COUNT(1) FROM dbo.InventoryStockCounts WHERE CAST(EnteredAtUtc AS date) = CAST(SYSUTCDATETIME() AS date)", conn))
                        {
                            var o = cmd.ExecuteScalar();
                            if (o != null && o != DBNull.Value)
                            {
                                try { hasCountsToday = Convert.ToInt32(o) > 0; } catch { hasCountsToday = false; }
                            }
                        }
                    }
                }
                catch { hasCountsToday = false; }

                if (!hasCountsToday)
                {
                    // Automatically open Stock Counts if none recorded today. User must complete or cancel; then re-check.
                    try
                    {
                        using (var sc = new StockCountsForm())
                        {
                            sc.ShowDialog(this);
                        }
                    }
                    catch (Exception ex)
                    {
                        MessageBox.Show($"Failed to open Stock Counts: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        return;
                    }

                    // Re-check after the StockCounts form closes
                    try
                    {
                        using (var conn = new SqlConnection(connectionString))
                        {
                            conn.Open();
                            using (var cmd = new SqlCommand("SELECT COUNT(1) FROM dbo.InventoryStockCounts WHERE CAST(EnteredAtUtc AS date) = CAST(SYSUTCDATETIME() AS date)", conn))
                            {
                                var o = cmd.ExecuteScalar();
                                if (o != null && o != DBNull.Value)
                                {
                                    try { hasCountsToday = Convert.ToInt32(o) > 0; } catch { hasCountsToday = false; }
                                }
                            }
                        }
                    }
                    catch { hasCountsToday = false; }

                    if (!hasCountsToday)
                    {
                        MessageBox.Show("Stock counts not recorded. Tender Declaration cannot proceed.", "Aborted", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }
                }
            }

            currentReceiptNo = GenerateCentralizedReceiptNumber();
            var tenderForm = new TenderDeclarationForm(currentReceiptNo);
            tenderForm.ShowDialog(this);
        }


        private void SaveCashDeclaration(DataGridView gridView, string eodId)
        {
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                using (var transaction = connection.BeginTransaction())
                {
                    try
                    {
                        // Create TenderDecl table if it doesn't exist
                        string createTableSql = @"
                            IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='TenderDecl' AND xtype='U')
                            CREATE TABLE TenderDecl (
                                EODID NVARCHAR(50) NOT NULL,
                                Denomination DECIMAL(18,2) NOT NULL,
                                Quantity INT NOT NULL,
                                TotalAmount DECIMAL(18,2) NOT NULL,
                                UserID NVARCHAR(50) NULL,
                                DeclarationDate DATETIME DEFAULT GETDATE(),
                                CONSTRAINT PK_TenderDecl PRIMARY KEY (EODID, Denomination)
                            )";
                        using (var cmd = new SqlCommand(createTableSql, connection, transaction))
                        {
                            cmd.ExecuteNonQuery();
                        }

                        // Delete existing declarations for this EOD ID
                        string deleteSql = "DELETE FROM TenderDecl WHERE EODID = @EODID";
                        using (var cmd = new SqlCommand(deleteSql, connection, transaction))
                        {
                            cmd.Parameters.AddWithValue("@EODID", eodId);
                            cmd.ExecuteNonQuery();
                        }

                        // Insert new declarations
                        string insertSql = @"
                            INSERT INTO TenderDecl (EODID, Denomination, Quantity, TotalAmount, UserID)
                            VALUES (@EODID, @Denomination, @Quantity, @TotalAmount, @UserID)";

                        foreach (DataGridViewRow row in gridView.Rows)
                        {
                            var denomText = row.Cells[0].Value?.ToString()?.Replace("?", "") ?? "0";
                            var quantityText = row.Cells[1].Value?.ToString() ?? "0";
                            var totalText = row.Cells[2].Value?.ToString()?.Replace("?", "") ?? "0";

                            if (decimal.TryParse(denomText, out decimal denomination) &&
                                int.TryParse(quantityText, out int quantity) &&
                                decimal.TryParse(totalText, out decimal total) &&
                                quantity > 0) // Only save entries with quantities > 0
                            {
                                using (var cmd = new SqlCommand(insertSql, connection, transaction))
                                {
                                    cmd.Parameters.AddWithValue("@EODID", eodId);
                                    cmd.Parameters.AddWithValue("@Denomination", denomination);
                                    cmd.Parameters.AddWithValue("@Quantity", quantity);
                                    cmd.Parameters.AddWithValue("@TotalAmount", total);
                                    cmd.Parameters.AddWithValue("@UserID", username);
                                    cmd.ExecuteNonQuery();
                                }
                            }
                        }

                        transaction.Commit();
                    }
                    catch
                    {
                        TryRollbackTransaction(transaction);
                        throw;
                    }
                }
            }
        }

        private string GenerateEODReport(DateTime reportDate)
        {
            var report = new StringBuilder();
            report.AppendLine("".PadRight(80, '='));
            report.AppendLine("RS PET STOP - AQUARIUM POS");
            report.AppendLine("END OF DAY REPORT");
            report.AppendLine($"Report Date: {reportDate:dddd, MMMM dd, yyyy}");
            report.AppendLine($"Generated: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
            report.AppendLine("".PadRight(80, '='));
            report.AppendLine();

            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();

                    // Get transaction summary
                    var transactionSummary = GetTransactionSummary(connection, reportDate);
                    report.AppendLine("TRANSACTION SUMMARY");
                    report.AppendLine("".PadRight(50, '-'));
                    report.AppendLine($"Total Transactions: {transactionSummary.TotalTransactions}");
                    report.AppendLine($"Total Sales Amount: ${transactionSummary.TotalSalesAmount:F2}");
                    report.AppendLine($"Total Items Sold: {transactionSummary.TotalItemsSold}");
                    report.AppendLine($"Average Transaction: ${transactionSummary.AverageTransaction:F2}");
                    report.AppendLine();

                    // Get payment breakdown
                    var paymentBreakdown = GetPaymentBreakdown(connection, reportDate);
                    report.AppendLine("PAYMENT METHOD BREAKDOWN");
                    report.AppendLine("".PadRight(50, '-'));
                    decimal totalPayments = 0;
                    foreach (var payment in paymentBreakdown)
                    {
                        report.AppendLine($"{payment.TenderType.PadRight(20)} ${payment.Amount:F2} ({payment.Count} transactions)");
                        totalPayments += payment.Amount;
                    }
                    report.AppendLine("".PadRight(50, '-'));
                    report.AppendLine($"{"Total Payments:".PadRight(20)} ${totalPayments:F2}");
                    report.AppendLine();

                    // Get hourly sales breakdown
                    var hourlySales = GetHourlySales(connection, reportDate);
                    report.AppendLine("HOURLY SALES BREAKDOWN");
                    report.AppendLine("".PadRight(50, '-'));
                    foreach (var hour in hourlySales)
                    {
                        var timeRange = $"{hour.Hour:00}:00-{(hour.Hour + 1):00}:00";
                        report.AppendLine($"{timeRange.PadRight(15)} ${hour.Amount:F2} ({hour.TransactionCount} trans)");
                    }
                    report.AppendLine();

                    // Get top selling items
                    var topItems = GetTopSellingItems(connection, reportDate);
                    report.AppendLine("TOP SELLING ITEMS");
                    report.AppendLine("".PadRight(50, '-'));
                    foreach (var item in topItems)
                    {
                        report.AppendLine($"{item.Description.PadRight(30)} Qty: {item.Quantity} Sales: ${item.TotalSales:F2}");
                    }
                    report.AppendLine();

                    // Add system information
                    report.AppendLine("SYSTEM INFORMATION");
                    report.AppendLine("".PadRight(50, '-'));
                    report.AppendLine($"Report generated by: {username}");
                    report.AppendLine($"System Date/Time: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
                    report.AppendLine();
                    report.AppendLine("".PadRight(80, '='));
                }
            }
            catch (Exception ex)
            {
                report.AppendLine($"ERROR GENERATING REPORT: {ex.Message}");
            }

            return report.ToString();
        }

        private dynamic GetTransactionSummary(SqlConnection connection, DateTime reportDate)
        {
            string sql = @"
                SELECT 
                    COUNT(DISTINCT TransactionNo) as TotalTransactions,
                    ISNULL(SUM(Amount), 0) as TotalSalesAmount,
                    COUNT(*) as TotalItemsSold,
                    CASE WHEN COUNT(DISTINCT TransactionNo) > 0 
                         THEN ISNULL(SUM(Amount), 0) / COUNT(DISTINCT TransactionNo) 
                         ELSE 0 END as AverageTransaction
                FROM TransPaymentEntry 
                WHERE CAST(Date AS DATE) = @ReportDate";

            using (var command = new SqlCommand(sql, connection))
            {
                command.Parameters.AddWithValue("@ReportDate", reportDate.Date);
                using (var reader = command.ExecuteReader())
                {
                    if (reader.Read())
                    {
                        return new
                        {
                            TotalTransactions = reader.GetInt32("TotalTransactions"),
                            TotalSalesAmount = reader.GetDecimal("TotalSalesAmount"),
                            TotalItemsSold = reader.GetInt32("TotalItemsSold"),
                            AverageTransaction = reader.GetDecimal("AverageTransaction")
                        };
                    }
                }
            }

            return new { TotalTransactions = 0, TotalSalesAmount = 0m, TotalItemsSold = 0, AverageTransaction = 0m };
        }

        private List<dynamic> GetPaymentBreakdown(SqlConnection connection, DateTime reportDate)
        {
            var payments = new List<dynamic>();
            string sql = @"
                SELECT 
                    TenderTypeCode,
                    COUNT(*) as TransactionCount,
                    SUM(Amount) as TotalAmount
                FROM TransPaymentEntry 
                WHERE CAST(Date AS DATE) = @ReportDate
                GROUP BY TenderTypeCode
                ORDER BY SUM(Amount) DESC";

            using (var command = new SqlCommand(sql, connection))
            {
                command.Parameters.AddWithValue("@ReportDate", reportDate.Date);
                using (var reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        payments.Add(new
                        {
                            TenderType = reader.GetString("TenderTypeCode"),
                            Count = reader.GetInt32("TransactionCount"),
                            Amount = reader.GetDecimal("TotalAmount")
                        });
                    }
                }
            }

            return payments;
        }

        private List<dynamic> GetHourlySales(SqlConnection connection, DateTime reportDate)
        {
            var hourlySales = new List<dynamic>();
            string sql = @"
                SELECT 
                    DATEPART(HOUR, Time) as Hour,
                    COUNT(DISTINCT TransactionNo) as TransactionCount,
                    SUM(Amount) as TotalAmount
                FROM TransPaymentEntry 
                WHERE CAST(Date AS DATE) = @ReportDate
                GROUP BY DATEPART(HOUR, Time)
                ORDER BY DATEPART(HOUR, Time)";

            using (var command = new SqlCommand(sql, connection))
            {
                command.Parameters.AddWithValue("@ReportDate", reportDate.Date);
                using (var reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        hourlySales.Add(new
                        {
                            Hour = reader.GetInt32("Hour"),
                            TransactionCount = reader.GetInt32("TransactionCount"),
                            Amount = reader.GetDecimal("TotalAmount")
                        });
                    }
                }
            }

            return hourlySales;
        }

        private List<dynamic> GetTopSellingItems(SqlConnection connection, DateTime reportDate)
        {
            var topItems = new List<dynamic>();

            // First, try to get from a sales/transaction details table if it exists
            string checkTableSql = @"
                SELECT COUNT(*) 
                FROM INFORMATION_SCHEMA.TABLES 
                WHERE TABLE_NAME IN ('TransactionDetails', 'SalesDetails', 'TransSalesEntry')";

            using (var checkCommand = new SqlCommand(checkTableSql, connection))
            {
                var tableExists = (int)checkCommand.ExecuteScalar() > 0;

                if (tableExists)
                {
                    // Try to find the actual sales detail table structure
                    string sql = @"
                        SELECT TOP 10
                            ISNULL(Description, 'Unknown Item') as Description,
                            COUNT(*) as Quantity,
                            SUM(ISNULL(Amount, 0)) as TotalSales
                        FROM (
                            SELECT 'Misc Sales' as Description, Amount 
                            FROM TransPaymentEntry 
                            WHERE CAST(Date AS DATE) = @ReportDate
                        ) SalesData
                        GROUP BY Description
                        ORDER BY TotalSales DESC";

                    using (var command = new SqlCommand(sql, connection))
                    {
                        command.Parameters.AddWithValue("@ReportDate", reportDate.Date);
                        try
                        {
                            using (var reader = command.ExecuteReader())
                            {
                                while (reader.Read())
                                {
                                    topItems.Add(new
                                    {
                                        Description = reader.GetString("Description"),
                                        Quantity = reader.GetInt32("Quantity"),
                                        TotalSales = reader.GetDecimal("TotalSales")
                                    });
                                }
                            }
                        }
                        catch
                        {
                            // If query fails, add a placeholder
                            topItems.Add(new
                            {
                                Description = "Sales Summary (Detail breakdown not available)",
                                Quantity = 1,
                                TotalSales = 0m
                            });
                        }
                    }
                }
                else
                {
                    // Add placeholder information
                    topItems.Add(new
                    {
                        Description = "Item details not available",
                        Quantity = 0,
                        TotalSales = 0m
                    });
                }
            }

            return topItems;
        }

        private void PrintEODReport(string reportContent)
        {
            var printDialog = new PrintDialog();
            var printDocument = new PrintDocument();

            printDocument.PrintPage += (sender, e) =>
            {
                if (e.Graphics == null) return;

                var font = new Font(GlobalSettings.ReceiptFont, 9, GlobalSettings.ReceiptFontStyle);
                var brush = new SolidBrush(Color.Black);
                var lines = reportContent.Split('\n');

                float yPosition = e.MarginBounds.Top;
                float lineHeight = font.GetHeight(e.Graphics);

                foreach (string line in lines)
                {
                    if (yPosition + lineHeight > e.MarginBounds.Bottom)
                    {
                        e.HasMorePages = true;
                        break;
                    }

                    e.Graphics.DrawString(FunctionEvents.ToAscii(line), font, brush, e.MarginBounds.Left, yPosition);
                    yPosition += lineHeight;
                }
            };

            printDialog.Document = printDocument;

            if (printDialog.ShowDialog() == DialogResult.OK)
            {
                printDocument.Print();
            }
        }



        private void SaveAdvanceOrder()
        {
            // Check if downpayment is equal to currentTotal


            if (totalPaid == currentTotal)
            {
                MessageBox.Show("Downpayment should not be equal to Grand Total. Please checkout full amount instead", "Invalid Downpayment", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            string customerName = "";
            string orderDescription = "";
            decimal downpayment = 0;
            decimal balance = 0;
            decimal advanceReceiptBalance = 0m;

            try
            {
                //MessageBox.Show("Downpayment should not be equal to Grand Total. Please checkout full amount instead", "Invalid Downpayment", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                // Prompt for Customer Name
                customerName = FunctionEvents.PromptForCustomerName();
                if (string.IsNullOrWhiteSpace(customerName))
                {
                    MessageBox.Show("Customer name is required.", "Missing Info", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }
                // Prompt for Order Description
                orderDescription = FunctionEvents.PromptForOrderDescription();
                if (string.IsNullOrWhiteSpace(orderDescription))
                {
                    MessageBox.Show("Order description is required.", "Missing Info", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    return;
                }
                decimal aquariumTotal = FunctionEvents.GetAquariumCategoryTotal(salesListView, connectionString);
                using (var connection = new SqlConnection(connectionString))
                {
                    connection.Open();
                    if (string.IsNullOrWhiteSpace(currentReceiptNo))
                    {
                        currentReceiptNo = GenerateCentralizedReceiptNumber();
                    }
                    currentTransNo = GetNextTransactionNoPlusOne();
                    string storeNo = "1";
                    string posTerminalNo = "1";
                    string transactionNo = currentTransNo;
                    string receiptNo = currentReceiptNo;
                    string type = checkoutButton.Tag?.ToString() ?? "DOWNPAYMENT";
                    // Prefer the currently logged-in user id from CurrentUser; fall back to the local username field
                    string userID = CurrentUser.Username ?? username;
                    // string eodid = GetNextEODID();
                    DateTime now = DateTime.Now;
                    string date = now.ToString("yyyy-MM-dd");
                    string time = now.ToString("hh:mm:ss tt");

                    // Log the ADVANCEORDER transaction header. If this is an initial downpayment flow, write to TransactionHeader as 'ADVANCEORDERS'
                    string txTypeForHeader = (type == "DOWNPAYMENT") ? "ADVANCEORDERS" : "ADVANCEORDER";
                    // Header will be written after downpayment is calculated so we can record the downpayment amount for DOWNPAYMENT flows
                    string prodStatusCode = FunctionEvents.Get1stProductionStatusCode();
                    string prodOrderNo = FunctionEvents.GenerateNextProdOrderNo();
                    int nonPaymentItemCount = FunctionEvents.GetNonPaymentItemCount(salesListView);

                    // Insert into Prod_Order_Header with customerName and orderDescription
                    PostingEvents.PostProductionOrders(
                    connectionString,
                    storeNo: "1", // Replace with actual store number
                    posTerminalNo: "1", // Replace with actual POS terminal number
                    transactionNo: currentTransNo,
                    receiptNo: currentReceiptNo,
                    prodOrderNo: prodOrderNo,
                    type: "SALES",
                    noOfItems: nonPaymentItemCount,
                    date: DateTime.Now.Date,
                    time: DateTime.Now.TimeOfDay,
                    customerName: customerName,
                    orderDescription: orderDescription,
                    eodid: "", // Replace with actual EODID if available
                    status: prodStatusCode,
                    aquariumTotal: aquariumTotal,
                    salesListView: salesListView
                );

                    decimal totalTransactionAmount = 0;
                    int lineNo = 1;

                    // Check if AdvanceOrderLines has UserID column (once, for both loops)
                    bool advanceOrderLinesHasUserId = false;
                    var checkLinesCmdGlobal = new SqlCommand("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'AdvanceOrderLines' AND COLUMN_NAME = 'UserID'", connection);
                    advanceOrderLinesHasUserId = checkLinesCmdGlobal.ExecuteScalar() != null;
                    try
                    {
                        var ensureVariationColumnCmd = new SqlCommand(@"
IF COL_LENGTH('AdvanceOrderLines', 'VariationId') IS NULL
    ALTER TABLE AdvanceOrderLines ADD VariationId NVARCHAR(200) NULL;", connection);
                        ensureVariationColumnCmd.ExecuteNonQuery();
                    }
                    catch
                    {
                        // Ignore schema upgrade errors and continue with legacy behavior.
                    }

                    bool advanceOrderLinesHasVariationId = false;
                    var checkVariationCmdGlobal = new SqlCommand("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'AdvanceOrderLines' AND COLUMN_NAME = 'VariationId'", connection);
                    advanceOrderLinesHasVariationId = checkVariationCmdGlobal.ExecuteScalar() != null;
                    // Insert non-payment lines
                    foreach (ListViewItem item in salesListView.Items)
                    {
                        var itemType = item.Tag?.ToString() ?? item.SubItems[0].Text;
                        if (!itemType.Equals("PAYMENT", StringComparison.OrdinalIgnoreCase))
                        {
                            int quantity = int.Parse(item.SubItems[1].Text);
                            decimal price = decimal.Parse(item.SubItems[2].Text.Replace("?", ""));
                            decimal discount = 0;
                            // if (item.SubItems.Count > 3)
                            // {
                            //     decimal.TryParse(item.SubItems[3].Text.Replace("?", ""), out discount);
                            // }
                            string itemNo = item.SubItems.Count > 4 ? item.SubItems[4].Text : "";
                            string variationId = item.SubItems.Count > 6 ? item.SubItems[6].Text : string.Empty;
                            string description = item.SubItems[0].Text;//item.SubItems.Count > 5 ? item.SubItems[0].Text : item.SubItems[5].Text;
                            decimal grossAmount = price * quantity;
                            decimal netAmount = grossAmount - discount;

                            // Insert line into AdvanceOrderLines (include UserID when available)
                            string insertLinesSql = advanceOrderLinesHasUserId && advanceOrderLinesHasVariationId ? @"
                                INSERT INTO AdvanceOrderLines (
                                    StoreNo, POSTerminalNo, TransactionNo, [LineNo], ReceiptNo, Type, [No.], Description, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, EODID, UserID, VariationId
                                ) VALUES (
                                    @storeNo, @posTerminalNo, @transactionNo, @lineNo, @receiptNo, @type, @no, @description, @quantity, @price, @discount, @grossAmount, @netAmount, @date, @time, @eodid, @UserID, @VariationId
                                )" : advanceOrderLinesHasUserId ? @"
                                INSERT INTO AdvanceOrderLines (
                                    StoreNo, POSTerminalNo, TransactionNo, [LineNo], ReceiptNo, Type, [No.], Description, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, EODID, UserID
                                ) VALUES (
                                    @storeNo, @posTerminalNo, @transactionNo, @lineNo, @receiptNo, @type, @no, @description, @quantity, @price, @discount, @grossAmount, @netAmount, @date, @time, @eodid, @UserID
                                )" : advanceOrderLinesHasVariationId ? @"
                                INSERT INTO AdvanceOrderLines (
                                    StoreNo, POSTerminalNo, TransactionNo, [LineNo], ReceiptNo, Type, [No.], Description, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, EODID, VariationId
                                ) VALUES (
                                    @storeNo, @posTerminalNo, @transactionNo, @lineNo, @receiptNo, @type, @no, @description, @quantity, @price, @discount, @grossAmount, @netAmount, @date, @time, @eodid, @VariationId
                                )" : @"
                                INSERT INTO AdvanceOrderLines (
                                    StoreNo, POSTerminalNo, TransactionNo, [LineNo], ReceiptNo, Type, [No.], Description, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, EODID
                                ) VALUES (
                                    @storeNo, @posTerminalNo, @transactionNo, @lineNo, @receiptNo, @type, @no, @description, @quantity, @price, @discount, @grossAmount, @netAmount, @date, @time, @eodid
                                )";

                            var cmdLine = new SqlCommand(insertLinesSql, connection);
                            cmdLine.Parameters.AddWithValue("@storeNo", storeNo);
                            cmdLine.Parameters.AddWithValue("@posTerminalNo", posTerminalNo);
                            cmdLine.Parameters.AddWithValue("@transactionNo", transactionNo);
                            cmdLine.Parameters.AddWithValue("@lineNo", lineNo);
                            cmdLine.Parameters.AddWithValue("@receiptNo", receiptNo);
                            cmdLine.Parameters.AddWithValue("@type", "ITEM");
                            cmdLine.Parameters.AddWithValue("@no", itemNo);
                            cmdLine.Parameters.AddWithValue("@description", description);
                            cmdLine.Parameters.AddWithValue("@quantity", quantity);
                            cmdLine.Parameters.AddWithValue("@price", price);
                            cmdLine.Parameters.AddWithValue("@discount", discount);
                            cmdLine.Parameters.AddWithValue("@grossAmount", grossAmount);
                            cmdLine.Parameters.AddWithValue("@netAmount", netAmount);
                            cmdLine.Parameters.AddWithValue("@date", date);
                            cmdLine.Parameters.AddWithValue("@time", time);
                            cmdLine.Parameters.AddWithValue("@eodid", ""); // Set EODID if available
                            if (advanceOrderLinesHasUserId)
                                cmdLine.Parameters.AddWithValue("@UserID", userID);
                            if (advanceOrderLinesHasVariationId)
                                cmdLine.Parameters.AddWithValue("@VariationId", string.IsNullOrWhiteSpace(variationId) ? (object)DBNull.Value : variationId);
                            cmdLine.ExecuteNonQuery();
                            lineNo++;
                        }
                    }

                    // Insert payment lines separately
                    foreach (ListViewItem item in salesListView.Items)
                    {
                        var itemType = item.Tag?.ToString() ?? item.SubItems[0].Text;
                        if (itemType.Equals("PAYMENT", StringComparison.OrdinalIgnoreCase))
                        {
                            int quantity = int.Parse(item.SubItems[1].Text);
                            decimal price = decimal.Parse(item.SubItems[2].Text.Replace("?", ""));
                            decimal discount = 0;
                            if (item.SubItems.Count > 3)
                            {
                                decimal.TryParse(item.SubItems[3].Text.Replace("?", ""), out discount);
                            }
                            string itemNo = item.SubItems.Count > 4 ? item.SubItems[4].Text : "";
                            if (string.IsNullOrWhiteSpace(itemNo))
                                itemNo = item.Text?.Trim() ?? string.Empty;
                            if (string.IsNullOrWhiteSpace(itemNo))
                                itemNo = item.SubItems[0].Text?.Trim() ?? string.Empty;
                            string description = item.SubItems.Count > 5 ? item.SubItems[5].Text : item.SubItems[0].Text;
                            decimal grossAmount = price * quantity;
                            decimal netAmount = grossAmount - discount;

                            // Insert payment line into AdvanceOrderLines (include UserID when available)
                            string insertPaymentSql = advanceOrderLinesHasUserId ? @"
                                INSERT INTO AdvanceOrderLines (
                                    StoreNo, POSTerminalNo, TransactionNo, [LineNo], ReceiptNo, Type, [No.], Description, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, EODID, UserID
                                ) VALUES (
                                    @storeNo, @posTerminalNo, @transactionNo, @lineNo, @receiptNo, @type, @no, @description, @quantity, @price, @discount, @grossAmount, @net_amount, @date, @time, @eodid, @UserID
                                )" : @"
                                INSERT INTO AdvanceOrderLines (
                                    StoreNo, POSTerminalNo, TransactionNo, [LineNo], ReceiptNo, Type, [No.], Description, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, EODID
                                ) VALUES (
                                    @storeNo, @posTerminalNo, @transactionNo, @lineNo, @receiptNo, @type, @no, @description, @quantity, @price, @discount, @grossAmount, @netAmount, @date, @time, @eodid
                                )";

                            var cmdLine = new SqlCommand(insertPaymentSql, connection);
                            cmdLine.Parameters.AddWithValue("@storeNo", storeNo);
                            cmdLine.Parameters.AddWithValue("@posTerminalNo", posTerminalNo);
                            cmdLine.Parameters.AddWithValue("@transactionNo", transactionNo);
                            cmdLine.Parameters.AddWithValue("@lineNo", lineNo);
                            cmdLine.Parameters.AddWithValue("@receiptNo", receiptNo);
                            cmdLine.Parameters.AddWithValue("@type", "PAYMENT");
                            cmdLine.Parameters.AddWithValue("@no", itemNo);
                            cmdLine.Parameters.AddWithValue("@description", description);
                            cmdLine.Parameters.AddWithValue("@quantity", quantity);
                            cmdLine.Parameters.AddWithValue("@price", netAmount);
                            cmdLine.Parameters.AddWithValue("@discount", 0);
                            cmdLine.Parameters.AddWithValue("@grossAmount", grossAmount);
                            cmdLine.Parameters.AddWithValue("@netAmount", netAmount);
                            cmdLine.Parameters.AddWithValue("@date", date);
                            cmdLine.Parameters.AddWithValue("@time", time);
                            cmdLine.Parameters.AddWithValue("@eodid", ""); // Set EODID if available
                            if (advanceOrderLinesHasUserId)
                                cmdLine.Parameters.AddWithValue("@UserID", userID);
                            cmdLine.ExecuteNonQuery();
                            lineNo++;
                        }
                    }

                    // Calculate downpayment as the sum of tender type items in salesListView
                    // Deduct total discount from totalTransactionAmount
                    totalTransactionAmount -= currentDiscount;
                    // Get all valid tender type codes from master table
                    var tenderTypeCodes = new HashSet<string>();

                    downpayment = totalPaid;
                    decimal NetAmount = currentTotal - currentDiscount;
                    balance = grandTotal - downpayment;

                    // Write TransactionHeader now. For DOWNPAYMENT/ADVANCEORDERS write the downpayment amount; otherwise write the grand total.
                    decimal amountForHeader = (type == "DOWNPAYMENT" || txTypeForHeader == "ADVANCEORDERS") ? downpayment : grandTotal;
                    WriteSalesTransactionHeader(currentReceiptNo, txTypeForHeader, amountForHeader, "", "");


                    // Check if UserID column exists in AdvanceOrderHeader
                    var checkCmd = new SqlCommand("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'AdvanceOrderHeader' AND COLUMN_NAME = 'UserID'", connection);
                    var userIdCol = checkCmd.ExecuteScalar();
                    if (userIdCol == null)
                    {
                        MessageBox.Show("Error: 'UserID' column does not exist in AdvanceOrderHeader table. Please check your database schema.", "Database Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        return;
                    }
                    // ensure balance equals NetAmount - Downpayment
                    decimal computedBalance = NetAmount - downpayment;
                    advanceReceiptBalance = computedBalance;

                    // FullyPaid/DatePaid are optional columns (see sql_advance_order_paid_status.sql) -
                    // not every install will have run that script yet, so check before referencing
                    // them. Covers the customer paying the full amount upfront (no separate downpayment
                    // step needed later via AdvanceOrdersHeaderForm's "Pay In Full" button).
                    var checkPaidCmd = new SqlCommand("SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'AdvanceOrderHeader' AND COLUMN_NAME IN ('FullyPaid', 'DatePaid')", connection);
                    bool hasFullyPaidColumns = Convert.ToInt32(checkPaidCmd.ExecuteScalar()) == 2;
                    bool isFullyPaidAtCreation = computedBalance <= 0m;

                    string insertSql = @"
                        INSERT INTO AdvanceOrderHeader (
                            StoreNo, POSTerminalNo, TransactionNo, ReceiptNo, Type, Quantity, Price, Discount, GrossAmount, NetAmount, Date, Time, UserID, Downpayment, Balance, CustomerName, Order_Description" +
                            (hasFullyPaidColumns ? ", FullyPaid, DatePaid" : "") + @"
                        ) VALUES (
                            @storeNo, @posTerminalNo, @transactionNo, @receiptNo, @type, @quantity, @price, @discount, @grossAmount, @netAmount, @date, @time, @UserID, @downpayment, @balance, @customerName, @orderDescription" +
                            (hasFullyPaidColumns ? ", @fullyPaid, @datePaid" : "") + @"
                        )";
                    var cmd = new SqlCommand(insertSql, connection);
                    cmd.Parameters.AddWithValue("@storeNo", storeNo);
                    cmd.Parameters.AddWithValue("@posTerminalNo", posTerminalNo);
                    cmd.Parameters.AddWithValue("@transactionNo", currentTransNo);
                    cmd.Parameters.AddWithValue("@receiptNo", receiptNo);
                    cmd.Parameters.AddWithValue("@type", type);
                    cmd.Parameters.AddWithValue("@quantity", 0);
                    cmd.Parameters.AddWithValue("@price", currentTotal);
                    cmd.Parameters.AddWithValue("@discount", currentDiscount);
                    cmd.Parameters.AddWithValue("@grossAmount", currentTotal);
                    cmd.Parameters.AddWithValue("@netAmount", NetAmount);
                    cmd.Parameters.AddWithValue("@date", date);
                    cmd.Parameters.AddWithValue("@time", time);
                    // Captured from the PromptForCustomerName/PromptForOrderDescription prompts above
                    // (both required, so always non-blank here) - previously prompted for but never
                    // actually persisted onto AdvanceOrderHeader, so CustomerName/Order_Description
                    // were blank on every advance order ever created despite the Pancake note and
                    // Supabase sync already being wired to read them.
                    cmd.Parameters.AddWithValue("@customerName", customerName);
                    cmd.Parameters.AddWithValue("@orderDescription", orderDescription);
                    cmd.Parameters.AddWithValue("@UserID", userID);
                    cmd.Parameters.AddWithValue("@downpayment", downpayment);
                    cmd.Parameters.AddWithValue("@balance", computedBalance);
                    if (hasFullyPaidColumns)
                    {
                        cmd.Parameters.AddWithValue("@fullyPaid", isFullyPaidAtCreation);
                        cmd.Parameters.AddWithValue("@datePaid", isFullyPaidAtCreation ? (object)DateTime.UtcNow : DBNull.Value);
                    }
                    cmd.ExecuteNonQuery();
                }
                // If this is a full advance order (not just an initial downpayment), record payment entries as well

                RecordPaymentEntry();

                try
                {
                    string advanceReceiptToSync = currentReceiptNo;
                    if (!string.IsNullOrWhiteSpace(advanceReceiptToSync))
                    {
                        try
                        {
                            var resp = OnlinefunctionsEvents.SyncAdvanceOrderToCloud(advanceReceiptToSync);
                            System.Diagnostics.Debug.WriteLine($"SyncAdvanceOrderToCloud(create) response for {advanceReceiptToSync}: {resp}");
                        }
                        catch (Exception syncEx)
                        {
                            System.Diagnostics.Debug.WriteLine($"SyncAdvanceOrderToCloud(create) failed for {advanceReceiptToSync}: {syncEx.Message}");
                            MessageBox.Show(
                                $"Advance order was saved locally, but cloud sync failed.\n\nReceipt: {advanceReceiptToSync}\nError: {syncEx.Message}",
                                "Cloud Sync Warning",
                                MessageBoxButtons.OK,
                                MessageBoxIcon.Warning);
                        }

                        // Portal (Supabase) push - independent of the Pancake push above, so a
                        // Pancake failure doesn't also block this, and vice versa. Silent/best-effort
                        // like the auto-sync elsewhere; the masterDataSyncTimer's 5-minute bulk sync
                        // is the safety net if this fails.
                        try
                        {
                            var portalResp = OnlinefunctionsEvents.SyncSingleAdvanceOrderToSupabase(advanceReceiptToSync);
                            System.Diagnostics.Debug.WriteLine($"SyncSingleAdvanceOrderToSupabase(create) response for {advanceReceiptToSync}: {portalResp}");
                        }
                        catch (Exception portalSyncEx)
                        {
                            System.Diagnostics.Debug.WriteLine($"SyncSingleAdvanceOrderToSupabase(create) failed for {advanceReceiptToSync}: {portalSyncEx.Message}");
                        }
                    }
                }
                catch
                {
                    // Do not block local posting if cloud sync fails unexpectedly.
                }

                PrintAdvanceOrderReceipt(currentReceiptNo, customerName, orderDescription, downpayment, advanceReceiptBalance);


                ClearSaleAndPayments();
                MessageBox.Show("Advance order saved!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);

                // Revert checkout UI back to normal SALES mode after saving an advance order
                try
                {
                    checkoutButton.Text = "CHECKOUT";
                    checkoutButton.Tag = "SALES";
                    checkoutButton.BackColor = Color.Green;
                    // hide tender types panel if visible
                    try { tenderTypesPanel.Visible = false; } catch { }
                    // reset payment/checkout flags
                    try { isInCheckoutMode = false; isInPaymentMode = false; } catch { }
                }
                catch
                {
                    // ignore UI update failures
                }

            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error saving advance order: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }


        private void ExportEODToExcel(DateTime reportDate)
        {
            var saveDialog = new SaveFileDialog
            {
                Filter = "Excel files (*.xlsx)|*.xlsx",
                FileName = $"EOD_Report_{reportDate:yyyy-MM-dd}.xlsx",
                DefaultExt = "xlsx"
            };

            if (saveDialog.ShowDialog() == DialogResult.OK)
            {
                try
                {
                    using (var package = new ExcelPackage())
                    {
                        var worksheet = package.Workbook.Worksheets.Add("EOD Report");

                        // Header
                        worksheet.Cells["A1"].Value = "RS PET STOP - END OF DAY REPORT";
                        worksheet.Cells["A1"].Style.Font.Bold = true;
                        worksheet.Cells["A1"].Style.Font.Size = 16;

                        worksheet.Cells["A2"].Value = $"Report Date: {reportDate:yyyy-MM-dd}";
                        worksheet.Cells["A3"].Value = $"Generated: {DateTime.Now:yyyy-MM-dd HH:mm:ss}";

                        int row = 5;

                        using (var connection = new SqlConnection(connectionString))
                        {
                            connection.Open();

                            // Transaction Summary
                            var summary = GetTransactionSummary(connection, reportDate);
                            worksheet.Cells[row, 1].Value = "TRANSACTION SUMMARY";
                            worksheet.Cells[row, 1].Style.Font.Bold = true;
                            row++;

                            worksheet.Cells[row, 1].Value = "Total Transactions:";
                            worksheet.Cells[row, 2].Value = summary.TotalTransactions;
                            row++;

                            worksheet.Cells[row, 1].Value = "Total Sales Amount:";
                            worksheet.Cells[row, 2].Value = summary.TotalSalesAmount;
                            worksheet.Cells[row, 2].Style.Numberformat.Format = "$#,##0.00";
                            row++;

                            worksheet.Cells[row, 1].Value = "Total Items Sold:";
                            worksheet.Cells[row, 2].Value = summary.TotalItemsSold;
                            row++;

                            worksheet.Cells[row, 1].Value = "Average Transaction:";
                            worksheet.Cells[row, 2].Value = summary.AverageTransaction;
                            worksheet.Cells[row, 2].Style.Numberformat.Format = "$#,##0.00";
                            row += 2;

                            // Payment Breakdown
                            worksheet.Cells[row, 1].Value = "PAYMENT METHOD BREAKDOWN";
                            worksheet.Cells[row, 1].Style.Font.Bold = true;
                            row++;

                            worksheet.Cells[row, 1].Value = "Payment Method";
                            worksheet.Cells[row, 2].Value = "Amount";
                            worksheet.Cells[row, 3].Value = "Count";
                            worksheet.Cells[row, 1, row, 3].Style.Font.Bold = true;
                            row++;

                            var payments = GetPaymentBreakdown(connection, reportDate);
                            foreach (var payment in payments)
                            {
                                worksheet.Cells[row, 1].Value = payment.TenderType;
                                worksheet.Cells[row, 2].Value = payment.Amount;
                                worksheet.Cells[row, 2].Style.Numberformat.Format = "$#,##0.00";
                                worksheet.Cells[row, 3].Value = payment.Count;
                                row++;
                            }
                        }

                        // Auto-fit columns
                        worksheet.Cells.AutoFitColumns();

                        package.SaveAs(new FileInfo(saveDialog.FileName));
                    }

                    MessageBox.Show($"EOD Report exported to {saveDialog.FileName}", "Export Complete",
                                  MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
                catch (Exception ex)
                {
                    MessageBox.Show($"Error exporting to Excel: {ex.Message}", "Export Error",
                                  MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            }
        }
    }
